  FT["SG-H3302"] = {"id":"SG-H3302","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NCCA1972-N1?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":1,"structureMode":"WHOLE","title":{"zh":"由新加坡武装部队教育中心指挥的全国学生军团","en":"National Cadet Corps under the Command of Singapore Armed Forces Educational Centre","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NCCA1972-N1","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 1 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3302-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"National Cadet Corps Act\n(Chapter 194, Section 7)\n[1st April 1988]\nThe Minister of State, Ministry of Education has, on the recommendation of the National Cadet Corps Council, placed all National Cadet Corps cadets participating in the Singapore Armed Forces Local Sponsorship Programme under the command of the Commanding Officer of the Singapore Armed Forces Education Centre."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Cadet Corps under the Command of Singapore Armed Forces Educational Centre","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3303"] = {"id":"SG-H3303","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/S536-2026?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":1,"structureMode":"WHOLE","title":{"zh":"全国社会服务理事会（修正）法 2026（生效）公告 2026","en":"National Council of Social Service (Amendment) Act 2026 (Commencement) Notification 2026","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation S536-2026","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 1 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3303-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"National Council of Social Service\n(Amendment) Act 2026\nNational Council of Social Service\n(Amendment) Act 2026\n(Commencement) Notification 2026\nIn exercise of the powers conferred by section 1 of the National Council of Social Service (Amendment) Act 2026, the Minister for Social and Family Development makes the following Notification:"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Council of Social Service (Amendment) Act 2026 (Commencement) Notification 2026","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3304"] = {"id":"SG-H3304","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/S537-2026?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"国家福利理事会（保留与过渡条文）条例 2026","en":"National Council of Social Service (Saving and Transitional Provisions) Regulations 2026","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation S537-2026","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3304-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations are the National Council of Social Service (Saving and Transitional Provisions) Regulations 2026 and come into operation on 1 August 2026."}},{"id":"SG-H3304-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In these Regulations —\n“amended Act” and “unamended Act” have the meanings given by section 18(20) of the National Council of Social Service (Amendment) Act 2026;\n“Council” and “sector member” have the meanings given by section 2 of the amended Act."}},{"id":"SG-H3304-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Saving and transitional provisions for nomination"},"text":{"en":"3.—(1) Any nomination of a person to be appointed as a member of the Council submitted to the Minister before 1 August 2026 by an organisation which —\n(a)immediately before 1 August 2026, held an appointment as a full Council member mentioned in section 15(1)(a) of the unamended Act; and\n(b)is deemed, on 1 August 2026, by virtue of section 18(5) of the National Council of Social Service (Amendment) Act 2026, to have been appointed as a sector member under section 15(1) of the amended Act, and whose appointment as such has not expired or been revoked by virtue of section 18(6) or (7) of the National Council of Social Service (Amendment) Act 2026,\nis treated on 1 August 2026 as a nomination of a person by a sector member for the purpose of section 5(3) of the National Council of Social Service Act 1992, unless the sector member withdraws the nomination before 4 p.m. on 1 August 2026.\n(2) A list of the nominees mentioned in paragraph (1) submitted to the Minister before 1 August 2026 is treated on 1 August 2026 at 4 p.m. as a list of nominees submitted by the Chairperson to the Minister for the purpose of section 5(2)(d) and (3) of the National Council of Social Service Act 1992, with the exclusion of any nominee who is withdrawn by a sector member in accordance with paragraph (1)."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Council of Social Service (Saving and Transitional Provisions) Regulations 2026","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3305"] = {"id":"SG-H3305","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NCSSA1992-S538-2026?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"国家社会服务理事会（行业会员）条例 2026","en":"National Council of Social Service (Sector Membership) Regulations 2026","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NCSSA1992-S538-2026","completenessNote":"全文，共 10 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3305-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations are the National Council of Social Service (Sector Membership) Regulations 2026 and come into operation on 1 August 2026."}},{"id":"SG-H3305-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Conditions for appointment or re-appointment as sector member"},"text":{"en":"2.—(1) Any organisation which satisfies all of the following requirements may apply for appointment or re‑appointment as a sector member:\n(a)the organisation satisfies the requirement in section 15(3) of the Act;\n(b)the organisation is —\n(i)registered under the Business Names Registration Act 2014;\n(ii)registered under the Societies Act 1966;\n(iii)incorporated under the Companies Act 1967;\n(iv)the trustee or trustees of a charitable trust registered under the Charities Act 1994; or\n(v)established by or under any written law;\n(c)the organisation has been carrying on business for a continuous period of at least 2 years;\n(d)the organisation has sufficient financial resources, and has maintained the ability to obtain sufficient financial resources, to maintain its business.\n(2) The Council may waive the requirement under paragraph (1)(c) subject to any conditions that the Council thinks fit."}},{"id":"SG-H3305-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Application for appointment or re-appointment as sector member"},"text":{"en":"3.—(1) An application for appointment or re‑appointment as a sector member must be made to the Council in the form and manner required by the Council.\n(2) The Council must consider every duly completed application and communicate its decision in writing to the applicant.\n(3) The Council may reject an application for appointment or re‑appointment as a sector member without giving any reason."}},{"id":"SG-H3305-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Appointment and re-appointment of organisations as sector members"},"text":{"en":"4.—(1) Where the Council is satisfied that an organisation is suitable for appointment or re‑appointment as a sector member, the Council may appoint or re‑appoint (as the case may be) that organisation as a sector member under section 15(1) of the Act.\n(2) When appointing or re-appointing an organisation as a sector member under section 15(1) of the Act, the Council may specify an expiry date for the appointment."}},{"id":"SG-H3305-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Nominations by sector members of proposed members of Council"},"text":{"en":"5.—(1) The Chairperson may determine the start date and end date of the period in which sector members may submit nominations of persons for appointment as a member of the Council under section 5(2)(d) of the Act.\n(2) After determining the nomination period, the Chairperson must cause the nomination period to be communicated in writing to all sector members.\n(3) Sector members may only make nominations during a nomination period.\n(4) A sector member may make only one nomination during a given nomination period.\n(5) A sector member may only nominate one of the following individuals for appointment as a member of the Council under section 5(2)(d) of the Act:\n(a)a member of the governing body of the sector member;\n(b)where the sector member is the trustee or trustees of a charitable trust, that trustee or one of those trustees, as the case may be;\n(c)a member of a committee established by the sector member;\n(d)an employee of the sector member;\n(e)a person who (whether individually or as part of a body) is entitled to exercise executive functions in relation to the sector member but is not a person mentioned in sub‑paragraph (a), (b), (c) or (d);\n(f)an individual engaged by the sector member to provide advisory services to the sector member.\n(6) A nomination must be made to the Chairperson in the form and manner required by the Council, and be accompanied by any information that the Council requires for the Minister to decide on the appointment.\n(7) In this regulation —\n“nomination” means a nomination by a sector member of a person for appointment as a member of the Council under section 5(2)(d) of the Act;\n“nomination period” means the period in which sector members may submit nominations determined under paragraph (1)."}},{"id":"SG-H3305-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Obligations of sector members"},"text":{"en":"6. Every sector member must —\n(a)submit a certified copy of its annual report, audited accounts and balance‑sheet to the Council within 6 months from the end of its financial year; and\n(b)furnish to the Council such information with respect to its organisation and functions, in such manner and at such times, as the Council may reasonably require."}},{"id":"SG-H3305-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Resignation from appointment as sector member"},"text":{"en":"7. A sector member may at any time resign as a sector member by giving the Council 3 months’ notice in writing of its intention to do so, or any shorter period that the Council may allow."}},{"id":"SG-H3305-A8","no":8,"noLabel":{"en":"8."},"heading":{"en":"Revocation of appointment as sector member"},"text":{"en":"8.—(1) The Council may revoke the appointment of a sector member in the manner provided by this regulation where that sector member —\n(a)ceases to satisfy the requirements of regulation 2(1)(a), (b) or (d);\n(b)fails to comply with regulation 6(a) or (b);\n(c)has aims, objects or activities that are contrary to the public interest, public order or national harmony;\n(d)fails to comply with the standards for the management and administration of, and the provision of social service by, sectors members as prescribed;\n(e)fails to comply with the standards for the cooperation of sector members with the Council as prescribed;\n(f)has been convicted of an offence involving fraud or dishonesty;\n(g)is guilty of improper or dishonourable conduct which makes the sector member unfit to provide, be involved in or directly support the provision of, social service;\n(h)has used or practised any deception, fraud or misrepresentation to promote or procure the appointment of a member of the Council under section 5(2)(d) of the Act, or procure any decision of the Council;\n(i)has mismanaged or misapplied any of its funds or properties;\n(j)has conducted itself in a manner prejudicial to the reputation or interests of the Council or any sector member; or\n(k)fails to take appropriate steps to prevent, or respond to, a relevant event in relation to a key appointment holder of the sector member.\n(2) In paragraph (1)(k) —\n“key appointment holder”, in relation to a sector member, means —\n(a)a member of the governing body of the sector member;\n(b)where the sector member is the trustee or trustees of a charitable trust, that trustee or one of those trustees, as the case may be; or\n(c)any other individual, by whatever name called, who has general management or supervision of the sector member’s business;\n“relevant event”, in relation to a key appointment holder of a sector member, means —\n(a)the conviction of the key appointment holder of an offence involving fraud or dishonesty;\n(b)improper or dishonourable conduct on the part of the key appointment holder which makes him or her unfit to provide, be involved in or directly support the provision of, social service;\n(c)the use or practice of any deception, fraud or misrepresentation by the key appointment holder to promote or procure the appointment of a member of the Council under section 5(2)(d) of the Act, or procure any decision of the Council;\n(d)the mismanagement or misapplication by the key appointment holder of any of the sector member’s funds or properties; or\n(e)the conduct of the key appointment holder in a manner prejudicial to the reputation or interests of the Council or any sector member.\n(3) If the Council intends to revoke the appointment of a sector member under this regulation, the Council must give the sector member written notice of its intention.\n(4) A notice given under paragraph (3) must state that, within 21 days of the service thereof, the sector member may make written representations to the Council and the Council must not determine the matter without considering any representation received within that period.\n(5) Upon consideration of any representation made under paragraph (4), if the Council revokes the appointment of a sector member, the Council must inform the sector member in writing of the revocation."}},{"id":"SG-H3305-A9","no":9,"noLabel":{"en":"9."},"heading":{"en":"Giving written notice"},"text":{"en":"9. In these Regulations, where the Council or Chairperson is required to give a sector member written notice or inform a sector member in writing, the Council or Chairperson (as the case may be) may do so by post, delivery or electronic communication."}},{"id":"SG-H3305-A10","no":10,"noLabel":{"en":"10."},"heading":{"en":"Revocation"},"text":{"en":"10. Revoke the National Council of Social Service (Membership and Fees) Regulations (Rg 3)."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Council of Social Service (Sector Membership) Regulations 2026","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3306"] = {"id":"SG-H3306","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NCSSA1992?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":50,"structureMode":"ARTICLE","title":{"zh":"国家社会服务理事会法 1992","en":"National Council of Social Service Act 1992","orig":null},"level":"law","status":"active","docNumber":"Act NCSSA1992","completenessNote":"全文，共 50 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。其中 6 条为官方正文中标注的已废止条文存根（照录）。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3306-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Short title"},"text":{"en":"1. This Act is the National Council of Social Service Act 1992."}},{"id":"SG-H3306-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Interpretation"},"text":{"en":"2. In this Act —\n“Chairperson” means the Chairperson of the Council appointed under section 5(2)(a) and includes any individual acting in that capacity;\n“Chief Executive Officer” means the Chief Executive Officer of the Council mentioned in section 22(1) and includes any individual acting in that capacity;\n“Community Chest” means the Community Chest established under section 13(1);\n“Council” means the National Council of Social Service established under section 3;\n“Deputy Chairperson” means the Deputy Chairperson of the Council appointed under section 5C(1);\n“Endowment Fund” means the Endowment Fund established under section 26(1);\n“member” means a member of the Council mentioned in section 5(2);\n“sector member” means a sector member of the Council appointed under section 15(1).\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Establishment of National Council of Social Service"},"text":{"en":"3. A body called the National Council of Social Service is established, which is a body corporate with perpetual succession and a common seal and with powers to sue and be sued in its corporate name and to perform any other acts that a body corporate may by law perform."}},{"id":"SG-H3306-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Common seal"},"text":{"en":"4.—(1) The common seal of the Council must be kept in such custody as the Council may direct.\n[Act 3 of 2026 wef 01/08/2026]\n(2) All deeds, documents and other instruments requiring the seal of the Council must —\n(a)be sealed with the common seal of the Council; and\n(b)be signed by the Chairperson and the Chief Executive Officer or some other person duly authorised by the Council for the purpose.\n[Act 3 of 2026 wef 01/08/2026]\n(3) All courts, judges and persons acting judicially are to take judicial notice of the common seal of the Council affixed to any document and presume that it was duly affixed.\n(4) Section 11 of the Registration of Deeds Act 1988 does not apply to any instrument purporting to have been executed under subsection (2)."}},{"id":"SG-H3306-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Constitution of Council"},"text":{"en":"5.—(1) The Council consists of at least 15 but not more than 27 members.\n(2) The members of the Council are —\n(a)a Chairperson to be appointed by the Minister;\n(b)the Chief Executive Officer;\n(c)the chairperson of the Community Chest;\n(d)subject to subsections (1) and (4), at least 7 members to be appointed by the Minister, from a list of nominees to be submitted by the Chairperson; and\n(e)subject to subsections (1) and (4), any number of other members to be appointed by the Minister.\n(3) The list of nominees to be submitted by the Chairperson to the Minister under subsection (2)(d) must consist of persons nominated by sector members, except that the Chairperson may exclude any nominee whose nomination does not meet the prescribed requirements in regulations made under section 37(2)(ba).\n(4) The number of members appointed under subsection (2)(d) must be at least half of the total number of members, excluding the Chairperson.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.001","no":5.001,"noLabel":{"en":"5A."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Appointment of members of Council"},"text":{"en":"5A.—(1) Every appointment of a member of the Council mentioned in section 5(2)(a), (d) or (e) must be made by instrument in writing given to the member.\n(2) The instrument must state —\n(a)the term of the appointment (which must not be longer than 3 years); and\n(b)the date the appointment takes effect (which must not be a date earlier than the date the member receives the instrument).\n(3) A member of the Council mentioned in section 5(2)(a), (d) or (e) may be re-appointed.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.002","no":5.002,"noLabel":{"en":"5B."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Membership disqualification"},"text":{"en":"5B.—(1) In appointing members of the Council, the Minister must have regard to whether the members of the Council will collectively possess the appropriate knowledge, skills and experience for the Council to perform its functions effectively.\n(2) However, the following individuals are disqualified to be or from being a member of the Council mentioned in section 5(2)(a), (d) or (e):\n(a)an employee of the Council (other than the Chief Executive Officer);\n(b)a Judge or judicial officer;\n(c)an undischarged bankrupt or an individual who has an arrangement with any of his or her creditors;\n(d)an individual who has been convicted of an offence involving dishonesty, fraud or moral turpitude and has not received a free pardon;\n(e)an individual who has been sentenced to imprisonment for a term of 6 months or more, and has not received a free pardon;\n(f)an individual who is —\n(i)disqualified under section 154(1) of the Companies Act 1967 from acting as a director, or taking part (whether directly or indirectly) in the management, of a company during the period of disqualification in that provision;\n(ii)disqualified by a court order under section 149(1), 149A(1) or 154(2) of the Companies Act 1967 from being a director, or in any way (whether directly or indirectly) being concerned in, or taking part in, the management, of a company during the period of disqualification in the court order;\n(iii)disqualified under section 58(1) of the Variable Capital Companies Act 2018 from acting as a director, or taking part (whether directly or indirectly) in the management, of a VCC during the period of disqualification in that provision; or\n(iv)disqualified by a court order under section 56(1), 57(1) or 58(2) of the Variable Capital Companies Act 2018 from being a director, or in any way (whether directly or indirectly) being concerned in, or taking part in, the management, of a VCC during the period of disqualification in the court order;\n(g)an individual who lacks capacity in respect of his or her duties as a member, within the meaning of the Mental Capacity Act 2008, or in respect of whom an order is made under section 10 of the Mental Health (Care and Treatment) Act 2008.\n(3) In this section —\n“company” has the meaning given by section 4(1) of the Companies Act 1967;\n“VCC” has the meaning given by section 2(1) of the Variable Capital Companies Act 2018.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.003","no":5.003,"noLabel":{"en":"5C."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Chairperson and Deputy Chairperson"},"text":{"en":"5C.—(1) The Minister may, by instrument in writing, appoint a member (other than the Chairperson or the Chief Executive Officer) to be the Deputy Chairperson of the Council for the period specified in the instrument.\n(2) The Chairperson or Deputy Chairperson holds office until whichever of the following happens first:\n(a)his or her term of office as Chairperson or Deputy Chairperson (as the case may be) expires;\n(b)he or she ceases to hold office as a member of the Council;\n(c)the Minister terminates his or her appointment as Chairperson or Deputy Chairperson, as the case may be.\n(3) Subject to section 5E, the Deputy Chairperson has and may perform all the functions and exercise all the powers of the Chairperson in relation to a matter if —\n(a)the Chairperson is unavailable; or\n(b)the Chairperson is interested (within the meaning given by Part 4 of the Public Sector (Governance) Act 2018) in the matter.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.004","no":5.004,"noLabel":{"en":"5D."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Premature vacancies"},"text":{"en":"5D.—(1) If a premature vacancy occurs in the office of any member of the Council, the Minister may, subject to sections 5, 5A and 5B, appoint an individual to fill the vacancy and hold that office for the remainder of the term for which the vacating member was appointed.\n(2) In this section, “premature vacancy”, for an office, means a vacancy that occurs in that office by virtue of section 5J(1) or for any reason other than the expiry of the term of the office.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.005","no":5.005,"noLabel":{"en":"5E."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Acting Chairperson and members of Council"},"text":{"en":"5E.—(1) The Minister may appoint a member of the Council (other than the Chief Executive Officer) to act temporarily as the Chairperson during any period, or during all periods, when the Chairperson is —\n(a)absent from duty or Singapore; or\n(b)for any reason, unable to perform the duties of the office.\n(2) The Minister may appoint an individual to act temporarily as a member of the Council (other than the Chairperson) during any period, or during all periods, when a member is —\n(a)absent from duty or Singapore; or\n(b)for any reason, unable to perform the duties of the office.\n(3) An individual is ineligible for appointment under this section to act as the Chairperson or a member of the Council if the individual is disqualified under section 5B(2) for appointment as a member of the Council.\n(4) The Minister may, at any time and without giving any reason, revoke the appointment of a person made under subsection (1) or (2).\n(5) The Minister may specify other terms and conditions of appointment in writing when making an appointment under subsection (1) or (2).\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.006","no":5.006,"noLabel":{"en":"5F."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Removal of member of Council"},"text":{"en":"5F.—(1) The Minister may, at any time and without giving any reason, remove a member of the Council mentioned in section 5(2)(a), (d) or (e) from office.\n(2) Every removal under subsection (1) must be made by written notice given to the member with a copy to the Council.\n(3) The notice must state the date the removal takes effect, which must not be a date earlier than the date the member receives the notice.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.007","no":5.007,"noLabel":{"en":"5G."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Resignation from office"},"text":{"en":"5G.—(1) A member of the Council (other than the Chief Executive Officer or the chairperson of the Community Chest) may resign his or her office by written notice to the Minister (with a copy to the Council) signed by the member.\n(2) The resignation is effective when the notice in subsection (1) is received by the Minister or at any later time specified in the notice.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.008","no":5.008,"noLabel":{"en":"5H."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Validity of acts, etc."},"text":{"en":"5H.—(1) Despite section 33 of the Interpretation Act 1965, the performance of any function or exercise of any power by the Council is not affected merely because at the relevant time —\n(a)there was a vacancy in the membership of the Council, including a vacancy arising from the failure to appoint a member;\n(b)there was some defect or irregularity existing in the appointment or continuance in office of an individual purporting to be a member of the Council; or\n(c)there was an irregularity in the Council’s decision-making procedure that does not affect the merits of the decision made.\n(2) The acts of an individual as a member of the Council are not affected merely because —\n(a)there was some defect or irregularity existing in the appointment or continuance in office of the individual purporting to be a member of the Council; or\n(b)in the case of an individual acting in the capacity of the Chairperson, a member or the Chief Executive Officer, the occasion for the individual so acting, or for his or her appointment, had not arisen or had ended.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.009","no":5.009,"noLabel":{"en":"5I."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Remuneration, etc."},"text":{"en":"5I.—(1) Subject to subsection (2), the members of the Council may be paid, out of the funds of the Council, such salaries, fees and allowances as the Minister may from time to time determine.\n(2) The members of the Council must not be paid salaries, fees or allowances from funds administered by the Council for charitable purposes.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.01","no":5.01,"noLabel":{"en":"5J."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Vacation of office"},"text":{"en":"5J.—(1) A member of the Council ceases to hold office if he or she —\n(a)dies;\n(b)is adjudicated a bankrupt or makes an arrangement with any of his or her creditors;\n(c)becomes otherwise disqualified from being a member under section 5B(2);\n(d)is removed from office in accordance with section 5F;\n(e)resigns in accordance with section 5G;\n(f)fails without reasonable cause to disclose any interest required under Division 1 of Part 4 of the Public Sector (Governance) Act 2018 and a notice is given under that Act to the Minister about that default;\n(g)fails to attend 3 consecutive meetings of the Council without the approval of the Council; or\n(h)is not re-appointed when his or her term of office expires.\n(2) A member of the Council is not entitled to any compensation or other payment or benefit relating to his or her ceasing, for any reason, to hold office as a member.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A5.011","no":5.011,"noLabel":{"en":"5K."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Other terms and conditions"},"text":{"en":"5K. The Minister may specify other terms and conditions of appointment of a member of the Council mentioned in section 5(2)(a), (d) or (e) in the instrument of appointment.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Meetings of Council"},"text":{"en":"6.—(1) The Council must hold such meetings as are necessary for performing its functions.\n(2) The Chairperson must appoint the times and places of the meetings of the Council, and cause notice of those meetings to be given to each member of the Council not present when the appointment is made.\n(3) The meetings of the Council must be held in accordance with the provisions of this Act and Part 4 of the Public Sector (Governance) Act 2018.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Quorum"},"text":{"en":"7.—(1) The quorum for a meeting of the Council is the higher of the following:\n(a)one-third of the number of members;\n(b)7 members.\n(2) No business may be transacted at a meeting of the Council if a quorum is not present.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Presiding at meetings"},"text":{"en":"8.—(1) At a meeting of the Council, the following person presides:\n(a)the Chairperson;\n(b)in the absence of the Chairperson, or if the Chairperson is interested in the matter (within the meaning given by Part 4 of the Public Sector (Governance) Act 2018), and there is a Deputy Chairperson who is present and is not interested in the matter (within the meaning given by Part 4 of that Act) — the Deputy Chairperson;\n(c)in any other case — a member of the Council elected from among the members present at the meeting to preside.\n(2) The person specified in subsection (1)(b) or (c) may perform the functions and exercise the powers of the Chairperson for the purposes of the meeting.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Voting at meetings"},"text":{"en":"9.—(1) Each member of the Council has one vote.\n(2) In addition to his or her general vote, the member presiding at a meeting has, in the case of an equality of votes, a casting vote.\n(3) A resolution of the Council is passed if it is agreed to by all members present without dissent, or if a majority of the votes cast on it by members present and voting are in favour of it.\n(4) A member present at a meeting of the Council is presumed to have agreed to, and to have cast a vote in favour of, a decision of the Council unless the member expressly dissents from or votes against the decision at the meeting or is prevented from voting by section 26 of the Public Sector (Governance) Act 2018.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 2 ESTABLISHMENT AND CONSTITUTION OF COUNCIL"},"heading":{"en":"Directions of Minister, etc."},"text":{"en":"10.—(1) The Minister may give to the Council any direction under section 5 of the Public Sector (Governance) Act 2018.\n(2) Without limiting subsection (1), the Minister may give such directions to the Council as are necessary in the circumstances if it appears to the Minister to be requisite or expedient to do so —\n(a)in the interests of relations with the government of a territory outside Singapore; or\n(b)in order to —\n(i)discharge or facilitate the discharge of an obligation binding on the Government by virtue of it being a member of an international organisation or a party to an international agreement;\n(ii)attain or facilitate the attainment of any other object the attainment of which is in the Minister’s opinion requisite or expedient in view of the Government being a member of such an organisation or a party to such an agreement; or\n(iii)enable the Government to become a member of such an organisation or a party to such an agreement.\n(3) To avoid doubt, the Minister is entitled —\n(a)to information in the possession of the Council; and\n(b)where the information is in or on a document, to have, and make and retain copies of, that document.\n(4) For the purposes of this section, the Minister may request the Council to —\n(a)provide information to the Minister; or\n(b)give the Minister access to information.\n(5) The Council must give effect to any direction given to it under subsection (1) or (2) and must comply with a request under subsection (4).\n(6) The Council must not disclose any direction given to it under this section if the Minister notifies the Council that, in the Minister’s opinion, disclosure of the direction is against the public interest.\n(7) In this section, “information” means information specified, or of a description specified, by the Minister that relates to the functions of the Council.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 3 OBJECTIVES, FUNCTIONS AND POWERS OF COUNCIL"},"heading":{"en":"Objectives and functions of Council"},"text":{"en":"11.—(1) The objectives of the Council are —\n(a)to build an effective, efficient and sustainable social service sector; and\n(b)to support the development of such a sector by —\n(i)strengthening social service delivery;\n(ii)strengthening capability building in the social service sector; and\n(iii)building a robust social service ecosystem which includes community support, philanthropy and volunteerism.\n(2) The Council has the following functions:\n(a)to assist the Government in relation to social services and the social service sector by providing advice, assisting in strategic planning and representing Singapore and advancing its interests internationally in matters relating to social service;\n(b)to act as a coordinating agency for the provision of social services and to direct the provision, development, implementation or operation of social services;\n(c)to facilitate support for and provision, development, implementation or operation of social services, including by —\n(i)providing consultancy or other services;\n(ii)promoting and developing competencies and professional and governance standards in relation to social service for both individuals and organisations;\n(iii)promoting or coordinating research and development into matters relating to social service; and\n(iv)promoting and facilitating the participation of the community, individuals and organisations;\n(d)to directly provide, develop, implement or operate social services, and undertake research into, and development of matters relating to, social service;\n(e)to establish and maintain standards and guidelines for the management and administration of, and the provision of social services by, sector members;\n(f)to raise and allocate funds to further the objectives and carry out the functions of the Council;\n(g)in the performance of its functions, to implement Government policy in relation to social service and the social service sector and to collaborate with any person or organisation and with other public sector bodies;\n(h)to perform any other functions that may be conferred on the Council by any other Act.\n(3) In addition to the functions conferred by this section, the Council may also undertake any other functions that the Minister may, by notification in the Gazette, assign to the Council, and in so undertaking —\n(a)the Council is deemed to be fulfilling the purposes of this Act; and\n(b)the provisions of this Act apply to the Council in respect of those other functions.\n(4) Nothing in this section imposes on the Council, directly or indirectly, any form of duty or liability enforceable by proceedings before any court to which the Council would not otherwise be subject.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 3 OBJECTIVES, FUNCTIONS AND POWERS OF COUNCIL"},"heading":{"en":"Powers of Council"},"text":{"en":"12.—(1) Subject to this Act, the Council has power to do all things necessary or expedient to be done for, or in connection with, the performance of its functions.\n(2) Without limiting subsection (1), the powers of the Council mentioned in that subsection include power —\n(a)to acquire and dispose of any property, both movable and immovable, and to use any such property, including mortgaging it;\n(b)to apply for, obtain and hold any intellectual property rights, and enter into agreements or arrangements for the commercial exploitation of those intellectual property rights;\n(c)to accept grants, gifts, donations or contributions from any source, whether subject to any trust or not, or raise funds by all lawful means;\n(d)to form or participate in the formation of a trust;\n(e)to act as trustee of property vested in the Council on trust;\n(f)to provide financial support, grant, aid or assistance to any person in connection with any function of the Council;\n(g)to provide scholarships, training grants and financial awards in the field of social service;\n(h)to charge for the provision of goods or services, or the performance of work, by or on behalf of the Council;\n(i)to waive or refund the whole or part of any fee or charges payable or paid to the Council under this Act or any other Act administered by the Council;\n(j)to establish and administer any scheme or programme relating to its functions;\n(k)to publish or provide any information, or publish or sponsor the publication of works;\n(l)to collect, compile, analyse and disseminate information of a statistical nature or otherwise concerning matters relating to its functions;\n(m)to enter into contracts, agreements and arrangements, including memoranda of understanding;\n(n)with the approval of the Minister, to form or participate in the formation of a body corporate, unincorporated association or organisation, or enter into a joint venture with any person or organisation; and\n(o)to do any other thing that is incidental to the performance of its functions.\n(3) To avoid doubt, subsection (1) does not limit any other power given to the Council by any other provision in this Act or any other Act.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 3 OBJECTIVES, FUNCTIONS AND POWERS OF COUNCIL"},"heading":{"en":"Community Chest"},"text":{"en":"13.—(1) The Council must establish the Community Chest.\n[Act 3 of 2026 wef 01/08/2026]\n(2) The Community Chest established by the Council has the following functions:\n(a)to raise funds on behalf of the Council;\n(b)to mobilise resources (financial or in kind, including the services of volunteers) to facilitate the provision of social services in Singapore.\n[Act 3 of 2026 wef 01/08/2026]\n(3) The Community Chest consists of —\n(a)a chairperson of the Community Chest to be appointed by the Minister;\n(b)a deputy chairperson of the Community Chest to be appointed by the chairperson of the Community Chest in consultation with the Chairperson of the Council; and\n(c)any number of other members of the Community Chest to be appointed by the chairperson of the Community Chest in consultation with the Chairperson of the Council.\n[Act 3 of 2026 wef 01/08/2026]\n(4) Subject to subsection (5), an individual is disqualified to be or from being the chairperson, the deputy chairperson or any other member of the Community Chest if he or she would be disqualified to be or from being a member of the Council under section 5B(2).\n[Act 3 of 2026 wef 01/08/2026]\n(5) The Chief Executive Officer may be a member of the Community Chest but is not to be appointed as the chairperson or deputy chairperson of the Community Chest.\n[Act 3 of 2026 wef 01/08/2026]\n(6) An individual may not be appointed as the chairperson, the deputy chairperson or any other member of the Community Chest unless, before appointment, he or she discloses to the Council the details of any interest (within the meaning given by Part 4 of the Public Sector (Governance) Act 2018) the individual may have if he or she were a member of the Community Chest.\n[Act 3 of 2026 wef 01/08/2026]\n(7) Subject to subsection (16), the chairperson of the Community Chest holds office for a period of 3 years or any shorter period specified by the Minister at the time of appointment, and on the terms determined by the Minister.\n[Act 3 of 2026 wef 01/08/2026]\n(8) Subject to subsection (16), the deputy chairperson and other members of the Community Chest hold office for a period specified by the chairperson of the Community Chest at the time of appointment, and on the terms determined by the Council.\n[Act 3 of 2026 wef 01/08/2026]\n(9) The chairperson, deputy chairperson and other members of the Community Chest may be re-appointed.\n[Act 3 of 2026 wef 01/08/2026]\n(10) The deputy chairperson of the Community Chest has and may perform all the functions and exercise all the powers of the chairperson of the Community Chest in relation to a matter if —\n(a)the chairperson of the Community Chest is unavailable; or\n(b)the chairperson of the Community Chest is interested (within the meaning given by Part 4 of the Public Sector (Governance) Act 2018) in the matter.\n[Act 3 of 2026 wef 01/08/2026]\n(11) The Chairperson of the Council may appoint a member of the Community Chest (other than the Chief Executive Officer) to act temporarily as the chairperson of the Community Chest during any period, or during all periods, when both the chairperson and deputy chairperson of the Community Chest are —\n(a)absent from duty or Singapore; or\n(b)for any reason, unable to perform the duties of the office of chairperson of the Community Chest.\n[Act 3 of 2026 wef 01/08/2026]\n(12) The Minister may, at any time and without giving any reason, remove the chairperson of the Community Chest from office.\n[Act 3 of 2026 wef 01/08/2026]\n(13) The chairperson of the Community Chest may, in consultation with the Chairperson of the Council, at any time and without giving any reason, remove the deputy chairperson or any other member of the Community Chest from office.\n[Act 3 of 2026 wef 01/08/2026]\n(14) Every removal under subsection (12) or (13) must be made by written notice given to the person being removed from office with a copy to the Community Chest, stating the date the removal takes effect, which must not be a date earlier than the date the person receives the notice.\n[Act 3 of 2026 wef 01/08/2026]\n(15) The chairperson, the deputy chairperson or a member of the Community Chest may resign his or her office in the following manner:\n(a)in the case of the chairperson of the Community Chest, by written notice to the Minister (with a copy to the Community Chest) signed by the chairperson;\n(b)in the case of the deputy chairperson or other member of the Community Chest, by written notice to the chairperson of the Community Chest (with a copy to the Community Chest) signed by the deputy chairperson or member, as the case may be.\n[Act 3 of 2026 wef 01/08/2026]\n(16) The chairperson, the deputy chairperson or a member of the Community Chest ceases to hold office if he or she —\n(a)dies;\n(b)is adjudicated a bankrupt or makes an arrangement with any of his or her creditors;\n(c)becomes otherwise disqualified from being a member under subsection (4);\n(d)is removed from office in accordance with subsection (12) or (13);\n(e)resigns in accordance with subsection (15);\n(f)fails without reasonable cause to disclose any interest required under Division 1 of Part 4 of the Public Sector (Governance) Act 2018 and a notice is given under that Act to the Council about that default;\n(g)fails to attend 3 consecutive meetings of the Community Chest without the approval of the Community Chest; or\n(h)is not re-appointed when his or her term of office expires.\n[Act 3 of 2026 wef 01/08/2026]\n(17) Section 5H applies, with the necessary modifications, to the Community Chest, and to members of the Community Chest or individuals purporting to be members of the Community Chest.\n[Act 3 of 2026 wef 01/08/2026]\n(18) Sections 20, 21 and 28 of the Public Sector (Governance) Act 2018 apply in relation to the Community Chest as they would apply if —\n(a)the Community Chest were a committee of the Council appointed under section 14; and\n(b)the chairperson, deputy chairperson and other members of the Community Chest were members of that committee.\n(19) Subject to this Act and any restrictions imposed by the Council by resolution, the Community Chest may regulate its own proceedings and business.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 3 OBJECTIVES, FUNCTIONS AND POWERS OF COUNCIL"},"heading":{"en":"Appointment of committees, etc."},"text":{"en":"14.—(1) The Council may, by resolution, appoint such number of committees as the Council thinks fit for purposes which, in the opinion of the Council, would be better regulated and managed by means of such committees.\n(2) A committee appointed under this section may consist of such individuals as the Council thinks fit, and may include individuals who are not members of the Council.\n(3) Without limiting subsection (1), the Council may appoint committees —\n(a)to advise the Council on matters relating to the Council’s functions and powers that are referred to the committee by the Council; or\n(b)to perform any function or exercise any power of the Council that is delegated to the committee.\n(4) An individual may not be appointed as a member of a committee unless, before appointment, he or she discloses to the Council the details of any interest (within the meaning given by Part 4 of the Public Sector (Governance) Act 2018) the individual may have if he or she were a member of that committee.\n(5) Subject to this Act, the Public Sector (Governance) Act 2018 and any restrictions imposed by the Council by resolution, a committee appointed under this section may regulate its own proceedings and business.\n(6) Section 5H applies, with the necessary modifications, to a committee and the members of the committee or individuals purporting to be members of the committee.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A14.001","no":14.001,"noLabel":{"en":"14A."},"chapter":{"en":"PART 3 OBJECTIVES, FUNCTIONS AND POWERS OF COUNCIL"},"heading":{"en":"Ability to delegate, etc."},"text":{"en":"14A.—(1) The Council may delegate any of its functions or powers, either generally or specially and subject to such conditions or restrictions as the Council thinks fit, to any of the following:\n(a)a member of the Council;\n(b)the Chief Executive Officer or an employee of the Council;\n(c)a committee of the Council appointed under section 14;\n(d)a company that is incorporated in Singapore and is a subsidiary of the Council.\n(2) A delegation under subsection (1) must be by resolution and written notice given to the delegate.\n(3) Subsection (1) does not apply to —\n(a)the power to make subsidiary legislation conferred by this Act or any other Act;\n(b)the power to delegate conferred by this section; or\n(c)any function or power under this Act or any other Act that is declared by this Act or that other Act to be non-delegable.\n(4) A delegation in accordance with this section —\n(a)except as otherwise provided in this Act or any other Act administered by the Council, does not affect or prevent the performance of any function or the exercise of any power by the Council;\n(b)is not affected by any change in the membership of the Council;\n(c)is not affected by any change in the membership of a committee appointed under section 14 (where the committee is the delegate); and\n(d)is not affected by any change in the individual appointed as the Chief Executive Officer or holding any specified office in the Council (where the delegate is the Chief Executive Officer or the holder of the specified office).\n(5) For the purposes of subsection (1)(d), a company is a subsidiary of the Council if —\n(a)the Council is the sole member of that company; or\n(b)the Council, as a member of that company, holds more than half of the voting power in that company.\n(6) A delegate who purports to perform a function or exercise a power under delegation —\n(a)is taken to do so in accordance with the terms of the delegation under this section, unless the contrary is shown; and\n(b)must produce evidence of the delegation, if reasonably required to do so.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 4 SECTOR MEMBERS AND PATRONS OF COUNCIL"},"heading":{"en":"Sector members"},"text":{"en":"15.—(1) The Council may appoint an organisation to be a sector member of the Council.\n(2) A sector member may be re-appointed.\n(3) To be appointed as a sector member, an organisation must either —\n(a)have the primary function of providing a social service in Singapore; or\n(b)have the primary function of directly supporting the provision of a social service in Singapore.\n(4) A sector member must comply with —\n(a)such standards for the management and administration of, and the provision of social service by, sector members as may be prescribed; and\n(b)such standards for the cooperation of sector members with the Council as may be prescribed.\n(5) The Council may at any time revoke the appointment of an organisation as a sector member in accordance with any regulations made under section 37.\n(6) In determining whether to appoint or re-appoint an organisation as a sector member under subsection (1) or (2), respectively, or whether to revoke the appointment of an organisation as a sector member under subsection (5), the Council may consider the organisation’s aims, objects and activities, including whether those aims, objects and activities are contrary to the public interest, public order or national harmony.\n(7) Sector members are not members of the Council for the purposes of section 5 and the definition of “member” in relation to a public body in section 2(1) of the Public Sector (Governance) Act 2018.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 4 SECTOR MEMBERS AND PATRONS OF COUNCIL"},"heading":{"en":"Appeal to Minister"},"text":{"en":"16.—(1) An organisation aggrieved by a decision mentioned in subsection (2) may appeal to the Minister within 14 days after notice of the decision is served on the organisation or such extended period as the Minister may allow in any particular case.\n(2) A decision for the purpose of subsection (1) is a decision of the Council —\n(a)refusing to appoint that organisation as a sector member under section 15(1);\n(b)refusing to re-appoint that organisation as a sector member under section 15(2); or\n(c)revoking that organisation’s appointment as a sector member under section 15(5).\n(3) Any organisation that appeals to the Minister under subsection (1) must —\n(a)in the appeal, state as concisely as possible the circumstances under which the appeal arises, and the issues and grounds for the appeal; and\n(b)submit the appeal to the Minister together with all relevant facts, evidence and arguments for the appeal, within the period specified in subsection (1).\n(4) Where an appeal has been made to the Minister under subsection (1), the Minister may require any party to the appeal to provide the Minister with such information or document as the Minister may require for determining the appeal, and any person so required must provide the information or document in such manner and within such period as may be specified by the Minister.\n(5) The Minister is not under any duty to hear, consider or determine any appeal if —\n(a)the appellant does not comply with subsection (3) or (4); or\n(b)it appears that the bringing of the appeal is or the proceedings of the appeal are frivolous or vexatious.\n(6) The decision appealed against must be complied with until the determination of the appeal unless otherwise directed by the Minister in any particular case.\n(7) The Minister may determine an appeal under this section by —\n(a)confirming, varying or cancelling the decision appealed against; or\n(b)directing the Council to reconsider the decision appealed against.\n(8) The decision of the Minister in any appeal is final.\n(9) Every appellant must be notified of the Minister’s decision under subsection (7).\n(10) The Minister may designate any of the following office-holders in his or her Ministry to hear and determine, in the Minister’s place, any appeal made under this section:\n(a)any Minister assigned by the Prime Minister to assist the Minister;\n(b)any Minister of State;\n(c)any Parliamentary Secretary.\n(11) In this section (except subsection (10)), a reference to the Minister in relation to an appeal includes a reference to any office-holder designated under subsection (10) to hear and determine the appeal.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 4 SECTOR MEMBERS AND PATRONS OF COUNCIL"},"text":{"en":"17. [Deleted by Act 3 of 2026 wef 01/08/2026]"},"status":"repealed"},{"id":"SG-H3306-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 4 SECTOR MEMBERS AND PATRONS OF COUNCIL"},"text":{"en":"18. [Deleted by Act 3 of 2026 wef 01/08/2026]"},"status":"repealed"},{"id":"SG-H3306-A19","no":19,"noLabel":{"en":"19."},"chapter":{"en":"PART 4 SECTOR MEMBERS AND PATRONS OF COUNCIL"},"text":{"en":"19. [Deleted by Act 3 of 2026 wef 01/08/2026]"},"status":"repealed"},{"id":"SG-H3306-A20","no":20,"noLabel":{"en":"20."},"chapter":{"en":"PART 4 SECTOR MEMBERS AND PATRONS OF COUNCIL"},"text":{"en":"20. [Deleted by Act 3 of 2026 wef 01/08/2026]"},"status":"repealed"},{"id":"SG-H3306-A21","no":21,"noLabel":{"en":"21."},"chapter":{"en":"PART 4 SECTOR MEMBERS AND PATRONS OF COUNCIL"},"heading":{"en":"Patrons of Council"},"text":{"en":"21. The Council may nominate suitable persons to be the patron-in-chief and patrons of the Council.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A22","no":22,"noLabel":{"en":"22."},"chapter":{"en":"PART 5 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Chief Executive Officer"},"text":{"en":"22.—(1) There must be a Chief Executive Officer of the Council, whose appointment, removal, discipline and promotion must be in accordance with the Public Sector (Governance) Act 2018.\n[5/2018]\n(2) The Council may, subject to the Public Sector (Governance) Act 2018, appoint an individual to act temporarily as the Chief Executive Officer during any period, or during all periods, when the Chief Executive Officer —\n(a)is absent from duty or Singapore; or\n(b)is, for any reason, unable to perform the duties of the office.\n[5/2018]"}},{"id":"SG-H3306-A23","no":23,"noLabel":{"en":"23."},"chapter":{"en":"PART 5 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Appointment of staff"},"text":{"en":"23. The Council may, subject to the Public Sector (Governance) Act 2018, appoint and employ, on such terms and conditions as it may determine, such other officers, employees, consultants and agents as may be necessary for the effective performance of its functions.\n[5/2018]"}},{"id":"SG-H3306-A24","no":24,"noLabel":{"en":"24."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"heading":{"en":"Financial year"},"text":{"en":"24. The financial year of the Council begins on 1 April of each year and ends on 31 March of the succeeding year.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A25","no":25,"noLabel":{"en":"25."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"heading":{"en":"Funds and property of Council"},"text":{"en":"25.—(1) The funds and property of the Council include —\n(a)all moneys paid to the Council by way of grants, subsidies, donations, gifts and contributions for the purposes of the Council;\n(b)all moneys paid to, and all other moneys and property lawfully received by, the Council for the purposes of the Council;\n(c)all fees, charges and other sums paid to the Council under this Act or any other Act administered by the Council, except as otherwise provided in this Act or that other Act;\n(d)all moneys, dividends, royalties, interest or income received from any transaction made under the powers of the Council under this Act or any other Act administered by the Council;\n(e)all moneys borrowed by the Council under this Act; and\n(f)all accumulations of income derived from any property or moneys referred to in paragraphs (a) to (e).\n(2) To avoid doubt, the funds and property of the Council include the funds in the Endowment Fund.\n(3) The moneys of the Council are to be applied only in payment of expenses incurred by it in the discharge of its functions, obligations and liabilities, and in making any payment that the Council is authorised or required to make.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A26","no":26,"noLabel":{"en":"26."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"heading":{"en":"Endowment Fund"},"text":{"en":"26.—(1) There is established an Endowment Fund which vests in the Council and consists of —\n(a)all donations and gifts accepted by the Council for the Endowment Fund;\n(b)all reserves of the Council in excess of 2 years of its operating expenditure; and\n(c)any other moneys that the Council decides to transfer to the Endowment Fund.\n(2) Any interest, dividends and other income derived from the Endowment Fund do not form part of the Endowment Fund.\n(3) The Endowment Fund may be applied for such purposes as may be approved by the Minister in writing.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A27","no":27,"noLabel":{"en":"27."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"heading":{"en":"Bank accounts"},"text":{"en":"27.—(1) The Council must open and maintain one or more accounts with such bank or banks as the Council thinks fit.\n(2) Every account under subsection (1) may only be operated by a person who is authorised to do so by the Council.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A28","no":28,"noLabel":{"en":"28."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"heading":{"en":"Power of investment"},"text":{"en":"28. The Council may invest its moneys in accordance with the standard investment power of statutory bodies as defined in section 33A of the Interpretation Act 1965.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A29","no":29,"noLabel":{"en":"29."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"heading":{"en":"Grants"},"text":{"en":"29. For the purpose of enabling the Council to carry out its functions, the Minister may make grants to the Council of such sums of money as the Minister may determine out of money to be provided by Parliament.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A30","no":30,"noLabel":{"en":"30."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"heading":{"en":"Power to borrow"},"text":{"en":"30.—(1) The Council cannot raise loans for the performance of its functions except in accordance with this section.\n(2) Subject to subsection (3), the Council may raise loans by —\n(a)mortgage, overdraft or other means, with or without security;\n(b)charge, whether legal or equitable, on any property vested in the Council or on any other revenue receivable by the Council under this Act or any other written law; or\n(c)the creation and issue of debentures or bonds, or such other instrument as the Minister may approve.\n(3) The Council may —\n(a)raise loans under subsection (2) from the Government;\n(b)obtain a credit facility for the purchase of goods or services mentioned in subsection (4) from a bank or financial institution, whether in or outside Singapore; or\n(c)with the approval of the Minister, raise a loan or obtain a credit facility from any other source, whether in or outside Singapore.\n(4) For the purposes of this section, the power to raise loans includes the power to enter into any financial agreement or arrangement under which credit facilities are granted to the Council for the purchase of goods or services.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A31","no":31,"noLabel":{"en":"31."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"heading":{"en":"Issue of shares, etc."},"text":{"en":"31. As a consequence of —\n(a)the vesting of any property, right or liability in the Council under this Act; or\n(b)any capital injection or other investment by the Government in the Council in accordance with any written law,\nthe Council must issue such shares or other securities to the Minister charged with the responsibility for finance as that Minister may direct.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A32","no":32,"noLabel":{"en":"32."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"heading":{"en":"Financial statements"},"text":{"en":"32. The Council must, as soon as practicable but no later than 30 June in each year, prepare and submit financial statements in respect of the preceding financial year to the auditor who must audit and report on them.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A33","no":33,"noLabel":{"en":"33."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"heading":{"en":"When audited financial statements must be given to Minister"},"text":{"en":"33. The Council must send the audited annual financial statements of the Council, signed by the Chairperson, together with a copy of any report made by the auditor of the Council, to the Minister no later than 30 September in each year.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A34","no":34,"noLabel":{"en":"34."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"text":{"en":"34. [Deleted by Act 3 of 2026 wef 01/08/2026]"},"status":"repealed"},{"id":"SG-H3306-A35","no":35,"noLabel":{"en":"35."},"chapter":{"en":"PART 6 FINANCIAL PROVISIONS"},"text":{"en":"35. [Repealed by Act 5 of 2018]"},"status":"repealed"},{"id":"SG-H3306-A36","no":36,"noLabel":{"en":"36."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Protection from personal liability"},"text":{"en":"36.—(1) No liability shall lie against the Chief Executive Officer, any member, employee or delegate of the Council, any member of a committee of the Council appointed under section 14, or any other person acting under the direction of the Council, for anything which is done or purported to be done, or omitted to be done, in good faith and with reasonable care in —\n(a)the performance or purported performance of any function of the Council, or of any other function under this Act; or\n(b)the exercise or purported exercise of any power of the Council, or of any other power under this Act.\n(2) No liability shall lie against the chairperson, the deputy chairperson or any member of the Community Chest for anything which is done or purported to be done, or omitted to be done, in good faith and with reasonable care in —\n(a)the performance or purported performance of any function of the Community Chest, or of any other function under this Act; or\n(b)the exercise or purported exercise of any power of the Community Chest, or of any other power under this Act.\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A37","no":37,"noLabel":{"en":"37."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Regulations"},"text":{"en":"37.—(1) The Council may, with the approval of the Minister, make such regulations as are necessary for carrying into effect the provisions of this Act, except for the matters provided for in section 38.\n[Act 3 of 2026 wef 01/08/2026]\n(2) Without limiting subsection (1), the Council may, with the approval of the Minister, make such regulations for or with respect to all or any of the following matters:\n(a)the procedure for applying for appointment or re-appointment of an organisation as a sector member;\n[Act 3 of 2026 wef 01/08/2026]\n(aa)the procedure for the revocation of the appointment of an organisation as a sector member;\n[Act 3 of 2026 wef 01/08/2026]\n(b)the conditions for being appointed or re-appointed as a sector member;\n[Act 3 of 2026 wef 01/08/2026]\n(ba)the procedure and criteria for nominations by sector members of proposed members of the Council under section 5(3), including limits on the number of nominations that a sector member can make in a given period of time;\n[Act 3 of 2026 wef 01/08/2026]\n(c)the standards and guidelines for the management and administration of, and the provision of social services by, sector members;\n[Act 3 of 2026 wef 01/08/2026]\n(ca)the standards and guidelines for the cooperation of sector members with the Council;\n[Act 3 of 2026 wef 01/08/2026]\n(d)the procedure for inquiry into complaints and information received relating to the conduct of sector members, their officers or employees, and the sanctions to be imposed in respect of any misconduct, including the issuance of letters of censure and the suspension or revocation of appointment as a sector member;\n[Act 3 of 2026 wef 01/08/2026]\n(e)the rates, charges and fees payable for purposes of this Act;\n(f)the procedure for the meetings of the Council;\n[Act 3 of 2026 wef 01/08/2026]\n(g)the procedure and quorum for the meetings of the Community Chest;\n(h)[Deleted by Act 3 of 2026 wef 01/08/2026]\n(i)the establishment, constitution and procedures of any committee mentioned in section 14 and any unincorporated association or organisation mentioned in section 12(2)(n);\n[Act 3 of 2026 wef 01/08/2026]\n(j)the information to be provided and the documents to be submitted to the Council by sector members, including annual reports, audited accounts and such information as the Council may require for carrying out its objects;\n[Act 3 of 2026 wef 01/08/2026]\n(k)to prescribe anything that is required or permitted to be prescribed under this Act.\n[Act 3 of 2026 wef 01/08/2026]\n(3) Regulations made under this section in relation to the procedure for the meetings of the Council must conform to the requirements of the Public Sector (Governance) Act 2018.\n[5/2018]\n[Act 3 of 2026 wef 01/08/2026]"}},{"id":"SG-H3306-A38","no":38,"noLabel":{"en":"38."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Regulations relating to appeal to Minister"},"text":{"en":"38. The Minister may make regulations in respect of the manner in which an appeal under section 16 may be made, and the procedure to be adopted in the hearing of any appeal.\n[Act 3 of 2026 wef 01/08/2026]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Council of Social Service Act 1992","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3307"] = {"id":"SG-H3307","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NEAA2002-S717-2023?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"国家环境局（职能转授）（第 2 号）公告 2023","en":"National Environment Agency (Assignment of Functions) (No. 2) Notification 2023","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NEAA2002-S717-2023","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3307-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the National Environment Agency (Assignment of Functions) (No. 2) Notification 2023 and comes into operation on 8 November 2023."}},{"id":"SG-H3307-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In this Notification —\n“carbon credit” means a certificate representing an amount of greenhouse gas emissions reduction or removal, generated from any project or programme outside Singapore;\n“greenhouse gas” has the meaning given by section 2(1) of the Carbon Pricing Act 2018."}},{"id":"SG-H3307-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Additional functions"},"text":{"en":"3. The Minister for Sustainability and the Environment assigns to the National Environment Agency the following functions in relation to any international agreement to which Singapore is a party, that was entered into pursuant to or for the purposes of implementing Article 6 of the Paris Agreement adopted on 12 December 2015 (called in this Notification the Paris Agreement):\n(a)to assess on behalf of the Government the capability of any carbon credit, or any project or programme generating greenhouse gas emissions reductions or removals, in meeting Singapore’s requirements as specified in such international agreement, insofar as the requirements relate to Article 6 of the Paris Agreement;\n(b)to issue any letter or other document communicating the outcome of the Government’s assessment whether a carbon credit, or a project or programme generating greenhouse gas emissions reductions or removals, meets Singapore’s requirements as specified in such international agreement (whether or not the requirements relate to Article 6 of the Paris Agreement)."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Environment Agency (Assignment of Functions) (No. 2) Notification 2023","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3308"] = {"id":"SG-H3308","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NEAA2002-S507-2023?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"国家环境局（职能转授）公告 2023","en":"National Environment Agency (Assignment of Functions) Notification 2023","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NEAA2002-S507-2023","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3308-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the National Environment Agency (Assignment of Functions) Notification 2023 and comes into operation on 17 July 2023."}},{"id":"SG-H3308-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Additional functions"},"text":{"en":"2.—(1) The Minister for Sustainability and the Environment assigns to the National Environment Agency the functions of constructing, developing, owning and managing, in its own right, or for and on behalf of the Government —\n(a)facilities comprising only funeral parlours;\n(b)facilities comprising only one or more establishments (other than funeral parlours) at which any trade to support funeral wakes or funerals or both (whether wholly or in part) is carried out; or\n(c)facilities comprising both funeral parlours and one or more other establishments at which any trade to support funeral wakes or funerals or both (whether wholly or in part) is carried out.\n(2) In this paragraph, “funeral parlour” has the meaning given by section 2 of the Environmental Public Health Act 1987."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Environment Agency (Assignment of Functions) Notification 2023","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3309"] = {"id":"SG-H3309","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NEAA2002?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":53,"structureMode":"ARTICLE","title":{"zh":"国家环境局法 2002","en":"National Environment Agency Act 2002","orig":null},"level":"law","status":"active","docNumber":"Act NEAA2002","completenessNote":"全文，共 53 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。其中 7 条为官方正文中标注的已废止条文存根（照录）。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3309-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Short title"},"text":{"en":"1. This Act may be cited as the National Environment Agency Act 2002."}},{"id":"SG-H3309-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Interpretation"},"text":{"en":"2. In this Act, unless the context otherwise requires —\n“accreditation, certification or inspection mark” means any accreditation, certification or inspection mark of the Agency specified under section 12(b);\n“Agency” means the National Environment Agency established under section 3;\n“auxiliary officer” means an individual who is appointed as an auxiliary officer under section 16A(1);\n“Chairperson” means the Chairperson of the Agency and includes a temporary Chairperson of the Agency;\n“chief executive” means the chief executive of the Agency, and includes any individual acting in that capacity;\n“Deputy Chairperson” means the Deputy Chairperson of the Agency and includes a temporary Deputy Chairperson of the Agency;\n“environmental written law” means a written law administered by any of the following:\n(a)the Agency;\n(b)the Director-General of Environmental Protection appointed under section 3(1) of the Environmental Protection and Management Act 1999;\n(c)the Director-General of Public Health appointed under section 3(1) of the Environmental Public Health Act 1987;\n“member” means a member of the Agency and includes a temporary member of the Agency.\n[4/2016; 5/2018]"}},{"id":"SG-H3309-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 2 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF AGENCY"},"heading":{"en":"Establishment and incorporation of National Environment Agency"},"text":{"en":"3. A body called the National Environment Agency is established, which is a body corporate with perpetual succession and a common seal and is by that name capable of —\n(a)suing and being sued;\n(b)acquiring, owning, holding and developing, or disposing of property, both movable and immovable; and\n(c)doing and suffering all other acts or things that a body corporate may lawfully do and suffer."}},{"id":"SG-H3309-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 2 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF AGENCY"},"heading":{"en":"Common seal"},"text":{"en":"4.—(1) The Agency must have a common seal that may be broken, changed, altered or made anew as the Agency thinks fit.\n(2) All deeds and other documents requiring the seal of the Agency must be sealed with the common seal of the Agency.\n(3) All instruments to which the common seal is affixed must be signed by —\n(a)any 2 members generally or specially authorised by the Agency for the purpose; or\n(b)one member and the chief executive.\n(4) The Agency may, by resolution or otherwise in writing, appoint any officer of the Agency or any other agent either generally or in any particular case to execute or sign on behalf of the Agency any agreement or other instrument not under seal in relation to any matter coming within the powers of the Agency.\n(5) All courts, judges and persons acting judicially are to take judicial notice of the common seal of the Agency affixed to any document and presume that it was duly affixed."}},{"id":"SG-H3309-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF AGENCY"},"heading":{"en":"Membership of Agency"},"text":{"en":"5.—(1) The Agency consists of —\n(a)a Chairperson;\n(b)a Deputy Chairperson; and\n(c)not less than 5 but not more than 12 other members,\nall of whom must be appointed by the Minister.\n(2) The Minister may appoint the chief executive to be a member."}},{"id":"SG-H3309-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 2 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF AGENCY"},"heading":{"en":"Chairperson may delegate functions"},"text":{"en":"6. The Chairperson may in writing authorise any member to exercise any power or perform any function conferred on the Chairperson by or under this Act."}},{"id":"SG-H3309-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 2 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF AGENCY"},"heading":{"en":"Term of office of members"},"text":{"en":"7.—(1) A member holds office on such conditions and for such term, not exceeding 3 years, as the Minister specifies in the member’s appointment.\n(2) Any member may at any time by written notice to the Minister resign from his or her office.\n(3) The Minister may at any time revoke the appointment of any member without giving any reason.\n(4) If a member dies or resigns or has his or her appointment revoked, the Minister may appoint any person to fill the vacancy for the remainder of the term for which the vacating member was appointed.\n(5) The Agency must pay to the Chairperson, the Deputy Chairperson and other members such salaries, fees and allowances as the Minister may determine."}},{"id":"SG-H3309-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 2 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF AGENCY"},"heading":{"en":"Temporary Chairperson, etc."},"text":{"en":"8. The Minister may appoint any person to be a temporary Chairperson, temporary Deputy Chairperson or temporary member during the temporary incapacity from illness or otherwise, or during the temporary absence from Singapore, of the Chairperson, Deputy Chairperson or any member, as the case may be."}},{"id":"SG-H3309-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 2 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF AGENCY"},"heading":{"en":"Meetings and proceedings of Agency"},"text":{"en":"9.—(1) The quorum at every meeting of the Agency is the higher of the following:\n(a)one‑third of the total number of members in office;\n(b)4 members.\n[2/2012]\n(2) The Chairperson or, in his or her absence, the Deputy Chairperson presides at all meetings of the Agency and, in the absence of the Chairperson and the Deputy Chairperson, the members present must elect one of their number to preside.\n(3) Meetings of the Agency must be held at such times and places as the Chairperson may determine.\n(4) All questions arising at any meeting must be decided by a majority of votes of the members present and voting.\n(5) At any meeting of the Agency, the Chairperson or, in his or her absence, the Deputy Chairperson has a deliberative vote and, in the case of an equality of votes, he or she also has a casting vote.\n(6) The validity of any proceedings of the Agency is not affected by any vacancy amongst its members or by any defect in the appointment of any member.\n(7) Subject to the provisions of this Act and the Public Sector (Governance) Act 2018, the Agency may regulate its own proceedings.\n[5/2018]"}},{"id":"SG-H3309-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 2 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF AGENCY"},"text":{"en":"10. [Repealed by Act 5 of 2018]"},"status":"repealed"},{"id":"SG-H3309-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 3 FUNCTIONS, DUTIES AND POWERS OF AGENCY"},"heading":{"en":"Functions and duties of Agency"},"text":{"en":"11.—(1) Subject to the provisions of this Act, the functions and duties of the Agency are as follows:\n(a)to identify, undertake research into, and conduct investigations and surveillance of environmental health concerns and vectors of infectious agents, and to develop strategies of prevention and control in connection with such matters;\n(b)to undertake licensing, provision of consultancy services, and promotion of professionalism in relation to pest control, environmental and other related industries;\n(c)to coordinate the implementation and management of upgrading programmes for hawker centres and the review of hawker policies;\n(d)to ensure cleanliness of public areas through the supervision of cleansing services and the prevention of littering;\n(e)to ensure adequate provision of cremation, columbaria and burial services and facilities;\n(f)to manage and regulate air emissions from industrial premises, trade premises and vehicles;\n(g)to monitor and assess the water quality of inland and coastal waters, and to manage and regulate the discharge of trade effluent, oil, chemicals, sewage and any other polluting matter into water courses or on land;\n(h)to construct, develop, manage and regulate refuse treatment and disposal facilities and to regulate refuse collection and disposal;\n(i)to control land contamination and regulate the remediation of contaminated land;\n(j)to regulate the fumigation of premises and articles with hydrogen cyanide or any other fumigant;\n(k)to regulate the import, export, possession, storage, transportation, sale and use of hazardous substances and the import, export, storage, transportation, collection, treatment and disposal of toxic industrial waste;\n(l)to manage and regulate environmental noise, and to monitor and assess ambient air and noise levels;\n(m)to promote energy efficiency, the use of clean energy, the use of clean technologies, the use of efficient pollution control technologies and waste recycling;\n(n)to manage on behalf of the Government any land, building or other property of the Government used in connection with waste recycling;\n(o)to embark on educational programmes to promote and encourage public awareness of and participation in environmental matters;\n(p)to provide advice on environmental pollution threats and disasters, and to develop and review standards and policies on environmental protection and environmental health;\n(q)to provide meteorological services for users, including government agencies, aviation and shipping communities and the general public;\n(r)to conduct meteorological observations, maintain reliable climatological records of Singapore and provide advice on meteorological matters;\n(s)to monitor and maintain records of seismological activities affecting Singapore;\n(t)to advise and make recommendations to the Government on matters, measures and regulations related to or connected with the environment, radiation, meteorology and seismology;\n(u)to represent the Government internationally on matters related to or connected with the environment, radiation, meteorology and seismology;\n(v)to control and regulate the import, export, possession, storage, transportation, sale and use of radioactive materials and irradiating apparatus;\n(w)to carry out any other functions imposed upon the Agency by or under this Act or any other written law.\n[27/2007; 11/2019]\n(2) The Agency may undertake any other functions that the Minister may assign to the Agency and in so doing, the Agency is deemed to be fulfilling the purposes of this Act and the provisions of this Act apply to the Agency in respect of those functions.\n(3) Nothing in this section is to be construed as imposing on the Agency, directly or indirectly, any form of duty or liability enforceable by proceedings before any court to which it would not otherwise be subject."}},{"id":"SG-H3309-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 3 FUNCTIONS, DUTIES AND POWERS OF AGENCY"},"heading":{"en":"Powers of Agency"},"text":{"en":"12. The Agency has power to do anything for the purpose of discharging its functions under this Act, or which is incidental or conducive to the discharge of those functions and, in particular, may —\n(a)prescribe and implement regulatory policies, strategies, measures, standards or any other requirements on any matter related to or connected with environmental health, environmental protection, radiation control, resource conservation, waste minimisation, waste recycling, waste collection and disposal and any other subject matter that may be necessary for the performance of the functions of the Agency;\n(b)specify, by notification in the Gazette, all the accreditation, certification or inspection marks of the Agency for use in relation to any function of the Agency, and control the use of those marks;\n(c)regulate, accredit or certify any person to carry out any test, study, activity or service related to or connected with environmental pollution control, radiation control, resource conservation, waste minimisation, waste recycling and waste collection and disposal;\n(d)request information from and collaborate or cooperate with any person, whether in Singapore or elsewhere, on matters related to or connected with weather, climate, environmental health, environmental protection, radiation control, resource conservation, waste minimisation, waste recycling, waste collection and disposal and any other subject matter that may be necessary for the performance of the functions of the Agency;\n(e)collect, analyse, compile, publish or disseminate information of a statistical nature related to or connected with weather, climate, environmental health, environmental protection, radiation control, resource conservation, waste minimisation, waste recycling, waste collection and disposal and any other subject matter that may be necessary for the performance of the functions of the Agency;\n(f)prescribe training requirements for matters related to or connected with environmental health, environmental protection, radiation control, resource conservation, waste minimisation, waste recycling and waste collection and disposal, and provide training, conduct tests or award certificates of proficiency;\n(g)establish meteorological offices and observation stations, arrange with any agency, authority or person to take and record meteorological observations and transmit meteorological reports and information;\n(h)with the Minister’s approval, form or participate in the formation of any company, partnership or joint venture as a shareholder or partner or in any other capacity;\n(i)enter into such contracts as may be necessary or expedient for the purpose of discharging its functions or duties;\n(j)become a member or an affiliate of any international body the functions or duties of which are similar to those of the Agency;\n(k)receive grants, donations or contributions from any source, or raise funds by all lawful means and apply those funds for any of its functions or duties;\n(l)charge fees for the issuance of any licence or approval, and fees, charges or commissions for services rendered by the Agency or for the use of any facilities of the Agency; and\n(m)do anything incidental or necessary to any of its functions or powers.\n[27/2007]"}},{"id":"SG-H3309-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 3 FUNCTIONS, DUTIES AND POWERS OF AGENCY"},"heading":{"en":"Directions by Minister"},"text":{"en":"13. The Minister may give to the Agency any direction under section 5 of the Public Sector (Governance) Act 2018.\n[5/2018]"}},{"id":"SG-H3309-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 3 FUNCTIONS, DUTIES AND POWERS OF AGENCY"},"heading":{"en":"Committees"},"text":{"en":"14.—(1) The Agency may appoint, alter or discharge committees, consisting of one or more persons (whether members or not), and define or vary the terms of reference of those committees.\n(2) Subject to the provisions of this Act and the Public Sector (Governance) Act 2018 and to the control of the Agency, each committee appointed under this section may regulate its procedure in such manner as the committee thinks fit.\n[5/2018]"}},{"id":"SG-H3309-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 3 FUNCTIONS, DUTIES AND POWERS OF AGENCY"},"heading":{"en":"Delegation of powers"},"text":{"en":"15.—(1) The Agency may in respect of a specified matter or class of matters, by writing, delegate to any member, officer or committee of the Agency any of its powers under this Act or under any other written law.\n[5/2018]\n(2) Every member, officer or committee purporting to act pursuant to a delegation under this section is, in the absence of proof to the contrary, presumed to be acting in accordance with the terms of the delegation."}},{"id":"SG-H3309-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 4 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Chief executive, officers and employees, etc."},"text":{"en":"16.—(1) There must be a chief executive of the Agency, whose appointment, removal, discipline and promotion must be in accordance with the Public Sector (Governance) Act 2018.\n[5/2018]\n(2) The Agency may, subject to the Public Sector (Governance) Act 2018, appoint an individual to act temporarily as the chief executive during any period, or during all periods, when the chief executive —\n(a)is absent from duty or Singapore; or\n(b)is, for any reason, unable to perform the duties of the office.\n[5/2018]\n(3) The Agency may, subject to the Public Sector (Governance) Act 2018, appoint and employ, on such terms and conditions as it may determine, such other officers, employees, consultants and agents as may be necessary for the effective performance of its functions.\n[5/2018]"}},{"id":"SG-H3309-A16.001","no":16.001,"noLabel":{"en":"16A."},"chapter":{"en":"PART 4 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Appointment of auxiliary officers"},"text":{"en":"16A.—(1) The Agency may in writing appoint an individual (who may or may not be a public officer) to be an auxiliary officer to assist the officers and employees of the Agency in the performance of any function of the Agency.\n[4/2016]\n(2) The Agency may, for any reason that appears to the Agency to be sufficient, at any time revoke an individual’s appointment as an auxiliary officer.\n[4/2016]\n(3) An auxiliary officer is to be issued with such equipment, or such description of equipment, as the chief executive may determine necessary for the effectual discharge of the duties of an auxiliary officer.\n[4/2016]\n(4) An auxiliary officer is not an officer or employee of the Agency.\n[4/2016]\n(5) An individual who is appointed as an auxiliary officer under subsection (1) does not, by virtue only of the appointment, become an agent of the Agency.\n[4/2016]"}},{"id":"SG-H3309-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 4 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Protection from personal liability"},"text":{"en":"17.—(1) No suit or other legal proceedings shall lie personally against any member, officer or employee of the Agency or other person acting under the direction of the Agency for anything which is in good faith done or intended to be done in the execution or purported execution of this Act or any other written law.\n(2) A claim against the Agency or Government does not arise solely on the ground that —\n(a)a product or process conforms to or is alleged to conform to a standard accepted by the Agency; or\n(b)a certificate, brand, marking or any other thing is issued for use or is used by the Agency in connection with, in respect of or in relation to, a product or process.\n(3) Where the Agency provides a service to the public by which information is supplied to the public, neither the Agency nor any of its employees involved in the supply of that information is liable for any loss or damage suffered by any member of the public by reason of any error or omission of whatever nature appearing therein or however caused if made in good faith and in the ordinary course of the discharge of the duties of such employees."}},{"id":"SG-H3309-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 4 PROVISIONS RELATING TO STAFF"},"text":{"en":"18. [Repealed by Act 5 of 2018]"},"status":"repealed"},{"id":"SG-H3309-A19","no":19,"noLabel":{"en":"19."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Financial year"},"text":{"en":"19. The financial year of the Agency begins on 1 April of each year and ends on 31 March of the succeeding year."}},{"id":"SG-H3309-A20","no":20,"noLabel":{"en":"20."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Estimates"},"text":{"en":"20.—(1) A copy of all annual estimates of revenue and expenditure and supplementary estimates must, upon their adoption by the Agency, be sent without delay to the Minister.\n[5/2018]\n(2) The Minister may approve or disallow any item or portion of any item shown in the annual estimates or supplementary estimates.\n[5/2018]\n(3) The Minister must return the annual estimates or supplementary estimates as amended under subsection (2) to the Agency, and the Agency is bound by the Minister’s decision.\n[5/2018]\n(4) Despite any provision of this section, the Agency may transfer all or any part of moneys assigned to one item of expenditure to any item under the same head of expenditure in any estimates approved by the Minister."}},{"id":"SG-H3309-A21","no":21,"noLabel":{"en":"21."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"All moneys recovered to be paid to Agency"},"text":{"en":"21. All moneys recovered or charges collected under this Act must be paid into and form part of the moneys of the Agency.\n[11/2019]"}},{"id":"SG-H3309-A22","no":22,"noLabel":{"en":"22."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Grants"},"text":{"en":"22. For the purpose of enabling the Agency to carry out its functions under this Act, the Minister may make grants to the Agency of such sums of money as the Minister may determine out of moneys to be provided by Parliament."}},{"id":"SG-H3309-A23","no":23,"noLabel":{"en":"23."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Borrowing power"},"text":{"en":"23.—(1) The Agency cannot raise loans for the performance of its functions under this Act or any other Act administered by the Agency except in accordance with this section.\n[7/2020]\n(2) Subject to subsection (3), the Agency may raise loans by —\n(a)mortgage, overdraft or other means, with or without security;\n(b)charge, whether legal or equitable, on any property vested in the Agency or on any other revenue receivable by the Agency under this Act or any other written law; or\n(c)the creation and issue of debentures, bonds or any other instrument as the Minister for Finance may approve.\n[7/2020]\n(3) The Agency may raise loans —\n(a)from the Government; or\n(b)with the approval of the Minister for Finance, from another source, whether within or outside Singapore.\n[7/2020]\n(4) For the purposes of this section, the power to raise loans includes the power to make any financial agreement under which credit facilities are granted to the Agency for the purchase of goods, materials or things.\n[7/2020]"}},{"id":"SG-H3309-A24","no":24,"noLabel":{"en":"24."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Issue of shares, etc."},"text":{"en":"24. As a consequence of the vesting of any property, rights or liabilities of the Government in the Agency under this Act, or of any capital injection or other investment by the Government in the Agency in accordance with any written law, the Agency must issue such shares or other securities to the Minister for Finance as that Minister may direct."}},{"id":"SG-H3309-A25","no":25,"noLabel":{"en":"25."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Bank accounts"},"text":{"en":"25.—(1) The Agency must open and maintain an account with such bank or banks as the Agency thinks fit.\n(2) Every such account must be operated by such person authorised to do so by the Agency."}},{"id":"SG-H3309-A26","no":26,"noLabel":{"en":"26."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Application of moneys"},"text":{"en":"26. The moneys of the Agency must be applied only in payment or discharge of the expenses, obligations and liabilities of the Agency and in making any payment that the Agency is authorised or required to make."}},{"id":"SG-H3309-A27","no":27,"noLabel":{"en":"27."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Power of investment"},"text":{"en":"27. The Agency may invest its moneys in accordance with the standard investment power of statutory bodies as defined in section 33A of the Interpretation Act 1965.\n[45/2004]"}},{"id":"SG-H3309-A28","no":28,"noLabel":{"en":"28."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"text":{"en":"28. [Repealed by Act 5 of 2018]"},"status":"repealed"},{"id":"SG-H3309-A29","no":29,"noLabel":{"en":"29."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"text":{"en":"29. [Repealed by Act 5 of 2018]"},"status":"repealed"},{"id":"SG-H3309-A30","no":30,"noLabel":{"en":"30."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"text":{"en":"30. [Repealed by Act 5 of 2018]"},"status":"repealed"},{"id":"SG-H3309-A31","no":31,"noLabel":{"en":"31."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"text":{"en":"31. [Repealed by Act 5 of 2018]"},"status":"repealed"},{"id":"SG-H3309-A32","no":32,"noLabel":{"en":"32."},"chapter":{"en":"PART 6 TRANSFER OF PROPERTY, ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Transfer to Agency of property, assets and liabilities"},"text":{"en":"32.—(1) As from 1 July 2002, such movable and immovable property vested in the Government as may be determined by the Minister for Finance and used or managed by any of the departments specified in the Schedule and all assets, interests, rights, privileges, liabilities and obligations of the Government relating to any such department are transferred to and vest in the Agency without further assurance, act or deed.\n(2) If any question arises as to whether any particular property, or whether any particular asset, interest, right, privilege, liability or obligation has been transferred to or vested in the Agency under subsection (1), a certificate under the hand of the Minister for Finance is conclusive evidence that the property, asset, interest, right, privilege, liability or obligation was or was not so transferred or vested.\n(3) Any immovable property to be transferred to and vested in the Agency under subsection (1) is held by the Agency upon such tenure and subject to such terms and conditions as the President may determine.\n(4) All proceedings in respect of the transferred properties by or against the Government which are pending on 1 July 2002 may be continued, completed and enforced by or against the Agency.\n(5) Every agreement relating to any of the transferred properties to which the Government was a party immediately before 1 July 2002, whether or not of such nature that the rights and liabilities thereunder could be assigned, has effect as from that date as if —\n(a)the Agency had been a party to such an agreement; and\n(b)for any reference to the Government there was substituted in respect of anything to be done on or after 1 July 2002 a reference to the Agency."}},{"id":"SG-H3309-A33","no":33,"noLabel":{"en":"33."},"chapter":{"en":"PART 6 TRANSFER OF PROPERTY, ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Transfer of employees"},"text":{"en":"33.—(1) As from 1 July 2002, such persons or categories of persons as the Minister may determine who, immediately before that date, were employed by the Government and posted to any of the departments specified in the Schedule are transferred to the service of the Agency on terms no less favourable than those enjoyed by them immediately prior to their transfer.\n(2) If any question arises as to whether any person or category of persons has been transferred to the service of the Agency under subsection (1), a certificate under the hand of the Minister is conclusive evidence that the person or category of persons was or was not so transferred.\n(3) Until such time as terms and conditions of service are drawn up by the Agency, the scheme and terms and conditions of the Government continue to apply to every person transferred to the service of the Agency under subsection (1) as if the person were still in the employment of the Government."}},{"id":"SG-H3309-A34","no":34,"noLabel":{"en":"34."},"chapter":{"en":"PART 6 TRANSFER OF PROPERTY, ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Pension rights, etc., of Government employees to be preserved"},"text":{"en":"34.—(1) The terms and conditions to be drawn up by the Agency must take into account the terms and conditions of service (including salaries and accrued rights to leave) enjoyed by the persons transferred to the service of the Agency under section 33 while in the employment of the Government.\n(2) Any term or condition relating to the length of service with the Agency must recognise the length of service of the persons so transferred while in the employment of the Government to be service with the Agency.\n(3) Nothing in the terms and conditions to be drawn up by the Agency adversely affects the conditions that would have been applicable to persons transferred to the service of the Agency as regards any pension, gratuity or allowance payable under the Pensions Act 1956.\n(4) Where a person has been transferred to the service of the Agency under section 33, the Government is liable to pay to the Agency such portion of any pension, gratuity or allowance payable to the person on his retirement as the same bears to the proportion which the aggregate amount of the person’s pensionable emoluments during his or her service with the Government bears to the aggregate amount of his or her pensionable emoluments during his or her service under both the Government and the Agency.\n(5) Where any person in the service of the Agency, whose case does not fall within the scope of any pension or other schemes established under this section, retires or dies in the service of the Agency or is discharged from such service, the Agency may grant to him or her or to such other person wholly or partly dependent on him or her, as the Agency thinks fit, such allowance or gratuity as the Agency may determine."}},{"id":"SG-H3309-A35","no":35,"noLabel":{"en":"35."},"chapter":{"en":"PART 6 TRANSFER OF PROPERTY, ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"No benefits in respect of abolition or reorganisation of office"},"text":{"en":"35. Despite the provisions of the Pensions Act 1956, no person who is transferred to the service of the Agency under section 33 is entitled to claim any benefit under that Act on the ground that the person has been retired from the service of the Government on account of abolition or reorganisation of office in consequence of the establishment and incorporation of the Agency."}},{"id":"SG-H3309-A36","no":36,"noLabel":{"en":"36."},"chapter":{"en":"PART 6 TRANSFER OF PROPERTY, ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Existing contracts"},"text":{"en":"36. All deeds, contracts, schemes, bonds, agreements, instruments and arrangements, subsisting immediately before 1 July 2002 to which the Government is a party and relating to any of the departments specified in the Schedule or to any person transferred to the service of the Agency under section 33 continue in force on and after that date and are enforceable by or against the Agency as if the Agency had been named therein or had been a party thereto instead of the Government."}},{"id":"SG-H3309-A37","no":37,"noLabel":{"en":"37."},"chapter":{"en":"PART 6 TRANSFER OF PROPERTY, ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Continuation and completion of disciplinary proceedings and other legal proceedings"},"text":{"en":"37.—(1) Where, on 1 July 2002, any disciplinary proceedings were pending against any employee of the Government transferred to the service of the Agency, the proceedings must be carried on and completed by the Agency.\n(2) Where, on 1 July 2002, any matter was in the course of being heard or investigated or had been heard or investigated by a committee acting under due authority but no order, ruling or direction had been made thereon, the committee must complete the hearing or investigation and make such order, ruling or direction as it could have made under the authority vested in it before that date.\n(3) Any order, ruling or direction made by a committee under this section is treated as an order, a ruling or a direction of the Agency and has the same force or effect as if it had been made by the Agency pursuant to the authority vested in the Agency under this Act.\n(4) All proceedings or causes of action pending or existing immediately before 1 July 2002 by or against the Government in respect of any of the departments specified in the Schedule may be continued, completed and enforced by or against the Agency."}},{"id":"SG-H3309-A38","no":38,"noLabel":{"en":"38."},"chapter":{"en":"PART 6 TRANSFER OF PROPERTY, ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Misconduct or neglect of duty by employee before transfer"},"text":{"en":"38. The Agency may reprimand, reduce in rank, retire, dismiss or punish in some other manner any person who had, while in the employment of the Government, been guilty of any misconduct or neglect of duty which would have rendered him or her liable to be reprimanded, reduced in rank, retired, dismissed or punished in some other manner if he or she had continued to be in the employment of the Government and if this Act had not been enacted."}},{"id":"SG-H3309-A38.001","no":38.001,"noLabel":{"en":"38A."},"chapter":{"en":"PART 6 TRANSFER OF PROPERTY, ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Transfer to Agency of property, employees, existing contracts, etc., from Health Sciences Authority relating to Centre for Radiation Protection"},"text":{"en":"38A.—(1) As from 1 July 2007, such movable and immovable property vested in the Health Sciences Authority as may be determined by the Minister for Finance and used or managed by the Centre for Radiation Protection and all assets, interests, rights, privileges, liabilities and obligations of the Health Sciences Authority relating to the Centre for Radiation Protection are transferred to and vest in the Agency without further assurance, act or deed.\n[27/2007]\n(2) As from 1 July 2007, all persons employed immediately before that date by the Health Sciences Authority and posted to the Centre for Radiation Protection are transferred to the service of the Agency on terms no less favourable than those enjoyed by them immediately prior to their transfer.\n[27/2007]\n(3) All deeds, contracts, schemes, bonds, agreements, instruments and arrangements subsisting immediately before 1 July 2007 to which the Health Sciences Authority is a party and relating to the Centre for Radiation Protection or to any person transferred to the service of the Agency under subsection (2) continue in force on and after that date and are enforceable by or against the Agency as if the Agency had been named therein or had been a party thereto instead of the Health Sciences Authority.\n[27/2007]\n(4) Section 32(2) to (5) applies, with the necessary modifications, to the transfer of property, assets, interests, rights, privileges, liabilities and obligations mentioned in subsection (1).\n[27/2007]\n(5) Sections 33(2), 34, 35, 37 and 38 apply, with the necessary modifications, to the transfer of persons mentioned in subsection (2).\n[27/2007]"}},{"id":"SG-H3309-A39","no":39,"noLabel":{"en":"39."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"text":{"en":"39. [Repealed by Act 5 of 2018]"},"status":"repealed"},{"id":"SG-H3309-A40","no":40,"noLabel":{"en":"40."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Symbol or representation of Agency"},"text":{"en":"40.—(1) The Agency has the exclusive right to the use of such symbol or representation as it may select or devise and thereafter display or exhibit that symbol or representation in connection with its activities or affairs.\n(2) Any person who uses a symbol or representation identical with that of the Agency, or which so resembles the Agency’s symbol or representation as to deceive or cause confusion, or to be likely to deceive or to cause confusion, shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3309-A41","no":41,"noLabel":{"en":"41."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Power to enter land to set up meteorological observation station"},"text":{"en":"41.—(1) Where, in any emergency, the chief executive is of the opinion that the public health or the safety of the public may be adversely affected, the chief executive may direct any officer or employee of the Agency to enter upon any land, after giving reasonable notice, to set up a meteorological observation station and to operate the station in such manner as may be reasonably necessary.\n(2) The Agency must pay compensation to the owner of the land for any permanent damage caused to the land in the exercise of the powers conferred by subsection (1).\n(3) If any dispute arises as to the amount of compensation payable to the owner of such land, the dispute may be summarily determined by a District Court or a Magistrate’s Court.\n(4) Except as provided in subsection (2), no action may be brought against the Agency for any compensation in respect of any damage caused arising out of the exercise of the powers conferred by subsection (1)."}},{"id":"SG-H3309-A42","no":42,"noLabel":{"en":"42."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Powers of enforcement, etc."},"text":{"en":"42.—(1) In addition to the powers conferred on an officer or employee of the Agency by this Act or any environmental written law, the officer or employee may —\n(a)on declaration of the officer’s or employee’s office, and production of such identification card as the chief executive may direct to be carried by an officer or employee of the Agency —\n(i)require any person whom the officer or employee reasonably believes to have committed any offence under this Act or that environmental written law to provide evidence of that person’s identity;\n(ii)for the purposes of this Act or that environmental written law —\n(A)require any person to provide any information or produce any book, document or copy of a book or document in the possession of that person; and\n(B)without fee or reward inspect, copy or make extracts from that book, document or copy; and\n(iii)when conducting any investigation under this Act or that environmental written law, require, by order in writing, the attendance before the officer or employee of any person within the limits of Singapore who, from any information given or otherwise obtained by the officer or employee, appears to be acquainted with the circumstances of the case; and\n(b)photograph or otherwise record the scene of any offence under this Act or that environmental written law, and any thing or individual in the scene.\n[4/2016]\n(2) Any person who —\n(a)refuses to give access to, or assaults, obstructs, hinders or delays, an officer or employee of the Agency in the discharge of the duties by such officer or employee under this Act or any environmental written law;\n(b)wilfully misstates or without lawful excuse refuses to give any information or produce any book, document or copy thereof required of him or her by an officer or employee of the Agency under subsection (1)(a); or\n(c)fails to comply with a lawful demand of an officer or employee of the Agency in the discharge of the duties by such officer or employee under this Act or any environmental written law,\nshall be guilty of an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 6 months or to both.\n[4/2016]\n(3) In this section —\n“photograph” includes making a digital image or a moving visual record;\n“scene”, in relation to an offence under this Act or any environmental written law, means —\n(a)any place or vehicle where the offence was committed, is reasonably suspected to have been committed, or is about to be committed; or\n(b)any place or vehicle associated with, or relevant to, the commission or suspected commission of the offence.\n[4/2016]"}},{"id":"SG-H3309-A42.001","no":42.001,"noLabel":{"en":"42A."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Authorisation of auxiliary officers to exercise powers of enforcement"},"text":{"en":"42A.—(1) The chief executive must, in writing, issue to each auxiliary officer an authorisation specifying the powers mentioned in subsection (3) that the auxiliary officer may exercise, and no other powers.\n[4/2016]\n(2) The powers that an auxiliary officer may be authorised under this section to exercise may be exercised only to the extent authorised by the chief executive under this section and directed by an officer or employee of the Agency.\n[4/2016]\n(3) An auxiliary officer may be authorised under this section to exercise all or any of the powers conferred on an officer or employee of the Agency by this Act or any environmental written law, in relation to any offence under this Act or that environmental written law.\n[4/2016]\n(4) The authorisation of the chief executive under subsection (1) issued to an auxiliary officer may also do all or any of the following:\n(a)limit the powers in subsection (3) that the auxiliary officer may exercise;\n(b)limit when, and where in Singapore, the auxiliary officer may exercise those powers or any of them;\n(c)limit the circumstances in which the auxiliary officer may exercise those powers or any of them.\n[4/2016]\n(5) An auxiliary officer who is authorised under subsection (1) to exercise any power in subsection (3) —\n(a)must obey all lawful directions (general or specific) of the chief executive and an officer or employee of the Agency when exercising that power; and\n(b)is deemed to be a public servant for the purposes of the Penal Code 1871 when exercising that power.\n[4/2016]\n(6) Without affecting subsection (5), where any law or written law protects an officer or employee of the Agency from liability for the officer’s or employee’s acts or omissions, that law or written law is taken to operate as if those acts or omissions included an auxiliary officer’s acts or omissions when acting in the course of the auxiliary officer’s duty as an auxiliary officer in accordance with —\n(a)the written authorisation of the chief executive under subsection (1); and\n(b)the lawful directions (general or specific) of the chief executive and an officer or employee of the Agency.\n[4/2016]\n(7) To avoid doubt, an auxiliary officer does not cease to be acting on the direction of an officer or employee of the Agency by reason only that the officer or employee is not present at all times.\n[4/2016]"}},{"id":"SG-H3309-A43","no":43,"noLabel":{"en":"43."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Corporate offenders and unincorporated associations"},"text":{"en":"43.—(1) Where an offence under this Act committed by a body corporate is proved —\n(a)to have been committed with the consent or connivance of an officer of the body corporate; or\n(b)to be attributable to any neglect on the part of an officer of the body corporate,\nthe officer as well as the body corporate shall be guilty of that offence and shall be liable to be proceeded against and punished accordingly.\n(2) Where the affairs of the body corporate are managed by its members, subsection (1) applies in relation to the acts and defaults of a member in connection with his or her functions of management as if he or she were a director of the body corporate.\n(3) Where an offence under this Act committed by a partnership is proved —\n(a)to have been committed with the consent or connivance of a partner; or\n(b)to be attributable to any neglect on the part of a partner,\nthe partner as well as the partnership shall be guilty of that offence and shall be liable to be proceeded against and punished accordingly.\n(4) Where an offence under this Act committed by an unincorporated association (other than a partnership) is proved —\n(a)to have been committed with the consent or connivance of an officer of the association or a member of its governing body; or\n(b)to be attributable to any neglect on the part of such an officer or member,\nthe officer or member as well as the association shall be guilty of that offence and shall be liable to be proceeded against and punished accordingly.\n(5) In this section —\n“officer” —\n(a)in relation to a body corporate, means a director, member of the committee of management, chief executive, manager, secretary or other similar officer of the body or person purporting to act in any such capacity; or\n(b)in relation to an unincorporated association (other than a partnership), means the president, the secretary and members of the committee of the association and includes persons holding positions analogous to those of president, secretary or member of a committee;\n“partner” includes a person purporting to act as a partner."}},{"id":"SG-H3309-A44","no":44,"noLabel":{"en":"44."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Jurisdiction of court"},"text":{"en":"44. Despite any provision to the contrary in the Criminal Procedure Code 2010, a District Court and a Magistrate’s Court have jurisdiction to try any offence under this Act and have power to impose the full penalty or punishment in respect of the offence."}},{"id":"SG-H3309-A45","no":45,"noLabel":{"en":"45."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Evidence"},"text":{"en":"45.—(1) Subject to subsection (3), a document or certificate purporting to be a report under the hand of the chief executive or any officer authorised by the chief executive upon any matter or thing in connection with the administration or enforcement of this Act or with an investigation carried out under this Act is admissible as evidence in any proceedings under this Act and is prima facie evidence of the facts stated therein.\n(2) For the purposes of this section, a document purporting to be a certificate mentioned in subsection (1) on its production by the prosecution is, until the contrary is proved, deemed to be such a certificate.\n(3) A certificate mentioned in subsection (1) shall not be received in evidence under that subsection unless the person charged has been given —\n(a)a copy of the certificate; and\n(b)notice of the intention of the prosecution to produce the certificate as evidence in the proceedings,\nat least 10 clear days before the commencement of the proceedings.\n(4) Where a certificate of the chief executive or any officer authorised by him or her is admitted in evidence under subsection (1), the person charged may require the chief executive or such officer to be called as a witness for the prosecution and be cross-examined as if he or she had given evidence of the matters stated in the certificate."}},{"id":"SG-H3309-A46","no":46,"noLabel":{"en":"46."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Composition of offences"},"text":{"en":"46.—(1) The chief executive or any officer authorised by him or her may compound any offence under this Act which is prescribed as a compoundable offence by collecting from a person reasonably suspected of having committed the offence a sum of money not exceeding $1,000.\n(2) On payment of the sum of money, no further proceedings are to be taken against such person in respect of the offence.\n(3) The Agency may, with the approval of the Minister, make regulations to prescribe the offences which may be compounded and the method and procedure by which those offences may be compounded under this section.\n(4) All composition sums collected under this section must be paid into the Consolidated Fund.\n[11/2019]"}},{"id":"SG-H3309-A47","no":47,"noLabel":{"en":"47."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Preservation of secrecy"},"text":{"en":"47.—(1) Except for the purpose of the performance of his or her duties or the exercise of his or her functions or when lawfully required to do so by any court or where required or allowed by the provisions of any written law, a person who is or has been —\n(a)a member, an officer, an employee, an auxiliary officer or an agent of the Agency; or\n(b)a member of a committee of the Agency,\nmust not disclose any information relating to the affairs of the Agency or of any other person which has been obtained by him or her in the performance of his or her duties or the exercise of his or her functions.\n[4/2016; 5/2018]\n(2) Any person who contravenes subsection (1) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $2,000 or to imprisonment for a term not exceeding 12 months or to both."}},{"id":"SG-H3309-A48","no":48,"noLabel":{"en":"48."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"Regulations"},"text":{"en":"48.—(1) The Agency may, with the approval of the Minister, make regulations for all or any of the following purposes:\n(a)regulating the proceedings of the Agency or of the committees of the Agency;\n(b)prescribing the form and duration of certificates and accreditation, certification and inspection marks for use in relation to any function of the Agency, the terms and conditions upon which and the circumstances in which —\n(i)the certificates may be granted, suspended or cancelled; or\n(ii)the accreditation, certification and inspection marks may be affixed, used or removed,\nand the fees payable in respect thereof;\n(c)prescribing any matter which is necessary or convenient to be prescribed for carrying out or giving effect to the provisions of this Act.\n(2) The regulations may provide that a contravention thereof shall be punishable with a fine not exceeding $10,000 or with imprisonment for a term not exceeding 12 months or with both and, in the case of a continuing offence, with a further fine not exceeding $1,000 for every day or part of a day during which the offence continues after conviction."}},{"id":"SG-H3309-A49","no":49,"noLabel":{"en":"49."},"chapter":{"en":"PART 7 MISCELLANEOUS"},"heading":{"en":"References in other written laws and documents"},"text":{"en":"49. Insofar as is necessary for preserving the effect of any written law or document on or after 1 July 2002 —\n(a)a reference therein to the Commissioner of Public Health is to be read as a reference to the Director‑General of Public Health appointed under the Environmental Public Health Act 1987;\n(b)a reference therein to the Director of Environmental Pollution Control is to be read as a reference to the Director‑General of Environmental Protection; and\n(c)a reference therein to the Director of Meteorological Service is to be read as a reference to the Director‑General of Meteorological Service."}},{"id":"SG-H3309-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nSections 32(1), 33(1), 36 and 37(4)\nDepartments\nDepartment\nMinistry\n1.Departments within —\nMinistry of the Environment\n(a)Environmental Public Health Division\n(b)Environmental Policy and Management Division\n2.Meteorological Service Department\nMinistry of Transport."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Environment Agency Act 2002","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3310"] = {"id":"SG-H3310","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NHBA1993-RG1?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"国家文物局（缩微与复制费用）条例","en":"National Heritage Board (Micrographic and Reprographic Fees) Regulations","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NHBA1993-RG1","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3310-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. These Regulations may be cited as the National Heritage Board (Micrographic and Reprographic Fees) Regulations."}},{"id":"SG-H3310-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Fees"},"text":{"en":"2.—(1) There shall be paid to the Board in respect of the matters set out in the first column of the Schedule the fees set out in the second column thereof.\n(2) The Board may in its discretion exempt from payment, in whole or in part, any fee under these Regulations."}},{"id":"SG-H3310-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nRegulation 2\nFirst column\nSecond Column\n1. Negative microfilm\n$3.20 per exposure for production of photoprint only.\n2. Duplicate diazo microfilm —\n(a) not exceeding 15 metres\n$6 per metre or part thereof.\n(b) exceeding 15 metres\n$100 per roll of not more than 30 metres.\n3. Diazo microfiche\n$5 per microfiche.\n4. Photographic print (photographic paper) from microfilm negative of a size —\n(a) not exceeding A4 (21 cm x 29.7 cm)\n(i) $8 per copy.\n(ii) $6 per copy for students.\n(b) not exceeding A3 (29.7 cm x 42 cm)\n(i) $9.50 per copy.\n(ii) $7.50 per copy for students.\n(c) not exceeding A2 (42 cm x 59.4 cm)\n(i) $16 per copy.\n(ii) $13 per copy for students.\n(d) not exceeding A1 (59.4 cm x 84.1 cm)\n(i) $25 per copy.\n(ii) $20 per copy for students.\n5. Photographic print (plain paper) from microfilm of a size —\n(a) not exceeding A4 (21 cm x 29.7 cm)\n30 cents per copy.\n(b) not exceeding A3 (29.7 cm x 42 cm)\n40 cents per copy.\n(c) not exceeding A2 (42 cm x 59.4 cm)\n$4 per copy.\n6. Photocopy of any document of a size —\n(a) not exceeding B4 (25 cm x 35.3 cm)\n30 cents per page.\n(b) not exceeding A3 (29.7 cm x 42 cm)\n40 cents per page.\n7. C60 cassette tape\n$6 per cassette tape.\n8. Processing —\n(a) 16 mm x 30.5 m roll film\n$6 per roll.\n(b) 35 mm x 30.5 m roll film\n$9 per roll.\n(c) 105 mm x 30.5 m roll film\n$35 per roll.\n9. Quality Control (Hypo) Test on 16/35/105 mm master negative sample strip\n$15 per roll.\n10. Quality Control (Resolution and Density) Test on 16/35/105 mm master negative\n$15 per roll.\n11.—(1) Microfilming of loose single-sided documents not exceeding A4 size in good physical condition (less than 5 years old) on 16 mm roll film\n$50 per roll.\n(2) Preparation prior to microfilming\n$25.\n12.—(1) Microfilming of loose single or double-sided documents not exceeding A3 size in fair physical condition (5 to 10 years old) on 16 mm roll film\n$55 per roll.\n(2) Preparation prior to microfilming\n$30.\n13.—(1) Microfilming of loose single or double-sided documents not exceeding A3 size in poor physical condition (more than 10 years old) on 16 mm roll film\n$70 per roll\n(2) Preparation prior to microfilming\n$35.\n14. Microfilming of single-sided 80 column or 132 column computer print-out (continuous run) in good physical condition (less than 5 years old) on 16 mm roll film\n$45 per roll.\n15.—(1) Microfilming of loose or bound documents (less than 10 cm in thickness) not exceeding A1 size in fair physical condition (5 to 10 years old) on 35 mm roll film\n$150 per roll.\n(2) Preparation prior to microfilming\n$30.\n16.—(1) Microfilming of plans or maps not exceeding A0 size in fair physical condition (5 to 10 years old) on 35 mm roll film\n$110 per roll.\n(2) Preparation prior to microfilming\n$55.\n17.—(1) Microfilming of loose documents not exceeding A3 size in good physical condition (less than 5 years old) on 105 mm roll fiche\n$400 per roll.\n(2) Preparation prior to microfilming\n$100.\n18.—(1) Microfilming of loose or bound documents (less than 2 cm in thickness) not exceeding A3 size in fair physical condition (5 to 10 years old) on 105 mm roll fiche\n$370 per roll.\n(2) Preparation prior to microfilming\n$85.\n19.—(1) Microfilming of loose or bound documents (less than 5 cm in thickness) not exceeding A3 size in good physical condition (less than 5 years old) on 105 mm cut fiche format\n$16 per cut fiche.\n(2) Preparation prior to microfilming\n$1.60 per fiche.\n19A.—(1) Microfilming of loose maps or plans on large format cut-sheet negative film —\n(a) 4″ x 5″/4″ x 6″ sheet\n$12 per sheet.\n(b) 8″ x 10″ sheet\n$15 per sheet.\n(2) Preparation prior to microfilming —\n(a) 4″ x 5″/4″ x 6″ sheet\n$1.20 per sheet.\n(b) 8″ x 10″ sheet\n$1.50 per sheet.\n20. Duplicate records belonging to departments/statutory boards —\n(a) 16 mm diazo microfilm\n$10 per roll.\n(b) 35 mm diazo microfilm\n$15 per roll.\n(c) 105 mm cut fiche\n$1.50 per fiche.\n21. Deacidification of A4 size documents\n$1 per sheet.\n22. Restoration of A4 size documents —\n(a) without leaf-casting\n$8 per sheet.\n(b) with leaf-casting\n$15 per sheet.\n23. Removal of stain of A4 size documents\n$7 per sheet.\n24. Encapsulation of A4 size documents\n$7 per sheet.\n25. Restoration of A4 size maps —\n(a) without leaf-casting\n$30 per sheet.\n(b) with leaf-casting\n$50 per sheet.\n26. Fumigation of documents\n$25 per cycle.\n27. Binding of A4 size books —\n(a) manually bound with leather\n$115 per book.\n(b) manually bound with cloth\n$70 per book.\n(c) machine bound\n$8 per book.\n28. Reproduction of black and white photographs of a size —\n(a) 89 mm x 140 mm\n$1.50.\n(b) 102 mm x 152 mm\n$2.50.\n(c) 152 mm x 203 mm\n$4.\n(d) 203 mm x 254 mm\n$7.\n(e) 254 mm x 305 mm\n$10.\n(f) 305 mm x 381 mm\n$15.\n(g) 406 mm x 508 mm\n$30.\n(h) 508 mm x 610 mm\n$45.\n(i) Size bigger than 508 mm x 610 mm\n15 cents per 645 mm2.\n29. Reproduction of colour photographs of a size —\n(a) 76 mm x 127 mm\n$4.\n(b) 127 mm x 127 mm\n$6.\n(c) 127 mm x 178 mm\n$7.\n(d) 203 mm x 203 mm\n$14.\n(e) 203 mm x 254 mm\n$15.\n(f) 279 mm x 356 mm\n$25.\n(g) 356 mm x 432 mm\n$36.\n(h) 406 mm x 508 mm\n$40.\n30. Reproduction of colour transcripts/slides of a size —\n(a) 35 mm\n$5.\n(b) 57 mm x 57 mm\n$25.\n(c) 102 mm x 127 mm\n$50.\n31. Usage of photographs/slides —\n(a) for commercial activities which are educational and cultural in nature and where the photographs/slides are not the main draw to the products/ services but are supplements. Commercial activities includes commercial illustrative purposes such as publications, television programmes and display purposes.\n$50 per photograph per usage.\n(b) in product development where the photographs/slides are the main draw to the products. Product development includes printing of photographs on T-shirts, mugs, calendars, picture postcards, and other souvenir merchandise items.\n$500 per photograph per usage.\n32. Search fee for audio-visual materials\n$25 per programme.\n33. Transfer cost for audio-visual materials —\n(a) from Betacam master to Betacam copy\n$200 per hour.\n(b) from Betacam master to U-matic copy\n$150 per hour.\n(c) from 1’ master to VHS copy\n$160 per copy.\n(d) from 1’ master to U-matic copy\n$175 per copy.\n(e) from U-matic master to U-matic copy\n$100 per copy.\n(f) from VHS to VHS\n$70 per copy.\n34. Usage fee for audio-visual materials\n$400 per programme per usage.\n35. Black and white photocopying of a size —\n(a) not exceeding A4\n$2 per copy.\n(b) not exceeding A3\n$2.50 per copy.\n36. Mono-colour photocopying of a size —\n(a) not exceeding A4\n$2.50 per copy.\n(b) not exceeding A3\n$3 per copy.\n37. 4-Colour photocopying of a size —\n(a) not exceeding A4\n$3 per copy.\n(b) not exceeding A3\n$3.50 per copy.\n38. Computer print-out of —\n(a) photograph index/list or Oral History synopsis\n$2.20 per A4 sheet.\n(b) black and white photograph image\n$2.70 per A4 sheet.\n39. Direct duplication of —\n(a) 16 mm x 30.5 m silver halide microfilm\n$25 per roll.\n(b) 35 mm x 30.5 m silver halide microfilm\n$40 per roll.\n40. Sulphate treatment (toning) of —\n(a) 16 mm x 30.5 m silver halide film\n$10 per roll.\n(b) 35 mm x 30.5 m silver halide microfilm\n$12 per roll.\n[S 442/95 wef 30/09/1995]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Heritage Board (Micrographic and Reprographic Fees) Regulations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3311"] = {"id":"SG-H3311","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NHBA1993-RG2?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"国家文物局（博物馆入场费）条例","en":"National Heritage Board (Museum Admission Fees) Regulations","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NHBA1993-RG2","completenessNote":"全文，共 4 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3311-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. These Regulations may be cited as the National Heritage Board (Museum Admission Fees) Regulations."}},{"id":"SG-H3311-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definition"},"text":{"en":"2. In these Regulations, “museum” means any museum established by the Board under section 11 of the Act or the museum transferred to the Board under section 37 of the Act."}},{"id":"SG-H3311-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Admission fees"},"text":{"en":"3. The admission fee for any museum shall be determined by the Chief Executive Officer but such fee shall not exceed $10 per person.\n[Subst. by S 443/95 wef 30/09/1995]"}},{"id":"SG-H3311-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Waiver, reduction and remission of fees"},"text":{"en":"4. The Chief Executive Officer may, in his discretion, waive, reduce or remit either wholly or in part any fee payable under regulation 3 in any particular case or class of cases."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Heritage Board (Museum Admission Fees) Regulations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3312"] = {"id":"SG-H3312","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NHBA1993?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":53,"structureMode":"ARTICLE","title":{"zh":"国家文物局法 1993","en":"National Heritage Board Act 1993","orig":null},"level":"law","status":"active","docNumber":"Act NHBA1993","completenessNote":"全文，共 53 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。其中 13 条为官方正文中标注的已废止条文存根（照录）。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3312-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Short title"},"text":{"en":"1. This Act is the National Heritage Board Act 1993."}},{"id":"SG-H3312-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Interpretation"},"text":{"en":"2. In this Act, unless the context otherwise requires —\n“Board” means the National Heritage Board established under section 3;\n“Chairperson” means the Chairperson of the Board and includes any temporary Chairperson of the Board;\n“chief executive officer” means the chief executive officer of the Board and includes any person acting in that capacity;\n“Deputy Chairperson” means the Deputy Chairperson of the Board and includes any temporary Deputy Chairperson of the Board;\n“Fund” means the National Heritage Endowment Fund established under section 35;\n“member” means a member of the Board;\n“object” includes any work of art and any artefact."}},{"id":"SG-H3312-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Establishment of National Heritage Board"},"text":{"en":"3. A body called the National Heritage Board is established, which is a body corporate with perpetual succession and is by that name capable of —\n(a)suing and being sued;\n(b)acquiring, owning, holding, developing and disposing of property, both movable and immovable; and\n(c)doing and suffering all such acts or things as bodies corporate may lawfully do or suffer."}},{"id":"SG-H3312-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Common seal"},"text":{"en":"4.—(1) The Board must have a common seal which must be kept in such custody as the Board thinks fit.\n(2) All deeds and other documents requiring the seal of the Board must be sealed with the common seal of the Board, and every document to which the common seal is affixed must be signed by —\n(a)any 2 members of the Board generally or specially authorised by the Board for the purpose; or\n(b)one member of the Board generally or specially authorised by the Board for the purpose and the chief executive officer.\n(3) All courts, judges and persons acting judicially are to take judicial notice of the common seal of the Board affixed to any document and presume that it was duly affixed."}},{"id":"SG-H3312-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Constitution of Board"},"text":{"en":"5.—(1) The Board consists of —\n(a)a Chairperson;\n(b)a Deputy Chairperson; and\n(c)not less than 10 and not more than 25 other members as the Minister may determine.\n(2) The Schedule applies with respect to the Board, its members and proceedings."}},{"id":"SG-H3312-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Functions of Board"},"text":{"en":"6. The functions of the Board are —\n(a)to explore and present the heritage and nationhood of the people of Singapore in the context of their ancestral cultures, their links with South-East Asia, Asia and the world through the collection, preservation, interpretation and display of objects and records;\n(b)to promote public awareness, appreciation and understanding of the arts, culture and heritage, both by means of the Board’s collections and by such other means as it considers appropriate;\n(c)to promote the establishment and development of organisations concerned with the national heritage of Singapore;\n(d)to advise the Government in respect of matters relating to the national heritage of Singapore; and\n(e)to perform such other functions as are conferred on the Board by any other written law."}},{"id":"SG-H3312-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Powers of Board"},"text":{"en":"7.—(1) The Board has power to do all things necessary or convenient to be done for or in connection with the performance of its functions.\n(2) Without limiting subsection (1), the powers of the Board include the following:\n(a)to develop and manage museums and other facilities related to its functions;\n(b)to collect, classify, preserve and display objects and records relevant to its functions;\n(c)to advise and facilitate the preservation of historic sites;\n(d)to undertake or sponsor research and investigation relevant to its functions;\n(e)to arrange for the acquisition, production or publication and the sale to the public of books, pamphlets, replicas and other materials related to its functions;\n(f)to undertake or sponsor programs for the training of persons in the professions and skills involved in the operation of museums;\n(g)to establish liaison with other museums, universities and other institutions to secure maximum collaboration of all activities relevant to its functions;\n(h)to arrange for or provide professional and technical services, on any terms and conditions that may be approved by the Board;\n(i)to raise funds by all lawful means and receive gifts and donations, whether on trust or otherwise;\n(j)to extend grants, contributions or loans to any person or organisation connected with the national heritage of Singapore;\n(k)to enter into contracts and establish trusts;\n(l)to enter into joint ventures with any person or organisation, or form or participate in the formation of a company;\n(m)to provide or undertake publicity in any form;\n(n)to charge fees, commissions or rent for any objects, services or facilities provided by the Board."}},{"id":"SG-H3312-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Appointment of committees and delegation of powers"},"text":{"en":"8.—(1) The Board may appoint any number of committees that it thinks fit consisting of its members or other persons or its members and other persons for purposes which, in the opinion of the Board, would be better regulated and managed by means of those committees.\n(2) The Board may, subject to any conditions or restrictions that it thinks fit, delegate to any such committee or to the Chairperson, all or any of the powers and functions vested in the Board by this Act; and any power or function so delegated may be exercised or performed by the committee or Chairperson in the name and on behalf of the Board.\n[5/2018]\n(3) The Board may, subject to any conditions or restrictions that it thinks fit, delegate to any employee of the Board or to any other person all or any of the powers and functions vested in the Board by this Act; and any power or function so delegated may be exercised or performed by the employee or person in the name and on behalf of the Board.\n[5/2018]"}},{"id":"SG-H3312-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONS AND POWERS OF BOARD"},"text":{"en":"9. [Repealed by Act 5 of 2018]"},"status":"repealed"},{"id":"SG-H3312-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Directions by Minister"},"text":{"en":"10.—(1) The Minister may give to the Board any direction under section 5 of the Public Sector (Governance) Act 2018.\n[5/2018]\n(2) The Board must give the Minister any information with regard to its property and activities that the Minister may require."}},{"id":"SG-H3312-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 3 NATIONAL MUSEUM OF SINGAPORE"},"heading":{"en":"Establishment of museums"},"text":{"en":"11.—(1) The Board may establish any museums that it thinks fit.\n(2) Every museum established by the Board under subsection (1) is to be known by any name that the Board thinks fit.\n(3) All museums established by the Board under subsection (1) and the museum transferred to the Board under section 37 are collectively known as the National Museum of Singapore."}},{"id":"SG-H3312-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 3 NATIONAL MUSEUM OF SINGAPORE"},"heading":{"en":"Appointment of directors of museums"},"text":{"en":"12. The Board may appoint a director for any museum established by the Board under section 11 and the museum transferred to it under section 37 who is responsible to the Board for the general management and control of the museum so established or transferred."}},{"id":"SG-H3312-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 3 NATIONAL MUSEUM OF SINGAPORE"},"heading":{"en":"Initial vesting of objects in Board"},"text":{"en":"13.—(1) Where the property in an object was vested in the Government immediately before 1 August 1993, and the object —\n(a)then formed part of the collections of the National Museum; or\n(b)was then in use in respect of the collections or solely for the purposes of the administration of the National Museum,\nthen the property is on that date to be vested instead in the Board.\n(2) In the case of an object mentioned in subsection (1)(a), it is immaterial that, immediately before 1 August 1993, it was situated elsewhere than at premises managed for the purposes of the National Museum.\n(3) On 1 August 1993, any right, power, duty or liability which was immediately before that date exercisable by or incumbent on the Government in relation to any object mentioned in subsection (1) is instead to be exercisable by or incumbent on the Board.\n(4) Subsections (1) and (3) do not apply as regards such object excepted from those provisions as the Minister may specify."}},{"id":"SG-H3312-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 3 NATIONAL MUSEUM OF SINGAPORE"},"heading":{"en":"Certain gifts vesting on or after 1 August 1993"},"text":{"en":"14.—(1) Subsection (2) applies to a gift (by will or otherwise) —\n(a)which is contained in an instrument made or executed before 1 August 1993 but coming into effect on or after that date; and\n(b)which would, apart from this Act, have vested an interest in property (of any nature) in the Government for the purposes of the National Museum.\n(2) The gift is to, in the absence of any contrary intention expressed in that or another instrument made by the testator or donor, have effect so as to vest the interest in the Board in place of the Government."}},{"id":"SG-H3312-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 3 NATIONAL MUSEUM OF SINGAPORE"},"heading":{"en":"Acquisition and disposal of objects"},"text":{"en":"15.—(1) The Board may acquire (whether by purchase, exchange or gift) any object which in its opinion is desirable to add to its collections.\n(2) Without affecting any power apart from this subsection, the Minister may transfer to the Board any object (whether or not the Minister acquired it before the Board’s establishment) if in the Minister’s opinion it would appropriately form part of its collections.\n(3) The Board may not dispose of an object of significant national or historical value, the property in which is vested in the Board and which is comprised in its collections, unless the object is —\n(a)a duplicate of another object the property in which is so vested and which is so comprised; or\n(b)in the Board’s opinion unsuitable for retention in its collections,\nand the disposal is done with the prior approval of the Minister and by way of sale, exchange or gift.\n(4) The Board may dispose of (by whatever means, including destruction) any object which the Board is satisfied has become useless for the purposes of its collections by reason of damage, physical deterioration or infestation by destructive organisms.\n(5) An object may be disposed of as mentioned in subsection (4) despite a trust or condition (express or implied) prohibiting or restricting the disposal of the object.\n(6) Money accruing to the Board by virtue of a disposal mentioned in this section must be applied by the Board in the acquisition of objects to be added to its collections."}},{"id":"SG-H3312-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 3 NATIONAL MUSEUM OF SINGAPORE"},"heading":{"en":"Lending and borrowing of objects"},"text":{"en":"16.—(1) Subject to subsection (2), the Board may lend any object the property in which is vested in the Board and which is comprised in its collections (whether or not the loan is for the purposes of public exhibition, and whether or not under the terms of the loan the object is to remain in Singapore).\n(2) In deciding whether or not to lend an object, and in determining the time for which and the conditions subject to which an object is to be lent, the Board —\n(a)must give special consideration to a request for the loan of an object for public exhibition; and\n(b)subject to paragraph (a), must have regard to the interests of students and other persons visiting the Board’s collections, the suitability of the prospective borrower, the purpose of the loan, the physical condition and degree of rarity of the object and any risks to which it is likely to be exposed.\n(3) Where the property in an object has become vested in the Board subject to a condition, the power conferred by subsection (1) is exercisable in a manner inconsistent with the condition if either —\n(a)25 years have elapsed since the date on which the property became vested in the Board; or\n(b)the person who first imposed the condition or his or her personal representatives have consented in writing to the exercise of the power in that manner.\n(4) The Board may accept loans of objects for the purpose, subject to the terms of the loan, of exhibiting them, or of study or research by the Board or by persons seeking to inspect them."}},{"id":"SG-H3312-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 4"},"text":{"en":"17. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 4"},"text":{"en":"18. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A19","no":19,"noLabel":{"en":"19."},"chapter":{"en":"PART 4"},"text":{"en":"19. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A20","no":20,"noLabel":{"en":"20."},"chapter":{"en":"PART 4"},"text":{"en":"20. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A21","no":21,"noLabel":{"en":"21."},"chapter":{"en":"PART 4"},"text":{"en":"21. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A22","no":22,"noLabel":{"en":"22."},"chapter":{"en":"PART 4"},"text":{"en":"22. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A23","no":23,"noLabel":{"en":"23."},"chapter":{"en":"PART 4"},"text":{"en":"23. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A24","no":24,"noLabel":{"en":"24."},"chapter":{"en":"PART 4"},"text":{"en":"24. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A25","no":25,"noLabel":{"en":"25."},"chapter":{"en":"PART 4"},"text":{"en":"25. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A26","no":26,"noLabel":{"en":"26."},"chapter":{"en":"PART 4"},"text":{"en":"26. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A27","no":27,"noLabel":{"en":"27."},"chapter":{"en":"PART 4"},"text":{"en":"27. [Repealed by Act 25 of 2012]"},"status":"repealed"},{"id":"SG-H3312-A28","no":28,"noLabel":{"en":"28."},"chapter":{"en":"PART 5 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Chief executive officer"},"text":{"en":"28.—(1) There must be a chief executive officer of the Board, whose appointment, removal, discipline and promotion must be in accordance with the Public Sector (Governance) Act 2018.\n[5/2018]\n(2) The Board may, subject to the Public Sector (Governance) Act 2018, appoint an individual to act temporarily as the chief executive officer during any period, or during all periods, when the chief executive officer —\n(a)is absent from duty or Singapore; or\n(b)is, for any reason, unable to perform the duties of the office.\n[5/2018]"}},{"id":"SG-H3312-A29","no":29,"noLabel":{"en":"29."},"chapter":{"en":"PART 5 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Appointment of staff"},"text":{"en":"29. The Board may, subject to the Public Sector (Governance) Act 2018, appoint and employ, on such terms and conditions as it may determine, such other officers, employees, consultants and agents as may be necessary for the effective performance of its functions.\n[5/2018]"}},{"id":"SG-H3312-A30","no":30,"noLabel":{"en":"30."},"chapter":{"en":"PART 5 PROVISIONS RELATING TO STAFF"},"text":{"en":"30. [Repealed by Act 5 of 2018]"},"status":"repealed"},{"id":"SG-H3312-A31","no":31,"noLabel":{"en":"31."},"chapter":{"en":"PART 6 FUNDS AND PROPERTY OF BOARD"},"heading":{"en":"Funds and property of Board"},"text":{"en":"31.—(1) The funds and property of the Board include —\n(a)all moneys and property transferred to the Board under section 37;\n(b)all gifts, donations and contributions to the Board;\n(c)all moneys received by the Board by way of grants;\n(d)all fees, commissions, rents, interests, dividends and other income accruing to the Board;\n(e)all moneys borrowed by the Board under this Act; and\n(f)all moneys recovered or collected by the Board or any officer or employee of the Board (excluding sums collected for the composition of offences) under this Act or any other written law that is administered and enforced by the Board.\n[36/2021]\n(2) The Board may open and maintain an account or accounts with any bank or banks as the Board thinks fit.\n(3) The Board may invest its funds in accordance with the standard investment power of statutory bodies as defined in section 33A of the Interpretation Act 1965.\n(4) Subject to the terms of any trust or endowment, the funds and property of the Board must be applied solely for the purposes of or in connection with the performance of the functions, powers and duties of the Board under this Act."}},{"id":"SG-H3312-A32","no":32,"noLabel":{"en":"32."},"chapter":{"en":"PART 6 FUNDS AND PROPERTY OF BOARD"},"heading":{"en":"Power to borrow"},"text":{"en":"32.—(1) For the performance of its functions or discharge of its duties under this Act or any other written law, the Board may raise loans from the Government or, with the approval of the Minister, raise loans within or outside Singapore from any source that the Minister may direct by —\n(a)mortgage, overdraft or other means, with or without security;\n(b)charge, whether legal or equitable, on any property vested in the Board or on any other revenue receivable by the Board under this Act or any other written law; or\n(c)the creation and issue of debentures, bonds or any other instrument as the Minister may approve.\n(2) For the purposes of this section, the power to raise loans includes the power to make any financial agreement whereby credit facilities are granted to the Board for the purchase of goods, materials or things."}},{"id":"SG-H3312-A32.001","no":32.001,"noLabel":{"en":"32A."},"chapter":{"en":"PART 6 FUNDS AND PROPERTY OF BOARD"},"heading":{"en":"Issue of shares, etc."},"text":{"en":"32A. As a consequence of the vesting of any property, rights or liabilities of the Government in the Board under this Act, or of any capital injection or other investment by the Government in the Board in accordance with any written law, the Board must issue such shares or other securities to the Minister for Finance as that Minister may direct."}},{"id":"SG-H3312-A33","no":33,"noLabel":{"en":"33."},"chapter":{"en":"PART 6 FUNDS AND PROPERTY OF BOARD"},"heading":{"en":"Grants"},"text":{"en":"33. For the purpose of enabling the Board to carry out its functions under this Act, the Minister may make grants to the Board of any sum of money that the Minister may determine out of moneys to be provided by Parliament."}},{"id":"SG-H3312-A34","no":34,"noLabel":{"en":"34."},"chapter":{"en":"PART 6 FUNDS AND PROPERTY OF BOARD"},"heading":{"en":"Income of Board to be exempt from income tax, etc."},"text":{"en":"34. The Board is deemed to be —\n(a)an institution specified in the First Schedule to, and under section 13(1)(e) of, the Income Tax Act 1947; and\n(b)an institution of a public character approved under the Charities Act 1994."}},{"id":"SG-H3312-A35","no":35,"noLabel":{"en":"35."},"chapter":{"en":"PART 6 FUNDS AND PROPERTY OF BOARD"},"heading":{"en":"Establishment of National Heritage Endowment Fund"},"text":{"en":"35.—(1) A fund called the National Heritage Endowment Fund is established, which vests in the Board and consists of —\n(a)all moneys received by the Board by gift, bequest or otherwise for the Fund;\n(b)any contributions to the Fund that the Minister may specify from moneys provided by Parliament; and\n(c)any other moneys that the Board may decide to transfer to the Fund.\n(2) Any interest, dividends and other income derived from the Fund must be credited to the general funds of the Board.\n(3) For the purposes of this section, “general funds of the Board” means the funds of the Board other than the Fund.\n(4) The Fund must not, except with the prior written approval of the Minister, be applied, disposed of or alienated otherwise than as specified in section 31(3) and (4)."}},{"id":"SG-H3312-A36","no":36,"noLabel":{"en":"36."},"chapter":{"en":"PART 6 FUNDS AND PROPERTY OF BOARD"},"heading":{"en":"Financial year"},"text":{"en":"36. The financial year of the Board begins on 1 April of each year and ends on 31 March of the succeeding year.\n[5/2018]"}},{"id":"SG-H3312-A37","no":37,"noLabel":{"en":"37."},"chapter":{"en":"PART 7 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Transfer of assets and liabilities"},"text":{"en":"37.—(1) As from 1 August 1993, all movable property vested in the Government immediately before that date and used or managed by the National Museum, the National Archives and Records Centre or the Oral History Department, and all assets, rights, interests, liabilities and obligations of the Government relating to the National Museum, the National Archives and Records Centre or the Oral History Department are to be transferred to and vested in the Board without further assurance.\n(2) As from 1 August 1993, the Board controls and manages the National Museum which is to be known by such name as the Board thinks fit.\n(3) If any question arises as to whether any particular property, or whether any particular asset, interest, right, liability or obligation has been transferred to or vested in the Board under subsection (1), a certificate under the hand of the Minister for Finance is conclusive evidence that the property, asset, interest, right, liability or obligation was or was not so transferred or vested."}},{"id":"SG-H3312-A38","no":38,"noLabel":{"en":"38."},"chapter":{"en":"PART 7 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Existing agreements, etc."},"text":{"en":"38. All deeds, bonds, agreements, instruments and working arrangements, subsisting immediately before 1 August 1993, affecting any of the property, rights, interests, liabilities and obligations transferred to or vested in the Board under section 37(1) continue in force on and after that date and are enforceable by or against the Board as if, instead of the Government or a person acting on behalf of the Government, the Board had been named therein or had been a party thereto."}},{"id":"SG-H3312-A39","no":39,"noLabel":{"en":"39."},"chapter":{"en":"PART 7 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Pending legal proceedings"},"text":{"en":"39. Any proceedings or cause of action pending or existing immediately before 1 August 1993 by or against the Government or any person acting on behalf of the Government relating to the National Museum, the National Archives and Records Centre or the Oral History Department may be continued and must be enforced by or against the Board."}},{"id":"SG-H3312-A40","no":40,"noLabel":{"en":"40."},"chapter":{"en":"PART 7 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Transfer of employees"},"text":{"en":"40.—(1) As from 1 August 1993, such categories of persons employed immediately before that date in the National Museum, the National Archives and Records Centre and the Oral History Department as the Minister may determine must be transferred to the service of the Board on terms no less favourable than those enjoyed by them immediately prior to their transfer.\n(2) Until such time as terms and conditions of service are drawn up by the Board, the scheme and terms and conditions of service in the Government continue to apply to every person transferred to the service of the Board under subsection (1) as if the person were still in the service of the Government."}},{"id":"SG-H3312-A41","no":41,"noLabel":{"en":"41."},"chapter":{"en":"PART 7 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Pension rights, etc., of Government employees to be preserved"},"text":{"en":"41.—(1) The terms and conditions of service of persons transferred to the service of the Board under section 40 must take into account the salaries and terms and conditions of service, including any accrued rights to leave, enjoyed by such persons while in the employment of the Government and any such term or condition relating to the length of service with the Board must provide for the recognition of service under the Government by persons so transferred to be service by them under the Board.\n(2) Nothing in the terms and conditions of service to be drawn up by the Board is to adversely affect the conditions that would have been applicable to persons transferred to the service of the Board as regards any pension, gratuity or allowance payable under the Pensions Act 1956.\n(3) In every case where a person has been transferred to the service of the Board under section 40, the Government is liable to pay the Board such portion of any gratuity, pension or allowance payable to such person on his or her retirement or otherwise leaving the service of the Board as the same shall bear to the proportion which the aggregate amount of his or her pensionable emoluments during his or her service with the Government bears to the aggregate amount of his or her pensionable emoluments during his or her service under both the Government and the Board.\n(4) Where any person who is transferred to the service of the Board under section 40 is a contributor under the Widows’ and Orphans’ Pension Act 1904, he or she must, for the purposes of that Act, continue to make contributions under that Act as if he or she had not been transferred to the service of the Board and, for the purposes of that Act, his or her service with the Board is deemed to be service with the Government."}},{"id":"SG-H3312-A42","no":42,"noLabel":{"en":"42."},"chapter":{"en":"PART 7 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"No benefits in respect of abolition or reorganisation of office"},"text":{"en":"42. Despite the provisions of the Pensions Act 1956, no person who is transferred to the service of the Board under section 40 is entitled to claim any benefit under the Pensions Act 1956 on the ground that he or she has been retired from the service of the Government on account of abolition or reorganisation of office in consequence of the establishment and incorporation of the Board."}},{"id":"SG-H3312-A43","no":43,"noLabel":{"en":"43."},"chapter":{"en":"PART 7 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Continuation and completion of disciplinary proceedings"},"text":{"en":"43.—(1) Where on 1 August 1993, any disciplinary proceedings are pending against any person transferred to the service of the Board under section 40, any committee acting under due authority to hear or investigate the matter continues to exist, despite this Act, for the purpose of completing the hearing or investigation and the making of an order or rendering a decision (as the case may be) and the Government or committee must complete the hearing or investigation in accordance with the authority vested in the Government or committee immediately before that date and make such order, ruling or direction as the Government or committee could have made under the authority vested in it immediately before that date.\n(2) Any order, ruling or direction made or given by the Government or committee pursuant to this section is to be treated as an order, ruling or direction of the Board and have the same force or effect as if it had been made or given by the Board pursuant to the authority vested in the Board under this Act."}},{"id":"SG-H3312-A44","no":44,"noLabel":{"en":"44."},"chapter":{"en":"PART 7 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Misconduct or neglect of duty by employee before transfer"},"text":{"en":"44. The Board may reprimand, reduce in rank, retire, dismiss or punish in some other manner a person transferred to the service of the Board under section 40 for any misconduct or neglect of duty committed prior to 1 August 1993 which would have rendered the person liable to be reprimanded, reduced in rank, retired, dismissed or punished in some other manner by the Government as if this Act had not been enacted."}},{"id":"SG-H3312-A45","no":45,"noLabel":{"en":"45."},"chapter":{"en":"PART 7 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Interpretation of this Part"},"text":{"en":"45. In this Part, “National Archives and Records Centre” means the National Archives and Records Centre established under the repealed National Archives and Records Centre Act (Cap. 193, 1985 Revised Edition) in force immediately before 1 August 1993."}},{"id":"SG-H3312-A46","no":46,"noLabel":{"en":"46."},"chapter":{"en":"PART 8 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Power to enter upon lands to conduct archaeological investigation"},"text":{"en":"46.—(1) Subject to this section, any person specifically authorised in writing by the Board, after giving not less than 24 hours’ notice in writing to the occupier of the land of his or her intention to enter the land and on production of his or her authority, if so required by or on behalf of the occupier, may enter for the purposes of archaeological investigation or examination at all reasonable times upon any land which the Board has reason to believe contains any ancient monument and may make excavations in the land.\n(2) No person may, under any power conferred by subsection (1), enter any dwelling house or any building, park, garden, pleasure ground or other land used for the amenity or convenience of a dwelling house except with the occupier’s consent.\n(3) No excavation may be made under the power conferred by subsection (1) except with the consent of every person whose consent to the making of the excavation would, apart from that subsection, be required.\n(4) Any power of entry under this section includes the power for any person entering any land in exercise of the power of entry to take with him or her any assistance or equipment reasonably required for the purpose to which his or her entry relates and to do there anything reasonably necessary for carrying out that purpose.\n(5) Without affecting subsection (4), where a person enters any land in exercise of any power of entry under this section for the purpose of carrying out any archaeological investigation or examination of the land, he or she may take and remove any samples of any description that appear to him or her to be reasonably required for the purpose of archaeological analysis.\n(6) Where a person enters any land in exercise of any power of entry under this section for the purpose of carrying out any archaeological investigation or examination of the land, he or she may take temporary custody of any object of archaeological or historical interest discovered during the course of the excavations carried out for that purpose, and remove it from its site for the purpose of examining, testing, treating, recording or preserving it.\n(7) The Board or other person by or on whose behalf the power of entry was exercised may not retain the object without the owner’s consent beyond the period that may be reasonably required for the purpose of examining and recording it and carrying out any test or treatment which appears to the Board or to that person to be desirable for the purpose of archaeological investigation or analysis or with a view to restoring or preserving the object.\n(8) Nothing in this section affects any right of the Government in relation to treasure trove.\n(9) Any person who wilfully obstructs or hinders any person in the exercise of the powers conferred by this section shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding one year or to both.\n(10) In this section —\n“ancient monument” means any monument which, in the opinion of the Board, is of public interest by reason of the historic, cultural, traditional, archaeological, architectural, artistic or symbolic significance attaching to it;\n“monument” has the meaning given by section 2 of the Preservation of Monuments Act 2009.\n[36/2021]\n(11) For the purposes of this section, “archaeological investigation” means any investigation of any land, objects or other material for the purpose of obtaining and recording any information of archaeological or historical interest and includes in the case of an archaeological investigation of any land —\n(a)any investigation for the purpose of discovering and revealing and (where appropriate) recovering and removing any objects or other material of archaeological or historical interest situated in, on or under the land; and\n(b)examining, testing, treating, recording and preserving any such objects or material discovered during the course of any excavation or inspection carried out for the purposes of any such investigation.\n(12) For the purposes of this section, an archaeological examination of any land means any examination or inspection of the land (including any buildings or other structures on the land) for the purpose of obtaining and recording any information of archaeological or historical interest."}},{"id":"SG-H3312-A47","no":47,"noLabel":{"en":"47."},"chapter":{"en":"PART 8 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Board’s symbol"},"text":{"en":"47.—(1) The Board has the exclusive right to the use of any symbol or representation that it may select or devise and to display or exhibit in connection with its activities or affairs.\n(2) A person who, without the permission of the Board, uses a symbol or representation identical with that of the Board or which so resembles the Board’s symbol or representation as to deceive or cause confusion, or to be likely to deceive or cause confusion, shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding one year or to both."}},{"id":"SG-H3312-A47.001","no":47.001,"noLabel":{"en":"47A."},"chapter":{"en":"PART 8 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Preservation of secrecy"},"text":{"en":"47A.—(1) Except for the purpose of the performance of his or her functions or the discharge of his or her duties or when lawfully required to do so by any court or where required or allowed by the provisions of this Act or any written law, no person who is or has been —\n(a)a member, an officer, an employee or an agent of the Board; or\n(b)a member of a committee appointed by the Board under this Act or any written law administered by the Board,\nmay disclose any information relating to the affairs of the Board or of any other person which has been obtained by him or her in the performance of his or her functions or the discharge of his or her duties.\n[5/2018]\n(2) Any person who contravenes subsection (1) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $2,000 or to imprisonment for a term not exceeding 12 months or to both."}},{"id":"SG-H3312-A48","no":48,"noLabel":{"en":"48."},"chapter":{"en":"PART 8 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Immunity of Board and its employees, etc."},"text":{"en":"48. No suit or other legal proceedings shall lie against the Board, any member, officer or employee of the Board or other person acting under the direction of the Board for anything which is in good faith done or intended to be done in the execution or purported execution of this Act or the Preservation of Monuments Act 2009."}},{"id":"SG-H3312-A49","no":49,"noLabel":{"en":"49."},"chapter":{"en":"PART 8 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Regulations"},"text":{"en":"49.—(1) The Board may, with the approval of the Minister, make regulations for any matter which may be prescribed under this Act and generally for the better carrying out of the objects and purposes of this Act.\n(2) Without limiting subsection (1), the regulations may —\n(a)provide for the use, custody, preservation, reproduction, removal, destruction and disposal of the objects and other documents under this Act;\n(b)provide for regulating the conduct of persons on any land or building owned by, or under the control of, the Board;\n(c)prescribe the forms, fees or registers for the purposes of this Act; and\n(d)provide for the exemption from the payment, in whole or in part, of any fee under this Act."}},{"id":"SG-H3312-A50","no":50,"noLabel":{"en":"50."},"chapter":{"en":"PART 8 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Transitional provisions"},"text":{"en":"50.—(1) Any scheme, contract, document, certificate, licence, permission or resolution prepared, made, granted or approved under the repealed National Archives and Records Centre Act (Cap. 193, 1985 Revised Edition) shall, so far as it is not inconsistent with the provisions of this Act, continue and be deemed to have been prepared, made, granted or approved under this Act.\n(2) Any subsidiary legislation made under the repealed National Archives and Records Centre Act (Cap. 193, 1985 Revised Edition) and in force immediately before 1 August 1993 shall, so far as it is not inconsistent with the provisions of this Act, continue in force as if made under this Act until it is revoked by subsidiary legislation made under this Act."}},{"id":"SG-H3312-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nSection 5(2)\nConstitution and proceedings of Board\nAppointment of Chairperson, Deputy Chairperson and other members\n1.—(1) The Chairperson, the Deputy Chairperson and other members must be appointed by the Minister.\n(2) The Deputy Chairperson may, subject to such directions as may be given by the Chairperson, exercise all or any of the powers exercisable by the Chairperson under this Act.\n(3) The Minister may appoint the chief executive officer to be a member.\nTenure of office of members\n2. The Chairperson, the Deputy Chairperson and every other member, unless their appointment is revoked under paragraph 5 or they resign during their term of office under paragraph 6, are to hold office for such term as the Minister may determine.\nTemporary Chairperson or Deputy Chairperson\n3. The Minister may appoint any member to be a temporary Chairperson or temporary Deputy Chairperson during the temporary incapacity from illness or otherwise, or during the temporary absence from Singapore, of the Chairperson or the Deputy Chairperson, as the case may be.\nTemporary members\n4. The Minister may appoint any person to be a temporary member during the temporary incapacity from illness or otherwise, or during the temporary absence from Singapore, of any member.\nRevocation of appointment\n5. The Minister may, at any time, revoke the appointment of the Chairperson or the Deputy Chairperson or any member without assigning any reason.\nResignation\n6. Any member may resign from his or her appointment at any time by giving notice in writing to the Minister.\nVacation of office of member\n7. The office of a member is vacated if the member —\n(a)becomes in any manner disqualified for membership of the Board; or\n(b)has been absent, without leave of the Board, from 3 consecutive meetings of the Board.\nFilling of vacancy in office of member\n8. If a member dies, resigns or has his or her appointment revoked or otherwise vacates his or her office before the expiry of the term for which he or she has been appointed, another person may be appointed by the Minister for the unexpired period of the term of office of the member in whose place he or she is appointed.\nDisqualification from membership\n9. No person may be appointed or may continue to hold office as a member if he or she —\n(a)has a mental disorder and is incapable of managing himself or herself or his or her affairs;\n(b)is an undischarged bankrupt or has made any arrangement or composition with his or her creditors; or\n(c)is convicted of an offence involving dishonesty, fraud or moral turpitude and has not received a free pardon.\nSalaries, fees and allowances payable to members\n10. There are to be paid to the Chairperson, the Deputy Chairperson and other members out of the funds of the Board such salaries, fees and allowances as the Minister may determine.\nMeetings of Board\n11.—(1) The Board is to meet for the despatch of business at such times and places as the Chairperson may appoint.\n(2) The quorum for a meeting of the Board is one-half of the total number of members.\n(3) Decisions at meetings of the Board are adopted by a simple majority of the votes of the members present and voting; and in the case of an equality of votes, the Chairperson or in his or her absence the Deputy Chairperson or the member presiding has a casting vote.\n(4) The Chairperson or in his or her absence the Deputy Chairperson presides at meetings of the Board.\n(5) Where both the Chairperson and the Deputy Chairperson are absent at a meeting, such member as the members present may elect presides at the meeting.\n(6) The Board may act despite any vacancy in its membership.\n(7) Subject to the provisions of this Act and the Public Sector (Governance) Act 2018, the Board may make standing orders to regulate its own procedure and, in particular, the holding of meetings, the notice to be given of the meetings, the proceedings at the meetings, the keeping of minutes and the custody, production and inspection of the minutes.\nValidity of acts of members\n12. The acts of a member are valid despite any defect that may afterwards be discovered in his or her appointment or qualifications.\n[5/2018]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Heritage Board Act 1993","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3313"] = {"id":"SG-H3313","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NLBA1995-S54-2019?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"国家图书馆管理局（费用与收费）条例 2019","en":"National Library Board (Fees and Charges) Regulations 2019","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NLBA1995-S54-2019","completenessNote":"全文，共 4 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3313-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations are the National Library Board (Fees and Charges) Regulations 2019 and come into operation on 31 January 2019."}},{"id":"SG-H3313-A1.001","no":1.001,"noLabel":{"en":"1A."},"heading":{"en":"Definitions"},"text":{"en":"1A. In these Regulations —\n“Government‑aided school” means a school that —\n(a)is established by any person other than the Government; and\n(b)is in receipt of any grant‑in‑aid from the Government under the Education (Grant‑in‑Aid) Regulations 1982;\n“Government school” has the meaning given by section 2 of the Education Act 1957;\n“independent school” means —\n(a)a school that is conducted by a governing board established by section 3(1) of the School Boards (Incorporation) Act 1990; or\n(b)an educational institution that is set out in Part I of the Schedule to the Education Endowment and Savings Schemes (Edusave Pupils Fund) Regulations (Rg 1);\n“Institute of Technical Education” means the Institute of Technical Education, Singapore established under section 3 of the Institute of Technical Education Act 1992;\n“junior college” means —\n(a)a junior college that is organised and conducted directly by the Government to provide full‑time pre‑university education;\n(b)a junior college that is established by a person other than the Government and is conducted by a committee of management in receipt of a grant‑in‑aid from the Government to defray the costs and expenses of conducting the junior college to provide full‑time pre‑university education; or\n(c)a centralised institute that provides full‑time pre‑university education;\n“polytechnic” means a polytechnic established by a public Act;\n“special education school” means an educational institution set out in Part II of the Schedule to the Education Endowment and Savings Schemes (Edusave Pupils Fund) Regulations;\n“specified educational institution” means an educational institution set out in Part III of the Schedule to the Education Endowment and Savings Schemes (Edusave Pupils Fund) Regulations;\n“specified private education institution” means —\n(a)the LASALLE College of the Arts; or\n(b)the Nanyang Academy of Fine Arts;\n“specified school” means —\n(a)a Government‑aided school;\n(b)a Government school;\n(c)an independent school;\n(d)the Institute of Technical Education;\n(e)a junior college;\n(f)a polytechnic;\n(g)a special education school;\n(h)a specified educational institution; or\n(i)a specified private education institution.\n[S 268/2025 wef 15/04/2025]"}},{"id":"SG-H3313-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Fees and charges"},"text":{"en":"2. The fees and charges specified in the second column of the Schedule are payable to the Board in respect of the matters specified opposite in the first column."}},{"id":"SG-H3313-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nRegulation 2\nFees and charges\nFirst column\nSecond column\n1.[Deleted by S 268/2025 wef 15/04/2025]\n2.[Deleted by S 268/2025 wef 15/04/2025]\n3.[Deleted by S 268/2025 wef 15/04/2025]\n4.[Deleted by S 268/2025 wef 15/04/2025]\n5.Registration as member of library for individuals who —\n$10.69\n(a)are not citizens of Singapore; and\n(b)are not —\n(i)below 21 years of age; and\n(ii)students of a specified school\n6.Membership of library for individuals who —\n$3.82 per month or $43.60 per year\n(a)are not citizens of Singapore;\n(b)are not permanent residents of Singapore; and\n(c)are not —\n(i)below 21 years of age; and\n(ii)students of a specified school\n7.Late return of library material (other than audiovisual library material) after expiry of loan period\n$0.15 per day or part of a day\n8.Late return of audiovisual library material after expiry of loan period\n$0.50 per day or part of a day\n9.Loss or damage of library material\n$7.28 per item lost or damaged (in addition to any replacement costs of the library material)\n10.Loss of casing of audiovisual library material\n$1.07 per casing\n11.Reservation of library material\n$1.58 per item\n[S 268/2025 wef 15/04/2025]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Library Board (Fees and Charges) Regulations 2019","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3314"] = {"id":"SG-H3314","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NLBA1995-S841-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"国家图书馆管理局（规定网站）条例 2022","en":"National Library Board (Prescribed Websites) Regulations 2022","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NLBA1995-S841-2022","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3314-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations are the National Library Board (Prescribed Websites) Regulations 2022 and come into operation on 31 October 2022."}},{"id":"SG-H3314-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Prescribed websites"},"text":{"en":"2. Each of the websites specified in the Schedule is prescribed as a Singapore website within the meaning of section 2 of the Act."}},{"id":"SG-H3314-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nRegulation 2\n1. https://www.8world.com/\n2. https://www.asiaone.com/\n3. https://www.channelnewsasia.com/\n4. https://sg.news.yahoo.com/\n5. https://www.straitstimes.com/\n6. https://www.todayonline.com/"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Library Board (Prescribed Websites) Regulations 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3315"] = {"id":"SG-H3315","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NLBA1995?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":49,"structureMode":"ARTICLE","title":{"zh":"国家图书馆管理局法 1995","en":"National Library Board Act 1995","orig":null},"level":"law","status":"active","docNumber":"Act NLBA1995","completenessNote":"全文，共 49 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3315-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Short title"},"text":{"en":"1. This Act is the National Library Board Act 1995."}},{"id":"SG-H3315-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Interpretation"},"text":{"en":"2. In this Act, unless the context otherwise requires —\n“Board” means the National Library Board established under section 3;\n“Chairperson” means the Chairperson of the Board and includes any temporary Chairperson of the Board;\n“chief executive officer” means the chief executive officer of the Board and includes any person acting in that capacity;\n“Deputy Chairperson” means the Deputy Chairperson of the Board and includes any temporary Deputy Chairperson of the Board;\n“Fund” means the National Library Board Endowment Fund established under section 34;\n“library information service” means any information service provided and managed in conjunction with a library or library service;\n“library materials” means —\n(a)any book, periodical, newspaper, pamphlet, musical score, map, chart, plan, picture, photograph or matter, in printed or electronic form;\n(b)any visual image (including a computer‑generated image) or sound, or aggregate of visual images or sounds or both, or data —\n(i)embodied in or recorded on a film (including a microfilm or a microfiche), negative, tape, disc, sound track or other device or thing, so as to be capable (with or without the aid of some other equipment) of being reproduced from it; or\n(ii)transmitted by electronic means; and\n(c)any online material made available on a Singapore website;\n“member” means a member of the Board;\n“National Archives” means the National Archives of Singapore transferred by the Statutes (Miscellaneous Amendments) (No. 2) Act 2012 to the Board and administered in accordance with Part 2A;\n“National Heritage Board” means the National Heritage Board established under section 3 of the National Heritage Board Act 1993;\n“online material” means any writing, visual image, video, sound recording or data accessible to the public generally, through the Internet on a website;\n“printed”, in relation to books or other materials, means produced by printing, lithography, duplication or any other like process, and “printer” has a corresponding meaning;\n“public archives” means those public records that —\n(a)are more than 25 years old;\n(b)are specified by the Board as being of national or historical significance; and\n(c)have been transferred to the Board or to any other place that the Board may determine;\n“public office” means any department, office, institution, agency, commission, board, local authority or statutory body or any other office of the Government or branch or subdivision thereof, and any other body that the President may, by notification in the Gazette, declare to be a public office;\n“public records” means papers, documents, records, registers, printed materials, books, maps, plans, drawings, photographs, microforms, videotapes, films, machine‑readable and electronic records, sound recordings and other forms of records of any kind, that are produced or received by any public office in the transaction of official business, or by any officer in the course of his or her official duties, and includes public archives;\n“publicly funded libraries” means all libraries owned by the Government or any statutory body and such other libraries which are, directly or indirectly, funded by the Government (whether fully or partially) as the Board may determine;\n“published in Singapore”, in relation to library materials other than online material, means produced and released in Singapore for sale or public distribution;\n“publisher” means any person who arranges for any library material to be published in Singapore;\n“Singapore website” means —\n(a)any website, the country code top level domain of which is associated with Singapore; or\n(b)any prescribed website or electronic service associated with Singapore.\n[30/2018]"}},{"id":"SG-H3315-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Establishment of National Library Board"},"text":{"en":"3. A body called the National Library Board is established, which is a body corporate with perpetual succession and is by that name capable of —\n(a)suing and being sued;\n(b)acquiring, owning, holding, developing and disposing of property, both movable and immovable; and\n(c)doing and suffering all such acts or things as bodies corporate may lawfully do or suffer."}},{"id":"SG-H3315-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Common seal"},"text":{"en":"4.—(1) The Board must have a common seal which must be kept in such custody as the Board thinks fit.\n(2) All deeds and other documents requiring the seal of the Board must be sealed with the common seal of the Board and every document to which the common seal is affixed must be signed by any 2 members of the Board generally or specially authorised by the Board for the purpose or by one member so authorised and the chief executive officer.\n(3) All courts, judges and persons acting judicially are to take judicial notice of the common seal of the Board affixed to any document and presume that it was duly affixed."}},{"id":"SG-H3315-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Constitution of Board"},"text":{"en":"5.—(1) The Board consists of —\n(a)a Chairperson;\n(b)a Deputy Chairperson; and\n(c)not less than 10 but not more than 20 other members as the Minister may determine.\n(2) The Schedule has effect with respect to the Board, its members and proceedings."}},{"id":"SG-H3315-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Functions of Board"},"text":{"en":"6. The functions of the Board are —\n(a)to establish and maintain libraries and to provide library information services;\n(b)to promote reading and encourage learning through the use of libraries and their services;\n(c)to provide a repository for library materials published in Singapore;\n(d)to acquire and maintain a comprehensive collection of library materials relating to Singapore and its people;\n(e)to establish standards for the training of library personnel in Singapore;\n(f)to provide advisory and consultancy services concerning libraries and library information services;\n(g)to compile and maintain a national union catalogue and a national bibliography;\n(h)to advise the Government on national needs and policies in respect of matters relating to publicly funded libraries and library information services in Singapore;\n(i)to provide a permanent repository of records of national or historical significance and to facilitate access to those records;\n(j)to conduct records management programmes for the Government; and\n(k)to record, preserve and disseminate the history of Singapore through oral history methodology or other means."}},{"id":"SG-H3315-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Powers of Board"},"text":{"en":"7.—(1) The Board has power to do all things necessary or convenient to be done for or in connection with the performance of its functions.\n(2) Without limiting subsection (1), the powers of the Board include power —\n(a)to develop and manage libraries established by the Board;\n(b)to develop a computer network of libraries in Singapore;\n(c)to define, develop and implement the national collection policy and strategy, and appoint different libraries and centres to collect library materials on different subject areas of importance and interest to Singapore;\n(d)to coordinate and facilitate access to library materials in all publicly funded libraries;\n(e)to obtain and provide information on the resources and services of libraries in Singapore;\n(f)to take appropriate measures to maintain and preserve library materials deposited with the Board under section 10 or otherwise acquired by the Board;\n(g)to make copies of any online material made available on a Singapore website, at the times and in the manner the Board considers appropriate;\n(h)to establish liaison with other library authorities and information providers and other archives and oral history centres (foreign or otherwise) to secure maximum collaboration of all activities relevant to the Board’s functions;\n(i)to undertake or sponsor programmes for the training of persons in the profession and skills involved in the operations of libraries, archives and oral history centres;\n(j)to arrange for or provide professional and technical services in connection with libraries on such terms and conditions as the Board may determine;\n(k)to undertake and facilitate research on libraries, librarianship, archival work and oral history;\n(l)to raise funds by all lawful means and to receive gifts and donations, whether on trust or otherwise;\n(m)to extend grants, contributions or loans to any person or organisation connected with the national literary heritage or library development in Singapore for purposes consistent with the provisions of this Act;\n(n)to enter into contracts and establish trusts;\n(o)to enter into joint ventures with any person or organisation, or form or participate in the formation of a company;\n(p)to provide or undertake publicity in any form; and\n(q)to charge fees, commissions or rent for any services or facilities provided by the Board.\n[30/2018]"}},{"id":"SG-H3315-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Directors and advisory committees for libraries"},"text":{"en":"8. The Board may appoint directors for the general management and control of the libraries it has established and may also appoint advisory committees to advise on the operations and services of those libraries."}},{"id":"SG-H3315-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Appointment of committees and delegation of powers"},"text":{"en":"9.—(1) The Board may appoint, from among its own members or other persons who are not members of the Board, any number of committees that it may think fit consisting of members or other persons or members and other persons for purposes which, in the opinion of the Board, would be better regulated and managed by means of those committees.\n(2) The Board may, subject to any conditions or restrictions that it may think fit, delegate to any such committee or to any member, officer or employee of the Board, any of the functions or powers of the Board under this Act.\n[5/2018]"}},{"id":"SG-H3315-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Deposit of library materials"},"text":{"en":"10.—(1) Except as otherwise provided by regulations, the publisher of every library material (other than online material) published in Singapore must, at the publisher’s own expense —\n(a)subject to paragraph (b), deposit 2 copies of that library material with the Board at a place determined by the Board within 4 weeks after the date of first publication; and\n(b)where the library material is in electronic form, deposit a copy of that library material with the Board in the form and manner determined by the Board, free of any technological or other restriction on access, within 4 weeks after the date of first publication.\n[30/2018]\n(2) The Board may by regulations made under section 47 prescribe —\n(a)the library materials which are not required to be deposited with the Board; and\n(b)the quality and the format of the copies of library materials required to be deposited, and the manner in which they must be deposited.\n[30/2018]\n(3) Every publisher of any library material who contravenes this section shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000."}},{"id":"SG-H3315-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Establishment of national union catalogue"},"text":{"en":"11.—(1) All publicly funded libraries must contribute their cataloguing and holding records, whether original or derived from other sources, towards the establishment of an up‑to‑date national union catalogue.\n(2) The Board may by regulations made under section 47 prescribe —\n(a)the standard and the format of the cataloguing and holding records required to be sent to the Board; and\n(b)the frequency of updating the cataloguing and holding records in the national union catalogue.\n[30/2018]"}},{"id":"SG-H3315-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Participation in interlibrary loan scheme"},"text":{"en":"12. All publicly funded libraries must participate in such scheme for interlibrary loan and interlibrary information services as may be established by the Board in consultation with such libraries."}},{"id":"SG-H3315-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 2 ESTABLISHMENT, CONSTITUTION, FUNCTIONSAND POWERS OF BOARD"},"heading":{"en":"Directions by Minister"},"text":{"en":"13.—(1) The Minister may give to the Board any direction under section 5 of the Public Sector (Governance) Act 2018.\n[5/2018]\n(2) The Board must give the Minister such information with regard to its property and activities as the Minister may require.\n[14"}},{"id":"SG-H3315-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"National Archives of Singapore"},"text":{"en":"14.—(1) On 28 March 2013, the National Archives of Singapore in which records of national or historical significance are preserved is transferred from the National Heritage Board to the Board.\n(2) The Board —\n(a)must examine the public records in any public office and advise that office as to their care and custody;\n(b)must take necessary measures to classify, identify, preserve and restore public records;\n(c)must make known information concerning archives by any means, including publications, exhibitions and heritage promotional activities;\n(d)must conduct a records management programme for the efficient creation, utilisation, maintenance, retention, preservation and disposal of public records;\n(e)must advise public offices concerning standards and procedures pertaining to the management of public records;\n(f)may provide information, consultation, research and other services related to archives;\n(g)may, subject to the terms and conditions (if any) on which the public archives were acquired, reproduce or publish any public archives; and\n(h)may acquire by purchase, donations, bequest or otherwise any document, book or other material which, in the opinion of the Board, is or is likely to be of national or historical significance.\n[14A"}},{"id":"SG-H3315-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Appointment of Director of National Archives"},"text":{"en":"15.—(1) The Board must appoint an officer of the Board as the Director of National Archives, who is responsible to the Board for the general management and control of the National Archives.\n(2) The Director of National Archives, and any person acting on behalf or under the direction of the Director of National Archives, must, with respect to access to public records, satisfy any security requirements applicable to, and take any oath of secrecy required to be taken by, persons who normally have access to the public records.\n(3) To avoid doubt, where an oath of secrecy is required to be taken under subsection (2), a person may take the oath by appearing before the person administering the oath through a live video link or live television link created using a remote communication technology that allows the person administering the oath to —\n(a)maintain visual contact and communicate with the person taking the oath, and any interpreter present, throughout the process; and\n(b)confirm the identity of the person taking the oath and any interpreter present.\n[Act 25 of 2023 wef 01/12/2023]\n[14B"}},{"id":"SG-H3315-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Transfer of public records to National Archives"},"text":{"en":"16. Any public records which, in the opinion of the Board, are of national or historical significance must be transferred to the care and control of the National Archives in accordance with such schedules or other agreements for the transfer of records as may be agreed on between the Board and the public office responsible for the public records.\n[14C"}},{"id":"SG-H3315-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Destruction or disposal of public records only on authority of Board"},"text":{"en":"17.—(1) A person must not, without the authorisation of the Board under subsection (4), destroy or otherwise dispose of, or authorise the destruction or disposal of, any public records which are in the person’s possession or under the person’s control.\n(2) Any person intending to destroy or dispose of, or to authorise the destruction or disposal of, any public records must first notify the Board of that intention and must, in the person’s notification, specify the nature of the public records in question.\n(3) The Board may inspect any public records specified in any notification under subsection (2) and must, if it requires those records to be made available to it, inform the person making the notification of that requirement, and the public records must be made available to the Board.\n(4) The Board may authorise the destruction of any specified classes of public records which by reason of their number, kind or routine nature do not in its opinion possess any enduring value for preservation as public archives.\n[14D"}},{"id":"SG-H3315-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Inspection of public records and recordings"},"text":{"en":"18.—(1) Except with the written authority of the Director of National Archives, a person who is not an officer of the National Archives must not inspect any public records or recordings that are not made available to the public under subsection (2).\n(2) Any person may, for the purpose of reference or research, inspect any public archives or recordings made available to the public subject to —\n(a)any conditions or restrictions imposed with the authority of the public office from which the public archives were acquired or the producer or distributor which provided the recordings, as the case may be; and\n(b)any conditions that the Director of National Archives may consider necessary for their preservation.\n(3) The National Archives are to be open for the inspection of public records during such hours as the Board may determine.\n(4) In this section, “recording” means any recording deposited with the Board under section 22.\n[14E"}},{"id":"SG-H3315-A19","no":19,"noLabel":{"en":"19."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Certified copy of public records"},"text":{"en":"19. Any copy of a public record which is certified by the Director of National Archives as a true copy of the original document is admissible in a court of law.\n[14F"}},{"id":"SG-H3315-A20","no":20,"noLabel":{"en":"20."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Reproduction of public records and recordings"},"text":{"en":"20.—(1) A person must not publish or reproduce the whole or any part of the contents of any public records which have been transferred to the National Archives or of any recording which has been deposited under section 22 except with the written consent of the Director of National Archives and in accordance with any conditions or restrictions that may be imposed with the authority of —\n(a)the public office from which the public records were acquired; or\n(b)the producer or distributor which provided the recordings,\nas the case may be.\n(2) Any person who contravenes subsection (1) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 12 months or to both.\n(3) Nothing in this section is to be construed as affecting or extending the law relating to copyright.\n[14G"}},{"id":"SG-H3315-A21","no":21,"noLabel":{"en":"21."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Prohibition of export, etc., of public records"},"text":{"en":"21.—(1) A person must not —\n(a)without the written permission of the Board, take or send out of Singapore any public records;\n(b)write on, mark, inscribe or otherwise deface any public records; or\n(c)mutilate, excise or otherwise damage any public records.\n(2) Any person who contravenes subsection (1) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 12 months or to both.\n[14H"}},{"id":"SG-H3315-A22","no":22,"noLabel":{"en":"22."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Deposit of certain recordings"},"text":{"en":"22.—(1) The producer or distributor of a recording must, within 6 months after a request in writing is made by the Board, provide (without charge) the Board with a copy of the recording in such form as may be specified in the request.\n(2) Any person who fails to comply with subsection (1) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 12 months or to both.\n(3) This section does not apply to or in respect of —\n(a)a recording that has not been broadcast or made public in Singapore; or\n(b)any recording of a class or kind that is exempted from the application of this section by any regulations that the Minister may make for the purpose.\n(4) In this section, “recording” means anything in which sounds are embodied or on which images are fixed or both, regardless of form.\n[14I"}},{"id":"SG-H3315-A23","no":23,"noLabel":{"en":"23."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Oral history centres"},"text":{"en":"23.—(1) The Board may, in addition to any oral history centre transferred under section 24, establish any other oral history centre for the purposes of this Act.\n(2) The purposes of any oral history centre transferred to the Board under section 24 or established by the Board under this section are —\n(a)to collect, document and disseminate information on the history of Singapore through oral history methodology or other means;\n(b)to interview persons who have influenced or participated in the history of Singapore, to preserve these interviews and to produce transcripts of selected interviews;\n(c)to preserve and care for the recordings and transcripts of such interviews;\n(d)to allow access to the recordings and transcripts of such interviews to persons seeking to inspect them in connection with study or research subject to any conditions or restrictions imposed by the interviewee or the Board; and\n(e)to disseminate information on the collection and work of the centre by any means, including publications, audiovisual educational packages, exhibitions, consultations, research and heritage promotional activities.\n[14J"}},{"id":"SG-H3315-A24","no":24,"noLabel":{"en":"24."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Transfer of archive undertakings, etc., from National Heritage Board"},"text":{"en":"24.—(1) All the lands, buildings and other property, movable or immovable, vested in the National Heritage Board immediately before 28 March 2013 (called in this section the transfer date) for the purposes of —\n(a)the National Archives; or\n(b)any oral history centre established by the National Heritage Board,\nand all assets, powers, interests, rights, privileges, debts, liabilities and obligations of the National Heritage Board relating to paragraph (a) or (b) become, on the transfer date, by virtue of this section and without further assurance, the property, assets, powers, interests, rights, privileges, debts, liabilities and obligations of the Board.\n(2) Every agreement relating to any of the properties, assets, interests, rights, privileges, liabilities or obligations transferred under subsection (1) and to which the National Heritage Board was a party immediately before the transfer date, whether or not of such nature that the rights and liabilities could be assigned, has effect as from that date as if —\n(a)the Board had been a party to such an agreement; and\n(b)for any reference to the National Heritage Board there were substituted in respect of anything to be done on or after the transfer date a reference to the Board.\n(3) If any question arises as to whether any particular property, asset, interest, right, privilege, liability or obligation has been transferred to or vested in the Board under subsection (1), a certificate under the hand of the Minister charged with the responsibility for finance is conclusive evidence that the property, asset, interest, right, privilege, liability or obligation was or was not so transferred or vested.\n(4) Any proceedings or cause of action pending or existing immediately before the transfer date by or against the National Heritage Board relating to the National Archives or any oral history centre transferred under subsection (1) may be continued and are to be enforced by or against the Board.\n(5) The operation of subsections (1), (2) and (3) is not to be regarded —\n(a)as a breach of contract or confidence or otherwise as a civil wrong;\n(b)as a breach of any contractual provision prohibiting, restricting or regulating the assignment or transfer of assets or liabilities;\n(c)as giving rise to any remedy by a party to a legal instrument, or as causing or permitting the termination of any legal instrument, because of a change in the beneficial or legal ownership of any asset or liability; or\n(d)as an event of default under any contract or other legal instrument.\n(6) Any provision in any existing contract, agreement, conveyance, deed, lease, guarantee, bond, indemnity and other instrument or undertaking to which the National Heritage Board is a party or may be bound prohibiting or having the effect of prohibiting the transfer of any property, assets, interests, rights, privileges, liabilities or obligations comprised in the undertaking transferred under subsection (1) is deemed by this Act to have been waived.\n(7) No attornment to the Board by a lessee from the National Heritage Board is required.\n[14K"}},{"id":"SG-H3315-A25","no":25,"noLabel":{"en":"25."},"chapter":{"en":"PART 2A NATIONAL ARCHIVES OF SINGAPORE AND ORAL HISTORY CENTRES"},"heading":{"en":"Transfer of employees from National Heritage Board, etc."},"text":{"en":"25.—(1) On 28 March 2013 (called in this section the transfer date), such categories of persons employed by the National Heritage Board immediately before that date in —\n(a)the National Archives; or\n(b)any oral history centre established by the National Heritage Board,\nas the Minister may determine are transferred to the service of the Board on terms no less favourable than those enjoyed by them immediately prior to their transfer.\n(2) Until such time as terms and conditions of service are drawn up by the Board, the scheme and terms and conditions of service in the National Heritage Board continue to apply to every person transferred to the service of the Board under subsection (1) as if he or she were still in the service of the National Heritage Board.\n(3) The terms and conditions of employment to be drawn up by the Board —\n(a)must take into account the salaries and terms and conditions of service, including any accrued rights to leave, enjoyed by the persons transferred to the service of the Board under this section while in the employment of the National Heritage Board;\n(b)in the case of any such term or condition relating to the length of service with the Board, must provide for the recognition of service under the National Heritage Board by the persons so transferred as service by them under the Board; and\n(c)must not adversely affect the conditions that would have been applicable to persons transferred to the service of the Board as regards any pension, gratuity or allowance payable under the Pensions Act 1956.\n(4) All deeds, schemes, bonds, agreements, instruments and arrangements subsisting immediately before the transfer date to which the National Heritage Board is a party and relating to any person transferred to the service of the Board under subsection (1) continue in force on and after that date and are enforceable by or against the Board as if the Board had been named therein or had been a party thereto instead of the National Heritage Board.\n(5) Any proceedings or cause of action relating to any employee transferred to the service of the Board under subsection (1) pending or existing immediately before the transfer date by or against the National Heritage Board, or any person acting on its behalf, may be continued and are to be enforced by or against the Board.\n(6) Where on the transfer date —\n(a)any disciplinary proceedings were pending against any employee of the National Heritage Board transferred to the service of the Board under subsection (1), the proceedings are to be carried on and completed by the Board; and\n(b)any matter was in the course of being heard or investigated or had been heard or investigated by a committee of the National Heritage Board acting under due authority but no order, ruling or decision had been made thereon, the committee is to complete the hearing or investigation and make such order, ruling or direction as it could have made under the authority vested in it before that date.\n(7) Any order, ruling or direction made by such a committee pursuant to subsection (6) is to be treated as an order, a ruling or a direction of the Board and has the same force or effect as if it had been made by the Board pursuant to the authority vested in the Board under this Act.\n(8) The Board may reprimand, reduce in rank, retire, dismiss or punish in some other manner a person transferred to the service of the Board under subsection (1) for any misconduct or neglect of duty committed before the transfer date which would have rendered that person liable to be reprimanded, reduced in rank, retired, dismissed or punished in some other manner if that person had continued to be in the employment of the National Heritage Board and if this Act had not been enacted.\n(9) To avoid doubt, section 18A of the Employment Act 1968 does not apply to the transfer under this section of any employee of the National Heritage Board to the Board.\n(10) Notwithstanding any other written law or any contract, no person who is transferred from the National Heritage Board to the service of the Board under subsection (1) is entitled to claim any benefit under that written law or contract for termination of his or her service on the ground of redundancy or abolition of his or her office in consequence of the transfer of the National Archives or any oral history centre from the National Heritage Board to the Board.\n(11) Except as otherwise provided in this section, nothing in subsection (1) prevents the terms and conditions of a transferred employee’s employment on or after the transfer date from being varied in accordance with those terms and conditions, or by or under any written law, or an award, a determination or an agreement; and “vary”, in relation to terms and conditions of service, includes omitting any of those terms and conditions, adding to those terms and conditions, or substituting new terms and conditions for any of those terms and conditions.\n(12) In every case where a person transferred to the service of the Board under this section is also a person transferred from the employment of the Government to the National Heritage Board under section 40 of the National Heritage Board Act 1993, the Government and the National Heritage Board are each liable to pay the Board such portion of any gratuity, pension or allowance payable under the Pensions Act 1956 to such person on his or her retirement as the same bears to the proportion which the aggregate amount of his or her pensionable emoluments during his or her service with the Government and the National Heritage Board, respectively, bears to the aggregate amount of his or her pensionable emoluments during his or her total service under the Government, the National Heritage Board and the Board.\n[14L"}},{"id":"SG-H3315-A26","no":26,"noLabel":{"en":"26."},"chapter":{"en":"PART 3 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Chief executive officer"},"text":{"en":"26.—(1) There must be a chief executive officer of the Board, whose appointment, removal, discipline and promotion must be in accordance with the Public Sector (Governance) Act 2018.\n[5/2018]\n(2) The Board may, subject to the Public Sector (Governance) Act 2018, appoint an individual to act temporarily as the chief executive officer during any period, or during all periods, when the chief executive officer —\n(a)is absent from duty or Singapore; or\n(b)is, for any reason, unable to perform the duties of the office.\n[15\n[5/2018]"}},{"id":"SG-H3315-A27","no":27,"noLabel":{"en":"27."},"chapter":{"en":"PART 3 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Appointment of staff"},"text":{"en":"27. The Board may, subject to the Public Sector (Governance) Act 2018, appoint and employ, on such terms and conditions as it may determine, such other officers, employees, consultants and agents as may be necessary for the effective performance of its functions.\n[16\n[5/2018]"}},{"id":"SG-H3315-A28","no":28,"noLabel":{"en":"28."},"chapter":{"en":"PART 4 FINANCIAL PROVISIONS"},"heading":{"en":"Funds of Board"},"text":{"en":"28. The funds of the Board consist of —\n(a)all moneys received by the Board by way of grants;\n(b)all gifts, donations and contributions to the Board;\n(c)all fees, commissions, rents, interests, dividends and other income accruing to the Board;\n(d)all moneys borrowed by the Board under this Act; and\n(e)all other moneys lawfully received by the Board for the purposes of the Board.\n[18"}},{"id":"SG-H3315-A29","no":29,"noLabel":{"en":"29."},"chapter":{"en":"PART 4 FINANCIAL PROVISIONS"},"heading":{"en":"Bank accounts and application of moneys"},"text":{"en":"29.—(1) The Board may open and maintain an account or accounts with such bank or banks as the Board thinks fit and every such account must be operated as far as practicable by cheque signed by such person or persons authorised to do so by the Board.\n(2) The moneys of the Board must be applied only in payment or discharge of the expenses, obligations and liabilities of the Board and in making any payments that the Board is authorised or required to make.\n[19"}},{"id":"SG-H3315-A30","no":30,"noLabel":{"en":"30."},"chapter":{"en":"PART 4 FINANCIAL PROVISIONS"},"heading":{"en":"Power of investment"},"text":{"en":"30. The Board may invest its funds in accordance with the standard investment power of statutory bodies as defined in section 33A of the Interpretation Act 1965.\n[20"}},{"id":"SG-H3315-A31","no":31,"noLabel":{"en":"31."},"chapter":{"en":"PART 4 FINANCIAL PROVISIONS"},"heading":{"en":"Power to borrow"},"text":{"en":"31. The Board may from time to time for the purposes of this Act raise loans from the Government or, with the consent of the Minister, from any other source.\n[21"}},{"id":"SG-H3315-A32","no":32,"noLabel":{"en":"32."},"chapter":{"en":"PART 4 FINANCIAL PROVISIONS"},"heading":{"en":"Issue of shares, etc."},"text":{"en":"32. As a consequence of the vesting of any property, rights or liabilities of the Government in the Board under this Act, or of any capital injection or other investment by the Government in the Board in accordance with any written law, the Board must issue such shares or other securities to the Minister for Finance as that Minister may from time to time direct.\n[21A"}},{"id":"SG-H3315-A33","no":33,"noLabel":{"en":"33."},"chapter":{"en":"PART 4 FINANCIAL PROVISIONS"},"heading":{"en":"Grants"},"text":{"en":"33. For the purpose of enabling the Board to carry out its functions under this Act, the Minister may from time to time make grants to the Board of such sums of money as the Minister may determine out of moneys to be provided by Parliament.\n[22"}},{"id":"SG-H3315-A34","no":34,"noLabel":{"en":"34."},"chapter":{"en":"PART 4 FINANCIAL PROVISIONS"},"heading":{"en":"Establishment of National Library Board Endowment Fund"},"text":{"en":"34.—(1) A fund called the National Library Board Endowment Fund is established, which vests in the Board and consists of —\n(a)all moneys received by the Board by gifts, bequests or otherwise for the Fund;\n(b)any contributions to the Fund that the Minister may specify from moneys provided by Parliament; and\n(c)any other moneys that the Board may decide to transfer to the Fund.\n(2) The income of the Fund is to be applied for all or any of the following purposes:\n(a)the provision of training programmes and scholarships for librarians and persons working in libraries;\n(b)the delivery of lectures by distinguished persons in the field of library and information science;\n(c)the sponsorship of major library promotional programmes;\n(d)the financing of research on reading and librarianship;\n(e)any other purposes consistent with this Act that the Board may decide.\n[23"}},{"id":"SG-H3315-A35","no":35,"noLabel":{"en":"35."},"chapter":{"en":"PART 4 FINANCIAL PROVISIONS"},"heading":{"en":"Financial year"},"text":{"en":"35. The financial year of the Board begins on 1 April of each year and ends on 31 March of the succeeding year.\n[24\n[5/2018]"}},{"id":"SG-H3315-A36","no":36,"noLabel":{"en":"36."},"chapter":{"en":"PART 5 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Transfer of assets and liabilities"},"text":{"en":"36.—(1) As from 1 September 1995, all movable property vested in the Government immediately before that date and used or managed by the National Library and all assets, rights, interests, liabilities and obligations of the Government relating to the National Library are transferred to and vest in the Board without further assurance.\n(2) As from 1 September 1995, the Board controls and manages all the libraries which are under the control of the National Library.\n(3) If any question arises as to whether any particular property, or whether any particular asset, right, interest, liability or obligation has been transferred to or vested in the Board under subsection (1), a certificate under the hand of the Minister for Finance is conclusive evidence that the property, asset, right, interest, liability or obligation was or was not so transferred or vested.\n[25"}},{"id":"SG-H3315-A37","no":37,"noLabel":{"en":"37."},"chapter":{"en":"PART 5 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Existing agreements, etc."},"text":{"en":"37. All deeds, bonds, agreements, instruments and arrangements, subsisting immediately before 1 September 1995, affecting any of the property, rights, interests, liabilities and obligations transferred to or vested in the Board under section 36(1) continue in force on and after that date and are enforceable by or against the Board as if, instead of the Government or a person acting on behalf of the Government, the Board had been named therein or had been a party thereto.\n[26"}},{"id":"SG-H3315-A38","no":38,"noLabel":{"en":"38."},"chapter":{"en":"PART 5 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Pending legal proceedings"},"text":{"en":"38. Any proceedings or cause of action pending or existing immediately before 1 September 1995 by or against the Government or any person acting on behalf of the Government relating to the National Library may be continued and enforced by or against the Board.\n[27"}},{"id":"SG-H3315-A39","no":39,"noLabel":{"en":"39."},"chapter":{"en":"PART 5 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Transfer of employees"},"text":{"en":"39.—(1) As from 1 September 1995, such categories of persons employed immediately before that date in the National Library as the Minister may determine are transferred to the service of the Board on terms no less favourable than those enjoyed by them immediately prior to their transfer.\n(2) Until such time as terms and conditions of service are drawn up by the Board, the scheme and terms and conditions of service in the Government continue to apply to every person transferred to the service of the Board under subsection (1) as if he or she were still in the service of the Government.\n[28"}},{"id":"SG-H3315-A40","no":40,"noLabel":{"en":"40."},"chapter":{"en":"PART 5 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Pension rights, etc., of Government employees to be preserved"},"text":{"en":"40.—(1) The terms and conditions of service of persons transferred to the service of the Board under section 39 must take into account the salaries and terms and conditions of service, including any accrued rights to leave, enjoyed by such persons while in the employment of the Government and any such term or condition relating to the length of service with the Board must provide for the recognition of service under the Government by persons so transferred to be service by them under the Board.\n(2) Nothing in the terms and conditions of service to be drawn up by the Board adversely affects the conditions that would have been applicable to persons transferred to the service of the Board as regards any pension, gratuity or allowance payable under the Pensions Act 1956.\n(3) In every case where a person has been transferred to the service of the Board under section 39, the Government is liable to pay the Board such portion of any gratuity, pension or allowance payable to that person on his or her retirement as the same bears to the proportion which the aggregate amount of his or her pensionable emoluments during his or her service with the Government bears to the aggregate amount of his or her pensionable emoluments during his or her service under both the Government and the Board.\n[29"}},{"id":"SG-H3315-A41","no":41,"noLabel":{"en":"41."},"chapter":{"en":"PART 5 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"No benefits in respect of abolition or reorganisation of office"},"text":{"en":"41. Notwithstanding the provisions of the Pensions Act 1956, no person who is transferred to the service of the Board under section 39 is entitled to claim any benefit under the Pensions Act 1956 on the ground that he or she has been retired from the service of the Government on account of abolition or reorganisation of office in consequence of the establishment and incorporation of the Board.\n[30"}},{"id":"SG-H3315-A42","no":42,"noLabel":{"en":"42."},"chapter":{"en":"PART 5 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Continuation and completion of disciplinary proceedings"},"text":{"en":"42.—(1) Where on 1 September 1995, any disciplinary proceedings are pending against any person transferred to the service of the Board under section 39, any committee acting under due authority to hear or investigate the matter continues to exist, notwithstanding this Act, for the purpose of completing the hearing or investigation and the making of an order or rendering a decision (as the case may be), and the Government or committee is to complete the hearing or investigation in accordance with the authority vested in the Government or committee immediately before that date and make such order, ruling or direction as the Government or committee could have made under the authority vested in it immediately before that date.\n(2) Any order, ruling or direction made or given by the Government or committee pursuant to this section is to be treated as an order, a ruling or a direction of the Board and has the same force or effect as if it had been made or given by the Board pursuant to the power vested in the Board under this Act.\n[31"}},{"id":"SG-H3315-A43","no":43,"noLabel":{"en":"43."},"chapter":{"en":"PART 5 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES"},"heading":{"en":"Misconduct or neglect of duty by employee before transfer"},"text":{"en":"43. The Board may reprimand, reduce in rank, retire, dismiss or punish in some other manner a person transferred to the service of the Board under section 39 for any misconduct or neglect of duty committed prior to 1 September 1995 which would have rendered him or her liable to be reprimanded, reduced in rank, retired, dismissed or punished in some other manner if he or she had continued to be in the employment of the Government and if this Act had not been enacted.\n[32"}},{"id":"SG-H3315-A44","no":44,"noLabel":{"en":"44."},"chapter":{"en":"PART 6 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Board’s symbol"},"text":{"en":"44.—(1) The Board has the exclusive right to use such symbol or representation as it may select or devise and display or exhibit in connection with its activities or affairs.\n(2) A person who, without the permission of the Board, uses a symbol or representation identical with that of the Board or which so resembles the Board’s symbol or representation as to deceive or cause confusion, or to be likely to deceive or cause confusion, shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 6 months or to both.\n[33"}},{"id":"SG-H3315-A45","no":45,"noLabel":{"en":"45."},"chapter":{"en":"PART 6 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Composition of offences"},"text":{"en":"45.—(1) The chief executive officer, or an officer or employee of the Board authorised in writing by the Board, may compound any offence under this Act that is prescribed as a compoundable offence by collecting from a person reasonably suspected of having committed the offence a sum not exceeding $500.\n[30/2018]\n(2) On payment of the sum of money, no further proceedings are to be taken against that person in respect of the offence.\n[30/2018]\n(3) All sums collected under this section must be paid into the Consolidated Fund.\n[33A\n[30/2018]"}},{"id":"SG-H3315-A46","no":46,"noLabel":{"en":"46."},"chapter":{"en":"PART 6 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Protection from personal liability"},"text":{"en":"46. No suit or other legal proceedings shall lie personally against any member, officer or employee of the Board or other person acting under the direction of the Board for anything which is in good faith done or intended to be done in the execution or purported execution of this Act.\n[34"}},{"id":"SG-H3315-A47","no":47,"noLabel":{"en":"47."},"chapter":{"en":"PART 6 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Regulations"},"text":{"en":"47.—(1) The Board may, with the approval of the Minister, make regulations for carrying out the purposes and provisions of this Act and for prescribing any matter which may be prescribed under this Act.\n(2) Without limiting subsection (1), the regulations may —\n(a)provide for the use of its libraries and library buildings and of their contents, fittings and furniture, and for protecting them from injury, destruction or misuse;\n(b)require from any persons using its libraries a guarantee or security against the loss of, or injury to, any library materials belonging to the libraries;\n(c)provide for the use, custody, preservation, reproduction, removal, destruction and disposal of public records and other documents under this Act;\n(d)provide for regulating the taking of oral history recordings and transcripts;\n(e)enable the officers or employees of the Board to exclude or remove from its libraries, library buildings, the National Archives, any oral history centre or any other land or building owned by or under the control of the Board persons committing any offence under this Act or any of its regulations;\n(f)provide for the preservation of order and the prevention of nuisance in any library, library building, the National Archives, any oral history centre or any other land or building owned by or under the control of the Board;\n(g)fix the days and times of admission to its libraries;\n(h)provide for the admission of vehicles to the grounds of its libraries and the regulation of traffic in those grounds;\n(i)prescribe the charges for the damage, loss or late return of borrowed library materials and for the waiving or refund of those charges; and\n(j)prescribe that any act or omission in contravention of the provisions of any regulations made under this Act shall be an offence and imposing penalties for those offences, which penalties shall not exceed a fine of $5,000.\n[35\n[30/2018]"}},{"id":"SG-H3315-A48","no":48,"noLabel":{"en":"48."},"chapter":{"en":"PART 6 MISCELLANEOUS PROVISIONS"},"heading":{"en":"Transitional provision"},"text":{"en":"48. Any scheme, contract, document, certificate, licence, permission or resolution prepared, made, granted or approved under the repealed National Library Act (Cap. 197, 1985 Revised Edition) continues and is, so far as it is not inconsistent with the provisions of this Act, deemed to have been prepared, made, granted or approved under this Act.\n[36"}},{"id":"SG-H3315-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nSection 5(2)\nConstitution and proceedings of Board\nAppointment of Chairperson, Deputy Chairperson and other members\n1.—(1) The Chairperson, the Deputy Chairperson and other members must be appointed by the Minister.\n(2) The Deputy Chairperson may, subject to any directions that the Chairperson may give, exercise all or any of the powers exercisable by the Chairperson under this Act.\n(3) The Minister may appoint the chief executive officer to be a member of the Board.\nTenure of office of members\n2. The Chairperson, the Deputy Chairperson and every other member hold office on such terms and conditions and for such period as the Minister may determine and are eligible for re‑appointment.\nTemporary Chairperson or Deputy Chairperson\n3. The Minister may appoint any member to be a temporary Chairperson or a temporary Deputy Chairperson during the temporary incapacity from illness or otherwise, or during the temporary absence from Singapore, of the Chairperson or the Deputy Chairperson, as the case may be.\nTemporary members\n4. The Minister may appoint any person to be a temporary member during the temporary incapacity from illness or otherwise, or during the temporary absence from Singapore, of any member.\nRevocation of appointment\n5. The Minister may, at any time, revoke the appointment of the Chairperson or the Deputy Chairperson or any member without giving any reason.\nResignation\n6. Any member may resign from his or her appointment at any time by giving written notice to the Minister.\nVacation of office\n7. The office of a member is vacated if the member —\n(a)becomes in any manner disqualified for membership of the Board; or\n(b)has been absent, without leave of the Board, from 3 consecutive meetings of the Board.\nFilling of vacancy in office of member\n8. If a member dies, resigns or has his or her appointment revoked or otherwise vacates his or her office before the expiry of the term for which he or she has been appointed, another person may be appointed by the Minister for the unexpired period of the term of office of the member in whose place he or she is appointed.\nDisqualification from membership\n9. A person must not be appointed or continue to hold office as a member if he or she —\n(a)is an undischarged bankrupt or has made any arrangement or composition with his or her creditors; or\n(b)is convicted of an offence involving dishonesty, fraud or moral turpitude and has not received a free pardon.\nSalaries, fees and allowances payable to members\n10. There are to be paid to the Chairperson, the Deputy Chairperson and other members out of the funds of the Board such salaries, fees and allowances as the Minister may determine.\nMeetings of Board\n11.—(1) The Board is to meet for the despatch of business at such times and places as the Chairperson may appoint.\n(2) At every meeting of the Board, one half of the total number of members forms a quorum.\n(3) Decisions at meetings of the Board are to be adopted by a simple majority of the votes of the members present and voting and, in the case of an equality of votes, the Chairperson or, in his or her absence, the Deputy Chairperson or the member presiding has a casting vote in addition to his or her original vote.\n(4) The Chairperson or in his or her absence the Deputy Chairperson presides at meetings of the Board.\n(5) Where both the Chairperson and the Deputy Chairperson are absent at a meeting, such member as the members present may elect presides at the meeting.\n(6) The Board may act despite any vacancy in its membership.\n(7) Subject to the provisions of this Act and the Public Sector (Governance) Act 2018, the Board may make rules to regulate its own procedure and, in particular, for the holding and proceedings of meetings, the notice to be given of the meetings, the keeping of minutes and the custody, production and inspection of the minutes.\nValidity of proceedings\n12. The validity of any proceedings of the Board is not affected by any defect in the appointment of any member.\n[5/2018]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Library Board Act 1995","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3316"] = {"id":"SG-H3316","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NPBA1996-S270-2019?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"国家公园局（认证标志）公告 2019","en":"National Parks Board (Certification Marks) Notification 2019","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NPBA1996-S270-2019","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3316-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the National Parks Board (Certification Marks) Notification 2019 and comes into operation on 1 April 2019."}},{"id":"SG-H3316-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Certification mark"},"text":{"en":"2. The International Plant Protection Convention (IPPC) Mark (defined under the International Standards on Phytosanitary Measures (ISPM 15)) set out in the Schedule is a certification mark of the Board for the export of wood packaging materials."}},{"id":"SG-H3316-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nParagraph 2\nCertification mark for the export of\nwood packaging materials\n*SG-000 is a unique number assigned by the Board to the authorised agency that performs treatment standards defined under ISPM 15."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Parks Board (Certification Marks) Notification 2019","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3317"] = {"id":"SG-H3317","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NPBA1996-S209-2019?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"国家公园局（移交日期）命令 2019","en":"National Parks Board (Transfer Date) Order 2019","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NPBA1996-S209-2019","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3317-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the National Parks Board (Transfer Date) Order 2019."}},{"id":"SG-H3317-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Transfer date"},"text":{"en":"2. The transfer date for the purposes of Part VII of the Act is 1 April 2019."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Parks Board (Transfer Date) Order 2019","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3318"] = {"id":"SG-H3318","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NPBA1996?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":35,"structureMode":"ARTICLE","title":{"zh":"国家公园局法 1996","en":"National Parks Board Act 1996","orig":null},"level":"law","status":"active","docNumber":"Act NPBA1996","completenessNote":"全文，共 35 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 3 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3318-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Short title"},"text":{"en":"1. This Act is the National Parks Board Act 1996."}},{"id":"SG-H3318-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Interpretation"},"text":{"en":"2. In this Act, unless the context otherwise requires —\n“animal” includes a mammal (other than a human being), a bird, a reptile, an amphibian, a fish, a mollusc, an arthropod, and the young or egg of any animal;\n“animal-related services” includes any of the following activities:\n(a)bathing, grooming or clipping of animals;\n(b)treatment, vaccination or inoculation of animals;\n(c)providing accommodation or boarding to or training of animals;\n(d)exhibiting (whether or not for sale) of animals;\n(e)trapping, restraining or immobilising animals;\n“animal-related services industry” means an industry consisting of persons carrying out any animal-related services in the course of business;\n“Board” means the National Parks Board established under the repealed National Parks Act (Cap. 198A, 1991 Revised Edition) in force before 1 July 1996 and continued by section 3;\n“Chairperson” means the Chairperson of the Board and includes any acting Chairperson of the Board;\n“Chief Executive” means the Chief Executive of the Board and includes any person acting in that capacity;\n“landscape industry” means an industry comprising persons who carry on any business or engage in any commercial activity in connection with one or more, or any part, or any combination, of the following:\n(a)landscaping works and services;\n(b)the supply of plants or landscaping or related products;\n(c)the growing and supply of flowers and ornamental plants;\n“landscaping works and services” includes the provision of services in landscape design, landscape architecture, planting and landscaping, arboriculture maintenance, horticulture maintenance and turf maintenance;\n“member” means a member of the Board;\n“national park” has the meaning given by the Parks and Trees Act 2005;\n“nature reserve” has the meaning given by the Parks and Trees Act 2005;\n“organism” has the meaning given by the Parks and Trees Act 2005;\n“Parks and Recreation Department” means the Parks and Recreation Department of the Ministry of National Development;\n“plant” has the meaning given by the Parks and Trees Act 2005;\n“public authority” means a body corporate established by a public Act for the purposes of a public function;\n“public park” has the meaning given by the Parks and Trees Act 2005;\n“subdelegate” means a person to whom a delegate under section 10(2) further delegates the performance or exercise of any of the Board’s functions, duties or powers;\n“transfer date” means 1 April 2019;\n“veterinary establishment” means any premises or place in which veterinary medicine is practised or veterinary services are provided;\n“veterinary medicine” means any branch or art of veterinary medicine and includes veterinary surgery;\n“veterinary product” means any chemical, substance or equipment used or designed for use in the practice of veterinary medicine or the provision of veterinary services;\n“veterinary science industry” means an industry consisting of persons carrying on business, or who engage in commercial activity, involving all or any of the following:\n(a)the practice of veterinary medicine;\n(b)the provision of veterinary services;\n(c)the management of a veterinary establishment;\n(d)the supply of veterinary products;\n“veterinary service” means a service provided in relation to an animal in the control or the possession of a person for any of the following purposes:\n(a)assessing, recording, maintaining or improving the health, welfare, comfort or wellbeing of the animal;\n(b)diagnosing or treating an illness, disability, disorder or condition of the animal;\n(c)examining or attending to the animal, including administering a veterinary product to or performing any surgical procedure on the animal;\n(d)performing any cosmetic procedure (including surgery) on the animal;\n(e)castrating or spaying of the animal;\n(f)giving advice based on a diagnosis or an examination mentioned in paragraph (b) or (c) or connected with a procedure in paragraph (d) or (e), including prescribing treatment, drugs, medications or medical appliances.\n[9/2017; 10/2019]"}},{"id":"SG-H3318-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 2 RECONSTITUTION OF BOARD"},"heading":{"en":"Reconstitution of National Parks Board"},"text":{"en":"3. As from 1 July 1996, the Board continues in existence and continues to be a body corporate with perpetual succession and capable of —\n(a)suing and being sued;\n(b)acquiring, owning, holding, developing and disposing of property, movable and immovable; and\n(c)doing and suffering such other acts or things as bodies corporate may lawfully do and suffer."}},{"id":"SG-H3318-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 2 RECONSTITUTION OF BOARD"},"heading":{"en":"Common seal"},"text":{"en":"4.—(1) As from 1 July 1996, the Board continues to have a common seal and the seal may be broken, changed, altered and made anew as the Board thinks fit.\n(2) All deeds and other documents requiring the seal of the Board must be sealed with the common seal of the Board and every document to which the common seal is affixed must be signed by any 2 members generally or specially authorised by the Board for the purpose or by one member so authorised and the Chief Executive.\n(3) Any document purporting to be a document duly executed under the seal of the Board is to be received in evidence and is, unless the contrary is proved, deemed to be a document so executed.\n(4) The Board may, by resolution or otherwise in writing, appoint an officer of the Board or any other agent either generally or in a particular case to execute or sign on behalf of the Board any agreement or other instrument not under seal in relation to any matter coming within the powers of the Board."}},{"id":"SG-H3318-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 RECONSTITUTION OF BOARD"},"heading":{"en":"Constitution of Board"},"text":{"en":"5. The First Schedule has effect with respect to the Board and its members."}},{"id":"SG-H3318-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 3 FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Functions of Board"},"text":{"en":"6.—(1) The functions of the Board are —\n(a)to control, administer and manage the national parks and nature reserves;\n(b)to plan, design, develop, manage and maintain public parks;\n(c)to provide, manage and maintain park and recreational infrastructure and facilities in the national parks, nature reserves and public parks;\n(d)to propagate, protect and preserve the animals, plants and other organisms of Singapore and, within the national parks, nature reserves and public parks, to preserve objects and places of aesthetic, historical or scientific interest;\n(e)to promote and protect the welfare, safety and health of animals, including controlling the following:\n(i)the use of animals in research, testing or teaching;\n(ii)the supply of veterinary products;\n(iii)the trapping or killing of animals in a wild state;\n(f)to manage the animal population in Singapore;\n(g)to prevent and manage threats and risks —\n(i)to animal health, animal welfare or plant health or all of them;\n(ii)to terrestrial and aquatic environments arising from animals or plants, or pests or diseases carried by animals or plants; and\n(iii)to public health and safety from animals or plants, or pests or diseases carried by animals or plants;\n(h)to regulate trade in endangered species of animals and plants;\n(i)to regulate veterinary establishments, practitioners of veterinary medicine and persons who provide veterinary services in the course of business;\n(j)to cooperate and collaborate in particular with —\n(i)any public officer, public authority or Health Officer in the administration of the Infectious Diseases Act 1976;\n(ii)the Health Sciences Authority in the administration of the Health Products Act 2007;\n(iii)the Director-General of Public Health and the Director‑General, Food Administration in the administration of the Environmental Public Health Act 1987; and\n(iv)the Director-General, Food Administration in the discharge of functions or powers under any written law;\n(k)to provide and control facilities for the study of and research into matters relating to animals, plants and other organisms in Singapore and the physical conditions in which they live;\n(l)to exhibit objects illustrative of the life sciences, applied sciences, history, technology and industry;\n(m)to promote the study, research and dissemination of knowledge in veterinary medicine, animal‑related services, botany, horticulture, biotechnology, arboriculture, landscape architecture, parks and recreation management and natural and local history;\n(n)to provide, manage and promote recreational, cultural, historical, research and educational facilities and resources in national parks, nature reserves and public parks and encourage their full and proper use by members of the public;\n(o)to advise the Government on all matters relating to animal health and welfare, plant health, veterinary medicine, animal‑related services, nature conservation and the planning, development and management of public parks;\n(p)to manage on behalf of the Government any State land used or to be used by the landscape industry, animal‑related services industry or veterinary science industry in Singapore and to promote the optimisation of the use of such land;\n(q)to promote the development, productivity and efficiency of the landscape industry, animal‑related services industry or veterinary science industry in Singapore;\n(r)to promote the advancement of skills and expertise of individuals in relation to any subject mentioned in paragraph (m) and of individuals employed in the landscape industry, animal‑related services industry or veterinary science industry in Singapore;\n(s)to represent the Government internationally on matters that relate to animal health and welfare, plant health, wildlife trade control and biodiversity, and matters connected with the landscape industry, animal‑related services industry and veterinary science industry in Singapore; and\n(t)to carry out such other functions and duties as are imposed upon the Board by or under this Act or any other written law.\n[9/2017; 10/2019]\n(2) In addition to the functions of the Board under subsection (1), the Board may undertake any other functions that the Minister may, by notification in the Gazette, assign to the Board and in so doing the Board is deemed to be fulfilling the purposes of this Act and the provisions of this Act apply to the Board in respect of those functions.\n[10/2019]\n(3) Nothing in this section imposes on the Board, directly or indirectly, any form of duty or liability enforceable by proceedings before any court to which the Board would not otherwise be subject.\n[10/2019]"}},{"id":"SG-H3318-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 3 FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Powers of Board"},"text":{"en":"7.—(1) The Board may, for the purposes of this Act, carry on any activity that appears to the Board to be advantageous, necessary or convenient for it to carry on for or in connection with the discharge of its duties and functions under this Act, or which is incidental or conducive to the discharge of those duties and functions, and, in particular, may exercise any of the powers specified in the Second Schedule.\n[10/2019]\n(2) This section is not to be construed as limiting any power of the Board conferred by or under any other written law."}},{"id":"SG-H3318-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 3 FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Directions of Minister"},"text":{"en":"8.—(1) The Minister may, after consulting the Board, give to the Board any direction under section 5 of the Public Sector (Governance) Act 2018.\n[5/2018]\n(2) The Board must provide the Minister with such information or facilities for obtaining information with respect to its property and activities in such manner and at such times as the Minister may require."}},{"id":"SG-H3318-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 3 FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Appointment of committees"},"text":{"en":"9. The Board may appoint from among its own members or other persons who are not members any number of committees consisting of members or other persons or members and other persons for purposes which, in the opinion of the Board, would be better regulated and managed by means of those committees."}},{"id":"SG-H3318-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 3 FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Ability to delegate, etc."},"text":{"en":"10.—(1) The Board may delegate the performance or exercise of any of its functions, duties or powers under this Act or any other Act, either generally or specially, to any of the following persons by resolution and written notice to the person or persons:\n(a)a member of the Board;\n(b)the Chief Executive, any employee of the Board or any other person performing duties in the Board;\n(c)a committee of the Board appointed under section 9;\n(d)a wholly-owned subsidiary company of the Board;\n(e)a person engaged as a contractor by the Board.\n[10/2019]\n(2) A delegation by the Board under subsection (1) of the performance or exercise of any of its functions, duties or powers —\n(a)to a person in subsection (1)(a), (b) or (c) may authorise the delegate to subdelegate the performance or exercise of the function, duty or power to another member, an appropriately qualified employee of the Board or person performing duties in the Board (called in this Act a subdelegate); or\n(b)to a person in subsection (1)(d) or (e) may authorise the delegate to subdelegate the performance or exercise of the function, duty or power to an appropriately qualified employee of that delegate (also called in this Act a subdelegate),\nbut subject to the same restrictions, and with the same effect, as if the subdelegate were the delegate.\n[10/2019]\n(3) Subsections (1) and (2) do not apply to —\n(a)the power to borrow money;\n(b)the power to raise or grant loans or advances to or subscribe to stocks, shares, bonds or debentures of a company or corporation; or\n(c)any other function, duty or power under this Act or any other Act administered by the Board that is declared by this Act or that Act to be non‑delegable.\n[10/2019]\n(4) A subdelegate to whom a function, duty or power of the Board is subdelegated under this section is not authorised to further delegate that function, duty or power to anyone else.\n[10/2019]\n(5) A delegation or subdelegation in accordance with this Act is not affected by any change in the membership of the Board or of any committee or by any change in the Chief Executive or any employee.\n[10/2019]\n(6) A delegate (or subdelegate) who purports to perform a function or duty or exercise a power under delegation (or subdelegation) —\n(a)is taken to do so in accordance with the terms of a delegation (or subdelegation) under this section, unless the contrary is shown; and\n(b)must produce evidence of the delegate’s (or subdelegate’s) authority to do so, if reasonably requested to do so.\n[10/2019]\n(7) In this section —\n(a)a reference to a wholly‑owned subsidiary company of the Board includes a company limited by guarantee the sole member of which is the Board; and\n(b)a reference to a person performing duties in the Board includes a person performing duties in the Board under a contract, or under an arrangement making available temporarily to the Board the services of public officers (or secondment).\n[10/2019]"}},{"id":"SG-H3318-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 3 FUNCTIONS AND POWERS OF BOARD"},"heading":{"en":"Protection from personal liability"},"text":{"en":"11. No liability shall lie against any member, any committee member, the Chief Executive or any employee, delegate or subdelegate of the Board, or any other person acting under the direction of the Board, for anything which is done or purported to be done, or omitted to be done, in good faith and with reasonable care in —\n(a)the exercise or purported exercise of any power under this Act; or\n(b)the performance or purported performance of any function under this Act.\n[10/2019]"}},{"id":"SG-H3318-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 4 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Chief Executive, officers and employees, etc."},"text":{"en":"12.—(1) There must be a Chief Executive of the Board, whose appointment, removal, discipline and promotion must be in accordance with the Public Sector (Governance) Act 2018.\n[5/2018]\n(2) The Board may appoint, subject to the Public Sector (Governance) Act 2018, an individual to act temporarily as the Chief Executive during any period, or during all periods, when the Chief Executive —\n(a)is absent from duty or Singapore; or\n(b)is, for any reason, unable to perform the duties of the office.\n[5/2018]\n(3) The Board may, subject to the Public Sector (Governance) Act 2018, appoint and employ, on such terms and conditions as it may determine, such other officers, employees, consultants and agents as may be necessary for the effective performance of its functions.\n[13\n[5/2018]"}},{"id":"SG-H3318-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 4 PROVISIONS RELATING TO STAFF"},"heading":{"en":"Public servants"},"text":{"en":"13. Without affecting sections 20 and 21 of the Public Sector (Governance) Act 2018, every subdelegate of the Board —\n(a)is taken to be a public servant for the purposes of the Penal Code 1871 in relation to the subdelegate’s performance or exercise of the Board’s functions, duties or powers under this Act or any other written law; and\n(b)is, in relation to the administration, assessment, collection or enforcement of payment of —\n(i)any financial penalty imposed under any written law administered by the Board; or\n(ii)any composition sum collected under this Act or any other written law administered by the Board,\ntaken to be a public officer for the purposes of the Financial Procedure Act 1966; and section 20 of that Act applies to each of the subdelegates even though the subdelegate is not or was not in the employment of the Government.\n[14\n[10/2019]"}},{"id":"SG-H3318-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Grants"},"text":{"en":"14. For the purpose of enabling the Board to carry out its functions under this Act, the Minister may, from time to time, make grants to the Board of such sums of money as the Minister may determine out of moneys to be provided by Parliament.\n[15"}},{"id":"SG-H3318-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Issue of shares, etc."},"text":{"en":"15. As a consequence of the vesting of any property, rights or liabilities of the Government in the Board under this Act, or of any capital injection or other investment by the Government in the Board in accordance with any written law, the Board must issue such shares or other securities to the Minister for Finance as that Minister may direct.\n[15A"}},{"id":"SG-H3318-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Bank accounts and payments"},"text":{"en":"16.—(1) The Board may open and maintain an account or accounts with such bank or banks as the Board thinks fit and every such account must be operated as far as practicable by cheque signed by such person or persons authorised to do so by the Board.\n(2) The moneys of the Board are to be applied only in payment or discharge of the expenses, obligations and liabilities of the Board and in making any payment that the Board is authorised or required to make."}},{"id":"SG-H3318-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Power of investment"},"text":{"en":"17. The Board may invest its moneys in accordance with the standard investment power of statutory bodies as defined in section 33A of the Interpretation Act 1965."}},{"id":"SG-H3318-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Minister’s approval of estimates"},"text":{"en":"18.—(1) A copy of all annual estimates of revenue and expenditure and supplementary estimates must, upon their adoption by the Board, be sent without delay to the Minister.\n[5/2018]\n(2) The Minister may approve or disallow any item or portion of any item shown in the annual estimates or supplementary estimates.\n[5/2018]\n(3) The Minister must return the annual estimates or supplementary estimates as amended under subsection (2) to the Board, and the Board is bound by the Minister’s decision.\n[5/2018]"}},{"id":"SG-H3318-A19","no":19,"noLabel":{"en":"19."},"chapter":{"en":"PART 5 FINANCIAL PROVISIONS"},"heading":{"en":"Financial year"},"text":{"en":"19. The financial year of the Board begins on 1 April of each year and ends on 31 March of the succeeding year.\n[5/2018]"}},{"id":"SG-H3318-A20","no":20,"noLabel":{"en":"20."},"chapter":{"en":"PART 6 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES TO BOARD"},"heading":{"en":"Transfer to Board of property, assets and liabilities"},"text":{"en":"20.—(1) As from 1 July 1996, all movable property vested in the Government immediately before that date for the purposes of the Parks and Recreation Department, and all assets, rights or interests vested in, and all outstanding debts, liabilities and obligations incurred by, the Government in connection therewith are transferred to and vest in the Board without further assurance.\n(2) If any question arises as to whether any particular movable property vested in the Government, or whether any particular asset, right, interest, liability or obligation of the Government has been transferred to or vested in the Board under subsection (1), a certificate under the hand of the Minister for Finance is conclusive evidence that the property, asset, right, interest, liability or obligation was or was not so transferred or vested."}},{"id":"SG-H3318-A21","no":21,"noLabel":{"en":"21."},"chapter":{"en":"PART 6 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES TO BOARD"},"heading":{"en":"Transfer of employees"},"text":{"en":"21.—(1) As from 1 July 1996, such persons employed immediately before that date in the Parks and Recreation Department as the Minister may determine are transferred to the service of the Board on terms no less favourable than those enjoyed by them immediately prior to their transfer.\n(2) The provisions relating to the transfer of employees set out in the Third Schedule have effect."}},{"id":"SG-H3318-A22","no":22,"noLabel":{"en":"22."},"chapter":{"en":"PART 6 TRANSFER OF ASSETS, LIABILITIES AND EMPLOYEES TO BOARD"},"heading":{"en":"Existing agreements and pending proceedings"},"text":{"en":"22. All deeds, bonds, agreements, instruments and arrangements subsisting immediately before 1 July 1996 affecting any movable property transferred under section 20 or any person transferred to the service of the Board under section 21 continue in full force and effect on and after that date and are enforceable by or against the Board instead of the Government or any person acting on its behalf as if the Board had been named therein or had been a party thereto."}},{"id":"SG-H3318-A23","no":23,"noLabel":{"en":"23."},"chapter":{"en":"PART 7 TRANSFER OF AVA VETERINARY UNDERTAKINGS"},"heading":{"en":"Interpretation of this Part"},"text":{"en":"23. In this Part, unless the context otherwise requires —\n“Agri-Food and Veterinary Authority” or “AVA” means the Agri‑Food and Veterinary Authority established by section 3 of the Agri‑Food and Veterinary Authority Act (Cap. 5, 2012 Revised Edition);\n“asset”, in relation to the transferor, means property of any kind (whether tangible or intangible, whether arising from, accruing under, created or evidenced by or the subject of, an instrument or otherwise and whether actual or contingent) of the transferor on the eve of the transfer date and includes, without limitation, any —\n(a)legal or equitable interest in real or personal property;\n(b)chose in action;\n(c)security;\n(d)money;\n(e)intellectual property;\n(f)infrastructure, plant and equipment;\n(g)records and information (including data) in any form; and\n(h)right;\n“AVA veterinary undertaking” means the departments of the transferor as follows:\n(a)the Community Animal Management Group;\n(b)the Corporate Development Group 2;\n(c)the Industry and Biosecurity Management Group;\n(d)the office of the Director-General, Agri‑Food and Veterinary Services;\n(e)the Plant Science and Health Group;\n(f)the Professional and Scientific Services Group;\n(g)the Wildlife Management Group;\n“liability”, in relation to the transferor, means any liability, duty or obligation (whether actual or contingent, liquidated or unliquidated, and whether owed alone or jointly, or jointly and severally, with any other person) of the transferor on the eve of the transfer date;\n“records”, in relation to the transferor, means registers, papers, documents, minutes, receipts, books of account and other records, however compiled, recorded or stored, of that transferor existing on the eve of the transfer date;\n“right”, in relation to the transferor, means any right, power, privilege or immunity of the transferor on the eve of the transfer date;\n“transferor” means the Agri-Food and Veterinary Authority;\n“transferring employee” means an employee of the transferor who, on the eve of the transfer date, is deployed in the AVA veterinary undertaking.\n[10/2019]"}},{"id":"SG-H3318-A24","no":24,"noLabel":{"en":"24."},"chapter":{"en":"PART 7 TRANSFER OF AVA VETERINARY UNDERTAKINGS"},"heading":{"en":"Transfer of undertaking to Board"},"text":{"en":"24.—(1) On the transfer date, all assets and liabilities of the transferor that relate to the functions of the AVA veterinary undertaking are transferred to the Board.\n[10/2019]\n(2) When any assets or liabilities are transferred under subsection (1), the following provisions have effect:\n(a)the assets of the transferor that are the subject of the transfer vest in the Board by virtue of this section and without the need for any further conveyance, transfer, assignment or assurance;\n(b)the liabilities of the transferor that are the subject of the transfer become by virtue of this section the liabilities of the Board;\n(c)all legal or other proceedings relating to those assets or liabilities that are started before the transfer date by or against the transferor or a predecessor of the transferor and pending immediately before that date are taken to be proceedings pending by or against the Board;\n(d)any legal or other proceedings relating to those assets or liabilities which could have been started immediately before the transfer date by or against the transferor or a predecessor of the transferor may be started by or against the Board;\n(e)a judgment or order of a court or other tribunal obtained before the transfer date by or against the transferor or a predecessor of the transferor relating to those assets or liabilities may be enforced by or against the Board;\n(f)any document relating to legal or other proceedings relating to those assets or liabilities that has been served on or by the transferor or a predecessor of the transferor before the transfer date is taken, where appropriate, to have been served on or by the Board;\n(g)any act, matter or thing done or omitted to be done before the transfer date in relation to those assets or liabilities by, to or in respect of the transferor or a predecessor of the transferor is (to the extent to which that act, matter or thing has any force or effect) taken to have been done or omitted by, to or in respect of the Board;\n(h)a reference in any written law, in any instrument made under any Act, in any contract, agreement, arrangement or undertaking, or in any document of any kind to the transferor or a predecessor of the transferor, to the extent to which the reference relates to those assets or liabilities, is taken to be, or includes, a reference to the Board;\n(i)a reference in any written law, in any instrument made under any Act, in any contract, agreement, arrangement or undertaking, or in any document of any kind to an officer of the transferor, as regards anything falling to be done or capable of being done on or after the transfer date and to the extent to which the reference relates to those assets or liabilities, is taken to be, or includes, a reference to an officer of the Board whom the Board appoints for that purpose.\n[10/2019]\n(3) In particular —\n(a)all security deposits deposited with the transferor in relation to any asset or liability transferred under subsection (1) and not forfeited before the transfer date; and\n(b)the benefits of all indemnities, guarantees or warranties given to the transferor in relation to any asset or liability transferred under subsection (1) and not discharged before that date,\nare, without further assurance, transferred and deemed deposited with or given to the Board.\n[10/2019]\n(4) The operation of this section does not —\n(a)constitute a breach of, or default under, an Act or other law, or otherwise a civil wrong or criminal wrong;\n(b)constitute a breach of duty of confidence (whether arising by contract, in equity, by custom, or in any other way);\n(c)constitute a breach of any contractual provision prohibiting, restricting or regulating the assignment or transfer of assets or liabilities or the disclosure of any information;\n(d)terminate an agreement or obligation, or fulfil any condition that allows a person to terminate any agreement or obligation, or give rise to any right or remedy in respect of any agreement or obligation;\n(e)cause any contract or other instrument to be void or otherwise unenforceable;\n(f)frustrate any contract;\n(g)release a surety or other obligor or obligee wholly or in part from an obligation; or\n(h)constitute an event of breach of, or default under, any contract or other instrument.\n[10/2019]\n(5) No attornment to the Board by a lessee from the transferor is required for the purpose of this section.\n[10/2019]"}},{"id":"SG-H3318-A25","no":25,"noLabel":{"en":"25."},"chapter":{"en":"PART 7 TRANSFER OF AVA VETERINARY UNDERTAKINGS"},"heading":{"en":"Transferring secondments and employees to Board"},"text":{"en":"25.—(1) On the transfer date, every transferring employee —\n(a)stops being an employee of the transferor; and\n(b)is each transferred to the service, and becomes an employee, of the Board on terms no less favourable than those enjoyed by the employee on the eve of the transfer date.\n[10/2019]\n(2) The transfer of a transferring employee to the Board —\n(a)does not interrupt continuity of service;\n(b)does not constitute a retrenchment or redundancy; and\n(c)does not entitle any employee so transferred to any payment or other benefit merely because he or she stops being employed by the transferor.\n[10/2019]\n(3) A certificate purporting to be signed by the Minister certifying that an individual named in the certificate was, with effect from the transfer date, employed by virtue of this section by the Board, is admissible in evidence in any proceedings as evidence of the matters stated in it.\n[10/2019]\n(4) Nothing in this section prevents —\n(a)any of the terms and conditions of employment of an individual transferred under this section from being altered by or under any law, award or agreement with effect from any time after the transfer date; and\n(b)an individual transferred under this section from resigning from the Board at any time after the transfer date, in accordance with the terms and conditions of his or her employment then applicable.\n[10/2019]\n(5) To avoid doubt, section 18A of the Employment Act 1968 does not apply to the transfer under this Part of any transferring employee to the Board.\n[10/2019]\n(6) On the transfer date, every public officer or employee of any other public authority whose services are made available (or is seconded) to any department in the AVA veterinary undertaking pursuant to an agreement or arrangement that —\n(a)is between the Government or that other public authority and the Agri‑Food and Veterinary Authority; and\n(b)is in force on the eve of the transfer date,\ncontinues on secondment to the Board.\n[10/2019]"}},{"id":"SG-H3318-A26","no":26,"noLabel":{"en":"26."},"chapter":{"en":"PART 7 TRANSFER OF AVA VETERINARY UNDERTAKINGS"},"heading":{"en":"General preservation of employment terms"},"text":{"en":"26.—(1) The service with the transferor of an employee transferred under section 25 (called in this section a transferred employee) must be regarded for all purposes as having been continuous with the service of the employee with the Board immediately before the transfer date.\n[10/2019]\n(2) On the transfer date —\n(a)a transferred employee retains all accrued rights as if employment with the Board were a continuation of employment with the transferor;\n(b)the liabilities of the transferor relating to the transferred employee’s accrued rights to leave and superannuation become the liabilities of the Board; and\n(c)a reference to the transferor in the contract of employment that had effect in relation to the transferred employee immediately before the transfer date is taken to be, or includes, a reference to the Board.\n[10/2019]\n(3) For any conduct of a transferred employee when he or she was employed by the transferor which would have rendered the employee liable to be reprimanded, reduced in rank, retired, dismissed or punished by the transferor, the Board may —\n(a)start any disciplinary proceedings against the employee;\n(b)carry on and complete any disciplinary proceedings started by the transferor against the transferred employee if those proceedings are pending on the eve of the transfer date; and\n(c)reprimand, reduce in rank, retire, dismiss or otherwise punish a transferred employee, as if the employee were not transferred.\n[10/2019]\n(4) Where, on the eve of the transfer date, any matter about the conduct of a transferred employee during his or her employment with the transferor —\n(a)was in the course of being heard or investigated by a committee of the transferor acting under due authority; or\n(b)had been heard or investigated by a committee of the transferor acting under due authority but no order, ruling or direction had been made,\nthat committee must complete the hearing or investigation and make such order, ruling or direction as it could have made under the authority vested in it before that date, and that order, ruling or direction is to be regarded as an order, ruling or direction of the Board.\n[10/2019]\n(5) Until such time as conditions of employment are drawn up by the Board for a transferred employee, the transferred employee is to be regarded as being employed by the Board on the same conditions of his or her employment with the transferor on the eve of the transfer date.\n[10/2019]\n(6) Any condition of employment relating to the length of service with the Board must recognise the length of service of the employees so transferred while in the employment of the transferor (including any previous service of the employee taken to be service with the transferor) to be service with the Board.\n[10/2019]\n(7) Nothing in section 25(6) —\n(a)breaks the continuity of service of the public officer or employee of another public authority whose secondment continues with the Board because of that provision; or\n(b)affects any rights, powers or immunities that such a public officer or an employee of a public authority has, or the extent to which such a public officer or an employee (as the case may be) is subject to obligations or liabilities in relation to discipline, by virtue of holding the office or position to which the officer or employee is seconded.\n[10/2019]"}},{"id":"SG-H3318-A27","no":27,"noLabel":{"en":"27."},"chapter":{"en":"PART 7 TRANSFER OF AVA VETERINARY UNDERTAKINGS"},"heading":{"en":"Transfer of records"},"text":{"en":"27. On the transfer date, every record, or part of any record, of the transferor that relates to —\n(a)any asset or liability transferred to the Board under section 24; or\n(b)any transferring employee,\nbecomes the record of the Board.\n[26A\n[10/2019]"}},{"id":"SG-H3318-A28","no":28,"noLabel":{"en":"28."},"chapter":{"en":"PART 7 TRANSFER OF AVA VETERINARY UNDERTAKINGS"},"heading":{"en":"Confirmation of undertaking transferred"},"text":{"en":"28.—(1) If any dispute arises —\n(a)as to whether an asset or a liability or a record is transferred under section 24 or 27; or\n(b)as to whether any, or any part of any, contract or document relates to an asset or a liability, or a record, transferred under section 24 or 27,\nthe Minister for Finance may determine the matter and is to provide the concerned parties with written notice of that determination.\n[10/2019]\n(2) The determination of the Minister for Finance under subsection (1) is final and binding on the transferor and the Board.\n[26B\n[10/2019]"}},{"id":"SG-H3318-A29","no":29,"noLabel":{"en":"29."},"chapter":{"en":"PART 8 GENERAL"},"heading":{"en":"Symbol of Board"},"text":{"en":"29.—(1) The Board has the exclusive right to the use of such symbols or representations as it may select or devise (called in this section the Board’s symbols) and thereafter display or exhibit in connection with its activities or affairs.\n(2) Any person who, without the permission of the Board, uses a symbol or representation identical with any of the Board’s symbols, or which so resembles any of the Board’s symbols as to or be likely to deceive or cause confusion, shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 6 months or to both.\n[27"}},{"id":"SG-H3318-A30","no":30,"noLabel":{"en":"30."},"chapter":{"en":"PART 8 GENERAL"},"heading":{"en":"Exclusion of liability for information supplied by Board"},"text":{"en":"30. Where the Board provides a service to the public whereby information is supplied to the public on payment of a prescribed fee, neither the Board nor any of its employees involved in the supply of such information shall be liable for any loss or damage suffered by members of the public by reason of any error or omission of whatever nature appearing therein or however caused if made in good faith and in the ordinary course of the discharge of the duties of those employees.\n[28"}},{"id":"SG-H3318-A31","no":31,"noLabel":{"en":"31."},"chapter":{"en":"PART 8 GENERAL"},"heading":{"en":"All moneys recovered to be paid to Board"},"text":{"en":"31.—(1) All moneys recovered or sums collected under this Act or any other Act administered by the Board, other than composition sums, are to be paid into and form part of the general funds of the Board.\n[9/2017]\n(2) All composition sums collected under any Act administered by the Board are to be paid into the Consolidated Fund.\n[29\n[9/2017]"}},{"id":"SG-H3318-A32","no":32,"noLabel":{"en":"32."},"chapter":{"en":"PART 8 GENERAL"},"heading":{"en":"Power to make regulations"},"text":{"en":"32.—(1) The Board may, with the approval of the Minister, make regulations for carrying out the purposes and provisions of this Act.\n(2) Without limiting subsection (1), the Board may, with the approval of the Minister, make regulations for or with respect to all or any of the following matters:\n(a)regulating the proceedings of the Board or of the committees of the Board;\n(b)the manner of appointment, conduct and discipline and the terms and conditions of service of the employees of the Board;\n(c)the establishment of funds for the payment of gratuities and other benefits to employees of the Board;\n(d)any other matter which by this Act is required or permitted to be prescribed or is necessary or convenient to be prescribed for carrying out or giving effect to any provision of this Act.\n[40"}},{"id":"SG-H3318-A900000","no":900000,"noLabel":{"en":"FIRST SCHEDULE"},"text":{"en":"FIRST SCHEDULE\nSection 5\nConstitution and Proceedings of Board\n1. The Board consists of —\n(a)a Chairperson; and\n(b)not less than 6 but not more than 10 other members as the Minister may determine.\n2.—(1) The Chairperson and members of the Board are appointed by the Minister.\n(2) The Minister may appoint one member to be the Deputy Chairperson who may, subject to such directions as may be given by the Chairperson, exercise all or any of the powers exercisable by the Chairperson under this Act.\n(3) The Minister may appoint the Chief Executive to be a member of the Board.\n3. A member holds office on such conditions and for such term as the Minister may determine and is eligible for re-appointment.\n4. The Minister may appoint any member of the Board to be a temporary Chairperson or temporary Deputy Chairperson during the incapacity from illness or otherwise of the Chairperson or the Deputy Chairperson, as the case may be.\n5. The Minister may, at any time, revoke the appointment of the Chairperson or any member without giving any reason.\n6. Any member may resign from his or her appointment at any time by giving written notice to the Minister.\n7. The Minister may appoint a person to be a temporary member of the Board during the incapacity from illness or otherwise of any member.\n8. The Chairperson may, in writing, authorise any member to exercise any power or perform any function conferred on the Chairperson by or under this Act.\n9. The office of a member is vacated if the member —\n(a)has been absent, without leave of the Board, from 3 consecutive meetings of the Board; or\n(b)becomes in any manner disqualified from membership of the Board under paragraph 11.\n10. If a member resigns, dies or has his or her appointment revoked or otherwise vacates his or her office before the expiry of the term for which he or she has been appointed, the Minister may appoint a person to fill the vacancy for the remainder of the term of which the vacating member was appointed.\n11. A person must not be appointed or continue to hold office as a member if he or she —\n(a)is an undischarged bankrupt or has made any arrangement with his or her creditors;\n(b)has been sentenced to imprisonment for a term of at least 6 months and has not received a free pardon; or\n(c)has a mental disorder and is incapable of managing himself or herself or his or her affairs.\n12. There are to be paid to the Chairperson and other members out of the funds of the Board such salaries, fees and allowances as the Minister may determine.\n13.—(1) The Board is to meet for the despatch of business at such times and places as the Chairperson may appoint.\n(2) At every meeting of the Board, 5 members form a quorum.\n(3) A decision at a meeting of the Board is adopted by a simple majority of the members present and voting except that in the case of an equality of votes the Chairperson or member presiding has a casting vote in addition to his or her original vote.\n(4) The Chairperson or, in his or her absence, the Deputy Chairperson presides at meetings of the Board.\n(5) Where both the Chairperson and the Deputy Chairperson are absent at a meeting of the Board, such member as the members present may elect presides at the meeting of the Board.\n(6) Where at least 4 members of the Board request the Chairperson by written notice signed by them to convene a meeting of the Board for any purpose specified in the notice, the Chairperson must, within 7 days from the receipt of the notice, convene a meeting for that purpose.\n14. The Board may act despite any vacancy in its membership.\n15. Subject to the provisions of this Act and the Public Sector (Governance) Act 2018, the Board may make rules to regulate its own procedure generally, and in particular, regarding the holding and proceedings of meetings, the notice to be given of the meetings, the keeping of minutes and the custody, production and inspection of the minutes.\n16. The validity of any proceedings of the Board is not affected by any defect in the appointment of any member.\n[5/2018]"}},{"id":"SG-H3318-A900001","no":900001,"noLabel":{"en":"SECOND SCHEDULE"},"text":{"en":"SECOND SCHEDULE\nSection 7\nPowers of Board\n1. To manage the national parks, nature reserves and public parks.\n2. To regulate the planting and maintenance of plants in public parks by prescribing guidelines and requirements for the design and maintenance thereof.\n3. To lay out, construct, plant, improve, equip, maintain, supervise and control the national parks, nature reserves and public parks and carry out the following activities:\n(a)erect any pavilion, recreation room, outhouse or other building;\n(b)provide entertainment or any amenity;\n(c)set apart any part thereof for the purpose of any game or recreation and exclude the public from such part while it is in actual use for that purpose;\n(d)provide any apparatus for games and recreation and facilities for boating and charge for the use thereof;\n(e)place or authorise any person to place chairs or seats and charge or authorise any person to charge for the use thereof;\n(f)provide and maintain refreshment stalls, food stalls and restaurants and manage them or let them to any person on such conditions as the Board may determine;\n(g)authorise any person to erect, maintain and operate any facility and charge or authorise any person to charge for the use thereof.\n4. To plant plants in public parks.\n5. To enter into contracts for the supply of goods, services or materials or for the execution of works or other contracts as may be necessary for the discharge of the duties and functions of the Board under this Act or any other written law which the Board is charged with the responsibility to administer.\n6. To receive fees, donations, grants, gifts of movable or immovable property from any source or raise funds by any lawful means.\n7. To regulate and control public access to the national parks, nature reserves and public parks.\n8. To promote or undertake publicity in any form.\n9. To make provision for the specialised training of any employee of the Board and in that connection offer scholarships for such training and expenditure incidental thereto.\n10. To make awards of recognition, grants, scholarships or contributions as the Board considers fit for the purposes of this Act.\n11. To develop, conduct and certify training programmes for any subject matter relating to any function of the Board.\n12. To establish, manage and administer any accreditation or certification scheme or a register, for any purpose relating to any function of the Board, including specifying, by notification in the Gazette, accreditation marks and certification marks of the Board and controlling the use of those accreditation marks or certification marks.\n13. To offer consultancy services, inform, advise and make recommendations or proposals to the Government or any person on any matter relating to the designation, conservation, development and management of parks and other areas reserved for the propagation of plants and animals, or any other function of the Board.\n14. To act in combination or association with any person engaged, concerned or interested in the promotion of the functions of the Board, and pay for or contribute to the cost and expenses involved in such combination or association.\n15. With the approval of the Minister, to join in the formation of a company, association, trust or partnership or enter into a joint venture with any person.\n16. With the approval of the Minister, to raise loans for the purposes of this Act.\n17. To collect, analyse, compile, publish or disseminate information relating to such subject matter as may be necessary for the discharge of the functions, objects or duties of the Board.\n18. To provide technical, consultancy or advisory services to any Government agency or to any other person or body in Singapore or elsewhere on any matter related to or connected with the functions, objects or duties of the Board.\n19. To charge fees or commissions for services rendered by the Board or for any use of any of its facilities.\n20. To carry out promotional activities or publicity in any form.\n21. To organise courses and other programmes that the Board thinks necessary or desirable for the discharge of its functions, objects or duties.\n22. To apply for, obtain and hold, whether on its own behalf or jointly with any other person, any intellectual property rights.\n23. To enter into agreements or arrangements for the commercial exploitation of those intellectual property rights, whether by assignment, licensing or otherwise.\n24. To participate in international, regional and bilateral negotiations on matters that relate to animal health and welfare, plant health, wildlife trade control and biodiversity, and to any matters connected with the landscape industry, animal‑related services industry and veterinary science industry.\n25. To engage in research, technology development studies or technical cooperation projects.\n[9/2017; 10/2019]"}},{"id":"SG-H3318-A900002","no":900002,"noLabel":{"en":"THIRD SCHEDULE"},"text":{"en":"THIRD SCHEDULE\nSection 21\nProvisions relating to Transfer of Employees\n1. The terms and conditions to be drawn up by the Board must take into account the salaries and terms and conditions of service, including any accrued rights to leave, enjoyed by the persons transferred to the service of the Board under section 21 while in the employment of the Government and any term or condition relating to the length of service with the Board must provide for the recognition of service under the Government by the persons so transferred to be service by them under the Board.\n2. Nothing in the terms and conditions to be drawn up by the Board is to adversely affect the conditions that would have been applicable to persons transferred to the service of the Board as regards any pension, gratuity or allowance payable under the Pensions Act 1956.\n3. In every case where a person has been transferred to the service of the Board under section 21, the Government is liable to pay to the Board such portion of any gratuity, pension or allowance payable to that person on his or her retirement as the same bears to the proportion which the aggregate amount of his or her pensionable emoluments during his or her service with the Government bears to the aggregate amount of his or her pensionable emoluments during his or her service under both the Government and the Board.\n4. Where any person in the service of the Board whose case does not come within the scope of any pension or other schemes established under this Schedule retires or dies in the service of the Board or is discharged from that service, the Board may grant to him or her or to such other person or persons wholly or partly dependent on him or her, as the Board thinks fit, such allowance or gratuity as the Board may determine.\n5. Despite the provisions of the Pensions Act 1956, no person who is transferred to the service of the Board under section 21 is entitled to claim any benefit under that Act on the ground that he or she has been retired from the service of the Government on account of abolition or re‑organisation of office in consequence of his or her transfer to the service of the Board."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Parks Board Act 1996","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3319"] = {"id":"SG-H3319","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NPFA2010?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":32,"structureMode":"ARTICLE","title":{"zh":"国家生产力基金法 2010","en":"National Productivity Fund Act 2010","orig":null},"level":"law","status":"active","docNumber":"Act NPFA2010","completenessNote":"全文，共 32 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 3 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3319-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Short title"},"text":{"en":"1. This Act is the National Productivity Fund Act 2010."}},{"id":"SG-H3319-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Interpretation"},"text":{"en":"2. In this Act, unless the context otherwise requires —\n“Board” means the Productivity Fund Administration Board established under section 7;\n“Chairperson” means the Chairperson of the Board;\n“Executive Secretary” means any Executive Secretary of the Board appointed under section 14(1) and includes any person acting in that capacity;\n“Fund” means the National Productivity Fund established under section 3;\n“invest” includes entering into a transaction or an arrangement for the protection of investments;\n“matters relating to productivity enhancement and continuing education” includes legislative or administrative action taken, or to be taken, by the Government or any public authority that affects or might affect the productivity performance of industry, industry development or the productivity performance of the Singapore economy as a whole;\n“member” means any member of the Board and includes any temporary member of the Board;\n“property” means any legal or equitable estate or interest (whether present or future and whether vested or contingent) in real or personal property of any description;\n“public authority” means any board, authority or agency established by or under any public Act to perform or discharge any public function."}},{"id":"SG-H3319-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 2 NATIONAL PRODUCTIVITY FUND"},"heading":{"en":"Establishment of National Productivity Fund"},"text":{"en":"3.—(1) A fund called the National Productivity Fund is established, into which must be paid —\n(a)all moneys from time to time appropriated from the Consolidated Fund and authorised to be paid into the Fund by this Act or any other written law;\n(b)all investments out of moneys in the Fund authorised to be made by this Act and the proceeds of any of those investments, including the net income from those investments;\n(ba)all moneys paid to or recovered by the Board (whether pursuant to any contract entered into, any legal action taken, or otherwise) in connection with the provision of any financing, incentive or grant from the Fund;\n[Act 29 of 2023 wef 18/09/2023]\n(c)all composition sums paid under section 28; and\n(d)all moneys received by the Board by way of charges and fees for services rendered by the Board to any person.\n(2) For the purposes of subsection (1)(b), the net income from investments is the amount ascertained by adding to, or deducting from, the income received from investments of moneys in the Fund any profit derived or loss sustained (as the case may be) from the realisation of those investments."}},{"id":"SG-H3319-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 2 NATIONAL PRODUCTIVITY FUND"},"heading":{"en":"Purposes of Fund"},"text":{"en":"4.—(1) The moneys in the Fund may be withdrawn and applied for all or any of the following purposes only:\n(a)the provision (whether directly or through an intermediary) of financing (but not loans) or incentives (including grants and scholarships) to any public authority, enterprise, educational institution or other person (whether in Singapore or elsewhere) undertaking or facilitating any programme on matters relating to productivity enhancement and continuing education;\n[Act 29 of 2023 wef 18/09/2023]\n(aa)the provision of grants (whether directly or through an intermediary) to any enterprise, for the purpose of —\n(i)making investments in Singapore; or\n(ii)carrying out economic activities in Singapore,\nin order to develop the Singapore economy or any part thereof;\n[Act 29 of 2023 wef 18/09/2023]\n(b)the payment of expenses incurred by the Board in the performance of its functions and the discharge of its duties under this Act, including any remuneration or allowances payable to the members of the Board who are not public officers;\n(c)the payment of all expenses incidental to or arising from the administration, investment and management of moneys in the Fund.\n(2) Except as otherwise provided by this section, a payment must not be made out of the Fund unless the payment is authorised by the Board."}},{"id":"SG-H3319-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 NATIONAL PRODUCTIVITY FUND"},"heading":{"en":"Withdrawals"},"text":{"en":"5. Moneys must not be withdrawn from the Fund unless they are charged upon the Fund or are authorised to be withdrawn under this Act."}},{"id":"SG-H3319-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 2 NATIONAL PRODUCTIVITY FUND"},"heading":{"en":"Transfer of money upon dissolution"},"text":{"en":"6. Upon dissolution of the Fund during any term of office of the Government (within the meaning of the Constitution), the balance of the moneys remaining in that Fund must be transferred to the Consolidated Fund and be added to the reserves of the Government not accumulated by it during that term of office."}},{"id":"SG-H3319-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 3 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF BOARD"},"heading":{"en":"Establishment and incorporation of Productivity Fund Administration Board"},"text":{"en":"7. A body called the Productivity Fund Administration Board is established, which is a body corporate with perpetual succession and is, by that name, capable of —\n(a)suing and being sued;\n(b)acquiring, owning, holding and developing or disposing of property, both movable and immovable; and\n(c)doing and suffering any other acts or things that bodies corporate may lawfully do and suffer."}},{"id":"SG-H3319-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 3 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF BOARD"},"heading":{"en":"Common seal"},"text":{"en":"8.—(1) The Board must have a common seal and the seal may be broken, changed, altered or made anew as the Board thinks fit.\n(2) All deeds, documents and other instruments requiring the seal of the Board must be sealed with the common seal of the Board in the presence of any 2 officers of the Board duly authorised by the Board to act in that behalf and must be signed by those officers.\n(3) All courts, judges and persons acting judicially are to take judicial notice of the common seal of the Board affixed to any document and presume that it was duly affixed.\n(4) The Board may by resolution or otherwise appoint an employee of the Board or any other agent, either generally or in a particular case, to execute or sign on behalf of the Board any agreement or other instrument not under seal in relation to any matter coming within the powers of the Board."}},{"id":"SG-H3319-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 3 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF BOARD"},"heading":{"en":"Constitution of Board"},"text":{"en":"9.—(1) The Board consists of the following members:\n(a)a Chairperson; and\n(b)not less than 3 but not more than 6 other members as the Minister may determine.\n(2) The First Schedule has effect with respect to the Board, its members and proceedings."}},{"id":"SG-H3319-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 3 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF BOARD"},"heading":{"en":"Functions and duties of Board"},"text":{"en":"10.—(1) Subject to the provisions of this Act, the functions and duties of the Board are —\n(a)to evaluate and review the proposals relating to the usage of the moneys in the Fund;\n(b)to approve the payment of money from the Fund for the purposes set out in section 4;\n(c)to manage and administer the Fund in accordance with this Act; and\n(d)to carry out any other functions imposed upon the Board by or under this Act or any other written law.\n(2) The Board may undertake any other functions that the Minister may assign to the Board and in so doing, the Board is deemed to be fulfilling the purposes of this Act, and the provisions of this Act apply to the Board in respect of those functions.\n(3) Nothing in this section imposes on the Board, directly or indirectly, any form of duty or liability enforceable by proceedings before any court to which it would not otherwise be subject."}},{"id":"SG-H3319-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 3 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF BOARD"},"heading":{"en":"Powers of Board"},"text":{"en":"11.—(1) Subject to the provisions of this Act, the Board may carry on any activities that appear to the Board to be advantageous, necessary or convenient for it to carry on for or in connection with the performance of its functions and the discharge of its duties under this Act or any other written law and, in particular, the Board may exercise any of the powers specified in the Second Schedule.\n(2) Despite subsection (1), the Board may, with the Minister’s approval, carry on such other activities incidental to the performance of its functions and the discharge of its duties under this Act or any other written law as the Board may, from time to time, consider expedient.\n(3) The Board must provide the Minister with information with respect to its property and activities in such manner and at such times as the Minister may require.\n(4) This section does not limit any power of the Board conferred by or under any other written law."}},{"id":"SG-H3319-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 3 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF BOARD"},"heading":{"en":"Appointment of committees and delegation of powers"},"text":{"en":"12.—(1) The Board may appoint from among its members or from other persons who are not members any number of committees that it thinks fit for purposes which, in the opinion of the Board, would be better regulated and managed by means of those committees, including but not limited to providing advice and guidance to the Board on the evaluation and review of the proposals relating to the usage of the moneys in the Fund.\n(2) The Board may, subject to any conditions or restrictions that it thinks fit, delegate to any committee appointed under subsection (1) or to the Chairperson or any Executive Secretary or to any other member, officer or employee of the Board, any of the functions, duties or powers of the Board under this Act or any other written law, except —\n(a)the power of delegation conferred by this section;\n(b)the power to make any subsidiary legislation; and\n(c)the power to borrow money.\n(3) Any function, duty or power delegated under subsection (2) to any committee or person may be performed, discharged or exercised by the committee or person to whom it has been delegated in the name and on behalf of the Board.\n(4) No delegation under this section prevents the performance, discharge or exercise of any function, duty or power by the Board."}},{"id":"SG-H3319-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 3 ESTABLISHMENT, INCORPORATION AND CONSTITUTION OF BOARD"},"heading":{"en":"Symbol or representation of Board"},"text":{"en":"13.—(1) The Board has the exclusive right to the use of any symbol or representation that the Board may select or devise and to display or exhibit that symbol or representation in connection with its activities or affairs.\n(2) Any person who uses a symbol or representation which —\n(a)is identical with that of the Board; or\n(b)so resembles the Board’s symbol or representation as to deceive or cause confusion, or to be likely to deceive or cause confusion,\nshall be guilty of an offence and shall be liable on conviction to —\n(c)a fine not exceeding $5,000 or to imprisonment for a term not exceeding 6 months or to both; and\n(d)in the case of a continuing offence, to a further fine not exceeding $250 for every day or part of a day during which the offence continues after conviction."}},{"id":"SG-H3319-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 4 STAFF AND FINANCIAL PROVISIONS"},"heading":{"en":"Appointment of Executive Secretaries and other employees"},"text":{"en":"14.—(1) The Board must appoint one or more Executive Secretaries on such terms and conditions as the Board may determine.\n(2) Each Executive Secretary —\n(a)is known by such designation as the Board may determine; and\n(b)is responsible to the Board for the proper administration and management of the functions and affairs of the Board in accordance with the policy laid down by the Board.\n(3) If any Executive Secretary is temporarily absent from Singapore or temporarily incapacitated by reason of illness or for any other reason temporarily unable to perform his or her duties, another person may be appointed by the Board to act in the place of the Executive Secretary during that period of absence from duty.\n(4) The Board may, from time to time, appoint and employ on such terms and conditions as the Board may determine such officers and employees as may be necessary for the effective performance of its functions and discharge of its duties under this Act or any other written law."}},{"id":"SG-H3319-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 4 STAFF AND FINANCIAL PROVISIONS"},"heading":{"en":"Protection from personal liability"},"text":{"en":"15.—(1) No suit or other legal proceedings shall lie personally against any member, officer or employee of the Board or any other person acting under the direction of the Board for anything which is in good faith done or intended to be done in the execution or purported execution of this Act or any other written law conferring or imposing a function or power or imposing a duty on the Board.\n(2) Where the Board provides a service to the public by which information is supplied to the public pursuant to any written law, neither the members of the Board nor any of its officers or employees involved in the supply of the information shall be liable for any loss or damage suffered by any member of the public by reason of any error or omission of any nature appearing therein or however caused if made in good faith and in the ordinary course of the discharge of the duties of such member, officer or employee."}},{"id":"SG-H3319-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 4 STAFF AND FINANCIAL PROVISIONS"},"heading":{"en":"Public servants"},"text":{"en":"16. All members, officers and employees of the Board are deemed to be public servants for the purposes of the Penal Code 1871."}},{"id":"SG-H3319-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 4 STAFF AND FINANCIAL PROVISIONS"},"heading":{"en":"Preservation of secrecy"},"text":{"en":"17.—(1) Except for the purpose of the performance of his or her duties or the exercise of his or her functions or when lawfully required to do so by any court or under the provisions of any written law, a person who is or has been —\n(a)a member, or an officer, employee, adviser or agent, of the Board; or\n(b)a member of a committee of the Board,\nmust not disclose any information relating to the affairs of the Board or of any other person which has been obtained by the person in the performance of his or her duties or the exercise of his or her functions under this Act.\n(2) Any person who contravenes subsection (1) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $2,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3319-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 4 STAFF AND FINANCIAL PROVISIONS"},"heading":{"en":"Bank accounts"},"text":{"en":"18.—(1) The Board must open and maintain one or more accounts with any bank or banks that the Board thinks fit.\n(2) Every such account must be operated by such person or persons authorised to do so by the Board."}},{"id":"SG-H3319-A19","no":19,"noLabel":{"en":"19."},"chapter":{"en":"PART 4 STAFF AND FINANCIAL PROVISIONS"},"heading":{"en":"Annual estimates"},"text":{"en":"19.—(1) The Board must, in every financial year, prepare or cause to be prepared and must adopt annual estimates of income and expenditure of the Board for the ensuing financial year.\n(2) Supplementary estimates may be adopted by the Board at any of its meetings.\n(3) A copy of all annual estimates and supplementary estimates must, upon their adoption by the Board, be sent immediately to the Minister.\n(4) The Minister may approve or disallow any item or portion of any item shown in the estimates, and must return the estimates as amended by him or her to the Board, and the Board is bound thereby."}},{"id":"SG-H3319-A20","no":20,"noLabel":{"en":"20."},"chapter":{"en":"PART 4 STAFF AND FINANCIAL PROVISIONS"},"heading":{"en":"Investments"},"text":{"en":"20. The Board may —\n(a)invest the Fund in any manner that it thinks fit; and\n(b)engage in any financial activity or participate in any financial arrangement for the purpose of managing or hedging against any financial risk that arises or is likely to arise from the investment."}},{"id":"SG-H3319-A21","no":21,"noLabel":{"en":"21."},"chapter":{"en":"PART 4 STAFF AND FINANCIAL PROVISIONS"},"heading":{"en":"Financial provisions"},"text":{"en":"21. The financial provisions set out in the Third Schedule have effect with respect to the Board."}},{"id":"SG-H3319-A22","no":22,"noLabel":{"en":"22."},"chapter":{"en":"PART 4 STAFF AND FINANCIAL PROVISIONS"},"heading":{"en":"Annual financial statements, etc."},"text":{"en":"22.—(1) The Board must, as soon as its accounts and financial statements have been audited in accordance with the provisions of this Act, send to the Minister a copy of the audited financial statements, signed by the Chairperson and an Executive Secretary, together with a copy of the auditor’s report.\n(2) Where the Auditor‑General is not the auditor of the Board, a copy of the audited financial statements and any report made by the auditor must be forwarded to the Auditor‑General at the same time they are submitted to the Board.\n(3) The Minister must, as soon as practicable, cause a copy of the audited financial statements and of the auditor’s report mentioned in subsection (1) to be presented to Parliament."}},{"id":"SG-H3319-A23","no":23,"noLabel":{"en":"23."},"chapter":{"en":"PART 4 STAFF AND FINANCIAL PROVISIONS"},"heading":{"en":"Annual report"},"text":{"en":"23.—(1) The Board must, as soon as practicable after the end of each financial year, cause to be prepared and transmitted to the Minister a report dealing generally with the activities of the Board during the preceding financial year and containing any information relating to the proceedings and policy of the Board that the Minister may direct.\n(2) The Minister must, as soon as practicable, cause a copy of every such report to be presented to Parliament."}},{"id":"SG-H3319-A24","no":24,"noLabel":{"en":"24."},"chapter":{"en":"PART 5 MISCELLANEOUS"},"heading":{"en":"Powers to obtain information and call for return"},"text":{"en":"24.—(1) The Board or any officer, employee or agent of the Board authorised by the Board in that behalf may by written notice require any person to provide, within the time specified in the notice, any information or document that may be required by the Board or the officer, employee or agent of the Board (as the case may be) for the purpose of inquiring into or ascertaining —\n(a)the truth or correctness of any statement which has been made, or of any information which has been given, by a person who has applied for any financing, incentive or grant from the Board; or\n[Act 29 of 2023 wef 18/09/2023]\n(b)whether any financing, incentive or grant from the Board has been properly applied by the person to whom it was provided.\n[Act 29 of 2023 wef 18/09/2023]\n(2) The Board or any officer, employee or agent of the Board authorised by the Board in that behalf has at all times full and free access to all lands, buildings, places, books, documents and other papers for any of the purposes of this Act and may for any such purpose inspect, make copies of or take extracts from those books, documents or papers, or take possession of any of those books, documents or papers, if, in the opinion of the Board or the person so authorised —\n(a)the inspection or copying of or extraction from the books, documents or papers cannot reasonably be performed without taking possession of them;\n(b)the books, documents or papers may be interfered with or destroyed unless possession of them is taken; or\n(c)the books, documents or papers may be required as evidence in any proceedings instituted or commenced for any of the purposes of, or in connection with, this Act."}},{"id":"SG-H3319-A25","no":25,"noLabel":{"en":"25."},"chapter":{"en":"PART 5 MISCELLANEOUS"},"heading":{"en":"Penalty for obstructing Board in carrying out duties"},"text":{"en":"25. Any person who at any time hinders or obstructs the Board or any officer, employee or agent of the Board acting in the discharge of their duties under this Act shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3319-A26","no":26,"noLabel":{"en":"26."},"chapter":{"en":"PART 5 MISCELLANEOUS"},"heading":{"en":"Forgery of certificates, false or misleading information, statement or document"},"text":{"en":"26. If any person —\n(a)forges or counterfeits any document or certificate required by the Board for the purposes of this Act;\n(b)gives any information required by the Board for the purposes of this Act knowing it to be false in any material particular; or\n(c)obtains any financing, incentive or grant from the Fund under this Act by means of any false or misleading statement or any document that is false or misleading in any material particular,\n[Act 29 of 2023 wef 18/09/2023]\nthe person shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3319-A27","no":27,"noLabel":{"en":"27."},"chapter":{"en":"PART 5 MISCELLANEOUS"},"heading":{"en":"Offences by bodies corporate, etc."},"text":{"en":"27.—(1) Where an offence under this Act committed by a body corporate is proved —\n(a)to have been committed with the consent or connivance of an officer; or\n(b)to be attributable to any act or default on the officer’s part,\nthe officer as well as the body corporate shall be guilty of the offence and shall be liable to be proceeded against and punished accordingly.\n(2) Where the affairs of a body corporate are managed by its members, subsection (1) applies in relation to the acts and defaults of a member in connection with the member’s functions of management as if the member were a director of the body corporate.\n(3) Where an offence under this Act committed by a partnership is proved —\n(a)to have been committed with the consent or connivance of a partner; or\n(b)to be attributable to any act or default on the partner’s part,\nthe partner as well as the partnership shall be guilty of the offence and shall be liable to be proceeded against and punished accordingly.\n(4) Where an offence under this Act committed by a limited liability partnership is proved to have been committed with the consent or connivance of, or to be attributable to any neglect on the part of, a partner or manager of the limited liability partnership, the partner or manager (as the case may be) as well as the partnership shall be guilty of that offence and shall be liable to be proceeded against and punished accordingly.\n(5) Where an offence under this Act committed by an unincorporated association (other than a partnership) is proved —\n(a)to have been committed with the consent or connivance of an officer of the unincorporated association or a member of its governing body; or\n(b)to be attributable to any act or default on the part of such an officer or member,\nthe officer or member as well as the unincorporated association shall be guilty of the offence and shall be liable to be proceeded against and punished accordingly.\n(6) In this section —\n“body corporate” and “partnership” exclude a limited liability partnership within the meaning of the Limited Liability Partnerships Act 2005;\n“officer” —\n(a)in relation to a body corporate, means any director, member of the committee of management, chief executive officer, manager, secretary or other similar officer of the body corporate and includes any person purporting to act in any such capacity; and\n(b)in relation to an unincorporated association (other than a partnership), means the president, the secretary, or any member of the committee of the unincorporated association, or any person holding a position analogous to that of the president, secretary or member of such a committee and includes any person purporting to act in any such capacity;\n“partner” includes a person purporting to act as a partner.\n(7) The Minister may make rules to provide for the application of any provision of this section, with any modifications that the Minister considers appropriate, to any body corporate, limited liability partnership or unincorporated association formed or recognised under the law of a territory outside Singapore."}},{"id":"SG-H3319-A28","no":28,"noLabel":{"en":"28."},"chapter":{"en":"PART 5 MISCELLANEOUS"},"heading":{"en":"Composition of offences"},"text":{"en":"28.—(1) An Executive Secretary or any officer authorised by an Executive Secretary may compound any offence under this Act which is prescribed as a compoundable offence by collecting from a person reasonably suspected of having committed the offence a sum not exceeding the lower of the following:\n(a)one half of the amount of the maximum fine that is prescribed for the offence; or\n(b)$2,000.\n(2) On payment of the sum of money, no further proceedings are to be taken against that person in respect of the offence.\n(3) The Board may, with the approval of the Minister, make regulations to prescribe the offences which may be compounded.\n(4) All sums collected under this section must be paid into the Fund."}},{"id":"SG-H3319-A29","no":29,"noLabel":{"en":"29."},"chapter":{"en":"PART 5 MISCELLANEOUS"},"heading":{"en":"Regulations"},"text":{"en":"29. The Board may, with the approval of the Minister, make regulations for carrying out the purposes and provisions of this Act."}},{"id":"SG-H3319-A900000","no":900000,"noLabel":{"en":"FIRST SCHEDULE"},"text":{"en":"FIRST SCHEDULE\nSection 9(2)\nConstitution and proceedings of Board\nAppointment of Chairperson and members\n1.—(1) The Chairperson and other members of the Board must be appointed by the Minister and hold office for such period and on such terms and conditions as the Minister may determine.\n(2) The members comprise such persons from the private sector and public sector as the Minister thinks fit.\n(3) The Minister may appoint any Executive Secretary as a member.\nTemporary Chairperson or member\n2. The Minister may appoint any person to be a temporary Chairperson or member during the temporary incapacity from illness or otherwise, or during the temporary absence from Singapore, of the Chairperson or any member, as the case may be.\nRevocation of appointment\n3. The Minister may, at any time, revoke the appointment of the Chairperson or any member if the Minister considers the revocation necessary in the interest of the effective and economical performance of the functions of the Board under this Act or in the public interest.\nResignation\n4. A member may resign from office at any time by giving at least one month’s written notice to the Minister.\nVacation of office\n5. The office of a member becomes vacant —\n(a)on his or her death;\n(b)if he or she becomes disqualified from membership of the Board;\n(c)if he or she is adjudicated a bankrupt;\n(d)if he or she resigns from office; or\n(e)if his or her appointment is revoked.\nFilling of vacancies\n6. If a vacancy occurs in the membership of the Board, the Minister may, subject to paragraph 7, appoint any person to fill the vacancy, and the person appointed holds office for the remainder of the term for which the vacating member was appointed.\nDisqualification from membership\n7. A person must not be appointed or continue to hold office as a member if the person —\n(a)is an undischarged bankrupt or has made any arrangement with the person’s creditors;\n(b)has been sentenced to imprisonment for a term exceeding 6 months and has not received a free pardon; or\n(c)is incapacitated by physical or mental illness.\nDisclosure of interest by members\n8.—(1) A member who is in any way, directly or indirectly, interested in a transaction or project of the Board must disclose the nature of his or her interest at the first meeting of the Board at which he or she is present after the relevant facts have come to his or her knowledge.\n(2) A disclosure under sub-paragraph (1) must be recorded in the minutes of the meeting of the Board and, after the disclosure, that member —\n(a)must not take part in any deliberation or decision of the Board with respect to that transaction or project; and\n(b)must be disregarded for the purpose of constituting a quorum of the Board for that deliberation or decision.\n(3) No act or proceedings of the Board may be questioned on the ground that a member has contravened this paragraph.\n(4) For the purposes of this paragraph, a member whose spouse, parent, son, adopted son, daughter or adopted daughter has an interest in the transaction or project mentioned in sub-paragraph (1) is deemed to be interested in that transaction or project.\nSalaries and fees payable to members of Board\n9. The members of the Board are to be paid such salaries, fees and allowances as the Minister may from time to time determine.\nQuorum\n10.—(1) At every meeting of the Board, 3 members constitute a quorum and no business may be transacted unless a quorum is present.\n(2) The Chairperson presides at meetings of the Board, and if the Chairperson is absent from any meeting or part of any meeting, such member as the members present may elect presides at that meeting or part of that meeting.\n(3) A decision at a meeting of the Board is adopted by a simple majority of the members present and voting except that, in the case of an equality of votes, the Chairperson of the meeting has a casting vote in addition to his or her original vote.\nTransaction of business by Board outside meetings\n11.—(1) Subject to the approval of a simple majority of all the members of the Board, the Board may transact any of its business by the circulation of papers among members of the Board.\n(2) A member who is in any way, directly or indirectly, interested in the business being transacted by circulation of papers must disclose the nature of the member’s interest in writing to the Chairperson at the first opportunity after the relevant facts have come to the member’s knowledge.\n(3) The disclosure under sub‑paragraph (2) must be recorded and treated as having been made in accordance with paragraph 8, and that member must not take part in the decision with respect to that transaction.\n(4) A written decision made by a simple majority of the members for the time being entitled to take part in the decision is taken to be a decision of the Board, and is as valid and effectual as if it had been made at a meeting of the Board duly convened and held.\n(5) Separate copies of a written decision may be distributed for signing by the members if the wording of the decision and approval is identical in each copy.\n(6) For the purpose of a decision under this paragraph, the Chairperson and each member has the same voting rights as they have at any meeting of the Board.\n(7) The decision of the Board is made when the last member of the Board required for the majority signs and the member’s decision is duly delivered to an officer appointed by an Executive Secretary.\n(8) The Chairperson may stipulate a period of time within which a decision may be made under this paragraph.\n(9) The Board may, if it thinks fit, deliberate on matters by the circulation of papers among all of the members of the Board.\n(10) For the purposes of this paragraph, papers (including disclosures and decisions) may be circulated among members or delivered to an officer appointed by an Executive Secretary by hand or fax or electronic transmission of the information in the papers concerned.\nVacancies\n12. The Board may act despite any vacancy in its membership.\nProcedure at meetings\n13.—(1) The Chairperson or any other officer authorised by the Chairperson must, subject to any standing orders that may be made by the Board under sub‑paragraph (2), summon all meetings of the Board for the despatch of business.\n(2) Subject to the provisions of this Act, the Board may make standing orders to regulate its own procedure generally and, in particular, regarding the holding of meetings, the notice to be given of the meetings, the proceedings at the meetings, the keeping of minutes, the custody, production and inspection of the minutes, and the opening, keeping, closing and auditing of accounts."}},{"id":"SG-H3319-A900001","no":900001,"noLabel":{"en":"SECOND SCHEDULE"},"text":{"en":"SECOND SCHEDULE\nSection 11(1)\nPowers of Board\n1. To promote and undertake publicity in any form on matters relating to productivity enhancement and continuing education, and matters relating to the promotion of investments or economic activities in Singapore (collectively called in this Schedule the Fund objects).\n[Act 29 of 2023 wef 18/09/2023]\n2. To provide information resources on matters relating to the study, development or dissemination of programmes, methods or techniques designed to increase productivity performance of industry, industry development or the productivity of the Singapore economy as a whole.\n3. To request information from and collaborate or cooperate with any person, whether in Singapore or elsewhere, on any Fund object and any other subject matter that may be necessary for the performance of the functions of the Board.\n[Act 29 of 2023 wef 18/09/2023]\n4. To publish or sponsor the publication of periodicals, booklets and other written materials, and produce or sponsor the production of films and other audiovisual works, on matters relating to the programmes, methods or techniques designed to increase productivity performance of industry, industry development or the productivity of the Singapore economy as a whole.\n5. To collect, compile, analyse, publish or disseminate by any convenient means information of a statistical nature or otherwise concerning matters relating to the functions of the Board.\n6. To publish in the Gazette all the accreditation and certification marks of the Board for use in relation to any function of the Board, and control the use of those marks.\n7. To initiate and undertake or enter into contractual consultancy, research and development projects, and conduct or commission research, pursuant to the functions of the Board under this Act.\n8. To engage in any activity, either alone or in conjunction with other international agencies or organisations, for the purpose of any Fund object, including promoting increased productivity performance of industry, industry development or the productivity of the Singapore economy as a whole and to obtain, collect and exchange information relating to that activity.\n[Act 29 of 2023 wef 18/09/2023]\n9. To provide technical, consultancy or advisory services to any Government agency or to any other person or body in Singapore or elsewhere on any matter related to or connected with the functions, objects or duties of the Board.\n10. To become a member or an affiliate of any international body, the functions, objects or duties of which are similar to those of the Board.\n11. To enter into any contracts that may be necessary or expedient for the purpose of discharging the functions and duties of the Board.\n12. To fund scholarships, make research grants or otherwise give financial or other assistance to persons engaged in study or research into any matter relating to productivity enhancement and continuing education.\n13. To charge fees or commissions for services rendered by the Board including advisory, training, consultancy, certification and accreditation services or for the use of any facility of the Board and to recover any costs and expenses incurred.\n14. To provide financial support, grant, aid or assistance to any person or organisation for all or any of the purposes of this Act or any other written law.\n15. To provide information or issue notices relating to any matter in connection with the functions and duties of the Board in such form or manner as the Board may determine.\n16. To make provision for welfare benefits, gratuities, pensions, provident funds, allowances or other superannuation benefits for employees or former employees (or their dependents) of the Board.\n17. To make provision for the training of any employee of the Board and, in that connection, to offer scholarships to intending trainees or otherwise pay for the cost of the training and all expenditure incidental to the training.\n18. To offer bursaries and scholarships for study at any school or institution of higher learning to members of the public and officers or employees of the Board and members of their families.\n19. To establish and maintain offices.\n20. To do anything incidental or necessary to any of the functions, duties or powers of the Board under this Act or any other written law."}},{"id":"SG-H3319-A900002","no":900002,"noLabel":{"en":"THIRD SCHEDULE"},"text":{"en":"THIRD SCHEDULE\nSection 21\nFinancial provisions\nFinancial year\n1. The financial year of the Board begins on 1 April and ends on 31 March of each year.\nAccounts of Board\n2.—(1) The Board must —\n(a)keep proper accounts and records of its transactions and affairs; and\n(b)do all things necessary to ensure that —\n(i)all payments out of its moneys are correctly made and properly authorised; and\n(ii)adequate control is maintained over the assets of, or in the custody of, the Board and over the expenditure incurred by the Board.\n(2) The Board must —\n(a)cause to be kept proper accounts and records of all transactions and affairs relating to the Fund;\n(b)do all things necessary to ensure that payments out of the Fund are correctly made and properly authorised; and\n(c)ensure that adequate control is maintained over the assets and receipts of the Fund.\n(3) The Board must appoint an officer to be an accounting officer of the Fund with responsibility for keeping proper accounts and records in relation thereto, and preparing and signing a statement of the Fund’s accounts in respect of each financial year.\nAuditor\n3. The accounts of the Board must be audited by the Auditor‑General or any other auditor that may be appointed annually by the Minister in consultation with the Auditor‑General.\nAppointment of auditor\n4. A person is not qualified for appointment as an auditor under paragraph 3 unless the person is a public accountant who is registered or deemed to be registered under the Accountants Act 2004.\nRemuneration of auditor\n5. The remuneration of the auditor must be paid out of the Fund.\nAnnual financial statements\n6. The Board must, as soon as practicable after the close of the financial year, prepare and submit the financial statements in respect of that year to the auditor who must audit and report on them.\nDuties of auditor\n7. The auditor must state in the report required under paragraph 8 —\n(a)whether the financial statements show fairly the financial transactions and the state of affairs of the Board;\n(b)whether proper accounting and other records have been kept, including records of all assets of the Board whether purchased, donated or otherwise;\n(c)whether the receipts, expenditure and investment of moneys and the acquisition and disposal of assets by the Board during the financial year were in accordance with the provisions of this Act; and\n(d)any other matters arising from the audit that the auditor considers necessary.\nAuditor’s report\n8.—(1) The auditor must, as soon as practicable after the accounts have been submitted for audit, send a report of the audit to the Board.\n(2) The auditor must submit such periodical and special reports to the Minister and to the Board as may appear to the auditor to be necessary or as the Minister or the Board may require.\nPowers of auditor\n9.—(1) The auditor or any person authorised by the auditor is entitled at any reasonable time to full and free access to all accounting and other records relating, directly or indirectly, to the financial transactions of the Board.\n(2) The auditor or any person authorised by the auditor may make copies of, or take extracts from, any such accounting and other records.\n(3) The auditor or any person authorised by the auditor may require any person to provide the auditor or person authorised with any information in the possession of that person or to which that person has access that the auditor or any duly authorised person considers necessary for the purposes of the auditor’s or authorised person’s functions under this Act.\nPenalty for obstructing auditor\n10. Any person who fails, without any reasonable cause, to comply with any requirement of the auditor or authorised person under paragraph 9 or who otherwise hinders, obstructs or delays the auditor or authorised person in the performance of the auditor’s or authorised person’s functions under this Act shall be guilty of an offence and shall be liable on conviction —\n(a)to a fine not exceeding $1,000; and\n(b)in the case of a continuing offence, to a further fine not exceeding $250 for every day or part of a day during which the offence continues after conviction."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Productivity Fund Act 2010","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3320"] = {"id":"SG-H3320","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRA1965-S699-2016?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"国民登记（罪行构成）条例 2016","en":"National Registration (Composition of Offences) Regulations 2016","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRA1965-S699-2016","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3320-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations are the National Registration (Composition of Offences) Regulations 2016 and come into operation on 1 January 2017."}},{"id":"SG-H3320-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Compoundable offences"},"text":{"en":"2. Any offence under section 16(1)(a), (b) or (d) of the Act, or regulation 17(4) or 20 of the National Registration Regulations (Rg 2), may be compounded in accordance with section 28 of the Act by —\n(a)the Commissioner; or\n(b)a registration officer appointed under section 3(4) of the Act for the purposes of section 28 of the Act.\n[S 499/2023 wef 31/12/2021]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Registration (Composition of Offences) Regulations 2016","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3321"] = {"id":"SG-H3321","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRA1965-S742-2017?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"国民登记（照片）条例 2017","en":"National Registration (Photographs) Regulations 2017","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRA1965-S742-2017","completenessNote":"全文，共 4 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3321-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations are the National Registration (Photographs) Regulations 2017 and come into operation on 1 January 2018."}},{"id":"SG-H3321-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Photograph to comply with requirements"},"text":{"en":"2. Every photograph provided to a registration officer for the purposes of registration or re‑registration under the Act must —\n(a)be taken not more than 3 months before the date of the application;\n(b)bear a similar likeness to the individual applying for registration or re-registration (called in these Regulations the applicant);\n(c)not be tampered with;\n(d)be clear and undistorted; and\n(e)comply with the specifications set out in the Schedule."}},{"id":"SG-H3321-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Revocation"},"text":{"en":"3. The National Registration (Photographs) Regulations (Rg 1) are revoked."}},{"id":"SG-H3321-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nRegulation 2(e)\nSpecifications of applicant’s photograph\nStandard and quality\n1.—(1) The photograph must be in colour.\n(2) The photograph must have a plain white background or, in the case where the applicant’s hair, hat or head covering is white, a plain light grey background.\n(3) The photograph must be in sharp focus and clear with no ink marks or creases.\n(4) If submitted in hard copy, the photograph must be printed on high quality paper at high resolution with a matt or semi‑matt finish.\n(5) The photograph must be taken with uniform lighting and must not show any flash reflection or shadow on the applicant’s face or any uneven bright spots or red eyes.\nDimensions\n2.—(1) The photograph must be 35 millimetres wide by 45 millimetres long when measured without borders.\n(2) The applicant’s face must take up at least 70% of the photograph and be between 25 millimetres and 35 millimetres when measured from the chin to the crown of the applicant’s head.\nStyle\n3.—(1) The photograph must show the applicant looking directly at the camera, with eyes open and clearly visible.\n(2) The photograph must clearly show both edges of the applicant’s face.\n(3) The photograph must not show the applicant looking over any shoulder (portrait style) and the applicant’s head must not be tilted.\n(4) No part of the applicant’s face is to be obscured.\n(5) The top of the applicant’s shoulders must be visible in the photograph.\n(6) The photograph must not show the applicant wearing any sunglasses.\n(7) If the applicant wears any spectacles, the photograph must show the applicant’s eyes clearly with no reflection off the spectacles.\n(8) The photograph must not show the applicant wearing any hat or other head covering unless —\n(a)it is a hat or head covering that the applicant habitually wears for religious reasons or due to custom; and\n(b)the photograph provides a full frontal view of the applicant’s head and shoulders, showing the applicant’s facial features in their entirety.\n(9) The photograph must show the applicant alone with no chair back, objects or other individuals visible."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Registration (Photographs) Regulations 2017","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3322"] = {"id":"SG-H3322","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRA1965-S700-2016?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"国民登记（规定机构）条例 2016","en":"National Registration (Prescribed Institutions) Regulations 2016","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRA1965-S700-2016","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3322-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations are the National Registration (Prescribed Institutions) Regulations 2016 and come into operation on 1 January 2017."}},{"id":"SG-H3322-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Prescribed institution"},"text":{"en":"2. Every institution set out in the Schedule is a prescribed institution for the purposes of section 3(4) of the Act."}},{"id":"SG-H3322-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nRegulation 2\nPrescribed Institutions\n1.Singapore Post Limited"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Registration (Prescribed Institutions) Regulations 2016","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3323"] = {"id":"SG-H3323","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NRA1965?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":36,"structureMode":"ARTICLE","title":{"zh":"国民登记法 1965","en":"National Registration Act 1965","orig":null},"level":"law","status":"active","docNumber":"Act NRA1965","completenessNote":"全文，共 36 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。其中 1 条为官方正文中标注的已废止条文存根（照录）。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3323-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Short title"},"text":{"en":"1. This Act is the National Registration Act 1965."}},{"id":"SG-H3323-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Interpretation"},"text":{"en":"2.—(1) In this Act, unless the context otherwise requires —\n“Commissioner” means the Commissioner of National Registration appointed under section 3;\n“document” means anything in which information of any description is recorded, whether in electronic or other form;\n“false identity card” means —\n(a)a document that is not an identity card but purports to be an identity card; or\n(b)an identity card that has been altered by an unauthorised person;\n“householder” means the owner, tenant, subtenant or occupier of a house, shophouse, flat, apartment, hut or other dwelling place;\n“identity card” means an identity card issued under this Act, and includes an identity card issued or deemed to be issued under the Registration of Persons Ordinance 1955 (Ordinance 32 of 1955);\n“immigration officer” means an immigration officer appointed under section 3 of the Immigration Act 1959;\n“personal identifier” means a personal identifier in any form (including digital form) that is specified in the Schedule;\n“police officer” has the meaning given by section 2(1) of the Police Force Act 2004;\n“public authority” means a body established or constituted by or under a public Act to perform or discharge a public function;\n“register” means the register specified in section 5;\n“registration officer”, in relation to any provision of this Act, means —\n(a)the Commissioner;\n(b)the Deputy Commissioner of National Registration;\n(c)an Assistant Commissioner of National Registration; or\n(d)a person appointed as a registration officer under section 3(4) for the purposes of that provision.\n[32/2016]\n(2) Unless the context otherwise requires —\n(a)a reference to the registration of a person under this Act includes a reference to the re‑registration of a person under this Act; and\n(b)a reference to a person who is registered, or required to be registered, under this Act includes a reference to a person who is re‑registered, or required to be re‑registered, under this Act.\n[32/2016]\n(3) The Minister may, by order in the Gazette, amend the Schedule, except that any other personal identifier so prescribed in the order —\n(a)must be an image, a measurement or a recording of an external part of the human body, or a measurement or a recording of a person’s voice; and\n(b)must not be an identifier the obtaining of which would involve the taking of an invasive sample from the human body within the meaning given by section 8 of the Registration of Criminals Act 1949.\n[32/2016]\n[Act 26 of 2022 wef 12/06/2023]"}},{"id":"SG-H3323-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Appointment of officers"},"text":{"en":"3.—(1) The Minister may, from among public officers, appoint a Commissioner of National Registration, a Deputy Commissioner of National Registration and such number of Assistant Commissioners of National Registration as the Minister considers necessary for the purposes of this Act.\n[32/2016]\n(2) The Commissioner is, subject to the general or special directions of the Minister, responsible for the administration of this Act.\n[32/2016]\n(3) The Deputy Commissioner of National Registration and every Assistant Commissioner of National Registration may, subject to any conditions or restrictions that the Commissioner may impose, perform the functions and exercise the powers of the Commissioner under this Act.\n[32/2016]\n(4) The Commissioner may, subject to subsection (5) and any conditions or restrictions that the Commissioner thinks fit, appoint, by name or office, any of the following persons to be a registration officer for the purposes of this Act or any particular provision of this Act:\n(a)a public officer;\n(b)an employee of a public authority;\n(c)an employee of a prescribed institution.\n[32/2016]\n(5) Under subsection (4), only a public officer may be appointed as a registration officer for the purposes of section 21, 22, 24 or 25.\n[32/2016]\n(6) The Commissioner may delegate any of the Commissioner’s functions or powers under this Act (except the power to appoint registration officers or the power to delegate conferred by this section), either generally or specially and subject to any conditions or restrictions that the Commissioner thinks fit, to a registration officer described in subsection (4)(a) or (b).\n[32/2016]\n(7) Every appointment and every delegation under this section must be in writing, and the instrument of appointment or delegation must be given to the appointee or delegate, as the case may be.\n[32/2016]\n(8) Where an officer specified in subsection (3) or a delegate of the Commissioner under subsection (6), in accordance with that subsection, performs (or is to perform) any function or exercises (or is to exercise) any power of the Commissioner under this Act, any reference to the Commissioner in this Act in respect of that function or power includes that officer or delegate, as the case may be.\n[32/2016]"}},{"id":"SG-H3323-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Public servants and public officers, etc."},"text":{"en":"4. Every registration officer —\n(a)is deemed to be a public servant for the purposes of the Penal Code 1871; and\n(b)is, in relation to his or her administration, collection or enforcement of payment of any fee, charge or composition sum under this Act, deemed to be a public officer for the purposes of the Financial Procedure Act 1966; and section 20 of that Act applies to him or her even though he or she is not or was not in the employment of the Government.\n[3A\n[32/2016]"}},{"id":"SG-H3323-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Establishment of register"},"text":{"en":"5.—(1) The Commissioner must cause to be kept and maintained a register of all persons in Singapore who are registered or required to be registered under this Act.\n[32/2016]\n(2) The register is to be in the form that the Commissioner thinks fit, and must contain —\n(a)the name and sex of every person registered or required to be registered under this Act; and\n[Act 17 of 2021 wef 29/05/2022]\n(b)any other particulars of that person that the Commissioner considers necessary.\n[32/2016]\n(3) A copy of or extract from any document, including a copy produced by way of microfilm or computer print-out, filed or lodged at the office of the Commissioner, certified to be a true copy or an extract under the hand and seal of the Commissioner is in any proceedings admissible in evidence as of equal validity with the original document.\n[4"}},{"id":"SG-H3323-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Registration"},"text":{"en":"6. Subject to section 7 and any exemptions which may be granted by regulations made under section 33, every person lawfully resident within Singapore must be registered under and in accordance with this Act.\n[5\n[32/2016]"}},{"id":"SG-H3323-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Re-registration of persons in possession of identity cards"},"text":{"en":"7.—(1) Every person who, on 3 June 1990, is in possession of a valid identity card issued under this Act must re‑register under this Act within the period that the Minister may, by notification in the Gazette, specify.\n(2) All identity cards issued under this Act before 3 June 1990 cease to be valid on the expiry of the period within which persons in possession of the identity cards are required to be re-registered under subsection (1).\n(3) Nothing in this section prevents the re‑registration of a person who fails to re-register within the period specified in subsection (1).\n[6\n[28/94]"}},{"id":"SG-H3323-A8","no":8,"noLabel":{"en":"8."},"heading":{"en":"Entry or alteration of names in register"},"text":{"en":"8.—(1) The name of a person to be entered in the register and, where the person’s name in the register is to be altered, the person’s altered name to be entered in the register —\n(a)must be in a form expressed in characters in the modern English alphabet;\n(b)may include a permitted character; and\n(c)must not exceed the number of characters permitted in the electronic form of the register for the entry of a name.\n[32/2016]\n(2) The Commissioner may refuse to enter or alter the name of a person in the register if the name (including the altered name) —\n(a)contains anything that represents or resembles a title, a rank or an award;\n(b)where the name adopts a patronymic or matronymic naming system to signify lineage, includes any expression or abbreviation (for the purpose of that naming system) that does not correspond to the person’s sex entered or to be entered in the register;\n[Act 17 of 2021 wef 29/05/2022]\n(c)is obscene or offensive; or\n(d)is contrary to the public interest.\n[32/2016]\n(3) In subsection (1)(b), “permitted character” has the meaning given by section 2(1) of the Registration of Births and Deaths Act 2021.\n[6A\n[Act 17 of 2021 wef 29/05/2022]\n[Act 2 of 2024 wef 16/04/2024]"}},{"id":"SG-H3323-A9","no":9,"noLabel":{"en":"9."},"heading":{"en":"Issue of identity cards"},"text":{"en":"9. Subject to this Act, every person registered under this Act must be issued with an identity card.\n[7\n[32/2016]"}},{"id":"SG-H3323-A10","no":10,"noLabel":{"en":"10."},"heading":{"en":"Change of residence"},"text":{"en":"10.—(1) Any person registered under this Act who changes his or her place of residence must, within 28 days thereof, report the change to a registration officer.\n[19/2001; 32/2016]\n(2) Where a person registered under this Act has changed or changes his or her place of residence to a place outside Singapore, he or she may inform a registration officer of his or her contact address in Singapore, which must be —\n(a)the address of any premises in Singapore which he or she still owns an estate or interest in and which is used or permitted under written law to be used as residence; or\n(b)the address of the place of residence in Singapore of —\n(i)his or her spouse, grandparent, parent, sibling, child or grandchild;\n(ii)any grandparent, parent or sibling of his or her spouse; or\n(iii)any sibling of any of his or her parents or his or her spouse’s parents or any child of any of his or her siblings or spouse’s siblings.\n[8\n[19/2001; 32/2016]"}},{"id":"SG-H3323-A11","no":11,"noLabel":{"en":"11."},"heading":{"en":"Transmission of information of change of person’s place of residence to Government departments, public authorities and public officers"},"text":{"en":"11.—(1) Where —\n(a)any person is required by any written law to inform any Government department, public authority or public officer of any change of his or her place of residence; and\n(b)it is provided by that written law that that person is deemed to have complied with the requirement thereunder to inform the Government department, public authority or public officer of any change of his or her place of residence if he or she makes a report of the change under section 10,\nthe Commissioner must, upon that person making a report of a change of his or her place of residence under section 10, transmit to the Government department, public authority or public officer information of the change of that person’s place of residence as reported by him or her.\n[28/94; 32/2016]\n(2) Where the Commissioner has transmitted information of a change of a person’s place of residence to any Government department, public authority or public officer under subsection (1) —\n(a)neither the Government nor any registration officer nor any authorised person involved in the transmission of the information shall be liable for any loss or damage suffered by any person as a result of any error or omission of whatever nature appearing in the information transmitted or however caused if such error or omission was made in good faith and in the ordinary course of the discharge of the duties of such registration officer or authorised person; and\n(b)the Government department, public authority or public officer to which or to whom the information has been transmitted shall not be liable for any loss or damage suffered by any person as a result of any error or omission of whatever nature appearing in the information transmitted or however caused by any registration officer or authorised person involved in the transmission of the information.\n[28/94; 32/2016]\n(3) In this section, “public officer” includes the holder of any statutory office.\n[8A\n[28/94]"}},{"id":"SG-H3323-A12","no":12,"noLabel":{"en":"12."},"heading":{"en":"Returns by householders"},"text":{"en":"12.—(1) Every householder must, when so required in writing by a registration officer, submit in respect of his or her household the returns, at the times during the year, that may be prescribed for the carrying out of the provisions of this Act.\n(2) Such returns must be sent by a householder to any public officer or public authority that may be declared by the Minister by notification in the Gazette to be a public officer or public authority for the purposes of this section.\n[32/2016]\n(3) The owner, manager or other person in charge of a hotel, boarding house, hostel or other like dwelling place may be required by a registration officer to submit the returns required under subsection (1).\n[9"}},{"id":"SG-H3323-A13","no":13,"noLabel":{"en":"13."},"heading":{"en":"Cancellation of registration"},"text":{"en":"13.—(1) Where a person has been registered under this Act and the Minister is satisfied that the registration —\n(a)was obtained by means of fraud, false representation or the concealment of any material fact; or\n(b)was effected by mistake,\nthe Minister may by order require the Commissioner to cancel the registration of that person.\n[32/2016]\n(2) Any person whose registration is cancelled under this section must forthwith surrender his or her identity card to the Commissioner.\n[10"}},{"id":"SG-H3323-A14","no":14,"noLabel":{"en":"14."},"heading":{"en":"Onus of proof of contents of written applications and of identity cards, etc."},"text":{"en":"14. The onus of proving the truth of the contents of any written application for registration made under this Act or the contents of an identity card is on the applicant or on the person to whom the identity card was issued or on any other person alleging the truth of the contents.\n[11\n[32/2016]"}},{"id":"SG-H3323-A15","no":15,"noLabel":{"en":"15."},"heading":{"en":"Proof of citizenship by birth"},"text":{"en":"15.—(1) No claim by a person seeking to be registered under this Act that he or she is a citizen of Singapore by birth may, subject to subsection (3), be accepted by a registration officer if the person making the claim does not produce a birth certificate or other evidence to the registration officer’s satisfaction.\n(2) The onus of proving the status of citizenship of Singapore by birth is on the person who makes the claim.\n(3) The evidence of —\n(a)a birth certificate without the name of the child;\n(b)a birth certificate without the name of the child, but supported by a statutory declaration to the effect that the birth certificate refers to the birth of the person referred to in the statutory declaration; or\n(c)an identity card issued or deemed to be issued under the Registration of Persons Ordinance 1955 (Ordinance 32 of 1955), in which the holder of the identity card is stated to have been born in Singapore,\nis not necessarily sufficient evidence for the purposes of subsection (1).\n[12\n[32/2016]"}},{"id":"SG-H3323-A16","no":16,"noLabel":{"en":"16."},"heading":{"en":"Offences and penalties"},"text":{"en":"16.—(1) Any person who —\n(a)is required to register under this Act, or being registered under this Act, is required to re-register under this Act fails to register or re-register within the prescribed time or period;\n(b)fails to report his or her change of residence as required under section 10;\n(c)informs a registration officer of an address as a contact address that is false or is not an address described in section 10(2)(a) or (b);\n(d)fails to submit, or fails to submit within the time prescribed, any returns that are required to be submitted under section 12;\n(e)without lawful authority or reasonable excuse, is in possession of one or more identity cards;\n(f)unlawfully deprives any person of an identity card;\n(g)fails or refuses to surrender his or her identity card to the Commissioner as required under section 13(2); or\n(h)defaces, mutilates or destroys an identity card,\nshall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 5 years or to both.\n[19/2001]\n(2) Any person who —\n(a)without lawful authority, parts with possession of any identity card to any person;\n(b)without lawful authority or reasonable excuse, knowingly obtains or is in possession of or makes use of a forged identity card or an identity card other than his or her own;\n(c)unlawfully issues or reproduces an identity card or any part of an identity card; or\n(d)forges, erases, alters or falsifies any entry in or tampers with an identity card,\nshall be guilty of an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 10 years or to both.\n(3) Any person who aids or abets in the commission of any offence under this Act shall be guilty of an offence.\n(4) Every offence under this Act is deemed to be an arrestable offence for the purposes of the Criminal Procedure Code 2010.\n[13"}},{"id":"SG-H3323-A16.001","no":16.001,"noLabel":{"en":"16A."},"heading":{"en":"Extended criminal jurisdiction for conduct within Singapore designated area for certain offences"},"text":{"en":"16A.—(1) Any conduct engaged in by a person in a Singapore designated area of a cross-border railway that, if engaged in within Singapore, would constitute an offence under —\n(a)section 16(1)(e) or (h);\n(b)section 16(2)(a), (b) or (d);\n(c)section 16(3); or\n(d)section 21(3),\nis to be treated for the purposes of that provision as if the person engaged in that conduct in Singapore.\n(2) Section 19 extends to apply to conduct engaged in by any person within a Singapore designated area of a cross-border railway that is —\n(a)an attempt to commit, or doing any act preparatory to the commission of, an offence mentioned in subsection (1); or\n(b)giving another person any assistance with intent to prevent, hinder or interfere with the apprehension, trial or punishment of that person for an offence mentioned in subsection (1).\n(3) A person who engages in any conduct mentioned in subsection (1) or (2) may be tried and punished for that conduct by a court in Singapore.\n(4) To be clear, it does not matter whether the conduct engaged in constitutes an offence under the laws of Malaysia, and this section does not affect sections 39 and 40 of the Cross-Border Railways (Border Control Co-location) Act 2026.\n(5) Section 21 extends to apply to and in relation to any document or identity card in the possession or control of any person within a Singapore designated area of a cross-border railway and in connection with an offence mentioned in subsection (1), subject to the following modifications:\n(a)any reference to a registration officer or a police officer is a reference to a registration officer or a police officer who is a Singapore preclearance officer;\n(b)any reference to demanding the surrender of any document or identity card from any person includes a reference to transferring custody of the document or identity card surrendered to a Malaysian border protection service officer without delay.\n(6) To be clear, sections 16(4) and 22(1) do not apply to or in relation to any person who engaged in any conduct mentioned in subsection (1) or (2) until the person is within Singapore.\n(7) In this section, “cross-border railway”, “cross-border train”, “Malaysian border protection service officer”, “Singapore designated area” and “Singapore preclearance officer” have the meanings given by section 3(1) of the Cross-Border Railways (Border Control Co-location) Act 2026.\n[Act 16 of 2026 wef 30/09/2026]"}},{"id":"SG-H3323-A17","no":17,"noLabel":{"en":"17."},"heading":{"en":"Provision of information by Housing and Development Board"},"text":{"en":"17.—(1) Any registration officer duly authorised by the Commissioner may, if the registration officer considers it necessary for administering or enforcing any requirement under this Act relating to the registration of any person or to the reporting of any change of residence, by written notice require the Board to disclose any secret or confidential document or information which is in the possession or control of the Board.\n[5/2010; 32/2016]\n(2) The Board must disclose the document or information required by a registration officer under subsection (1) despite any obligation as to secrecy or confidentiality imposed by any law.\n[5/2010]\n(3) Any registration officer to whom any document or information has been disclosed under subsection (2) must not disclose that document or information to any other person except —\n(a)to another law enforcement officer for the performance of his or her official duties in administering or facilitating the administration of any written law, provided the Board consents to the disclosure; or\n(b)for the purpose of criminal proceedings.\n[5/2010]\n(4) Any registration officer who contravenes subsection (3), or any law enforcement officer who discloses any document or information obtained under that subsection to any other person other than for the purpose specified in paragraph (a) or (b) of that subsection, shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $2,000 or to imprisonment for a term not exceeding 12 months or to both.\n[5/2010]\n(5) In this section, unless the context otherwise requires —\n“Board” means the Housing and Development Board established under section 3 of the Housing and Development Act 1959;\n“disclose”, in relation to any document or information, includes allowing access to the document or information;\n“law enforcement officer” means —\n(a)any police officer;\n(b)any immigration officer; or\n(c)any registration officer.\n[13A\n[5/2010; 32/2016]"}},{"id":"SG-H3323-A18","no":18,"noLabel":{"en":"18."},"text":{"en":"18. [Repealed by Act 26 of 2022 wef 12/06/2023]"},"status":"repealed"},{"id":"SG-H3323-A19","no":19,"noLabel":{"en":"19."},"heading":{"en":"Attempt to commit offences and assisting offenders"},"text":{"en":"19.—(1) Without affecting the operation of Chapters 5 and 23 of the Penal Code 1871, any person who attempts to commit or does any act preparatory to the commission of an offence under this Act shall be deemed to be guilty of the offence under this Act.\n(2) A person knowing or having reasonable cause to believe that another person is guilty of an offence under this Act must not give that other person any assistance with intent thereby to prevent, hinder or interfere with the apprehension, trial or punishment of that person for that offence.\n[15"}},{"id":"SG-H3323-A20","no":20,"noLabel":{"en":"20."},"heading":{"en":"False or invalid documents in connection with registration, etc."},"text":{"en":"20. A registration officer may take possession of any document produced to the registration officer in connection with the registration of a person, or the alteration of any particulars of the person entered in the register, under this Act if the registration officer reasonably suspects that the document is false or invalid.\n[15A\n[32/2016]"}},{"id":"SG-H3323-A21","no":21,"noLabel":{"en":"21."},"heading":{"en":"Demand for surrender of suspicious identity cards"},"text":{"en":"21.—(1) A registration officer or a police officer may demand that a person having possession or control of an identity card (including a document purporting to be an identity card) to surrender the identity card to the registration officer or police officer if there are reasonable grounds to suspect that —\n(a)the identity card has been obtained by means of any false or misleading information, document or statement;\n(b)the identity card has been used in the commission of an offence under this Act; or\n(c)the identity card is a false identity card.\n[32/2016]\n(2) Any person who receives a demand from a registration officer or a police officer under subsection (1) must comply with the demand.\n[32/2016]\n(3) Any person who contravenes subsection (2) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 6 months or to both.\n[15B\n[32/2016]"}},{"id":"SG-H3323-A22","no":22,"noLabel":{"en":"22."},"heading":{"en":"Arrest, search and detention"},"text":{"en":"22.—(1) Where any person —\n(a)is reasonably suspected by a registration officer or police officer of the commission of any offence under this Act; or\n(b)on demand by a registration officer or a police officer —\n(i)does not give his or her name and address;\n(ii)gives a name or address which the officer has reason to believe is false; or\n(iii)gives as his or her address a place outside Singapore,\nthat person may be arrested without warrant by the registration officer or police officer.\n[32/2016]\n(2) If a registration officer or a police officer reasonably suspects that any evidence of the commission of an offence under this Act is likely to be found on any premises, or in any vehicle, train, vessel or aircraft, or on any person, the officer may, without warrant and with any assistance that the officer thinks necessary —\n(a)enter and search the premises;\n(b)stop, board and search the vehicle, train, vessel or aircraft (whether in a public or private place); or\n(c)stop and search the person (whether in a public or private place),\nas the case may be.\n[32/2016]\n(3) A registration officer or a police officer exercising any power under subsection (2) may, if the circumstances so warrant, with any assistance that the officer thinks necessary —\n(a)break open any door, window, lock, fastener, compartment, box, container or other thing; or\n(b)remove by force any obstruction to the exercise of that power.\n[32/2016]\n(4) A registration officer or a police officer carrying out a search under subsection (2) may take possession or make copies of any document found during the search that the officer reasonably believes to be connected to the commission of an offence under this Act.\n[32/2016]\n(5) A woman must not be searched under this section except by a woman.\n[16\n(6) Any person arrested under subsection (1) may be detained at —\n(a)a lock-up appointed as a place of confinement under section 4(1) of the Prisons Act 1933; or\n(b)an immigration depot designated under the Immigration Act 1959.\n[Act 16 of 2024 wef 17/06/2024]\n[Act 16 of 2024 wef 17/06/2024]"}},{"id":"SG-H3323-A23","no":23,"noLabel":{"en":"23."},"heading":{"en":"How arrested person is to be dealt with"},"text":{"en":"23.—(1) A registration officer or a police officer who makes an arrest under section 22(1) must comply with sections 67 and 68 of the Criminal Procedure Code 2010.\n[32/2016]\n(2) In subsection (1), a reference to a police officer in sections 67 and 68 of the Criminal Procedure Code 2010 includes a reference to a registration officer.\n[16A\n[32/2016]"}},{"id":"SG-H3323-A23.001","no":23.001,"noLabel":{"en":"23A."},"heading":{"en":"Bail and bond"},"text":{"en":"23A.—(1) A person who has been arrested by a registration officer or police officer under section 22(1) may be released on bail or on personal bond granted by any registration officer.\n(2) Division 5 (Bails and bonds) of Part 6 of the Criminal Procedure Code 2010 applies to the release of a person on bail or on personal bond under this section or section 92 or 93 of the Criminal Procedure Code 2010 (as the case may be) with the following modifications:\n(a)any reference to “officer”, “police officer” or “police officer of or above the rank of sergeant” is to be read to include a registration officer;\n(b)the reference to the Commissioner of Police in section 92(1) of the Criminal Procedure Code 2010 is to be read to include the Commissioner.\n[Act 16 of 2024 wef 17/06/2024]"}},{"id":"SG-H3323-A24","no":24,"noLabel":{"en":"24."},"heading":{"en":"Investigation powers"},"text":{"en":"24.—(1) A registration officer may investigate an offence under this Act.\n[32/2016]\n(2) In any case relating to the commission of an offence under this Act, a registration officer —\n(a)has all the powers of a police officer under the Criminal Procedure Code 2010 in relation to an investigation into an arrestable offence; and\n(b)when exercising the powers of a police officer under the Criminal Procedure Code 2010, is deemed to be an officer not below the rank of inspector of police.\n[16B\n[32/2016]"}},{"id":"SG-H3323-A25","no":25,"noLabel":{"en":"25."},"heading":{"en":"Notice to attend court"},"text":{"en":"25.—(1) Where a registration officer has reasonable grounds to believe that a person has committed an offence under this Act (called in this section the alleged offender), the registration officer may, instead of applying to a court for a summons under the Criminal Procedure Code 2010, immediately serve upon the alleged offender a prescribed notice, requiring the alleged offender to attend at the court and on the date and time specified in the notice.\n[32/2016]\n(2) A duplicate of the notice must be prepared by the registration officer and, if so required by a court, produced to the court.\n[32/2016]\n(3) The registration officer may serve the notice on the alleged offender in the same manner as the service of a summons under section 116 of the Criminal Procedure Code 2010.\n[32/2016]\n(4) Where the alleged offender appears before the court, the court is to take cognizance of the alleged offence and proceed as though the alleged offender were produced before the court under a summons issued under section 153 of the Criminal Procedure Code 2010.\n[32/2016]\n(5) If the alleged offender fails to appear before the court in person or by counsel on the date and time specified in the notice, the court may, if satisfied that the notice was duly served on the alleged offender, issue a warrant for the arrest of the alleged offender unless before that date —\n(a)in the case of an offence which may be compounded, the alleged offender has been permitted to compound the offence; or\n(b)the notice has been cancelled under subsection (7).\n[32/2016]\n(6) Where the alleged offender is arrested under a warrant issued under subsection (5) —\n(a)the alleged offender must be produced before a court; and\n(b)the court is to proceed as though the alleged offender were produced before the court under a summons issued under section 153 of the Criminal Procedure Code 2010.\n[Act 31 of 2022 wef 01/11/2022]\n(7) A registration officer may cancel a notice issued under subsection (1) at any time before the date specified in that notice for the alleged offender named in that notice to attend court.\n[16C\n[32/2016]"}},{"id":"SG-H3323-A26","no":26,"noLabel":{"en":"26."},"heading":{"en":"Registration officers and police officers to produce identification"},"text":{"en":"26.—(1) When exercising any power under this Act, every registration officer and police officer must —\n(a)if not in uniform, declare his or her office; and\n(b)on demand by any person affected by the exercise of that power, produce to that person any identification card or other document that the Commissioner (in the case of registration officers) or the Commissioner of Police (in the case of police officers) may direct to be carried.\n[32/2016]\n(2) Despite any provision of this Act, it is not an offence for a person to refuse to comply with any request, demand or order made or given by a registration officer or a police officer who does not comply with subsection (1).\n[16D\n[32/2016]"}},{"id":"SG-H3323-A27","no":27,"noLabel":{"en":"27."},"heading":{"en":"Report of certain persons admissible as evidence"},"text":{"en":"27.—(1) Any document purporting to be a report under the hand of any of the persons mentioned in subsection (2) upon any matter or thing duly submitted to that person for examination, analysis or report, may be used as evidence in any trial or other proceedings under this Act, unless the court requires that person to be called as a witness:\nProvided that in any case in which the Public Prosecutor intends to give in evidence any such report, the Public Prosecutor must deliver a copy of the report to the accused not less than 10 clear days before the commencement of the trial or other proceedings.\n[32/2016]\n(2) The following are persons to whom this section applies:\n(a)any officer or any person duly authorised to issue identity cards by virtue of any written law, including subsidiary legislation, in force in Malaysia; and\n(b)any police officer of Malaysia charged with the registration or collation of fingerprints.\n[17"}},{"id":"SG-H3323-A28","no":28,"noLabel":{"en":"28."},"heading":{"en":"Composition of offences"},"text":{"en":"28.—(1) The Commissioner or a registration officer may compound any offence under this Act that is prescribed as a compoundable offence by collecting from a person reasonably suspected of having committed the offence a sum not exceeding $500.\n[32/2016]\n(2) On payment of the sum of money, no further proceedings are to be taken against that person in respect of the offence.\n[17A\n[32/2016]"}},{"id":"SG-H3323-A29","no":29,"noLabel":{"en":"29."},"heading":{"en":"Police officers’ functions and powers under Criminal Procedure Code 2010"},"text":{"en":"29. To avoid doubt, nothing in this Act affects a police officer’s functions or powers under the Criminal Procedure Code 2010 or any other written law.\n[17B\n[32/2016]"}},{"id":"SG-H3323-A30","no":30,"noLabel":{"en":"30."},"heading":{"en":"Obligation to be in possession of travel document"},"text":{"en":"30. Nothing in this Act relieves any person of any obligation under any other written law to be in possession of a passport or any other travel document whatsoever.\n[18\n[32/2016]"}},{"id":"SG-H3323-A31","no":31,"noLabel":{"en":"31."},"heading":{"en":"Payments into Consolidated Fund"},"text":{"en":"31. All fees, charges and composition sums collected under this Act are to be paid into the Consolidated Fund.\n[18A\n[32/2016]"}},{"id":"SG-H3323-A32","no":32,"noLabel":{"en":"32."},"heading":{"en":"Service of documents"},"text":{"en":"32.—(1) A document permitted or required by this Act to be served on an individual may be served —\n(a)by giving it to the individual personally;\n(b)by sending it by prepaid registered post to the address specified by the individual for the service of documents or, if no address is so specified, the individual’s residential address or business address;\n(c)by leaving it at the individual’s residential address with an adult apparently resident there, or at the individual’s business address with an adult apparently employed there;\n(d)by affixing a copy of the document in a conspicuous place at the individual’s residential address or business address;\n(e)by sending it by fax to the fax number given by the individual as the fax number for the service of documents; or\n(f)by sending it by email to the individual’s email address.\n[32/2016]\n(2) Service of a document under this section takes effect —\n(a)if the document is sent by fax and a notification of successful transmission is received, on the day of transmission;\n(b)if the document is sent by email, at the time that the email becomes capable of being retrieved by the individual; and\n(c)if the document is sent by prepaid registered post, 2 days after the day the document was posted (even if it is returned undelivered).\n[32/2016]\n(3) However, this section does not apply to documents to be served in proceedings in court.\n[32/2016]\n(4) In this section —\n“business address”, in relation to an individual, means the individual’s usual or last known place of business in Singapore;\n“email address”, in relation to an individual, means the last email address given by the individual to the person serving the document as the email address for the service of documents under this Act;\n“residential address”, in relation to an individual, means the individual’s usual or last known place of residence in Singapore.\n[18B\n[32/2016]"}},{"id":"SG-H3323-A33","no":33,"noLabel":{"en":"33."},"heading":{"en":"Regulations"},"text":{"en":"33.—(1) The Minister may make regulations for or in respect of any purpose which is considered by the Minister necessary for carrying out the provisions of this Act and for the prescribing of any matter which is authorised or required under this Act to be prescribed.\n(2) Without limiting subsection (1), the Minister may, by such regulations, provide for —\n(a)the manner in which and the places at which applications for registration of persons under this Act must be made;\n(b)the establishment of a central registry;\n(c)the obligation of a person to furnish information and documents for the purposes of the person’s registration, or the alteration of any particulars of the person entered in the register, under this Act;\n(d)the taking and recording of personal identifiers of persons registered or required to be registered under this Act;\n(e)the issue of identity cards and the particulars to be entered on the identity cards and the different categories of identity cards that may be issued to any categories or classes of persons that may be prescribed;\n(f)the inspection of identity cards by persons in charge of hotels, boarding houses, hostels and any other classes or descriptions of persons that may be prescribed;\n(g)the replacement and cancellation of identity cards which have been issued under this Act;\n(h)the re-registration of persons who have obtained identity cards or replacements of identity cards within any prescribed period;\n(i)the maximum charges that may be made for, and the conditions which may be imposed in respect of, the taking by any person of photographs for the purposes of this Act;\n(j)the surrender or return of identity cards, whether by the holders of the identity cards or other persons;\n(k)the custody and production of identity cards;\n(l)the times and places for the attendance before a registration officer of applicants and holders of identity cards;\n(m)the publication of information derived from the register;\n(n)the making of corrections to and alterations in the register and identity cards;\n(o)the absolute or conditional exemption of any person or category of persons from the provisions of this Act;\n(p)the prescribing of fees and charges for the purposes of this Act;\n(q)subject to Part 19 of the Criminal Procedure Code 2010 and section 17 of the National Library Board Act 1995, the destruction of identity cards issued, and documents obtained by the Commissioner or registration officers, under this Act; and\n(r)the prescribing of anything that is required or permitted to be prescribed under this Act.\n[32/2016]\n(3) The regulations may provide that a contravention of any provision of the regulations shall be an offence punishable with a fine not exceeding $3,000 or with imprisonment for a term not exceeding 2 years or with both.\n[32/2016]\n(4) The Minister may authorise the Commissioner to devise and use such forms as the Commissioner considers necessary for the purposes of this Act.\n[19"}},{"id":"SG-H3323-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nSection 2(1) and (3)\nPersonal identifiers\n1.A person’s fingerprint or handprint (taken using paper and ink, digital scanning technologies or otherwise).\n2.A photograph or other image of a person’s face and shoulders.\n3.An image of a person’s iris (taken using iris scanning technologies).\n4.A person’s signature.\n[32/2016]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Registration Act 1965","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3324"] = {"id":"SG-H3324","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRA1965-RG2?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":30,"structureMode":"ARTICLE","title":{"zh":"国民登记条例","en":"National Registration Regulations","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRA1965-RG2","completenessNote":"全文，共 30 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。其中 5 条为官方正文中标注的已废止条文存根（照录）。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3324-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. These Regulations may be cited as the National Registration Regulations."}},{"id":"SG-H3324-A2","no":2,"noLabel":{"en":"2."},"text":{"en":"2. [Deleted by S 701/2016 wef 01/01/2017]"},"status":"repealed"},{"id":"SG-H3324-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Registration and re-registration under Act"},"text":{"en":"3.—(1) Subject to paragraph (3), a person who is required to register under the Act —\n(a)may apply for registration in accordance with these Regulations at any time within the year that the person attains the age of 15 years; and\n(b)must apply for registration in accordance with these Regulations within one year after attaining the age of 15 years (called in this regulation the specified period).\n[S 847/2020 wef 01/10/2020]\n(1A) [Deleted by S 701/2016 wef 01/01/2017]\n(2) [Deleted by S 847/2020 wef 01/10/2020]\n(3) Every person who is required to register under the Act but who was resident outside Singapore during the whole of the specified period must, within one year after the person’s return to Singapore, apply for registration in accordance with these Regulations.\n[S 701/2016 wef 01/01/2017]\n[S 847/2020 wef 01/10/2020]\n(4) Nothing in this regulation prevents the registration of a person who fails to apply for registration within the time specified in paragraph (1) or (3), as the case may be.\n[S 701/2016 wef 01/01/2017]\n(5) Without prejudice to section 16(1)(a) of the Act, every person who is required to re-register under section 7 of the Act but who has failed to do so before 31st December 1995 shall, as soon as is practicable, apply for re‑registration in accordance with these Regulations.\n[S 701/2016 wef 01/01/2017]\n[S 847/2020 wef 01/10/2020]\n[S 410/2022 wef 31/12/2021]"}},{"id":"SG-H3324-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Procedure and documents"},"text":{"en":"4.—(1) Every person who applies for registration under regulation 3(1) or (3), or re‑registration under regulation 3(5), 14, 14A or 14B, shall —\n(a)subject to paragraph (3), provide to the registration officer an unmounted photograph that complies with the specifications set out in the National Registration (Photographs) Regulations 2017 (G.N. No. S 742/2017);\n[S 743/2017 wef 01/01/2018]\n(aa)provide such other personal identifiers as the registration officer may require;\n[S 701/2016 wef 01/01/2017]\n(ab)submit to all reasonable steps for the taking or recording of any personal identifier;\n[S 701/2016 wef 01/01/2017]\n(b)surrender his previous identity card, if any;\n(c)[Deleted by S 701/2016 wef 01/01/2017]\n(d)give the following particulars to the registration officer:\n(i)his name or if he is known by different names, each of his names in full;\n(ii)[Deleted by S 526/2002 wef 30/09/2002]\n(iii)the full particulars of his place of residence;\n(iv)his race;\n(v)his language or dialect;\n(vi)his place of birth;\n(vii)his date of birth and sex;\n(viii)[Deleted by S 526/2002 wef 30/09/2002]\n(ix)his status as a citizen of Singapore or other citizenship or national status;\n(x)[Deleted by S 526/2002 wef 30/09/2002]\n(xi)such other particulars as the registration officer may consider necessary; and\n(e)produce such documentary evidence as the registration officer may consider necessary to support the accuracy of any particulars submitted.\n[S 701/2016 wef 01/01/2017]\n[S 743/2017 wef 01/01/2018]\n(2) The registration officer may, in his discretion, endorse, with a stamp or other distinguishing mark, any document produced to him under this regulation.\n(3) A person is not required to submit an unmounted photograph under paragraph (1)(a) if the person has, within 3 months immediately preceding the date of the application mentioned in paragraph (1), submitted a photograph under regulation 3(1)(b) of the Passports Regulations 2007 (G.N. No. S 651/2007) that complies with regulation 3(2) of those Regulations.\n[S 743/2017 wef 01/01/2018]"}},{"id":"SG-H3324-A4.001","no":4.001,"noLabel":{"en":"4A."},"heading":{"en":"Authorisation for proxies"},"text":{"en":"4A. A person required to make an application or a report mentioned in regulation 3(1), 9(1), 10(1), 11(1), 14(1) or 14A(1) or who wishes to apply for re-registration under regulation 14B(1), may authorise another person to make the application or report mentioned in that regulation on behalf of the firstmentioned person.\n[S 847/2020 wef 01/10/2020]"}},{"id":"SG-H3324-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Issue of identity cards"},"text":{"en":"5.—(1) The registration officer may issue to the person mentioned in regulation 4 an identity card containing that person’s photograph and such other particulars as the Commissioner considers necessary for the purposes of identification of that person.\n[S 701/2016 wef 01/01/2017]\n(2) Identity cards issued under these Regulations shall be of 2 types; one type being pink in colour for citizens of Singapore and the other being blue in colour for persons who are not citizens of Singapore.\n(3) [Deleted by S 701/2016 wef 01/01/2017]"}},{"id":"SG-H3324-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Custody of identity card"},"text":{"en":"6. Subject to the provisions of these Regulations, any person to whom an identity card is issued shall, upon collection of the identity card, be responsible for its custody.\n[S 40/2009 wef 16/02/2009]"}},{"id":"SG-H3324-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Officers who may require production of identity cards"},"text":{"en":"7.—(1) Any registration officer, immigration officer, police officer, officer of customs, officer of the Central Narcotics Bureau or Special Investigator of the Corrupt Practices Investigation Bureau (referred to in this regulation as the inspecting officer) and any other officer or class or description of officer authorised in writing in that behalf by the Commissioner, may at any time require any person (not being a person exempted from registration under regulation 22) to produce his identity card for inspection, or to produce it within such time to such person and at such place as the officer requiring its production may think fit.\n(2) An inspecting officer may retain any identity card for the purpose of investigations.\n(3) Any inspecting officer, or any other officer authorised by the Commissioner, purporting to act under paragraph (1), shall, if so requested by any person from whom he has required the production of an identity card, produce for inspection by the person the written authority under which he purports to be acting.\n[S 701/2016 wef 01/01/2017]\n(4) For the purpose of receiving or considering any application for, or any matter connected with, the citizenship of Singapore as provided in any law for the time being in force relating to the citizenship of Singapore, any public officer or other person having any statutory duty under the provisions of any such law shall have all the powers of an inspecting officer conferred by paragraphs (1) and (2)."}},{"id":"SG-H3324-A8","no":8,"noLabel":{"en":"8."},"heading":{"en":"Other authority entitled to demand production of identity cards"},"text":{"en":"8.—(1) Any authority to whom a person required to be registered under the Act applies for the grant of any licence, permit or other document or for the exercise of the authority’s lawful functions, may, in its discretion, require the applicant to produce his identity card.\n[S 701/2016 wef 01/01/2017]\n(2) If the applicant does not produce to the authority his identity card or other proof to the satisfaction of the authority that he has been registered under the Act, or exempted from registration under these Regulations, the authority may, in its discretion, defer consideration of the application until the applicant produces either his identity card or such other proof.\n[S 701/2016 wef 01/01/2017]\n(3) Where an invalid identity card has been produced to any authority referred to in paragraph (1), it shall be lawful for the authority to retain such identity card and forward it to the Commissioner for cancellation.\n(4) For the purpose of this regulation, “invalid identity card” means an identity card which ceased to be valid under section 7(2) of the Act.\n[S 410/2022 wef 31/12/2021]\n(5) For the purposes of this regulation, a reference to a person required to be registered under the Act includes a reference to a person permitted to re‑register under regulation 14B.\n[S 743/2017 wef 01/01/2018]"}},{"id":"SG-H3324-A9","no":9,"noLabel":{"en":"9."},"heading":{"en":"Replacement identity cards"},"text":{"en":"9.—(1) Subject to paragraph (1A), where an identity card is lost, destroyed or so defaced that any particulars on the identity card are no longer decipherable, the person to whom the card relates must, within 14 days after the date on which the person becomes aware of that fact, report that fact and apply for a replacement identity card, in the form and manner required by the Commissioner.\n[S 847/2020 wef 01/10/2020]\n(1A) If the person mentioned in paragraph (1) is resident outside Singapore at the time that the identity card is lost, destroyed or defaced, the person must, in the form and manner required by the Commissioner —\n(a)report the loss, destruction or defacement of the identity card within 14 days after the date on which the person becomes aware of that fact; and\n(b)apply for a replacement identity card within 14 days after the person’s return to Singapore.\n[S 847/2020 wef 01/10/2020]\n(2) A replacement identity card may be issued in place of the one lost, destroyed or defaced on such conditions as may be imposed by the Commissioner.\n(3) Any person issued with a replacement for a lost identity card and who subsequently recovers possession of the lost identity card shall, within 7 days of its recovery, surrender the recovered identity card to a registration officer for cancellation.\n[S 701/2016 wef 01/01/2017]\n(4) Subject to paragraph (5), any person who finds or comes into possession of an identity card which does not belong to him shall, without undue delay, deliver it to the person to whom it relates or to a registration officer or to a police officer.\n[S 701/2016 wef 01/01/2017]\n[S 410/2022 wef 29/05/2022]\n(5) Paragraph (4) does not apply to a person who, knowing of the death of another person (called in this paragraph the deceased person), finds or comes into possession of the deceased person’s identity card.\n[S 410/2022 wef 29/05/2022]\n(6) Any person who, without reasonable excuse, contravenes paragraph (4) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $3,000 or to imprisonment for a term not exceeding 2 years or to both.\n[S 410/2022 wef 29/05/2022]"}},{"id":"SG-H3324-A10","no":10,"noLabel":{"en":"10."},"heading":{"en":"Replacement identity cards for incorrect particulars"},"text":{"en":"10.—(1) A person registered under the Act who —\n(a)changes his name; or\n(b)has in his possession an identity card containing any particulars, other than his address, which are to his knowledge incorrect,\nshall, within 28 days, report the fact to a registration officer and apply for a replacement identity card with the correct particulars.\n[S 701/2016 wef 01/01/2017]\n(2) A registration officer, if satisfied that any person who —\n(a)reports any change of name under paragraph (1), has in fact changed his name; or\n(b)reports that any particulars on his identity card, other than his address, are incorrect,\nmay issue him a replacement identity card.\n(3) A registration officer or a police officer may, in his discretion, require a person in possession of an identity card which, in the opinion of the registration officer or police officer, is in any way unsatisfactory for the purpose of the identification of that person to surrender the card and apply for the issue of a replacement identity card."}},{"id":"SG-H3324-A10.001","no":10.001,"noLabel":{"en":"10A."},"heading":{"en":"Collection of identity card"},"text":{"en":"10A.—(1) Upon the issue of an identity card (including a replacement identity card), the Commissioner or a registration officer shall, by notice in writing, inform the person to whom the identity card is issued to collect the identity card and surrender any previous identity card within such time and in such manner as may be specified in the notice.\n[S 40/2009 wef 16/02/2009]\n(2) A registration officer may, by notice in writing, cancel any identity card that is not collected within the period specified in paragraph (1).\n[S 40/2009 wef 16/02/2009]\n(3) The fee payable in respect of an identity card that is cancelled under paragraph (2) shall not be refunded.\n[S 40/2009 wef 16/02/2009]"}},{"id":"SG-H3324-A11","no":11,"noLabel":{"en":"11."},"heading":{"en":"Report of change of residence"},"text":{"en":"11.—(1) A report of change of residence under section 10 of the Act shall be in such form and manner as the Commissioner may require.\n[S 847/2020 wef 01/10/2020]\n[S 410/2022 wef 31/12/2021]\n(2) The form, if sent by post, shall be post-free.\n(3) Where the Commissioner amends the register in relation to a person’s residence after receiving a report of change of residence under section 10 of the Act, the Commissioner must send to the person a label stating the new residence (called in these Regulations a new address label) for affixing on the person’s identity card, or cause a new address label to be affixed on the person’s identity card.\n[S 847/2020 wef 01/10/2020]\n[S 410/2022 wef 31/12/2021]"}},{"id":"SG-H3324-A11.001","no":11.001,"noLabel":{"en":"11A."},"heading":{"en":"Affixing of new address label on identity card"},"text":{"en":"11A. A person who has received a new address label under regulation 11(3) must, as soon as practicable after receiving the new address label, affix it, or cause it to be affixed, on the person’s identity card.\n[S 847/2020 wef 01/10/2020]"}},{"id":"SG-H3324-A12","no":12,"noLabel":{"en":"12."},"text":{"en":"12. [Deleted by S 410/2022 wef 29/05/2022]"},"status":"repealed"},{"id":"SG-H3324-A13","no":13,"noLabel":{"en":"13."},"heading":{"en":"Surrendering of identity cards"},"text":{"en":"13.—(1) Any person registered under the Act —\n(a)who intends to leave Singapore permanently;\n(b)who ceases to be a citizen of Singapore; or\n[S 745/2025 wef 01/12/2025]\n(c)[Deleted by S 745/2025 wef 01/12/2025]\n(d)whose entry permit has been cancelled under the Immigration Act 1959,\n[S 410/2022 wef 31/12/2021]\nshall surrender his identity card to a registration officer or, in exceptional circumstances, to an immigration officer or to a diplomatic or consular officer of the Government of Singapore in a foreign country —\n(i)within 14 days of the date of his intended departure, if he is leaving Singapore permanently; or\n(ii)immediately, after ceasing to be a citizen of Singapore or after the cancellation of his entry permit.\n[S 745/2025 wef 01/12/2025]\n[S 701/2016 wef 01/01/2017]\n(2) Any officer to whom any identity card is surrendered by any person under paragraph (1) shall issue a receipt to the person in such form as the Commissioner may determine.\n[S 413/2006 wef 15/07/2006]"}},{"id":"SG-H3324-A14","no":14,"noLabel":{"en":"14."},"heading":{"en":"Re‑registration at age of 30 years"},"text":{"en":"14.—(1) Subject to paragraphs (2) and (3), any person who —\n(a)has been registered under the Act; and\n(b)attains the age of 30 years on or after 1 January 2002,\nmust, within one year after attaining the age of 30 years (called in this regulation the specified period), apply for re‑registration in accordance with these Regulations.\n(2) Paragraph (1) does not apply to a person who has been issued with an identity card or a replacement identity card within 10 years immediately before the person attains the age of 30 years.\n(3) Where a person mentioned in paragraph (1) —\n(a)proves to the satisfaction of the Commissioner that the person will be resident outside of Singapore during the whole of the specified period — the person may apply for re-registration in accordance with these Regulations at any time within the period of one year immediately before the date on which the person attains the age of 30 years; or\n(b)resides outside Singapore during the whole of the specified period — the person must, within one year after the person’s return to Singapore, apply for re-registration in accordance with these Regulations.\n[S 847/2020 wef 01/10/2020]\n(4) Nothing in this regulation prevents the re‑registration of a person who fails to apply for re‑registration within the time specified in paragraph (1) or (3), as the case may be.\n[S 701/2016 wef 01/01/2017]"}},{"id":"SG-H3324-A14.001","no":14.001,"noLabel":{"en":"14A."},"heading":{"en":"Re‑registration at age of 55 years"},"text":{"en":"14A.—(1) Subject to paragraphs (2) and (3), any person who —\n(a)has been registered under the Act; and\n(b)attains the age of 55 years on or after 1 January 2017,\nmust, within one year after attaining the age of 55 years (called in this regulation the specified period), apply for re‑registration in accordance with these Regulations.\n(2) Paragraph (1) does not apply to a person who has been issued with an identity card or a replacement identity card within 10 years immediately before the person attains the age of 55 years.\n(3) Where a person mentioned in paragraph (1) —\n(a)proves to the satisfaction of the Commissioner that the person will be resident outside of Singapore during the whole of the specified period — the person may apply for re-registration in accordance with these Regulations at any time within the period of one year immediately before the date on which the person attains the age of 55 years; or\n(b)resides outside Singapore during the whole of the specified period — the person must, within one year after the person’s return to Singapore, apply for re-registration in accordance with these Regulations.\n[S 847/2020 wef 01/10/2020]\n(4) Nothing in this regulation prevents the re‑registration of a person who fails to apply for re‑registration within the time specified in paragraph (1) or (3), as the case may be.\n[S 701/2016 wef 01/01/2017]"}},{"id":"SG-H3324-A14.002","no":14.002,"noLabel":{"en":"14B."},"heading":{"en":"Optional re-registration for persons born before 1 January 1962"},"text":{"en":"14B.—(1) Subject to paragraph (2), any person who —\n(a)has been registered under the Act; and\n(b)is born before 1 January 1962,\nmay apply for re‑registration in accordance with these Regulations.\n(2) Where a person mentioned in paragraph (1) receives a written notification from the Commissioner inviting that person to apply for re‑registration under that paragraph within a period of one year after the date of that notification (called in this regulation the specified period), that person may only apply for re‑registration —\n(a)in any case where that person resides outside Singapore during the whole of the specified period, within one year after that person’s return to Singapore; or\n(b)in any other case, within the specified period.\n(3) Paragraphs (1) and (2) do not apply to a person who has been issued with an identity card or a replacement identity card on or after 1 January 2008.\n(4) [Deleted by S 847/2020 wef 01/10/2020]\n(5) To avoid doubt, a person mentioned in paragraph (1) or (2) is not a person required to re‑register, or to be re‑registered, under the Act.\n[S 847/2020 wef 01/10/2020]\n[S 743/2017 wef 01/01/2018]"}},{"id":"SG-H3324-A15","no":15,"noLabel":{"en":"15."},"heading":{"en":"Publication of information"},"text":{"en":"15. The Commissioner may, in his discretion, cause to be published any information derived from the register required to be kept and maintained under section 5 of the Act.\n[S 410/2022 wef 31/12/2021]"}},{"id":"SG-H3324-A16","no":16,"noLabel":{"en":"16."},"heading":{"en":"Powers of registration officer"},"text":{"en":"16. A registration officer may, for the purpose of carrying out the provisions of these Regulations —\n(a)call upon any person to appear before him to answer any question which the registration officer may consider reasonably necessary to ask that person; or\n[S 701/2016 wef 01/01/2017]\n(b)require any person applying for registration or re-registration to make such further declaration or supply such further particulars or documents as the registration officer may reasonably require.\n[S 701/2016 wef 01/01/2017]\n(c)[Deleted by S 701/2016 wef 01/01/2017]"}},{"id":"SG-H3324-A17","no":17,"noLabel":{"en":"17."},"heading":{"en":"Duties of hotel keepers, etc."},"text":{"en":"17.—(1) The owner, manager or other person in charge of any hotel, boarding house, hostel or other like dwelling place shall not accommodate any person, other than a person exempted from registration or re-registration under regulation 22, unless he is in possession of an identity card issued to him and produces it at the time of his request for accommodation to the owner, manager or other person.\n(2) Where any person seeks accommodation at any hotel, boarding house, hostel or other like dwelling place and is not in possession of, or fails to produce, an identity card issued to him, it shall be the duty of the owner, manager or other person in charge thereof to notify the nearest police station of the fact immediately.\n(3) Where any person seeks accommodation at any hotel, boarding house, hostel or other like dwelling place and claims to be a person exempted from registration under regulation 22, the owner, manager or other person in charge thereof shall take all reasonable steps to satisfy himself that the person claiming such exemption is entitled in law to the exemption before providing accommodation for him.\n(3A) Paragraph (3) does not apply if all of the following conditions are fulfilled by the owner, manager or other person in charge of the hotel, boarding house, hostel or other like dwelling place, or any person employed to work at such dwelling place, or any combination of such persons:\n(a)before the person seeking accommodation is allowed to occupy a room, all reasonable steps have been taken to ensure that the person’s physical facial features match his or her photograph in his or her passport;\n(b)before the person seeking accommodation is allowed to occupy a room, all of the following information is submitted to the Immigration & Checkpoints Authority through the EVA System:\n(i)the following particulars as stated in the person’s passport that is presented at the point of the person’s check-in:\n(A)the person’s full name;\n(B)the person’s nationality;\n(C)the document number assigned to the passport;\n(D)the person’s date of birth;\n(E)the person’s gender;\n(ii)the accommodation booking identification number of the person’s booking of the room at the hotel, boarding house, hostel or other like dwelling place;\n(iii)where the room is in a hotel under the Hotels Act 1954, the licence number of the licence granted in respect of the hotel by the Hotels Licensing Board established under section 3(1) of that Act;\n(iv)the date of the person’s check-in at the hotel, boarding house, hostel or other like dwelling place;\n(v)the date on which the person is expected to check out;\n(c)within 24 hours of allowing the person to occupy a room, the following 3 images are submitted to the Immigration & Checkpoints Authority through the EVA System:\n(i)a digitally scanned copy of the full page in the person’s passport containing the person’s biodata;\n(ii)a photograph of the person’s face taken at the point of the person’s check-in, that complies with the specifications specified in paragraph (3E);\n(iii)either of the following:\n(A)where the person’s passport is an electronic machine-readable passport containing an electronic microchip — the image of the person extracted from the electronic microchip;\n(B)where the person’s passport is not an electronic machine-readable passport containing an electronic microchip — a digitally scanned copy of the person’s photograph in his or her passport.\n[S 587/2022 wef 08/07/2022]\n(3B) For the purpose of paragraph (3A)(a), the use of any facial recognition technology to ascertain whether a person’s physical facial features match his or her photograph in his or her passport does not of itself constitute taking all reasonable steps unless the facial recognition technology —\n(a)is used at the hotel, boarding house, hostel or other like dwelling place as part of the check-in process for the person; and\n(b)only incorrectly matches a person’s physical facial features to his or her photograph in his or her passport in no more than one out of every 200 persons.\n[S 587/2022 wef 08/07/2022]\n(3C) For the purpose of paragraph (3A)(a), (b)(i) and (c)(i) and (iii), the same passport must be used for all the steps mentioned in those provisions.\n[S 587/2022 wef 08/07/2022]\n(3D) For the purpose of paragraph (3A)(b) and (c)(ii), the check-in must take place within the premises of the hotel, boarding house, hostel or other like dwelling place at which the person is seeking accommodation.\n[S 587/2022 wef 08/07/2022]\n(3E) The specifications for a photograph under paragraph (3A)(c)(ii) are as follows:\n(a)the photograph must be in colour;\n(b)the photograph must be in sharp focus and clear with no ink marks or creases;\n(c)the photograph must provide a full frontal view of the person’s head and shoulders;\n(d)no part of the person’s face must be obstructed by any hair;\n(e)the photograph must not show the person wearing any sunglasses;\n(f)the photograph must show the person looking directly at the camera, with eyes open and clearly visible;\n(g)the photograph must show the person’s facial features in their entirety;\n(h)the photograph must not show the person wearing any hat or other head covering, other than a hat or head covering which the person habitually wears for religious reasons or due to custom, and where such hat or head covering is worn, the photograph must still provide a full frontal view of the person’s head and shoulders, showing the person’s facial features in their entirety with his or her eyes open and clearly visible, and both edges of the person’s face must be clear.\n[S 587/2022 wef 08/07/2022]\n(4) Any owner, manager or person in charge of a hotel, boarding house, hostel or other like dwelling place who accommodates any person in contravention of this regulation or fails or neglects to notify the police in accordance with paragraph (2) shall be guilty of an offence.\n(5) In this regulation, a reference to a person employed to work at a hotel, boarding house, hostel or other like dwelling place, includes a person who is engaged to work at such hotel, boarding house, hostel or other like dwelling place under a contract for services.\n[S 587/2022 wef 08/07/2022]\n(6) In this regulation, “EVA System” means the E-Visitor Authentication System owned by the Singapore Tourism Board.\n[S 587/2022 wef 08/07/2022]"}},{"id":"SG-H3324-A18","no":18,"noLabel":{"en":"18."},"text":{"en":"18. [Deleted by S 701/2016 wef 01/01/2017]"},"status":"repealed"},{"id":"SG-H3324-A19","no":19,"noLabel":{"en":"19."},"text":{"en":"19. [Deleted by S 556/2007 wef 01/12/2007]"},"status":"repealed"},{"id":"SG-H3324-A20","no":20,"noLabel":{"en":"20."},"heading":{"en":"Offences"},"text":{"en":"20. Any person who —\n(a)in any application or report (as the case may be) under regulation 3(1), (3) or (5), 9(1), 10(1), 11(1), 14, 14A or 14B, whether made on his own behalf or on behalf of another, makes any statement or gives any information which is false in any material particular, and which he either knows or believes to be false or does not believe to be true;\n[S 847/2020 wef 01/10/2020]\n(b)[Deleted by S 413/2006 wef 15/07/2006]\n(c)fails to comply with a summons or requisition of a registration officer made under regulation 16;\n(d)being a parent or guardian of a person under the age of 16 years, conduces, by neglect or otherwise, to the commission of an offence by such person;\n(e)being a person who has been granted unrestricted residence in Singapore under any written law relating to immigration in force in Singapore and who has not applied for registration in accordance with these Regulations within 30 days after the date of his entry into Singapore or, if he was already in Singapore at the time of the grant, within 30 days after the date of the grant;\n[S 701/2016 wef 01/01/2017]\n(f)being a public officer or a registration officer, except in the public interest and with the permission of the Commissioner, or for the purpose of criminal proceedings, publishes or communicates to any person any information contained in the register required to be kept under section 5 of the Act or any book or record made under or for the purpose of carrying out the provisions of these Regulations; or\n[S 701/2016 wef 01/01/2017]\n[S 410/2022 wef 31/12/2021]\n(g)fails to comply with any provision (except regulation 9(4)) of these Regulations,\n[S 701/2016 wef 01/01/2017]\n[S 410/2022 wef 29/05/2022]\nshall be guilty of an offence and shall be liable on conviction to imprisonment for a term not exceeding 2 years or to a fine not exceeding $3,000 or to both."}},{"id":"SG-H3324-A21","no":21,"noLabel":{"en":"21."},"text":{"en":"21. [Deleted by S 701/2016 wef 01/01/2017]"},"status":"repealed"},{"id":"SG-H3324-A22","no":22,"noLabel":{"en":"22."},"heading":{"en":"Exempted persons"},"text":{"en":"22.—(1) The following persons shall be exempted from the requirement to register under the Act:\n(a)the President of Singapore;\n(b)a child of any age before the start of the year in which he attains the age of 15 years;\n[S 610/2008 wef 01/12/2008]\n(c)any person who is authorised or permitted to remain in Singapore by virtue of a pass issued under the Immigration Act 1959;\n[S 847/2020 wef 01/10/2020]\n[S 410/2022 wef 31/12/2021]\n(d)any person to whom a diplomatic identity card, a consular identity card or an international organisation identity card has been issued by the Government;\n(e)a member of any visiting armed force lawfully present in Singapore (excluding locally enlisted personnel) in possession of the official identity card or other document of identity ordinarily issued to members of such force; and\n(f)any person in possession of a valid identity card which has been issued to him in any of the States of Malaya under the provisions of any law for the time being in force in the States of Malaya relating to the issue of identity cards and who has not been granted unrestricted residence in Singapore under any written law relating to immigration in force in Singapore.\n[S 701/2016 wef 01/01/2017]\n(2) Every person referred to in paragraph (1)(f) who resides in Singapore for a period exceeding 30 days shall report to a registration officer in such form as the Commissioner may require —\n(a)his place of residence in Singapore, within 40 days of his arrival in Singapore; and\n(b)every subsequent change of residence in Singapore, within 28 days of such change."}},{"id":"SG-H3324-A23","no":23,"noLabel":{"en":"23."},"heading":{"en":"Destruction of identity cards and other documents"},"text":{"en":"23.—(1) Subject to Part 19 of the Criminal Procedure Code 2010 and section 17 of the National Library Board Act 1995, the Commissioner may order the destruction of any of the following items in the Commissioner’s possession if the Commissioner is of the opinion that the item is obsolete, invalid or no longer required:\n(a)any identity card issued under the Act;\n(b)any document (including a record of a personal identifier) obtained by the Commissioner or a registration officer from a person registered or required to be registered under the Act.\n[S 743/2017 wef 01/01/2018]\n[S 410/2022 wef 31/12/2021]\n(2) For the purposes of this regulation, a reference to a person required to be registered under the Act includes a reference to a person permitted to re‑register under regulation 14B.\n[S 743/2017 wef 01/01/2018]"}},{"id":"SG-H3324-A24","no":24,"noLabel":{"en":"24."},"heading":{"en":"Fees"},"text":{"en":"24.—(1) The fees payable for the purposes of these Regulations shall be as set out in the Schedule.\n(2) The Commissioner may, in his discretion, waive any fee required to be paid under these Regulations."}},{"id":"SG-H3324-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nRegulation 24\nFEES\n1.For the issue of an identity card to a citizen of Singapore —\n(a)on registration or re-registration under regulation 3\n$ 10.\n(b)on re-registration under regulation 14, 14A or 14B\n$ 10.\n2.For the issue of an identity card to a person who is not a citizen of Singapore —\n(a)on registration or re-registration under regulation 3\n$ 50.\n(b)on re-registration under regulation 14, 14A or 14B\n$ 50.\n3.For the replacement of a lost identity card —\n(a)first replacement\n$100.\n(b)second and every subsequent replacement\n$300.\n4.For the replacement of an identity card due to damage, defacement or change of particulars\n$ 60.\n[S 743/2017 wef 01/01/2018]\n[S 701/2016 wef 01/01/2017]\n[G.N. Nos. S 226/91; S159/95; S560/95; S134/96; S538/96; S 130/97; S115/98; S356/98; S133/99; S575/99]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Registration Regulations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3325"] = {"id":"SG-H3325","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRDA2007-S410-2012?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"全国疾病登记（急性心肌梗塞通报）条例 2012","en":"National Registry of Diseases (Acute Myocardial Infarction Notification) Regulations 2012","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRDA2007-S410-2012","completenessNote":"全文，共 7 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 3 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3325-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations may be cited as the National Registry of Diseases (Acute Myocardial Infarction Notification) Regulations 2012 and shall come into operation on 1st September 2012."}},{"id":"SG-H3325-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In these Regulations, unless the context otherwise requires —\n“acute myocardial infarction” means myocardial infarction with one or more of the following:\n(a)changes in cardiac biomarkers beyond the typical limits applicable to the particular test used, together with —\n(i)symptoms indicative of myocardial ischaemia; or\n(ii)electrocardiogram changes indicative of new myocardial ischaemia;\n(b)development of new pathological Q waves in the electrocardiogram of the patient;\n(c)new loss of viable myocardium or new regional wall motion abnormality;\n(d)fresh thrombus,\nand includes acute myocardial infarction developed as a complication of cardiovascular intervention for some other cardiac condition;\n“patient” means a person to whom a notification referred to in regulation 3 relates."}},{"id":"SG-H3325-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Form, time and manner of notification for acute myocardial infarction"},"text":{"en":"3. For the purposes of section 6(1) of the Act, a notification by the manager of a healthcare institution to the Registrar that a person has been diagnosed with or is undergoing treatment for acute myocardial infarction at the healthcare institution shall —\n(a)contain the information specified in the First Schedule;\n(b)be made in the appropriate Form or Listing specified in the Second Schedule, which Form or Listing may be downloaded from the Registry’s Internet website at http://www.nrdo.gov.sg or obtained from the office of the Registry during such hours as the office is open for business;\n(c)be sent to the Registrar —\n(i)by hand (including by courier);\n(ii)by registered mail; or\n(iii)by using such secure electronic notification system as may be approved by the Registrar; and\n(d)be made —\n(i)where the patient has been diagnosed with acute myocardial infarction, not later than 3 months after the diagnosis of that disease was first made;\n(ii)where the patient is undergoing treatment for acute myocardial infarction which commenced before 1st September 2012 and continues on or after that date, not later than 30th November 2012; or\n(iii)where the patient is undergoing treatment for acute myocardial infarction which commenced on or after 1st September 2012, not later than 3 months after the treatment commenced."}},{"id":"SG-H3325-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Collection of additional information under section 7 of Act"},"text":{"en":"4. Upon receiving a notification referred to in regulation 3 from the manager of a healthcare institution, the Registrar or an authorised Registry officer may, for the purposes of section 7(1) of the Act, require the manager to provide all or any of the additional information specified in the Third Schedule concerning the patient."}},{"id":"SG-H3325-A900000","no":900000,"noLabel":{"en":"FIRST SCHEDULE"},"text":{"en":"FIRST SCHEDULE\nRegulation 3(a)\nInformation to be Submitted with Notification\n1.Identification number of patient (NRIC number, passport number, Foreign Identification number or hospital registration number).\n2.Name of patient.\n3.Date of birth or age of patient (if date of birth is unknown)."}},{"id":"SG-H3325-A900001","no":900001,"noLabel":{"en":"SECOND SCHEDULE"},"text":{"en":"SECOND SCHEDULE\nRegulation 3(b)\nForms of Notification\n1.Acute myocardial infarction notification forms set out at http://www.nrdo.gov.sg.\n2.Acute myocardial infarction case listings.\n3.Cardiac biomarkers listings.\n4.Hospital inpatient discharge summaries."}},{"id":"SG-H3325-A900002","no":900002,"noLabel":{"en":"THIRD SCHEDULE"},"text":{"en":"THIRD SCHEDULE\nRegulation 4\nAdditional Information\n1.Patient’s particulars:\n(a)gender;\n(b)ethnic group;\n(c)citizenship or resident status;\n(d)country of birth;\n(e)residential postal code.\n2.Other information:\n(a)dates of admission and discharge;\n(b)discharge status;\n(c)name of admitting healthcare institution;\n(d)if patient transferred to admitting healthcare institution, name of transferring healthcare institution;\n(e)whether patient was admitted before transfer, if applicable;\n(f)details of arrival at emergency medicine department (including date, time(s), and whether electrocardiogram was transmitted from ambulance to emergency medicine department);\n(g)presenting symptoms or signs (including date and time of onset of symptoms or signs);\n(h)venue where cardiopulmonary resuscitation and/or direct current shock was applied;\n(i)heart failure classification in emergency medicine department or upon admission;\n(j)care setting where patient was managed after onset of acute myocardial infarction.\n3.Risk factor profile (including date profile taken).\n4.Investigations (including date(s) and findings).\n5.Classification of acute myocardial infarction and treatment(s) of acute myocardial infarction (including type(s), date(s) and time(s) of treatment(s)).\n6.Details of medications administered.\n7.Complications during hospitalisation (including date(s)), if any.\n8.Current status of patient:\n(a)living or deceased;\n(b)where the patient is deceased, the date, time, place and cause of death.\n9.Patient’s electrocardiograms.\n10.Details of notifying healthcare institution:\n(a)person who made the notification;\n(b)name of notifying healthcare institution."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Registry of Diseases (Acute Myocardial Infarction Notification) Regulations 2012","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3326"] = {"id":"SG-H3326","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRDA2007-S353-2009?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"全国疾病登记（癌症通报）条例 2009","en":"National Registry of Diseases (Cancer Notification) Regulations 2009","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRDA2007-S353-2009","completenessNote":"全文，共 7 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 3 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3326-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations may be cited as the National Registry of Diseases (Cancer Notification) Regulations 2009 and shall come into operation on 1st August 2009."}},{"id":"SG-H3326-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In these Regulations, unless the context otherwise requires —\n“cancer” includes in-situ neoplasms, neoplasms with borderline or uncertain malignant potential, as well as all tumours (malignant, borderline, in-situ and benign) of the brain and other parts of the central nervous system (including the pituitary gland, craniopharyngeal duct and pineal gland);\n“patient” means a person to whom a notification referred to in regulation 3 relates."}},{"id":"SG-H3326-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Form, time and manner of notification for cancer"},"text":{"en":"3. For the purposes of section 6(1) of the Act, a notification by the manager of a healthcare institution to the Registrar that a person has been diagnosed with or is undergoing treatment for cancer at the healthcare institution shall —\n(a)contain, in relation to that patient, the information specified in the First Schedule;\n(b)be made in any of the Forms set out in the Second Schedule or at the Registry’s Internet website at http://www.nrdo.gov.sg;\n(c)be sent to the Registrar —\n(i)by hand (including by courier);\n(ii)by registered mail; or\n(iii)by using such secure electronic notification system as may be approved by the Registrar; and\n(d)be made within the following time:\n(i)where the patient has been diagnosed with cancer through a confirmatory diagnostic test, not later than 3 months after the diagnosis of that cancer was first made; or\n(ii)where the patient is undergoing treatment for cancer in the healthcare institution, not later than 3 months after the treatment for that cancer commenced."}},{"id":"SG-H3326-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Collection of additional information under section 7 of Act"},"text":{"en":"4. Upon receiving a notification referred to in regulation 3, the Registrar or an authorised Registry officer may, for the purposes of section 7(1) of the Act, require the manager of the healthcare institution who made the notification to provide all or any of the additional information specified in the Third Schedule concerning the patient."}},{"id":"SG-H3326-A900000","no":900000,"noLabel":{"en":"FIRST SCHEDULE"},"text":{"en":"FIRST SCHEDULE\nRegulation 3(a)\nInformation of Patient to be Submitted With Notification\n1. Identification number (including NRIC, passport number, Foreign Identification Number or hospital registration number).\n2. Name.\n3. Date of birth or age (if date of birth is unknown).\n4. Name of notifying healthcare institution (including department).\n5. Date the cancer was diagnosed.\n6. Primary site of the cancer."}},{"id":"SG-H3326-A900001","no":900001,"noLabel":{"en":"SECOND SCHEDULE"},"text":{"en":"SECOND SCHEDULE\nRegulation 3(b)\nForms of Notification\n1. Cancer notification form set out at the Registry’s Internet website at http://www.nrdo.gov.sg.\n2. Hospital inpatient discharge summaries.\n3. Cancer case listings.\n4. Nuclear medicine, radiotherapy, oncology, haematology or histopathology reports."}},{"id":"SG-H3326-A900002","no":900002,"noLabel":{"en":"THIRD SCHEDULE"},"text":{"en":"THIRD SCHEDULE\nRegulation 4\nAdditional Information\n1. Patient’s particulars:\n(a)gender;\n(b)ethnic group;\n(c)citizenship or resident status;\n(d)country of birth.\n2. Details of notifying healthcare institution:\n(a)medical practitioner in charge of the case;\n(b)healthcare institution (including specific centre, department or clinic) responsible for subsequent treatment or follow-up;\n(c)person who made the notification.\n3. Diagnosis information:\n(a)basis for diagnosis;\n(b)grade or differentiation;\n(c)histological diagnosis.\n4. Current status of patient:\n(a)living or deceased;\n(b)where patient is deceased, the date, place and cause of death.\n5. Clinical staging and treatment:\n(a)clinical stage of cancer;\n(b)tumour size;\n(c)treatment (including type and date of treatment).\n6. Risk factors."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Registry of Diseases (Cancer Notification) Regulations 2009","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3327"] = {"id":"SG-H3327","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRDA2007-S98-2011?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"全国疾病登记（慢性肾衰竭通报）条例 2011","en":"National Registry of Diseases (Chronic Kidney Failure Notification) Regulations 2011","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRDA2007-S98-2011","completenessNote":"全文，共 7 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 3 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3327-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations may be cited as the National Registry of Diseases (Chronic Kidney Failure Notification) Regulations 2011 and shall come into operation on 1st March 2011."}},{"id":"SG-H3327-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2.—(1) In these Regulations, unless the context otherwise requires —\n“chronic kidney failure”, in relation to a patient, refers to the state when —\n(a)the Glomerular Filtration Rate (GFR) (corrected to the body surface area of 1.73m2) of the patient is less than 15 ml/min;\n(b)the serum creatinine level of the patient is more than or equal to 500 µmol/L or 5.7mg/dl; or\n(c)the patient’s kidney function has deteriorated to the extent that, in the opinion of a medical practitioner responsible for the management of his care, the patient requires treatment for kidney failure,\nand the patient is not, in the opinion of a medical practitioner responsible for the management of his care, suffering from acute kidney failure;\n“patient” means a person to whom a notification referred to in regulation 3 relates;\n“treatment for chronic kidney failure” means any treatment for kidney failure administered to a patient suffering from chronic kidney failure;\n“treatment for kidney failure” means any of the following modalities of treatment:\n(a)haemodialysis and its related modalities (including chronic haemofiltration and chronic haemodiafiltration);\n(b)peritoneal dialysis;\n(c)kidney transplantation (including follow-up medical treatment post-transplant);\n(d)conservative medical management.\n(2) In these Regulations —\n(a)any reference to the date of commencement of treatment for chronic kidney failure of a patient at a healthcare institution shall be a reference to the date on which the patient first receives any modality of such treatment at that healthcare institution; and\n(b)any reference to the date of change of modality of treatment for chronic kidney failure of a patient at a healthcare institution shall be a reference to the date on which the patient first receives a different modality of such treatment from that which he was previously receiving at that healthcare institution."}},{"id":"SG-H3327-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Form, time and manner of notification for chronic kidney failure"},"text":{"en":"3. For the purposes of section 6(1) of the Act, a notification by the manager of a healthcare institution to the Registrar under that section shall —\n(a)contain, in relation to the patient, the information specified in the First Schedule;\n(b)be made in the appropriate Form or Listing specified in the Second Schedule, which Form or Listing may be downloaded from the Registry’s Internet website at http://www.nrdo.gov.sg or obtained from the office of the Registry during such hours as the office is open for business;\n(c)be sent to the Registrar —\n(i)by hand (including by courier);\n(ii)by registered mail; or\n(iii)by using such secure electronic notification system as may be approved by the Registrar; and\n(d)be made within the following time:\n(i)in the case of a patient diagnosed with chronic kidney failure at the healthcare institution, not later than 3 months after that diagnosis is made;\n(ii)in the case of a patient who undergoes kidney transplantation at the healthcare institution, not later than 3 months after the completion of any transplant operation;\n(iii)in the case of a patient who undergoes treatment for chronic kidney failure (other than kidney transplantation) at the healthcare institution —\n(A)which commenced before 1st March 2011 and continues on or after that date, not later than 31st May 2011; or\n(B)which commenced on or after 1st March 2011, not later than 3 months after the date of commencement of the treatment;\n(iv)in the case of a patient who undergoes a change of modality of treatment for chronic kidney failure at the healthcare institution, not later than one month after the date of change of modality of such treatment."}},{"id":"SG-H3327-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Collection of additional information under section 7 of Act"},"text":{"en":"4. Upon receiving a notification referred to in regulation 3 from the manager of a healthcare institution, the Registrar or an authorised Registry officer may, for the purposes of section 7(1) of the Act, require the manager to provide all or any of the additional information specified in the Third Schedule concerning the patient."}},{"id":"SG-H3327-A900000","no":900000,"noLabel":{"en":"FIRST SCHEDULE"},"text":{"en":"FIRST SCHEDULE\nRegulation 3(a)\nInformation to be Submitted\nWith Notification\n1. Identification number of patient (NRIC number, passport number, Foreign Identification Number or hospital registration number).\n2. Name of patient.\n3. Date of birth or age of patient (if date of birth is unknown).\n4. Gender of patient."}},{"id":"SG-H3327-A900001","no":900001,"noLabel":{"en":"SECOND SCHEDULE"},"text":{"en":"SECOND SCHEDULE\nRegulation 3(b)\nForms of Notification\n1. Diagnosis of or commencement of treatment for chronic kidney failure notification form at http://www.nrdo.gov.sg.\n2. Change of modality of treatment or change of healthcare institution form at http://www.nrdo.gov.sg.\n3. Kidney transplant form at http://www.nrdo.gov.sg.\n4. Listings of patients diagnosed with or undergoing treatment for chronic kidney failure.\n5. Listings of patients undergoing or who have undergone haemodialysis or peritoneal dialysis.\n6. Listings of patients who have undergone kidney transplantation.\n7. Listings of patients with Glomerular Filtration Rate (GFR) (corrected to the body surface area of 1.73m2) of less than 15 ml/min or with serum creatinine level of more than or equal to 500 µmol/L or 5.7mg/dl."}},{"id":"SG-H3327-A900002","no":900002,"noLabel":{"en":"THIRD SCHEDULE"},"text":{"en":"THIRD SCHEDULE\nRegulation 4\nAdditional Information\nPart I\nfor Diagnosis of or Commencement of Treatment\nfor Chronic Kidney Failure\n1. Referring or treating healthcare institution:\n(a)referral clinic or centre;\n(b)current centre;\n(c)date treatment started at current centre;\n(d)current modality of treatment.\n2. Particulars of patient:\n(a)ethnic group(s);\n(b)citizenship or resident status;\n(c)country of birth;\n(d)highest education level;\n(e)religion;\n(f)residential postal code.\n3. Diagnostic information:\n(a)primary renal disease leading to chronic kidney failure;\n(b)date reached chronic kidney failure;\n(c)Glomerular Filtration Rate (GFR) at diagnosis;\n(d)serum creatinine level at diagnosis;\n(e)height of patient at diagnosis (including date);\n(f)weight of patient at diagnosis (including date);\n(g)Glomerular Filtration Rate (GFR) at first dialysis;\n(h)serum creatinine level at first dialysis;\n(i)height of patient at first dialysis (including date);\n(j)weight of patient at first dialysis (including date).\n4. Co-morbid conditions (including type(s), date(s) of diagnosis, and hepatitis status).\n5. Current status of patient:\n(a)living or deceased;\n(b)where patient is deceased, the date, place and cause of death.\n6. Rehabilitation status and quality of life:\n(a)limitation on or preclusion from transplant.\nPart II\nfor Change of Healthcare Institution or\nChange of Modality of Treatment\n1. Particulars of patient:\n(a)clinic or centre from which the patient was referred;\n(b)highest education level;\n(c)religion;\n(d)residential postal code.\n2. Information on change of healthcare institution (where applicable):\n(a)healthcare institution transferred from;\n(b)new healthcare institution;\n(c)date treatment started at new healthcare institution.\n3. Information on change of modality (where applicable):\n(a)new modality of treatment.\n4. Transplantation (where applicable as the new modality of treatment):\n(a)date of transplant;\n(b)place of transplant follow-up;\n(c)date of first follow-up treatment (post-transplant).\n5. Current status of patient:\n(a)living or deceased;\n(b)where the patient is deceased, the date, place and cause of death.\nPart III\nfor Transplant Patients\n1. Referring or treating healthcare institution:\n(a)referral clinic or centre;\n(b)current centre;\n(c)date of first follow-up treatment (post-transplant).\n2. Particulars of patient:\n(a)citizenship or resident status;\n(b)ethnic group(s);\n(c)country of birth;\n(d)highest education level;\n(e)religion;\n(f)residential postal code.\n3. Dialysis history:\n(a)whether patient was on dialysis prior to transplant.\n4. Glomerular Filtration Rate (GFR) at time of transplant:\n(a)serum creatinine level at time of transplant (including date);\n(b)height of patient at time of transplant (including date);\n(c)weight of patient at time of transplant (including date);\n(d)Glomerular Filtration Rate (GFR) at time of transplant (including date).\n5. Transplant information:\n(a)date of transplant;\n(b)place where patient underwent transplant;\n(c)where transplant was done overseas, country and centre where patient underwent transplant;\n(d)graft number.\n6. Donor information:\n(a)gender;\n(b)ethnic group(s);\n(c)date of birth or age (if date of birth is unknown);\n(d)whether donor is living or deceased;\n(e)in respect of living donor: relationship of living donor to recipient; and\n(f)in respect of deceased donor: whether donor’s heart was beating or non-beating at the point the kidney was removed from the donor’s body.\n7. Graft status:\n(a)whether graft is functioning;\n(b)if graft is functioning, current serum creatinine level, Glomerular Filtration Rate (GFR), and height and weight of the patient (including date);\n(c)if graft is not functioning, date and cause of graft loss.\nPart IV\nfor Patients Undergoing Treatment\n1. Treating healthcare institution:\n(a)current centre;\n(b)date treatment started at current centre.\n2. Particulars of patient:\n(a)citizenship or resident status;\n(b)ethnic group(s);\n(c)country of birth;\n(d)highest education level;\n(e)religion;\n(f)residential postal code.\n3. Co-morbid conditions (including type(s) and date(s) of diagnosis and hepatitis status).\n4. Current status of patient:\n(a)living or deceased;\n(b)where the patient is deceased, the date, place and cause of death.\n5. Rehabilitation status and quality of life:\n(a)limitation on or preclusion from transplant.\n6. Nutrition:\n(a)last serum albumin level (including date);\n(b)laboratory method used.\n7. Anaemia:\n(a)last haemoglobin level (including date);\n(b)erythropoietin stimulating agent administered, if any (including type and dosage);\n(c)transferrin saturation (including date);\n(d)serum ferritin level (including date).\n8. Mineral metabolism:\n(a)serum calcium level (including date);\n(b)serum phosphate level (including date);\n(c)serum immunoreactive parathyroid hormone level (including date);\n(d)corrected calcium level (including date).\n9. Haemodialysis data:\n(a)dialysis prescription:\n(i)frequency of haemodialysis sessions;\n(ii)duration of each dialysis session;\n(b)vascular access:\n(i)current vascular access;\n(c)adequacy:\n(i)last urea reduction ratio (including date, pre-dialysis urea and post-dialysis urea);\n(ii)last Kt/V (where K is the dialyzer clearance, t is the time and V is the volume of water in patient’s body) (including date).\n10. Peritoneal Dialysis data:\n(a)adequacy of peritoneal dialysis:\n(i)last weekly total Kt/V (including date);\n(ii)residual creatinine clearance at last total creatinine clearance measurement (including date);\n(b)peritoneal dialysis outcome:\n(i)ever had peritonitis (including date of first episode);\n(c)technique survival:\n(i)cause of permanent transfer from peritoneal dialysis to haemodialysis (where applicable);\n(ii)date of permanent transfer from peritoneal dialysis to haemodialysis (where applicable).\n11. Post-Transplant data:\n(a)graft status:\n(i)whether graft is functioning;\n(ii)if graft is functioning, current serum creatinine level, Glomerular Filtration Rate (GFR), and height and weight of the patient (including date);\n(iii)if graft is not functioning, date and cause of graft loss."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Registry of Diseases (Chronic Kidney Failure Notification) Regulations 2011","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3328"] = {"id":"SG-H3328","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRDA2007-S530-2009?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"国家疾病登记处（肝脏——肝切除后（供体）通报）条例 2009","en":"National Registry of Diseases (Liver — Post Hepatic Resection (Donor) Notification) Regulations 2009","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRDA2007-S530-2009","completenessNote":"全文，共 8 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 4 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3328-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations may be cited as the National Registry of Diseases (Liver — Post Hepatic Resection (Donor) Notification) Regulations 2009 and shall come into operation on 1st November 2009."}},{"id":"SG-H3328-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In these Regulations, unless the context otherwise requires —\n“hepatic resection” means the surgical removal of a part of the liver;\n“liver — post hepatic resection (donor)” refers to the absence of a part of the liver in a person due to having undergone hepatic resection for the purpose of transplantation of a part of his liver into the body of another living person;\n“patient” means a person to whom a notification referred to in regulation 3 relates;\n“recipient” means the person into whose body a part of the patient’s liver is or will be transplanted."}},{"id":"SG-H3328-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Form, time and manner of notification for liver — post hepatic resection (donor)"},"text":{"en":"3. For the purposes of section 6(1) of the Act, a notification by the manager of a healthcare institution to the Registrar that a person has undergone hepatic resection for the purpose of transplantation into the body of another living person or is undergoing any treatment for liver — post hepatic resection (donor), at the healthcare institution shall —\n(a)contain, in relation to that patient, the information specified in the First Schedule;\n(b)be made in any of the Forms set out in the Second Schedule or at the Registry’s Internet website at http://www.nrdo.gov.sg;\n(c)be sent to the Registrar —\n(i)by hand (including by courier);\n(ii)by registered mail; or\n(iii)by using such secure electronic notification system as may be approved by the Registrar; and\n(d)be made within the following time:\n(i)where the patient has undergone hepatic resection, not later than 3 months after hepatic resection; or\n(ii)where the patient is undergoing treatment for liver — post hepatic resection (donor) in the healthcare institution, not later than 3 months after the first of such treatments received by the patient at that healthcare institution on or after 1st November 2009."}},{"id":"SG-H3328-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Collection of additional information under section 7 of Act"},"text":{"en":"4. Upon receiving a notification referred to in regulation 3, the Registrar or an authorised Registry officer may, for the purposes of section 7(1) of the Act, require the manager of the healthcare institution who made the notification to provide all or any of the additional information specified in the Third and Fourth Schedules concerning the patient."}},{"id":"SG-H3328-A900000","no":900000,"noLabel":{"en":"FIRST SCHEDULE"},"text":{"en":"FIRST SCHEDULE\nRegulation 3(a)\nInformation of Patient to be Submitted\nWith Notification\n1. Identification number (including NRIC number, passport number, Foreign Identification Number or hospital registration number).\n2. Name.\n3. Date of birth or age (if date of birth is unknown).\n4. Name of notifying healthcare institution (including department).\n5. Date of hepatic resection (for new cases)."}},{"id":"SG-H3328-A900001","no":900001,"noLabel":{"en":"SECOND SCHEDULE"},"text":{"en":"SECOND SCHEDULE\nRegulation 3(b)\nForms of Notification\n1. New Case Registration Form for Liver Donor set out at the Registry’s Internet website at http://www.nrdo.gov.sg.\n2. Follow-up Form for Liver Donor set out at the Registry’s Internet website at http://www.nrdo.gov.sg.\n3. Hospital inpatient discharge summaries.\n4. Donor case listings."}},{"id":"SG-H3328-A900002","no":900002,"noLabel":{"en":"THIRD SCHEDULE"},"text":{"en":"THIRD SCHEDULE\nRegulation 4\nAdditional Information for New Cases\n1. Particulars of patient for new case registration:\n(a)citizenship or resident status;\n(b)gender;\n(c)ethnic group;\n(d)marital status;\n(e)country of birth;\n(f)educational level;\n(g)employment status;\n(h)relationship to recipient.\n2. Particulars of recipient:\n(a)name;\n(b)identification number (including NRIC number, passport number, Foreign Identification Number or hospital registration number);\n(c)date of birth or age (if date of birth is unknown);\n(d)citizenship or resident status;\n(e)gender;\n(f)ethnic group;\n(g)marital status;\n(h)name of recipient’s healthcare institution.\n3. Patient baseline information (pre-donation):\n(a)date of baseline information;\n(b)weight;\n(c)height;\n(d)smoking status;\n(e)EQ-5D (including mobility, self-care, usual activities, pain or discomfort and anxiety or depression);\n(f)liver panel (including date);\n(g)full blood count (including date);\n(h)prothrombin time (PT) (including date);\n(i)ultrasound, CT scan or MRI (including findings and date).\n4. Data related to donor hepatic resection:\n(a)place of surgery;\n(b)type of hepatic resection;\n(c)complications during hospitalisation (including type(s), and date if the donor has liver failure or impairment);\n(d)date of initial discharge;\n(e)live donor discharge disposition.\n5. Details of notifying healthcare institution:\nperson who made the notification."}},{"id":"SG-H3328-A900003","no":900003,"noLabel":{"en":"FOURTH SCHEDULE"},"text":{"en":"FOURTH SCHEDULE\nRegulation 4\nAdditional Information for Cases\nUndergoing Treatment\n1. Patient’s status (at follow-up):\n(a)date of consultation;\n(b)healthcare institution (including specific centre, department or clinic) responsible for subsequent treatment or follow-up;\n(c)weight;\n(d)height;\n(e)smoking status;\n(f)employment status;\n(g)EQ-5D (including mobility, self-care, usual activities, pain or discomfort and anxiety or depression);\n(h)other illnesses since last visit (including diagnosis and date of diagnosis);\n(i)admission to hospital since last visit (including diagnosis and date of admission).\n2. Investigations (at follow-up):\n(a)liver panel (including date);\n(b)full blood count (including date);\n(c)prothrombin time (PT) (including date);\n(d)ultrasound, CT Scan or MRI (including date and findings);\n(e)ERCP or MRCP (including date and findings).\n3. Adverse condition relating to liver:\nwhether or not the patient has liver failure (including date, cause of liver failure, on transplant waiting list and reason for not on transplant waiting list).\n4. Vital status:\n(a) whether patient is living or deceased;\n(b)where the patient is deceased, the date, place and cause of death.\n5. Details of notifying healthcare institution:\nperson who made the notification."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Registry of Diseases (Liver — Post Hepatic Resection (Donor) Notification) Regulations 2009","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3329"] = {"id":"SG-H3329","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRDA2007-S531-2009?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"国家疾病登记处（单肾——肾切除后（供体）通报）条例 2009","en":"National Registry of Diseases (Single Kidney — Post Nephrectomy (Donor) Notification) Regulations 2009","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRDA2007-S531-2009","completenessNote":"全文，共 8 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 4 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3329-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations may be cited as the National Registry of Diseases (Single Kidney — Post Nephrectomy (Donor) Notification) Regulations 2009 and shall come into operation on 1st November 2009."}},{"id":"SG-H3329-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In these Regulations, unless the context otherwise requires —\n“nephrectomy” means the surgical removal of a kidney;\n“patient” means a person to whom a notification referred to in regulation 3 relates;\n“recipient” means the person into whose body a patient’s kidney is or will be transplanted;\n“single kidney — post nephrectomy (donor)” refers to the absence of a kidney in a person due to having undergone nephrectomy for the purpose of transplantation of his kidney into the body of another living person."}},{"id":"SG-H3329-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Form, time and manner of notification for single kidney — post nephrectomy (donor)"},"text":{"en":"3. For the purposes of section 6(1) of the Act, a notification by the manager of a healthcare institution to the Registrar that a person has undergone nephrectomy for the purpose of transplantation into the body of another living person or is undergoing any treatment for single kidney — post nephrectomy (donor), at the healthcare institution shall —\n(a)contain, in relation to that patient, the information specified in the First Schedule;\n(b)be made in any of the Forms set out in the Second Schedule or at the Registry’s Internet website at http://www.nrdo.gov.sg;\n(c)be sent to the Registrar —\n(i)by hand (including by courier);\n(ii)by registered mail; or\n(iii)by using such secure electronic notification system as may be approved by the Registrar; and\n(d)be made within the following time:\n(i)where the patient has undergone nephrectomy, not later than 3 months after the nephrectomy; or\n(ii)where the patient is undergoing treatment for single kidney — post nephrectomy (donor) in the healthcare institution, not later than 3 months after the first of such treatments received by the patient at that healthcare institution on or after 1st November 2009."}},{"id":"SG-H3329-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Collection of additional information under section 7 of Act"},"text":{"en":"4. Upon receiving a notification referred to in regulation 3, the Registrar or an authorised Registry officer may, for the purposes of section 7(1) of the Act, require the manager of the healthcare institution who made the notification to provide all or any of the additional information specified in the Third and Fourth Schedules concerning the patient."}},{"id":"SG-H3329-A900000","no":900000,"noLabel":{"en":"FIRST SCHEDULE"},"text":{"en":"FIRST SCHEDULE\nRegulation 3(a)\nInformation of Patient\nto be Submitted With Notification\n1. Identification number (including NRIC number, passport number, Foreign Identification Number or hospital registration number).\n2. Name.\n3. Date of birth or age (if date of birth is unknown).\n4. Name of notifying healthcare institution (including department).\n5. Date of nephrectomy (for new cases)."}},{"id":"SG-H3329-A900001","no":900001,"noLabel":{"en":"SECOND SCHEDULE"},"text":{"en":"SECOND SCHEDULE\nRegulation 3(b)\nForms of Notification\n1. New Case Registration Form for Kidney Donor set out at the Registry’s Internet website at http://www.nrdo.gov.sg.\n2. Yearly Follow-up Form for Kidney Donor set out at the Registry’s Internet website at http://www.nrdo.gov.sg.\n3. Hospital inpatient discharge summaries.\n4. Donor case listings."}},{"id":"SG-H3329-A900002","no":900002,"noLabel":{"en":"THIRD SCHEDULE"},"text":{"en":"THIRD SCHEDULE\nRegulation 4\nAdditional Information for New Cases\n1. Particulars of patient for new case registration:\n(a)citizenship or resident status;\n(b)gender;\n(c)ethnic group;\n(d)marital status;\n(e)country of birth;\n(f)educational level;\n(g)employment status;\n(h)relationship to recipient.\n2. Particulars of recipient:\n(a)name;\n(b)identification number (including NRIC number, passport number, Foreign Identification Number or hospital registration number);\n(c)citizenship or resident status;\n(d)date of birth or age (if date of birth is unknown);\n(e)gender;\n(f)ethnic group;\n(g)marital status;\n(h)name of recipient’s healthcare institution.\n3. Patient baseline information (pre-donation):\n(a)date of baseline information;\n(b)blood pressure;\n(c)weight;\n(d)height;\n(e)smoking status;\n(f)EQ-5D (including mobility, self-care, usual activities, pain or discomfort and anxiety or depression);\n(g)diabetes mellitus;\n(h)oral glucose tolerance test;\n(i)hyperlipidemia;\n(j)serum creatinine;\n(k)creatinine clearance or radionuclide GFR;\n(l)urine FEME;\n(m)24-hour urine protein;\n(n)whether patient is on anti-hypertensives;\n(o)whether patient is on hypolipidemics;\n(p)other abnormalities of kidney (including stone, cyst and others).\n4. Data related to donor nephrectomy:\n(a)place of surgery;\n(b)name of lead surgeon;\n(c)type of nephrectomy;\n(d)date of initial discharge;\n(e)live donor discharge disposition;\n(f)complications during hospitalisation (including type(s); if the donor has renal failure or impairment, serum creatinine and whether creatinine is measured with IDMS Standard).\n5. Details of notifying healthcare institution:\nperson who made the notification."}},{"id":"SG-H3329-A900003","no":900003,"noLabel":{"en":"FOURTH SCHEDULE"},"text":{"en":"FOURTH SCHEDULE\nRegulation 4\nAdditional Information for Cases\nUndergoing Treatment\n1. Particulars of patient (at follow-up):\n(a)date of consultation;\n(b)healthcare institution (including specific centre, department or clinic) responsible for subsequent treatment or follow-up;\n(c)complications within 6 weeks of discharge (including type(s); if the patient has renal failure or impairment, serum creatinine and whether creatinine is measured with IDMS Standard; and if the patient has other re-hospitalisation, reason and duration);\n(d)blood pressure;\n(e)weight;\n(f)smoking status;\n(g)employment status;\n(h)EQ-5D (including mobility, self-care, usual activities, pain or discomfort and anxiety or depression).\n2. Risk factors (at follow-up):\n(a)diabetes mellitus (including HbA1C and type of treatment if patient has diabetes mellitus; and whether the patient has impaired fasting glycemia or impaired glucose tolerance if not diabetic);\n(b)hyperlipidemia.\n3. Investigations (at follow-up):\n(a)fasting blood sugar;\n(b)serum creatinine;\n(c)creatinine clearance or radionuclide GFR;\n(d)Urine FEME;\n(e)24-hour urine protein or urine protein or creatinine ratio.\n4. Medications (at follow-up):\n(a)whether patient is on anti-hypertensives;\n(b)whether patient is on hypolipidemics.\n5. Complications (at follow-up):\n(a)other illnesses since last visit (including diagnosis);\n(b)admissions to hospital since last visit (including reason and date of admission);\n(c)whether or not the patient has Chronic Kidney Disease Stage 5 (including date, cause of Chronic Kidney Disease Stage 5, on transplant waiting list and reason for not on transplant waiting list).\n6. Vital status:\n(a)whether patient is living or deceased;\n(b)where the patient is deceased, the date, place and cause of death.\n7. Details of notifying healthcare institution:\nperson who made the notification."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Registry of Diseases (Single Kidney — Post Nephrectomy (Donor) Notification) Regulations 2009","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3330"] = {"id":"SG-H3330","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRDA2007-S412-2012?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"全国疾病登记处（急性心肌梗塞指明实体）公告 2012","en":"National Registry of Diseases (Specified Entity for Acute Myocardial Infarction) Notification 2012","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRDA2007-S412-2012","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3330-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification may be cited as the National Registry of Diseases (Specified Entity for Acute Myocardial Infarction) Notification 2012 and shall come into operation on 1st September 2012."}},{"id":"SG-H3330-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Specified entity for acute myocardial infarction"},"text":{"en":"2. The National Registry of Diseases Office of the Health Promotion Board established under the Health Promotion Board Act (Cap. 122B) is declared to be a specified entity for the collection of information relating to acute myocardial infarction for the purposes of section 24 of the Act."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Registry of Diseases (Specified Entity for Acute Myocardial Infarction) Notification 2012","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3331"] = {"id":"SG-H3331","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRDA2007-S355-2009?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"国家疾病登记处（癌症指定实体）公告 2009","en":"National Registry of Diseases (Specified Entity for Cancer) Notification 2009","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRDA2007-S355-2009","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3331-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification may be cited as the National Registry of Diseases (Specified Entity for Cancer) Notification 2009 and shall come into operation on 1st August 2009."}},{"id":"SG-H3331-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Specified entity for cancer"},"text":{"en":"2. The Minister hereby declares the National Registry of Diseases Office of the Health Promotion Board to be a specified entity for cancer for the purposes of section 24 of the Act."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Registry of Diseases (Specified Entity for Cancer) Notification 2009","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3332"] = {"id":"SG-H3332","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NRDA2007-S100-2011?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"全国疾病登记处（慢性肾功能衰竭指明实体）公告 2011","en":"National Registry of Diseases (Specified Entity for Chronic Kidney Failure) Notification 2011","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NRDA2007-S100-2011","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3332-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification may be cited as the National Registry of Diseases (Specified Entity for Chronic Kidney Failure) Notification 2011 and shall come into operation on 1st March 2011."}},{"id":"SG-H3332-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Specified entity for chronic kidney failure"},"text":{"en":"2. The National Registry of Diseases Office of the Health Promotion Board established under the Health Promotion Board Act (Cap. 122B) is declared to be a specified entity for the collection of information relating to chronic kidney failure for the purposes of section 24 of the Act."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Registry of Diseases (Specified Entity for Chronic Kidney Failure) Notification 2011","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3333"] = {"id":"SG-H3333","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NRDA2007?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":25,"structureMode":"ARTICLE","title":{"zh":"全国疾病登记法 2007","en":"National Registry of Diseases Act 2007","orig":null},"level":"law","status":"active","docNumber":"Act NRDA2007","completenessNote":"全文，共 25 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3333-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Short title"},"text":{"en":"1. This Act is the National Registry of Diseases Act 2007."}},{"id":"SG-H3333-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Interpretation"},"text":{"en":"2. In this Act, unless the context otherwise requires —\n“agent of the Registry” means any public officer or employee of any statutory body who is appointed by the Director‑General under section 3(3) to be an agent of the Registry;\n[Act 11 of 2023 wef 01/05/2023]\n“anonymised”, when used to describe information pertaining to an individual, means that the identity of that individual has been concealed or protected, whether by presenting the information in a statistical form or otherwise, such that it cannot be readily discovered or ascertained from that information;\n“approved conveyance” has the meaning given by section 2(1) of the Healthcare Services Act 2020;\n[Act 19 of 2025 wef 05/12/2025]\n“approved permanent premises” has the meaning given by section 2(1) of the Healthcare Services Act 2020;\n[Act 19 of 2025 wef 05/12/2025]\n“authorised Registry officer” means any Registry officer who is duly authorised by the Registrar in writing to carry out any particular function or to exercise any particular power under this Act;\n[Deleted by Act 11 of 2023 wef 01/05/2023]\n“Director‑General” means the Director‑General of Health;\n[Act 11 of 2023 wef 01/05/2023]\n“disclose”, in relation to any information held by the Registry, includes to grant to any person access to that information;\n“disease” means any physical or mental ailment, disorder, defect or morbid condition (whether of sudden onset or gradual development), or the recurrence of that ailment, disorder, defect or morbid condition;\n“healthcare institution” means —\n(a)any approved permanent premises at which, or any approved conveyance in or from which, the holder of a licence granted under the Healthcare Services Act 2020 is approved to provide any one or more of the following licensable healthcare services:\n(i)an acute hospital service;\n(ii)an ambulatory surgical centre service;\n(iii)a clinical laboratory service;\n(iv)a community hospital service;\n(v)a nuclear medicine service;\n(vi)an outpatient dental service;\n(vii)an outpatient medical service;\n(viii)an outpatient renal dialysis service;\n(ix)a radiological service;\n(x)any other licensable healthcare service that may be prescribed; or\n(b)any facility, premises or conveyance declared by the Minister, by order in the Gazette, to be a healthcare institution for the purposes of this Act;\n[Act 19 of 2025 wef 05/12/2025]\n“individually-identifiable”, when used to describe information pertaining to an individual, means that the identity of that individual can be readily discovered or ascertained from that information;\n“investigation officer” means any public officer who is appointed under section 13 to be an investigation officer for the purposes of this Act;\n“licensable healthcare service” has the meaning given by section 3(1) of the Healthcare Services Act 2020;\n[Act 19 of 2025 wef 05/12/2025]\n“manager”, in relation to a healthcare institution, means the individual having the management or control of the healthcare institution;\n[Act 3 of 2020 wef 03/01/2022]\n“medical practitioner” means a medical practitioner registered under the Medical Registration Act 1997 and who holds a valid practising certificate;\n“register” means a register kept and maintained by the Registrar under section 5;\n“Registrar” means the person appointed by the Director‑General under section 3 to be the Registrar of the Registry and includes a Deputy Registrar and an Assistant Registrar;\n[Act 11 of 2023 wef 01/05/2023]\n“Registry” means the National Registry of Diseases established under section 4;\n“Registry officer” means any person who is appointed by the Director‑General under section 3 to be an officer of the Registry;\n[Act 11 of 2023 wef 01/05/2023]\n“regulations” means regulations made under section 23;\n“reportable disease” means a disease that is specified in the Schedule;\n“requisite consent”, for the purposes of section 11 or 12, means —\n(a)the consent, given in the prescribed form and manner, of the person whose individually‑identifiable information is to be disclosed under that section; or\n(b)where the person mentioned in paragraph (a) is unable to give his or her own consent due to age, infirmity of mind or body or any other cause, the consent, given in the prescribed form and manner, of such other person who is authorised by the regulations to give such consent for and on his or her behalf."}},{"id":"SG-H3333-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 2 NATIONAL REGISTRY OF DISEASES"},"heading":{"en":"Appointment of Registrar, etc."},"text":{"en":"3.—(1) The Director‑General must, with the approval of the Minister, appoint a Registrar who is responsible for the administration of the Registry.\n[Act 11 of 2023 wef 01/05/2023]\n(2) The Director‑General may, with the approval of the Minister, appoint —\n(a)a Deputy Registrar;\n(b)one or more Assistant Registrars; and\n(c)such other Registry officers as the Director‑General may consider necessary,\nto assist the Registrar in the administration of the Registry.\n[Act 11 of 2023 wef 01/05/2023]\n(3) The Director‑General may appoint any public officer or employee of any statutory body to be an agent of the Registry to assist in the collection and collation of any information under this Act, subject to such conditions and limitations as the Director‑General may specify.\n[Act 11 of 2023 wef 01/05/2023]\n(4) The Registrar, Deputy Registrar, Assistant Registrars, Registry officers and agents of the Registry are deemed to be public servants within the meaning of the Penal Code 1871."}},{"id":"SG-H3333-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 2 NATIONAL REGISTRY OF DISEASES"},"heading":{"en":"National Registry of Diseases"},"text":{"en":"4. A National Registry of Diseases is established, the functions of which are —\n(a)to collect information on reportable diseases that have been diagnosed and treated in Singapore;\n(b)to establish, keep and maintain for each reportable disease a register containing individually‑identifiable information obtained under this Act;\n(c)to compile and publish statistics on the epidemiology, management and outcomes of reportable diseases;\n(d)to provide information for the purpose of supporting —\n(i)health services that are being provided by healthcare institutions to the patients of the healthcare institutions who are suffering from any reportable disease; and\n(ii)national public health policies, initiatives, programmes and related studies concerning any reportable disease; and\n(e)generally to do all such acts, matters and things as are necessary to be carried out under this Act."}},{"id":"SG-H3333-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 NATIONAL REGISTRY OF DISEASES"},"heading":{"en":"Registers"},"text":{"en":"5.—(1) The Registrar must keep and maintain for each reportable disease a register containing individually-identifiable information of each person who is diagnosed with and treated for that disease in Singapore.\n(2) The registers kept and maintained under subsection (1) must not be open for inspection by the public."}},{"id":"SG-H3333-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 3 NOTIFICATION OF REPORTABLE DISEASES"},"heading":{"en":"Duty to notify Registrar of reportable diseases"},"text":{"en":"6.—(1) Where a person is diagnosed with or undergoes treatment for a reportable disease at a healthcare institution, the manager of the healthcare institution must, in the form and within the time prescribed, notify the Registrar of that fact.\n(2) Any manager of a healthcare institution who —\n(a)without reasonable excuse, fails to comply with the requirements of subsection (1); or\n(b)in compliance or purported compliance with subsection (1), furnishes as true information which the manager knows or has reason to believe to be false,\nshall be guilty of an offence and shall be liable on conviction to a fine not exceeding $2,000.\n(3) A certificate under the hand of the Registrar stating that a notification required under subsection (1) has not been furnished or is incorrect is prima facie evidence of the facts stated in the certificate."}},{"id":"SG-H3333-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 3 NOTIFICATION OF REPORTABLE DISEASES"},"heading":{"en":"Collection of information"},"text":{"en":"7.—(1) Upon a notification being made to the Registrar under section 6, the Registrar or an authorised Registry officer may require the manager of the healthcare institution who made the notification to provide any additional information that may be prescribed concerning the person to whom the notification relates.\n(2) For the purpose of subsection (1), the Registrar or an authorised Registry officer may require the manager of the healthcare institution —\n(a)to furnish the prescribed additional information to any Registry officer or agent of the Registry; or\n(b)to produce to the Registrar or any Registry officer or agent of the Registry for inspection any medical record, book or document which contains or may contain the prescribed additional information.\n(3) Any manager of a healthcare institution who —\n(a)without reasonable excuse, fails to comply with the requirement of the Registrar or an authorised Registry officer under this section; or\n(b)in compliance or purported compliance with this section, furnishes as true information which the manager knows or has reason to believe to be false,\nshall be guilty of an offence and shall be liable on conviction to a fine not exceeding $2,000.\n(4) A certificate under the hand of the Registrar stating that the additional information required under subsection (1) has not been furnished or is incorrect is prima facie evidence of the facts stated in the certificate."}},{"id":"SG-H3333-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 4 CONFIDENTIALITY AND DISCLOSURE"},"heading":{"en":"Confidentiality"},"text":{"en":"8.—(1) Except in the case of a prosecution for an offence under this Act, the Registrar, a Registry officer, an agent of the Registry or any other person who acts under the direction of the Director‑General or Registrar for any purpose related to the Registry is not compellable in any proceedings to give evidence in respect of, or to produce any document containing, any individually‑identifiable information which has been obtained under this Act.\n[Act 11 of 2023 wef 01/05/2023]\n(2) Unless otherwise provided by this Act, the Registrar, a Registry officer, an agent of the Registry or any other person who acts under the direction of the Director‑General or Registrar for any purpose related to the Registry must not disclose the contents of any register or any individually‑identifiable information which may have come to his or her knowledge in the course of performing any duty or function under this Act or carrying out any act in relation to the Registry.\n[Act 11 of 2023 wef 01/05/2023]\n(3) Any person who fails to comply with subsection (2) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 12 months or to both."}},{"id":"SG-H3333-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 4 CONFIDENTIALITY AND DISCLOSURE"},"heading":{"en":"Disclosure and publication of anonymised information"},"text":{"en":"9.—(1) The Registrar —\n(a)may, on a request by any person and —\n(i)upon payment by the person of the prescribed fee; and\n(ii)subject to the conditions that the Registrar may impose; and\n(b)must, on a request by the Director‑General,\ndisclose or publish any information held by the Registry in an anonymised form.\n[Act 11 of 2023 wef 01/05/2023]\n(2) Any person who fails to comply with any condition imposed under subsection (1) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3333-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 4 CONFIDENTIALITY AND DISCLOSURE"},"heading":{"en":"National public health programmes"},"text":{"en":"10.—(1) The Registrar may, with the approval of the Director‑General, disclose individually‑identifiable information held by the Registry to any public officer or any other person for the purpose of conducting national public health programmes concerning any reportable disease.\n[Act 11 of 2023 wef 01/05/2023]\n(2) In determining whether to approve the disclosure under subsection (1), the Director‑General must, subject to subsection (3), have regard to —\n(a)the aims and objectives of the national public health programme, including any public health benefits to Singapore;\n(b)the identity of the public officers or persons involved in the programme to whom the individually‑identifiable information held by the Registry will be disclosed;\n(c)the use to which the individually‑identifiable information will or may be put; and\n(d)the measures that will be put in place under the national public health programme to protect the individually‑identifiable information from unauthorised disclosure.\n[Act 11 of 2023 wef 01/05/2023]\n(3) The Director‑General must not approve any disclosure under subsection (1) unless the Director‑General is satisfied that the national public health programme cannot be carried out with anonymised information.\n[Act 11 of 2023 wef 01/05/2023]\n(4) The Director‑General may, when granting approval under subsection (1), impose the conditions that the Director‑General considers necessary with respect to —\n(a)the identities of the public officers or persons, or class of public officers or persons who are authorised to receive or handle the individually‑identifiable information;\n(b)the use to which the individually‑identifiable information is to or may be put; and\n(c)the measures that must be put in place under the national public health programme to protect the individually‑identifiable information from unauthorised disclosure.\n[Act 11 of 2023 wef 01/05/2023]\n(5) The Director‑General may, at any time, vary or revoke any of the existing conditions imposed under subsection (4) or impose new conditions.\n[Act 11 of 2023 wef 01/05/2023]\n(6) The Director‑General may, at any time, revoke the approval given under subsection (1).\n[Act 11 of 2023 wef 01/05/2023]\n(7) Any person who fails to comply with any condition imposed under subsection (4) or any new condition imposed under subsection (5) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 12 months or to both."}},{"id":"SG-H3333-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 4 CONFIDENTIALITY AND DISCLOSURE"},"heading":{"en":"Medical treatment"},"text":{"en":"11. The Registrar may, if he or she thinks fit, disclose to a medical practitioner any individually-identifiable information of a medical nature held by the Registry concerning a person suffering from a reportable disease if the Registrar is satisfied that —\n(a)the medical practitioner is responsible for the treatment and care of that person;\n(b)the disclosure is necessary for the proper treatment of that person; and\n(c)the requisite consent has been given for the disclosure."}},{"id":"SG-H3333-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 4 CONFIDENTIALITY AND DISCLOSURE"},"heading":{"en":"Disclosure of individually‑identifiable information for public health research"},"text":{"en":"12.—(1) A person (called in this section the researcher) who requires any individually‑identifiable information held by the Registry for the purpose of carrying out any medical, epidemiological or other form of public health research concerning any reportable disease may apply to the Registrar in the prescribed form for the disclosure of the information.\n(2) The Registrar may, subject to the conditions that he or she thinks fit to impose and upon the payment by the researcher of the prescribed fees (if any) disclose to the researcher the individually‑identifiable information if the Registrar is satisfied that —\n(a)the research cannot be carried out with anonymised information;\n(b)the requisite consent has been given for the individually‑identifiable information to be disclosed to the researcher for the purpose of the research;\n(c)the research may —\n(i)improve the quality of health services provided for patients suffering from any reportable disease in Singapore; or\n(ii)support any national public health policy, initiative or programme concerning any reportable disease; and\n(d)the researcher and the research comply with the prescribed conditions, if any.\n(3) A researcher to whom the individually-identifiable information of any person has been disclosed under subsection (2) must not —\n(a)use the individually‑identifiable information for any purpose other than the purpose approved by the Registrar; or\n(b)disclose the name or any other individually‑identifiable information of that person unless the requisite consent has been given for the disclosure.\n(4) A researcher to whom the individually‑identifiable information of any person has been disclosed under subsection (2) must not disclose —\n(a)the name or any other information leading to the identification of the healthcare institution in which that person has been diagnosed with, or has been or is being examined or treated for, a reportable disease unless the manager of that healthcare institution has given his or her consent for the disclosure in the prescribed form and manner; or\n(b)the name or any other information leading to the identification of the person who provided the individually‑identifiable information to the Registrar under this Act, unless that person has given his or her consent for the disclosure in the prescribed form and manner.\n(5) Before making any decision on an application under subsection (1), the Registrar may refer the application to a national research advisory committee comprising at least 3 and not more than 5 members appointed by the Director‑General and, in making a decision, the Registrar must have regard to any report made to the Registrar by the national research advisory committee.\n[Act 11 of 2023 wef 01/05/2023]\n(6) Where a researcher to whom any individually-identifiable information of any person has been disclosed under subsection (2) contravenes subsection (3) or (4) or any condition imposed under subsection (2), the researcher shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 12 months or to both."}},{"id":"SG-H3333-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 5 ENFORCEMENT POWERS"},"heading":{"en":"Appointment of investigation officers"},"text":{"en":"13.—(1) The Director‑General may, in writing, appoint any public officer to be an investigation officer for the purpose of conducting an investigation into any offence under this Act.\n[Act 11 of 2023 wef 01/05/2023]\n(2) Every investigation officer, when exercising any of his or her powers under this Act, must, if not in uniform, declare his or her office and must, on demand, produce to any person affected by the exercise of that power such identification card as the Director‑General may direct to be carried by the investigation officer when exercising that power.\n[Act 11 of 2023 wef 01/05/2023]"}},{"id":"SG-H3333-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 5 ENFORCEMENT POWERS"},"heading":{"en":"Powers of entry, inspection, search, seizure, etc."},"text":{"en":"14.—(1) An investigation officer has, for the purposes of investigating any offence under this Act, the power to do all or any of the following:\n(a)to enter, inspect and search, without warrant at any reasonable time, any place which the investigation officer has reason to believe contains evidence relating to or connected with an offence under this Act;\n(b)for the purposes of paragraph (a) —\n(i)to inspect and make copies of and take extracts from, or require the occupier or any person having the management or control of any place mentioned in that paragraph to provide copies of or extracts from, any book, document, record or electronic material;\n(ii)to inspect and make copies of and take extracts from, or require the occupier or any person having the management or control of any place mentioned in that paragraph to provide copies of or extracts from, any medical record of any person who has been or who is being treated or examined at that place, even if the prior consent of the person has not been obtained;\n(iii)to seize and remove from any place mentioned in that paragraph any book, document, record, electronic material, article or thing which the investigation officer reasonably believes to be the subject matter of, or to be connected with the commission of, an offence under this Act; and\n(iv)to make such examination or inquiry as may be necessary to ascertain whether the provisions of this Act have been complied with;\n(c)to require any person, by way of a written order, to produce any book, document, record, electronic material, article or thing that the investigation officer considers is necessary or desirable for the purposes of an investigation under this Act.\n(2) The occupier or any person having the management and control of, or who is found in, any place mentioned in subsection (1)(a) must render all necessary assistance and cooperation to the investigation officer as are necessary for an entry, inspection, examination, inquiry or otherwise for the exercise of the officer’s powers under this Act in relation to that place.\n(3) Any person who —\n(a)obstructs, hinders or impedes an investigation officer in the exercise of the officer’s power under this section; or\n(b)fails to comply with any order or requirement of an investigation officer under this section or to produce any book, document, record, electronic material, article or thing which the person is required by or under this Act to produce to an investigation officer,\nshall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3333-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 5 ENFORCEMENT POWERS"},"heading":{"en":"Powers to examine and secure attendance"},"text":{"en":"15.—(1) An investigation officer may —\n(a)examine orally any person supposed to be acquainted with the facts and circumstances of any offence or matter under this Act, and to reduce to writing any statement made by the person so examined; and\n(b)require by written order the attendance before himself or herself of any person, being within the limits of Singapore, who, from information given or otherwise, appears to be acquainted with the facts and circumstances of any offence or matter under this Act and that person must attend as required.\n(2) The person mentioned in subsection (1)(a) is bound to state truly the facts and circumstances with which the person is acquainted concerning any offence or matter under this Act, except only that the person may decline to make, with regard to any fact or circumstance, a statement which would have a tendency to expose the person to a criminal charge, penalty or forfeiture.\n(3) A statement made by a person under this section must —\n(a)be read over to the person; and\n(b)after correction (if necessary), be signed by the person.\n(4) If any person fails to attend as required by an order under subsection (1)(b), the investigation officer may report the failure to a Magistrate who may then issue a warrant to secure the attendance of that person as required by the order."}},{"id":"SG-H3333-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 6 MISCELLANEOUS"},"heading":{"en":"Offences by bodies corporate, etc."},"text":{"en":"16.—(1) Where an offence under this Act committed by a body corporate is proved —\n(a)to have been committed with the consent or connivance of an officer; or\n(b)to be attributable to any neglect on the officer’s part,\nthe officer as well as the body corporate shall be guilty of the offence and shall be liable to be proceeded against and punished accordingly.\n(2) Where the affairs of a body corporate are managed by its members, subsection (1) applies in relation to the acts and defaults of a member in connection with the member’s functions of management as if the member were a director of the body corporate.\n(3) Where an offence under this Act committed by a partnership is proved —\n(a)to have been committed with the consent or connivance of a partner; or\n(b)to be attributable to any neglect on the partner’s part,\nthe partner as well as the partnership shall be guilty of the offence and shall be liable to be proceeded against and punished accordingly.\n(4) Where an offence under this Act committed by an unincorporated association (other than a partnership) is proved —\n(a)to have been committed with the consent or connivance of an officer of the unincorporated association or a member of its governing body; or\n(b)to be attributable to any neglect on the part of that officer or member,\nthe officer or member as well as the unincorporated association shall be guilty of the offence and shall be liable to be proceeded against and punished accordingly.\n(5) In this section —\n“body corporate” includes a limited liability partnership which has the meaning given by section 2(1) of the Limited Liability Partnerships Act 2005;\n“officer” —\n(a)in relation to a body corporate, means any director, partner, member of the committee of management, chief executive, manager, secretary or other similar officer of the body corporate and includes any person purporting to act in any such capacity; or\n(b)in relation to an unincorporated association (other than a partnership), means the president, the secretary, or any member of the committee of the unincorporated association, or any person holding a position analogous to that of president, secretary or member of a committee and includes any person purporting to act in any such capacity;\n“partner” includes a person purporting to act as a partner.\n(6) The Minister may, by regulations, provide for the application of any provision of this section, with the modifications that the Minister considers appropriate, to any body corporate or unincorporated association formed or recognised under the law of a territory outside Singapore."}},{"id":"SG-H3333-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 6 MISCELLANEOUS"},"heading":{"en":"Protection from liability"},"text":{"en":"17.—(1) No action, suit or other legal proceedings shall lie against the Government or personally against the Director‑General, the Registrar, a Registry officer, an agent of the Registry, an investigation officer or any other person for anything done or omitted to be done in good faith in the course of or in connection with —\n(a)the exercise or purported exercise of any power under this Act;\n(b)the performance or purported performance of any function or the discharge or purported discharge of any duty under this Act; or\n(c)the compliance or purported compliance with this Act.\n[Act 11 of 2023 wef 01/05/2023]\n(2) A person who makes a notification to the Registrar under section 6 or who otherwise makes available to the Registrar, a Registry officer, an agent of the Registry or an investigation officer any document or other information for the purpose of complying with the requirements of this Act, shall not, by virtue of doing so —\n(a)be liable to any suit or other legal proceedings for breach of confidence; or\n(b)be held in any proceedings before any court or tribunal or in any other respect to have breached any code of professional etiquette or ethics, or to have departed from any accepted form of professional conduct.\n(3) Where pursuant to this Act the Registrar discloses to any person any information that is held by the Registry, neither the Registrar nor any Registry officer involved in the disclosure of the information shall be liable for any loss or damage suffered by that person or by any other person by reason of any error or omission of any nature appearing in the information disclosed or however caused if the error or omission was made in good faith and in the ordinary course of the discharge of the duties of the Registrar or Registry officer."}},{"id":"SG-H3333-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 6 MISCELLANEOUS"},"heading":{"en":"Obstructing Registrar, Registry officer, etc., in execution of duty"},"text":{"en":"18. Any person who obstructs, hinders or impedes the Registrar, a Registry officer or an agent of the Registry in the performance or execution of his or her duty or anything which he or she is authorised, empowered or required to do under this Act shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3333-A19","no":19,"noLabel":{"en":"19."},"chapter":{"en":"PART 6 MISCELLANEOUS"},"heading":{"en":"Jurisdiction of court"},"text":{"en":"19. Despite any provision to the contrary in the Criminal Procedure Code 2010, a District Court has jurisdiction to try any offence under this Act and has power to impose the full penalty or punishment in respect of the offence."}},{"id":"SG-H3333-A20","no":20,"noLabel":{"en":"20."},"chapter":{"en":"PART 6 MISCELLANEOUS"},"heading":{"en":"Composition of offences"},"text":{"en":"20.—(1) The Director‑General may compound any offence under this Act that is prescribed as a compoundable offence by collecting from the person reasonably suspected of having committed that offence a sum not exceeding the lower of the following —\n(a)one half of the amount of the maximum fine prescribed for that offence;\n(b)$5,000.\n[Act 11 of 2023 wef 01/05/2023]\n(2) On payment of the sum of money mentioned in subsection (1), no further proceedings may be taken against that person in respect of the offence.\n(3) All sums collected under this section must be paid into the Consolidated Fund."}},{"id":"SG-H3333-A21","no":21,"noLabel":{"en":"21."},"chapter":{"en":"PART 6 MISCELLANEOUS"},"heading":{"en":"General exemption"},"text":{"en":"21.—(1) The Minister may, by order in the Gazette, either permanently or for such period as the Minister may think fit, exempt any person or class of persons from all or any of the provisions of this Act.\n(2) The Minister may, when granting an exemption under subsection (1), impose such conditions as the Minister thinks fit."}},{"id":"SG-H3333-A22","no":22,"noLabel":{"en":"22."},"chapter":{"en":"PART 6 MISCELLANEOUS"},"heading":{"en":"Amendment of Schedule"},"text":{"en":"22. The Minister may, by order in the Gazette, amend the Schedule."}},{"id":"SG-H3333-A23","no":23,"noLabel":{"en":"23."},"chapter":{"en":"PART 6 MISCELLANEOUS"},"heading":{"en":"Regulations"},"text":{"en":"23.—(1) The Minister may make regulations for carrying out the purposes and provisions of this Act.\n(2) Without limiting subsection (1), the Minister may make regulations with respect to all or any of the following matters:\n(a)the circumstances under and the manner in which individually‑identifiable information held by the Registry may be anonymised for the purposes of disclosure and publication under section 9;\n(b)the circumstances under and the manner in which persons whose individually‑identifiable information is held by the Registry, or the next‑of‑kin of those persons, may be contacted for the purposes of any national public health programme mentioned in section 10;\n(c)the circumstances under and the manner in which individually‑identifiable information held by the Registry may be disclosed for the purposes of any medical, epidemiological or other form of public health research mentioned in section 12;\n(d)the circumstances under and the manner in which a person may obtain certified extracts of individually‑identifiable information relating to himself or herself;\n(e)the forms to be used for the purposes of this Act;\n(f)the fees and charges payable under or for the purposes of this Act;\n(g)the offences which may be compounded under section 20;\n(h)any other matter as may be necessary or expedient to be prescribed for carrying out the provisions of this Act.\n(3) The Minister may, in making any regulations, provide that any contravention of or failure to comply with any regulation shall be an offence punishable with a fine not exceeding $10,000 or with imprisonment for a term not exceeding 6 months or with both."}},{"id":"SG-H3333-A24","no":24,"noLabel":{"en":"24."},"chapter":{"en":"PART 6 MISCELLANEOUS"},"heading":{"en":"Saving provision for personal information previously collected"},"text":{"en":"24.—(1) As from the date on which any disease becomes a reportable disease for the purposes of this Act —\n(a)any personal information that had already been collected by a specified entity before that date pertaining to a person who had been diagnosed with or who had undergone treatment for that disease for the purposes of a national disease registry is deemed to be personal information that has been collected under and for the purposes of this Act in relation to that reportable disease; and\n(b)any person who had made a notification of any such personal information to the specified entity before that date is entitled to the same protection from liability under section 17(2) as if the person had made the notification under section 6 on or after that date.\n(2) In subsection (1), “specified entity” means any entity that is declared by the Minister by notification in the Gazette to be a specified entity for the purposes of this section."}},{"id":"SG-H3333-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nSections 2 and 22\nReportable diseases\n1. Cancer, including in situ neoplasms, neoplasms with borderline or uncertain malignant potential, as well as all tumours (malignant, borderline, in situ and benign) of the brain and other parts of the central nervous system (including the pituitary gland, craniopharyngeal duct and pineal gland).\n2. Single Kidney — Post Nephrectomy (Donor).\n3. Liver — Post Hepatic Resection (Donor).\n4. Chronic kidney failure, as defined in the National Registry of Diseases (Chronic Kidney Failure Notification) Regulations 2011.\n5. Acute myocardial infarction as defined in the National Registry of Diseases (Acute Myocardial Infarction Notification) Regulations 2012.\n[S 354/2009; S 529/2009; S 99/2011; S 411/2012]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Registry of Diseases Act 2007","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3334"] = {"id":"SG-H3334","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NRFA2006?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"国家研究基金法 2006","en":"National Research Fund Act 2006","orig":null},"level":"law","status":"active","docNumber":"Act NRFA2006","completenessNote":"全文，共 18 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3334-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Short title"},"text":{"en":"1. This Act is the National Research Fund Act 2006."}},{"id":"SG-H3334-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"General interpretation"},"text":{"en":"2. In this Act, unless the context otherwise requires —\n“Board” means the National Research Foundation Board established under section 9;\n“Council” means the Research, Innovation and Enterprise Council established under section 10;\n“Fund” means the National Research Fund established under section 4;\n“invest” includes entering into a transaction or an arrangement for the protection of investments;\n“knowledge” means any knowledge or other information, whether or not the possessor of the knowledge or information has any legally enforceable rights in relation to it;\n“property” means any legal or equitable estate or interest (whether present or future and whether vested or contingent) in real or personal property of any description;\n“public authority” means any board or authority established by or under any written law to perform or discharge any public function;\n“securities” includes shares, inscribed stock, debentures, bonds, debenture stock, notes or any other document creating, evidencing or acknowledging indebtedness."}},{"id":"SG-H3334-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Meaning of “research and development activities”"},"text":{"en":"3.—(1) In this Act, “research and development activities” means —\n(a)systematic, investigative or experimental activities that involve innovation and are carried on either wholly or partly within Singapore for the purpose of —\n(i)increasing or acquiring new knowledge (whether or not that knowledge will have specific practical application); or\n(ii)creating new or improved materials, products, devices, processes or services; or\n(b)other activities that are carried on either wholly or partly within Singapore for a purpose related to the carrying out of activities of the kind mentioned in paragraph (a) or incidental or conducive to the attainment or furtherance of the purposes mentioned in that paragraph, including —\n(i)scientific and technical information services (such as data collection) to support activities of the kind mentioned in paragraph (a);\n(ii)building expenditure incurred in the acquisition or construction of a building, or of an extension, alteration or improvement to, or of maintenance of a building used or to be used for in activities of the kind mentioned in paragraph (a);\n(iii)training and management of manpower for activities of the kind mentioned in paragraph (a);\n(iv)feasibility studies with a view to establishing the strategic direction of any specific research and development activity; and\n(v)any other work or services (including patenting, licensing and other activities) necessary to support activities of the kind mentioned in paragraph (a).\n(2) For the purposes of this section, the following activities must not be taken to be systematic, investigative or experimental activities:\n(a)market research, market testing or market development, and sale promotion (including consumer survey);\n(b)testing and standardisation;\n(c)prospecting, exploring or drilling for minerals, petroleum or natural gas for the purpose of discovering deposits, determining more precisely the location of deposits or determining the size or quality of deposits;\n(d)the making of cosmetic modifications or stylistic changes to products, processes or production methods;\n(e)pre-production activities such as demonstration of commercial viability, tooling-up and trial runs;\n(f)routine collection of information, except as part of the research and development process;\n(g)preparation for teaching;\n(h)routine software development;\n(i)legal and administrative aspects of patenting, licensing and other activities, unless mentioned in subsection (1)(b)(v);\n(j)activities associated with complying with statutory requirements or standards;\n(k)any activity related to the reproduction of a commercial product or process by a physical examination of an existing system or plan, blueprints, detailed specifications or publicly available information."}},{"id":"SG-H3334-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 2 NATIONAL RESEARCH FUND"},"heading":{"en":"Establishment of National Research Fund"},"text":{"en":"4.—(1) A fund called the National Research Fund is established, which must be held, managed and administered as a Government fund.\n(2) There must be paid into the Fund —\n(a)all moneys from time to time appropriated from the Consolidated Fund and authorised to be paid into the Fund by this Act or any other written law;\n(b)all other revenues of Singapore allocated by any written law to the Fund;\n(c)all gifts and donations paid by any person or organisation to the Government for the purposes of the Fund generally;\n(d)amounts received by the Board or Government —\n(i)from the sale of any property paid for with money from the Fund;\n(ii)from the sale of any property produced, or from dealing with patents or other intellectual property rights in respect of inventions made, in the course of any research and development activity paid for with money from the Fund; or\n(iii)in respect of any work paid for with money from the Fund;\n(e)all investments out of moneys in the Fund authorised to be made by this Act or any other written law and the proceeds of any of those investments, including the net income from those investments; and\n(f)all sums received by way of repayment of any loan or advance from the Fund and any interest from that loan or advance.\n(3) The Fund must be regarded as comprising public moneys for the purposes of any other written law.\n(4) For the purposes of subsection (2)(e), the net income from investments is the amount ascertained by adding to, or deducting from, the income received from investments of moneys in the Fund any profit derived or loss sustained (as the case may be) from the realisation of those investments."}},{"id":"SG-H3334-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 NATIONAL RESEARCH FUND"},"heading":{"en":"Purposes of Fund"},"text":{"en":"5.—(1) The object of the Fund is to provide for the funding and administration of research and development activities with a view to —\n(a)encouraging the development in Singapore of innovative products, processes and services;\n(b)increasing investment by the public and private sectors in Singapore in research and development activities that will make Singapore more internationally competitive;\n(c)promoting the technological advancement of the public and private sectors in Singapore through a focus on innovation; and\n(d)creating an environment that is conducive to increase commercialisation of new processes and product technologies.\n(2) The moneys in the Fund may be withdrawn and applied for all or any of the following purposes only:\n(a)to provide financial assistance (including loans and scholarships) to any public authority, enterprise, educational institution or other person (whether in Singapore or elsewhere) undertaking or facilitating research and development activities;\n(b)to promote or assist (financially or otherwise) any enterprise engaged in the exploitation of research and development activities undertaken by any public authority, enterprise, educational institution or other person (whether in Singapore or elsewhere), where the enterprise, in the opinion of the Board —\n(i)is profitable and efficient or capable of becoming profitable and efficient; and\n(ii)has reasonable prospects for profitability, development, expansion, growth or providing viable employment;\n(c)the payment of remuneration or allowances payable to persons (other than public officers) engaged to advise the Board or Council in the performance of their respective functions under this Act;\n(d)the payment of other expenses incurred by the Board or Council in the performance of their respective functions under this Act, including any remuneration or allowances payable to the members of the Board or Council who are not public officers;\n(e)the payment of expenses mentioned in section 6.\n(3) The moneys in the Fund may also be invested in —\n(a)any investment authorised under section 7 of the Financial Procedure Act 1966; and\n(b)any other investments that the Board thinks fit, not being any stock, bond, fund or security issued by the Government."}},{"id":"SG-H3334-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 2 NATIONAL RESEARCH FUND"},"heading":{"en":"Expenses"},"text":{"en":"6. All expenses incidental to or arising from the administration, investment and management of moneys in the Fund are charged upon and payable out of the Fund."}},{"id":"SG-H3334-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 2 NATIONAL RESEARCH FUND"},"heading":{"en":"Withdrawals"},"text":{"en":"7.—(1) Moneys must not be withdrawn from the Fund unless they are charged upon the Fund or are authorised to be withdrawn or transferred under this Act.\n(2) A payment must not be made out of the Fund unless the payment is authorised by the Board."}},{"id":"SG-H3334-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 3 ADMINISTRATION OF FUND"},"heading":{"en":"Responsibility for Fund"},"text":{"en":"8. The Fund is managed and administered by the Board subject to the direction of the Council."}},{"id":"SG-H3334-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 3 ADMINISTRATION OF FUND"},"heading":{"en":"National Research Foundation Board"},"text":{"en":"9.—(1) There is established a body called the National Research Foundation Board comprising any number of members that the Minister thinks fit.\n(2) Each member of the Board must be appointed by the Minister and holds office for such period (not exceeding 3 years) as the Minister may in any case determine.\n(3) Subject to subsection (4), the functions and duties of the Board are —\n(a)to coordinate research and development activities undertaken or promoted by the Government, public authorities whose objects are similar to the object of the Fund, enterprises, educational institutions or other persons in Singapore, and to facilitate cooperation, communication, collaboration and exchange of ideas and knowledge between them;\n(b)to investigate and evaluate the requirement for funding any research and development activity generally or specifically;\n(c)to develop policies and plans for research and development activities in Singapore in the national interest;\n(d)to approve the payment of money from the Fund;\n(e)to advise the Minister on any matter relating to the management and administration of the Fund that the Board considers appropriate or that is referred to the Board by the Minister;\n(f)to submit to the Minister for approval, not later than 30 days before the end of each financial year of the Fund, a budget for the Fund in respect of the financial year next following in relation to that Fund;\n(g)to submit to the Minister an annual report respecting the Fund not later than 30 days after the end of each financial year in relation to that Fund; and\n(h)to exercise such other powers and perform such other functions and duties with respect to the management, operation and administration of the Fund as may be prescribed.\n(4) The Board must, in the exercise of its powers and the performance of its functions and duties under this Act, comply with any directives that the Council may issue."}},{"id":"SG-H3334-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 3 ADMINISTRATION OF FUND"},"heading":{"en":"Research, Innovation and Enterprise Council"},"text":{"en":"10. There is established a body called the Research, Innovation and Enterprise Council comprising any persons from the private sector and public sector that the Minister thinks fit, and whose functions are —\n(a)to provide advice and guidance to the Government in the formulation of its policies and laws on all types of research and development activities and innovation in Singapore; and\n(b)to lead in the promotion of all aspects of research and development activities and innovation in Singapore, by —\n(i)identifying and promoting activities and programmes that will make Singapore more internationally competitive; and\n(ii)alerting the public and private sectors to any new business opportunities that arise from the exploitation of results of any research and development activities or innovation."}},{"id":"SG-H3334-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 3 ADMINISTRATION OF FUND"},"heading":{"en":"Accounts to be kept"},"text":{"en":"11.—(1) The Board must —\n(a)cause to be kept proper accounts and records of all transactions and affairs relating to the Fund;\n(b)do all things necessary to ensure that payments out of the Fund are properly authorised and correctly made; and\n(c)ensure that adequate control is maintained over the assets and receipts of the Fund.\n(2) The Board must appoint a public officer to be an accounting officer of the Fund with responsibility for keeping proper accounts and records in relation to the Fund, and preparing and signing a statement of the Fund’s accounts in respect of each financial year."}},{"id":"SG-H3334-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 3 ADMINISTRATION OF FUND"},"heading":{"en":"Financial statements and audit reports"},"text":{"en":"12.—(1) The Board must, as soon as practicable after the close of each financial year of the Fund, cause to be prepared and submitted to the Auditor‑General the financial statements and accounts for the Fund relating to that financial year, and the Auditor‑General must then audit or cause an audit of the statements and accounts and report on them.\n(2) The financial year of the Fund is a period of 12 months ending on 31 March in any year.\n(3) The remuneration of the auditor must be paid out of the Fund.\n(4) As soon as the accounts of the Fund and the financial statements have been audited in accordance with this Act, a copy of the audited financial statements, together with a copy of any report made by the auditor, must be submitted to the Board.\n(5) Where the Auditor‑General is not the auditor of the Fund, a copy of the audited financial statements and any report made by the auditor must be forwarded to the Auditor‑General at the same time they are submitted to the Board.\n(6) The Minister must as soon as practicable cause a copy of the audited financial statements of the Fund and the auditor’s report to be presented to Parliament."}},{"id":"SG-H3334-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 3 ADMINISTRATION OF FUND"},"heading":{"en":"Application of Financial Procedure Act 1966"},"text":{"en":"13. The Financial Procedure Act 1966 applies to the Fund to the extent that it is not inconsistent with any of the provisions of this Act."}},{"id":"SG-H3334-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 4 MISCELLANEOUS"},"heading":{"en":"Persons not to reveal trade secrets, etc."},"text":{"en":"14.—(1) If a person exercising any function under this Act obtains protected information about the affairs of another person, the person must not disclose that protected information to any other person unless the disclosure —\n(a)is made with the written consent of the person to whom the information relates;\n(b)is for the purpose of the administration or enforcement of this Act; or\n(c)is in compliance with the requirement of any court, tribunal, authority or person having lawful authority to require the production of documents or the answering of questions.\n(2) If any person acts in contravention of subsection (1), the person shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 2 years or to both.\n(3) For the purpose of this section, the reference to a person disclosing any protected information includes the person permitting any other person to have any access to any record, document or other thing containing that information which is in the person’s possession or under the person’s control by virtue of the person being or having been a member of the Board or Council.\n(4) In this section, “protected information” means information the disclosure of which would or could reasonably be expected to disclose a trade secret or to adversely affect a person in relation to the lawful business affairs of that person."}},{"id":"SG-H3334-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 4 MISCELLANEOUS"},"heading":{"en":"Forgery of certificates and false information"},"text":{"en":"15. If any person —\n(a)forges or counterfeits any document or certificate required by the Board for the purposes of this Act; or\n(b)in relation to any application (whether by the person or on behalf of another) to the Board for its permission, consent or approval, or for any grant or financial assistance, makes (whether orally, electronically, in writing or otherwise) or provides any statement to the Board which is false, and which the person either knows or believes to be false or does not believe to be true,\nthe person shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $5,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3334-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 4 MISCELLANEOUS"},"heading":{"en":"Offences by bodies corporate, etc."},"text":{"en":"16.—(1) Where an offence under this Act committed by a body corporate is proved —\n(a)to have been committed with the consent or connivance of an officer; or\n(b)to be attributable to any neglect on the officer’s part,\nthe officer as well as the body corporate shall be guilty of the offence and shall be liable to be proceeded against and punished accordingly.\n(2) Where the affairs of a body corporate are managed by its members, subsection (1) applies in relation to the acts and defaults of a member in connection with the member’s functions of management as if the member were a director of the body corporate.\n(3) Where an offence under this Act committed by a partnership is proved —\n(a)to have been committed with the consent or connivance of a partner; or\n(b)to be attributable to any neglect on the partner’s part,\nthe partner as well as the partnership shall be guilty of the offence and shall be liable to be proceeded against and punished accordingly.\n(4) Where an offence under this Act committed by an unincorporated association (other than a partnership) is proved —\n(a)to have been committed with the consent or connivance of an officer of the unincorporated association or a member of its governing body; or\n(b)to be attributable to any neglect on the part of such an officer or a member,\nthe officer or member as well as the unincorporated association shall be guilty of the offence and shall be liable to be proceeded against and punished accordingly.\n(5) In this section —\n“body corporate” includes a limited liability partnership within the meaning of section 2(1) of the Limited Liability Partnerships Act 2005;\n“officer” —\n(a)in relation to a body corporate, means any director, partner, member of the committee of management, chief executive, manager, secretary or other similar officer of the body corporate and includes any person purporting to act in any such capacity; or\n(b)in relation to an unincorporated association (other than a partnership), means the president, the secretary, or any member of the committee of the unincorporated association, or any person holding a position analogous to that of president, secretary or member of a committee and includes any person purporting to act in any such capacity;\n“partner” includes a person purporting to act as a partner.\n(6) Regulations may provide for the application of any provision of this section, with any modifications that the Minister considers appropriate, to any body corporate or unincorporated association formed or recognised under the law of a territory outside Singapore."}},{"id":"SG-H3334-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 4 MISCELLANEOUS"},"heading":{"en":"Disclosure of interests of member of Board or Council"},"text":{"en":"17.—(1) A member of the Board or Council who has a direct or indirect pecuniary interest in a matter being considered or about to be considered by the Board or Council (as the case may be) being an interest that could conflict with the proper performance of that member’s functions in relation to the consideration of the matter must, as soon as practicable after the relevant facts have come to the knowledge of that member, disclose the nature of that interest at a meeting of the Board or Council, as the case may be.\n(2) A disclosure under subsection (1) must be recorded in the minutes of the meeting of the Board or Council, as the case may be."}},{"id":"SG-H3334-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 4 MISCELLANEOUS"},"heading":{"en":"Regulations"},"text":{"en":"18. The Minister may make regulations for carrying out the purposes and provisions of this Act."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Research Fund Act 2006","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3335"] = {"id":"SG-H3335","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NSEA1970-OR1?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"国民服役人员（雇佣）（私人雇主与法定机构）命令","en":"National Servicemen (Employment) (Private Employers and Statutory Bodies) Order","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NSEA1970-OR1","completenessNote":"全文，共 4 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3335-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the National Servicemen (Employment) (Private Employers and Statutory Bodies) Order."}},{"id":"SG-H3335-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In this Order, unless the context otherwise requires —\n“private employer” means an employer other than the Government;\n“substantive salary” means the remuneration excluding allowances and bonus payments payable to an employee in respect of work done under the contract of service."}},{"id":"SG-H3335-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Private employer and statutory body to employ only persons from register"},"text":{"en":"3. It is hereby directed that —\n(a)every private employer employing more than 10 employees; and\n(b)every statutory body,\nshall not, except with the consent of the Director, engage or re-engage any employee otherwise than from among the persons whose names appear in the register kept by the Director."}},{"id":"SG-H3335-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption"},"text":{"en":"4. This Order shall not apply to a private employer or statutory body employing an employee who —\n(a)is appointed as a member of the Academic Staff of the National University of Singapore, the Singapore Polytechnic or the Ngee Ann Polytechnic;\n(b)holds a post in a statutory body carrying a substantive salary of $1,920 and above;\n(c)holds a post in any company, corporation or partnership carrying a substantive salary of $1,920 and above or is employed by any association or body of persons and receives a substantive salary of $1,920 and above;\n(d)is employed as a minister of religion;\n(e)is employed as a domestic servant;\n(f)is employed as a building construction worker; or\n(g)being a woman is employed as a midwife, air hostess, dance hostess, bar waitress, nurse, model, private secretary, receptionist, telephone operator, hairdresser, seamstress, beautician, usher and shop assistant."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National Servicemen (Employment) (Private Employers and Statutory Bodies) Order","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3336"] = {"id":"SG-H3336","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NSEA1970?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"国民服役人员（雇佣）法 1970","en":"National Servicemen (Employment) Act 1970","orig":null},"level":"law","status":"active","docNumber":"Act NSEA1970","completenessNote":"全文，共 11 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3336-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Short title"},"text":{"en":"1. This Act is the National Servicemen (Employment) Act 1970."}},{"id":"SG-H3336-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Interpretation"},"text":{"en":"2. In this Act, unless the context otherwise requires —\n“employee” includes any person seeking employment;\n“employer” includes any person desiring to employ other persons;\n“register” means the register established and maintained under section 4;\n“registered person” means a person whose name appears for the time being in the register."}},{"id":"SG-H3336-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Appointment of Director and Assistant Directors"},"text":{"en":"3.—(1) The Minister may appoint an officer to be styled the Director of Employment (referred to in this Act as the Director), and may appoint such number of Assistant Directors of Employment as he may think fit.\n(2) The Director shall have superintendence of all matters relating to this Act, subject to the direction and control of the Minister.\n(3) The Assistant Directors may perform all the duties imposed and exercise all the powers conferred on the Director by this Act.\n(4) All appointments made under this section shall be published in the Gazette."}},{"id":"SG-H3336-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Register"},"text":{"en":"4.—(1) The Director shall establish and maintain a register of persons who have completed full-time national service under any written law for the time being in force relating to national service or enlistment.\n(2) The register shall be maintained in such form, and entries therein, and alterations and removals of those entries, shall be made in such manner as the Minister may determine."}},{"id":"SG-H3336-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Powers of Minister to make orders directing employment of registered persons"},"text":{"en":"5.—(1) The Minister may, by order published in the Gazette, direct that, after such date as may be specified therein, an employer to whom the order applies shall not, except with the written consent of the Director, engage or re-engage any employee otherwise than from among registered persons.\n(2) No order made under subsection (1) shall apply to an employer who takes or offers to take into his employment at any time a person whom apart from that subsection it would have been his duty to take into employment either —\n(a)by virtue of any written law; or\n(b)by virtue of any agreement made before 2 January 1971.\n(3) An order made under subsection (1) may be made so as to apply —\n(a)either to all employers or to such employers or class of employers as may be specified in the order; and\n(b)either to all employees or to such employees or class of employees as may be specified in the order,\nand may provide that any directions contained in the order shall not apply in any specified circumstances.\n(4) Any employer who contravenes the provisions of an order made under subsection (1) shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $2,000, and in respect of each employee employed by him in contravention of any such provision, to a further fine not exceeding $50 for every day on which that employee is so employed.\n(5) Where, in respect of the employment of any person, there has been any contravention of the provisions of an order made under subsection (1), the person shall not, by reason only of that contravention, be deemed to be employed under an illegal contract of employment.\n(6) Any order made under subsection (1) may be varied or revoked by a subsequent order of the Minister published in the Gazette."}},{"id":"SG-H3336-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Provisions for exemption and appeals"},"text":{"en":"6.—(1) If an employer to whom an order made under section 5(1) applies is unable to find a registered person whom he considers suitable to fill any vacancy, the employer may, after obtaining the written consent of the Director, employ any other person to fill the vacancy.\n(2) If the Director refuses to give his consent to the employment of any other person in the circumstances set out in subsection (1), he shall notify the employer in writing of the refusal and his reasons therefor, and if the employer is dissatisfied with the refusal he may, within 14 days of the refusal, appeal to the Appeals Board appointed under subsection (3).\n(3) For the purposes of hearing appeals under subsection (2), the Minister shall appoint an Appeals Board consisting of such number of persons as he may think fit.\n(4) The decision of the Appeals Board on every appeal under this section shall be final and conclusive and shall not be called in question in any court."}},{"id":"SG-H3336-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Obligation of employee to notify Director"},"text":{"en":"7.—(1) Any registered person shall, upon securing employment, notify the Director in writing within 7 days of the employment.\n(2) Any person who fails to comply with subsection (1) shall have his name deleted from the register."}},{"id":"SG-H3336-A8","no":8,"noLabel":{"en":"8."},"heading":{"en":"Entry into premises and furnishing of information"},"text":{"en":"8.—(1) The Director, or any public officer authorised in writing by the Director, may for the purposes of this Act, on producing, if so required, documentary evidence of his identity —\n(a)enter, at any reasonable time, any premises other than premises used solely as a dwelling;\n(b)request any person whom the Director or the public officer has reason to believe to be an employer or an employee to produce to him and to allow him to examine such documents and to furnish him such information, being documents or information in the possession or under the control of the person, as the Director or the public officer may specify.\n(2) Any person who —\n(a)wilfully obstructs the Director or any such public officer in the exercise of any of his powers under subsection (1);\n(b)fails to produce or furnish any document or information in accordance with a request made to him under subsection (1); or\n(c)knowingly makes any false statement for any purpose connected with this Act,\nshall be guilty of an offence and shall be liable on conviction to a fine not exceeding $1,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3336-A9","no":9,"noLabel":{"en":"9."},"heading":{"en":"Powers of Director to summon any person"},"text":{"en":"9.—(1) If the Director has reason to believe that any provision of this Act has been contravened or if he wishes to inquire into any matter connected with the provisions of this Act, he may summon any person who he has reason to believe is able to give information respecting the matter, and the person so summoned shall attend at the time and place specified in the summons and answer truthfully all questions which the Director may put to him.\n(2) Any person so summoned who neglects to attend as required by the summons shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $500 or to imprisonment for a term not exceeding 3 months or to both."}},{"id":"SG-H3336-A10","no":10,"noLabel":{"en":"10."},"heading":{"en":"Offences by corporations"},"text":{"en":"10. Where any offence under this Act committed by a body corporate is proved to have been committed with the consent or connivance of, or to be attributable to any reckless neglect of duty on the part of, any director, manager, secretary or other officer of the body corporate, he as well as the body corporate shall be guilty of that offence and shall be liable to be proceeded against and punished accordingly."}},{"id":"SG-H3336-A11","no":11,"noLabel":{"en":"11."},"heading":{"en":"Rules"},"text":{"en":"11. The Minister may make rules for carrying out or giving effect to the provisions of this Act, and, without prejudice to the generality of the foregoing power, may make rules —\n(a)prescribing matters which are to constitute conditions of, or disqualifications from, the retention in the register of the names of any persons, either generally or in particular circumstances; and\n(b)prescribing the issue of certificates to persons whose names appear on the register and the custody, use and delivery up of those certificates."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Servicemen (Employment) Act 1970","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3337"] = {"id":"SG-H3337","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NSEA1970-R1?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"国民服役人员（雇佣）规则","en":"National Servicemen (Employment) Rules","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NSEA1970-R1","completenessNote":"全文，共 15 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3337-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART I GENERAL"},"heading":{"en":"Citation"},"text":{"en":"1. These Rules may be cited as the National Servicemen (Employment) Rules."}},{"id":"SG-H3337-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART I GENERAL"},"heading":{"en":"Definitions"},"text":{"en":"2. In these Rules, unless the context otherwise requires —\n“Board” means the Appeals Board appointed by the Minister under section 6(3) of the Act;\n“Chairman” means the Chairman of the Board nominated by the Minister under rule 11(2);\n“panel” means the panel of members nominated under rule 11(4)."}},{"id":"SG-H3337-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART II REGISTRATION"},"heading":{"en":"Registration and disclosure of particulars"},"text":{"en":"3.—(1) The Director shall register every person who has completed full-time national service and has a satisfactory report from his Commanding Officer.\n(2) Any person registered under the provisions of the Act and these Rules shall not have his name retained on the Register for more than 5 years from the date of registration.\n(3) A registered person shall disclose to the Director the following particulars:\n(a)name, including former names (if any);\n(b)address;\n(c)identity card number;\n(d)rank;\n(e)army vocation;\n(f)place and date of birth;\n(g)race and religion;\n(h)citizenship;\n(i)marital status;\n(j)education, skill, qualification and experience;\n(k)details of driving licence (if any); and\n(l)any other particulars which may be considered necessary by the Director."}},{"id":"SG-H3337-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART II REGISTRATION"},"heading":{"en":"Deletion from register"},"text":{"en":"4.—(1) A registered person may have his name deleted from the Register for any of the following reasons:\n(a)if it is found that he has been registered in error;\n(b)if he is found to have been convicted of a criminal offence;\n(c)if he fails to attend interviews, which he is directed by the Director to attend, on 3 different occasions;\n(d)if he does not, without good reason, commence work after accepting employment; or\n(e)if he is reported by an employer to have committed gross misconduct.\n(2) A person whose name is not registered under rule 3 on the ground that he has an unsatisfactory report from his Commanding Officer and a person whose name is deleted from the Register under paragraph (1) shall be informed in writing of the reasons for the non-registration or deletion from the Register.\n(3) A person who is affected by the exercise of the provisions of paragraph (2) may, within 30 days of the receipt of such information, appeal to the Director in writing.\n(4) The decision of the Director on every appeal under this rule shall be final and shall not be called in question in any court."}},{"id":"SG-H3337-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART III EMPLOYMENT CARD"},"heading":{"en":"Issue of Employment Card"},"text":{"en":"5. The Director shall issue an Employment Card in the Form A set out in the Schedule to every person who has been registered under rule 3."}},{"id":"SG-H3337-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART III EMPLOYMENT CARD"},"heading":{"en":"Duty of employer"},"text":{"en":"6. An employer upon engaging in employment a registered person shall take possession of his Employment Card, complete the particulars of employment therein and return it to the Director within 7 days of the acceptance of employment."}},{"id":"SG-H3337-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART III EMPLOYMENT CARD"},"heading":{"en":"Issue of new Employment Card"},"text":{"en":"7.—(1) A registered person who wishes to change his employment may make an application to the Director for the issue of a new Employment Card.\n(2) The Director may issue a new Employment Card if he is satisfied that there is sufficient justification to warrant a change of employment."}},{"id":"SG-H3337-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART III EMPLOYMENT CARD"},"heading":{"en":"Loss and replacement of Employment Card"},"text":{"en":"8. Any registered person who has lost his Employment Card shall report such loss to the Director within 7 days of the loss and apply for a replacement."}},{"id":"SG-H3337-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART IV APPLICATION FOR EXEMPTIONS"},"heading":{"en":"Manner of application"},"text":{"en":"9.—(1) An application by an employer under section 6(1) of the Act to employ a non-registered person shall be made in the Form B set out in the Schedule.\n(2) An employer whose application receives the consent of the Director or whose application is rejected shall be informed in writing by the Director of the consent or rejection within 7 days of the receipt of the application.\n(3) Where an employer employs a person pursuant to the consent of the Director he shall within 7 days of the employment of the person inform the Director in the Form C set out in the Schedule."}},{"id":"SG-H3337-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART IV APPLICATION FOR EXEMPTIONS"},"heading":{"en":"Nomination for vacancies"},"text":{"en":"10. Where an application by an employer under section 6(1) of the Act to employ a non-registered person has been rejected, the Director may, at the request of the employer, nominate any registered person whom he thinks suitable to fill the vacancy for which the application has been rejected."}},{"id":"SG-H3337-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART V APPEALS BOARD"},"heading":{"en":"Membership of Board"},"text":{"en":"11.—(1) The Board shall consist of 3 members to be selected from a panel of 21 members.\n(2) The Chairman shall be the nominee of the Minister.\n(3) One of the members selected shall be a nominee of the National Trades Union Congress and the other a nominee of any one of the organisations in paragraph (4)(c).\n(4) The panel shall be composed of —\n(a)7 nominees of the Minister;\n(b)7 nominees of the National Trades Union Congress; and\n(c)one nominee of each of the following organisations:\n(i)National Employers’ Council;\n(ii)Singapore Employers’ Federation;\n(iii)Singapore Manufacturers’ Association;\n(iv)Chinese Chamber of Commerce;\n(v)Indian Chamber of Commerce;\n(vi)International Chamber of Commerce;\n(vii)Malay Chamber of Commerce."}},{"id":"SG-H3337-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART V APPEALS BOARD"},"heading":{"en":"Duration of appointment, vacancies, etc."},"text":{"en":"12.—(1) The members of the panel shall each hold office for a term of one year from the date of their respective nominations and shall be eligible for renomination on completion of that period.\n(2) The Minister may revoke the nomination of any member of the panel without assigning any reason.\n(3) The seat of a member of the panel shall become vacant —\n(a)on his death;\n(b)if he resigns his seat; or\n(c)if his appointment is revoked under paragraph (2).\n(4) If a vacancy occurs in the panel of members, the body whose nominee the former holder of the vacant seat was shall nominate another person to fill the vacancy.\n(5) A person nominated under paragraph (4) shall hold office for so long as the member in whose place he is nominated would have held office.\n(6) The Minister may appoint a Secretary to the Board."}},{"id":"SG-H3337-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART V APPEALS BOARD"},"heading":{"en":"Manner of dealing with appeals"},"text":{"en":"13.—(1) The Board shall hear and determine appeals from employers, under section 6(3) of the Act, against the refusal of the Director to give his consent to the employment of any other person in the circumstances set out in section 6(1) of the Act.\n(2) Where the Board is divided in opinion on an appeal, the appeal shall be decided according to the decision of the majority of the Board or, if there is no such majority decision, according to the decision of the Chairman.\n(3) A decision of the Board on an appeal shall be signed by the Chairman and shall be delivered by him or by the Secretary to the Board on the direction of the Chairman.\n(4) Subject to these Regulations and any directions given by the Minister, the Board may regulate its own procedure."}},{"id":"SG-H3337-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART V APPEALS BOARD"},"heading":{"en":"Representation"},"text":{"en":"14. Any person may, with the permission of the Board, be represented by an advocate and solicitor in proceedings before the Board."}},{"id":"SG-H3337-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nFORM B\nAPPLICATION FOR EXEMPTION\nRule 9(1)\nFORM C\nPARTICULARS OF THE SELECTED CANDIDATES\nRule 9(3)"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Servicemen (Employment) Rules","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3338"] = {"id":"SG-H3338","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NSA2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"国家象征法 2022","en":"National Symbols Act 2022","orig":null},"level":"law","status":"active","docNumber":"Act NSA2022","completenessNote":"全文，共 21 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 2 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3338-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Short title and commencement"},"text":{"en":"1. This Act is the National Symbols Act 2022 and comes into operation on a date that the Minister appoints by notification in the Gazette."}},{"id":"SG-H3338-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Interpretation"},"text":{"en":"2. In this Act, unless the context otherwise requires —\n“canton”, in relation to a flag, means the top left quarter of the obverse of the flag;\n“national symbol” means a national symbol of Singapore declared by Part 2;\n“presidential symbol” means a presidential symbol of Singapore declared by Part 3."}},{"id":"SG-H3338-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 2 NATIONAL SYMBOLS OF SINGAPORE"},"heading":{"en":"National Flag"},"text":{"en":"3.—(1) The design and description of the National Flag of Singapore are set out in Part 1 of the First Schedule.\n(2) The National Flag of Singapore is declared to be a national symbol of Singapore."}},{"id":"SG-H3338-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 2 NATIONAL SYMBOLS OF SINGAPORE"},"heading":{"en":"National Anthem"},"text":{"en":"4.—(1) The lyrics and music of the National Anthem of Singapore are set out in Part 2 of the First Schedule.\n(2) The National Anthem of Singapore is declared to be a national symbol of Singapore."}},{"id":"SG-H3338-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 NATIONAL SYMBOLS OF SINGAPORE"},"heading":{"en":"National Pledge"},"text":{"en":"5.—(1) The words of the National Pledge of Singapore are set out, in each of the 4 official languages, in Part 3 of the First Schedule.\n(2) The National Pledge of Singapore is declared to be a national symbol of Singapore."}},{"id":"SG-H3338-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 2 NATIONAL SYMBOLS OF SINGAPORE"},"heading":{"en":"National Coat of Arms"},"text":{"en":"6.—(1) The design and description of the National Coat of Arms of Singapore are set out in Part 4 of the First Schedule.\n(2) The National Coat of Arms of Singapore is declared to be a national symbol of Singapore.\n(3) The National Coat of Arms of Singapore may also be called the State Crest of Singapore."}},{"id":"SG-H3338-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 2 NATIONAL SYMBOLS OF SINGAPORE"},"heading":{"en":"Public seal"},"text":{"en":"7.—(1) The design and description of the public seal of Singapore are set out in Part 5 of the First Schedule.\n(2) The public seal of Singapore is declared to be a national symbol of Singapore.\n(3) The public seal of Singapore is to be kept by the President."}},{"id":"SG-H3338-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 2 NATIONAL SYMBOLS OF SINGAPORE"},"heading":{"en":"Lion Head symbol"},"text":{"en":"8. The Lion Head symbol, as depicted in Part 6 of the First Schedule, is declared to be a national symbol of Singapore."}},{"id":"SG-H3338-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 2 NATIONAL SYMBOLS OF SINGAPORE"},"heading":{"en":"National flower"},"text":{"en":"9.—(1) The national flower of Singapore is specified in Part 7 of the First Schedule.\n(2) The national flower of Singapore is declared to be a national symbol of Singapore."}},{"id":"SG-H3338-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 3 PRESIDENTIAL SYMBOLS OF SINGAPORE"},"heading":{"en":"Presidential Standard"},"text":{"en":"10.—(1) The design and description of the Presidential Standard are set out in Part 1 of the Second Schedule.\n(2) The Presidential Standard is declared to be a presidential symbol of Singapore."}},{"id":"SG-H3338-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 3 PRESIDENTIAL SYMBOLS OF SINGAPORE"},"heading":{"en":"Presidential Coat of Arms"},"text":{"en":"11.—(1) The design and description of the Presidential Coat of Arms are set out in Part 2 of the Second Schedule.\n(2) The Presidential Coat of Arms is declared to be a presidential symbol of Singapore.\n(3) The Presidential Coat of Arms may also be called the Presidential Crest."}},{"id":"SG-H3338-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 3 PRESIDENTIAL SYMBOLS OF SINGAPORE"},"heading":{"en":"Seal of President"},"text":{"en":"12.—(1) The design and description of the seal of the President are set out in Part 3 of the Second Schedule.\n(2) The seal of the President is declared to be a presidential symbol of Singapore.\n(3) The seal of the President is to be kept by the President."}},{"id":"SG-H3338-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 4 GENERAL PROVISIONS"},"heading":{"en":"Amendment of Schedules"},"text":{"en":"13. The President may, by Proclamation in the Gazette, amend any of the Schedules in relation to any aspect or description of a national symbol or presidential symbol."}},{"id":"SG-H3338-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 4 GENERAL PROVISIONS"},"heading":{"en":"Regulations"},"text":{"en":"14.—(1) The President may make regulations for the purposes of this Act.\n(2) Without limiting subsection (1), the regulations may —\n(a)regulate the circumstances and manner in which a national symbol or presidential symbol may be used;\n(b)enable a prescribed person to permit or prohibit the use of a national symbol or presidential symbol, and provide for appeals against the prescribed person’s decisions;\n(c)provide that the contravention of a regulation is an offence; and\n(d)prescribe the penalty for an offence under the regulations, which penalty must not exceed a fine of $30,000 or imprisonment for a term not exceeding 6 months or both."}},{"id":"SG-H3338-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 4 GENERAL PROVISIONS"},"heading":{"en":"Consent of Public Prosecutor"},"text":{"en":"15. A prosecution under this Act may only be instituted by or with the consent of the Public Prosecutor."}},{"id":"SG-H3338-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 5 REPEAL AND RELATED AMENDMENTS"},"heading":{"en":"Repeal of Singapore Arms and Flag and National Anthem Act 1959"},"text":{"en":"16. The Singapore Arms and Flag and National Anthem Act 1959 is repealed."}},{"id":"SG-H3338-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 5 REPEAL AND RELATED AMENDMENTS"},"heading":{"en":"Related amendment to Evidence Act 1893"},"text":{"en":"17. Section 59(1) of the Evidence Act 1893 is amended by deleting paragraph (f) and substituting the following paragraph:\n“(f)the public seal, the seal of the President, the seals of all the courts in Singapore, the seals of notaries public, all seals that any person is authorised to use by any law in force for the time being in Singapore, and all seals of which English courts take judicial notice;”."}},{"id":"SG-H3338-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 5 REPEAL AND RELATED AMENDMENTS"},"heading":{"en":"Related amendment to Foreign Interference (Countermeasures) Act 2021"},"text":{"en":"18. Section 117(1) of the Foreign Interference (Countermeasures) Act 2021 is amended by deleting the words “National Emblems” in paragraph (b)(iv) and substituting the words “Foreign National Emblems”."}},{"id":"SG-H3338-A19","no":19,"noLabel":{"en":"19."},"chapter":{"en":"PART 5 REPEAL AND RELATED AMENDMENTS"},"heading":{"en":"Related amendments to National Emblems (Control of Display) Act 1949"},"text":{"en":"19. The National Emblems (Control of Display) Act 1949 is amended —\n(a)by deleting the words “national emblems” in the following provisions and substituting in each case the words “foreign national emblems”:\nLong title\nSection 3 (section heading);\n(b)by deleting the words “National Emblems” in section 1 and substituting the words “Foreign National Emblems”;\n(c)by deleting the definition of “national emblem” in section 2 and substituting the following definition:\n“ “foreign national emblem” means any flag, banner or other emblem being or purporting to be the flag, banner or other emblem of any state, or the flag, banner or other emblem of any political organisation claiming to be a national movement in any state or any likeness or resemblance however reproduced of any national leader or former national leader of any state or the leader or former leader of any such political organisation;”; and\n(d)by deleting the words “national emblem” in the following provisions and substituting in each case the words “foreign national emblem”:\nSection 3(1)\nSection 4(a) and (b)\nSection 5\nSection 7\nSection 8(1)(a) and (b)."}},{"id":"SG-H3338-A900000","no":900000,"noLabel":{"en":"FIRST SCHEDULE"},"text":{"en":"FIRST SCHEDULE\nSections 3(1), 4(1), 5(1), 6(1), 7(1), 8 and 9(1)\nNational symbols of Singapore\nPart 1\nNATIONAL FLAG\n1. The National Flag of Singapore consists of 2 equal horizontal sections, red above white. In the canton is a white crescent moon beside 5 white stars arranged in a circle. The ratio of the width to the length is 2:3.\n2. Red symbolises universal fellowship and equality. White signifies pervading and everlasting purity and virtue. The crescent moon represents a young nation on the ascendant, and the 5 stars stand for the nation’s ideals of democracy, peace, progress, justice and equality.\nPart 2\nNATIONAL ANTHEM\nMAJULAH SINGAPURA\nLyrics and music by Zubir Said\nMAJULAH SINGAPURA\nMari kita rakyat Singapura\nSama-sama menuju bahagia\nCita-cita kita yang mulia\nBerjaya Singapura\nMarilah kita bersatu\nDengan semangat yang baru\nSemua kita berseru\nMajulah Singapura\nMajulah Singapura\nPart 3\nNATIONAL PLEDGE\nWe, the citizens of Singapore,\npledge ourselves as one united people,\nregardless of race, language or religion,\nto build a democratic society based on justice and equality\nso as to achieve happiness, prosperity and progress for our nation.\nKami, warganegara Singapura,\nsebagai rakyat yang bersatu padu,\ntidak kira apa bangsa, bahasa, atau ugama,\nberikrar untuk membina suatu masyarakat yang demokratik,\nberdasarkan kepada keadilan dan persamaan untuk mencapai kebahagiaan,\nkemakmuran dan kemajuan bagi negara Kami.\n我们是新加坡公民，\n誓愿不分种族、言语、宗教，\n团结一致，建设公正平等的民主社会，\n并为实现国家之幸福、繁荣与进步，共同努力。\n[S 671/2025 wef 10/10/2025]\nPart 4\nNATIONAL COAT OF ARMS\n1. The National Coat of Arms of Singapore consists of a shield emblazoned with a white crescent moon and 5 white stars against a red background. The shield is supported by a lion on the left and a tiger on the right. Below the shield is a banner with the words “Majulah Singapura”.\n2. The colours and elements of the shield are based on the National Flag of Singapore. The lion represents Singapore, the Lion City; the tiger represents Singapore’s historical links with Malaysia. “Majulah Singapura” is the motto of Singapore.\nPart 5\nPUBLIC SEAL\nThe public seal of Singapore consists of the National Coat of Arms of Singapore encircled by the words “Republic of Singapore”.\nPart 6\nLION HEAD SYMBOL\nPart 7\nNATIONAL FLOWER\nThe Vanda Miss Joaquim (Papilionanthe Miss Joaquim) is the national flower of Singapore."}},{"id":"SG-H3338-A900001","no":900001,"noLabel":{"en":"SECOND SCHEDULE"},"text":{"en":"SECOND SCHEDULE\nSections 10(1), 11(1) and 12(1)\nPresidential symbols of Singapore\nPart 1\nPRESIDENTIAL STANDARD\n1. The Presidential Standard is based on the canton of the National Flag of Singapore. The ratio of the width to the length is 2:3.\n2. The Presidential Standard represents the President, the Head of State of Singapore.\nPart 2\nPRESIDENTIAL COAT OF ARMS\n1. The Presidential Coat of Arms consists of a shield emblazoned with a lion carrying a stalk of laurel against a red and white background. The shield is crowned by a crescent moon and 5 stars, and encircled by an orchid wreath. Below the wreath is a red banner with the word “Singapura”.\n2. The red and white colours, and the crescent moon and 5 stars, are based on the National Flag of Singapore. The lion carrying a stalk of laurel symbolises victory and glory to Singapore, the Lion City. The shield symbolises the oath of the Head of State to preserve, protect and defend the Constitution of the Republic of Singapore.\nPart 3\nSEAL of president\nThe seal of the President consists of the Presidential Coat of Arms encircled by the words “President of the Republic of Singapore”."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Symbols Act 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3339"] = {"id":"SG-H3339","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NSA2022-S536-2023?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":39,"structureMode":"ARTICLE","title":{"zh":"国家象征条例 2023","en":"National Symbols Regulations 2023","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NSA2022-S536-2023","completenessNote":"全文，共 39 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3339-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Regulations are the National Symbols Regulations 2023 and come into operation on 1 August 2023."}},{"id":"SG-H3339-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Definitions"},"text":{"en":"2. In these Regulations —\n“authorised officer” means a public officer appointed as an authorised officer under regulation 3;\n“display” —\n(a)in relation to the National Flag, includes exhibiting, flying or hanging the National Flag; and\n(b)in relation to an image of the National Flag, includes printing, painting or placing the image of the National Flag on any surface;\n“Government department” means any department or office of the Government, and includes Parliament, the courts and other Organs of State;\n“image” —\n(a)in relation to the National Flag, means —\n(i)a picture or visual image (whether electronically generated or otherwise) of the National Flag; or\n(ii)any other such picture or visual image that is capable of being mistaken for an image of the National Flag; and\n(b)in relation to the Presidential Standard, means a picture or visual image (whether electronically generated or otherwise) of the Presidential Standard;\n“National Anthem” means the National Anthem of Singapore as set out in Part 2 of the First Schedule to the Act;\n“National Coat of Arms” means the National Coat of Arms of Singapore as set out in Part 4 of the First Schedule to the Act;\n“National Day period” means the period beginning 1 July and ending 30 September (both dates inclusive) of each year;\n“National Flag” means the National Flag of Singapore as set out in Part 1 of the First Schedule to the Act;\n“National Pledge” means the National Pledge of Singapore in any of the 4 official languages as set out in Part 3 of the First Schedule to the Act;\n“perform”, in relation to the National Anthem, includes playing a recording of the National Anthem;\n“Presidential Coat of Arms” means the Presidential Coat of Arms as set out in Part 2 of the Second Schedule to the Act;\n“Presidential Standard” means the Presidential Standard as set out in Part 1 of the Second Schedule to the Act;\n“public seal” means the public seal of Singapore as set out in Part 5 of the First Schedule to the Act;\n“seal of the President” means the seal of the President as set out in Part 3 of the Second Schedule to the Act."}},{"id":"SG-H3339-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Authorised officers"},"text":{"en":"3. The Minister may appoint one or more public officers to be authorised officers for the purposes of these Regulations."}},{"id":"SG-H3339-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Exercise of Minister’s functions by Second Minister, etc."},"text":{"en":"4. The functions of the Minister in these Regulations may be exercised by a Second Minister, Minister of State or Parliamentary Secretary assisting the Minister."}},{"id":"SG-H3339-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Disrespecting National Flag"},"text":{"en":"5.—(1) A person commits an offence if —\n(a)the person knowingly does an act in relation to the National Flag; and\n(b)the act is disrespectful to the National Flag.\n(2) A person in possession of the National Flag must not, without reasonable excuse, allow or cause the National Flag to touch the floor or ground, even when lowering the National Flag from a staff or flagpole.\n(3) A person who contravenes paragraph (2) commits an offence.\n(4) A person who is guilty of an offence under paragraph (1) or (3) shall be liable on conviction to a fine not exceeding $30,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Display of National Flag outside buildings"},"text":{"en":"6.—(1) If the National Flag is displayed outside a building, the National Flag must be displayed on or in front of the building.\n(2) If the National Flag is displayed outside a building or in an open space, the National Flag —\n(a)must be flown from a flagpole; and\n(b)must not be flown at night unless the National Flag is properly illuminated.\n(3) Paragraph (2) does not apply during —\n(a)the National Day period; and\n(b)any other period that the Minister may specify (which period must be published in the Gazette).\n(4) A person who knowingly contravenes paragraph (1) or (2) commits an offence and shall be liable on conviction to a fine not exceeding $5,000."}},{"id":"SG-H3339-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Display of National Flag on vehicles, vessels and aircrafts"},"text":{"en":"7.—(1) The National Flag must not be displayed on a motor vehicle unless —\n(a)the President is travelling in the motor vehicle;\n(b)a Minister is travelling in the motor vehicle on official business;\n(c)the display is during the National Day period and the motor vehicle is not a hearse; or\n(d)the Minister approves the display.\n(2) The National Flag must not be displayed on a vessel or aircraft unless —\n(a)the vessel or aircraft is a Government vessel or aircraft;\n(b)the vessel or aircraft is authorised to do so under written law;\n(c)the display is during the National Day period; or\n(d)the Minister approves the display.\n(3) The Minister must not give approval under paragraph (1)(d) or (2)(d) unless the Minister is satisfied that the display of the National Flag will not give rise to disrespect to the National Flag.\n(4) A person who knowingly contravenes paragraph (1) or (2) commits an offence and shall be liable on conviction to a fine not exceeding $5,000."}},{"id":"SG-H3339-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Display of National Flag in relation to other flags, objects, etc."},"text":{"en":"8.—(1) Subject to international practice, the National Flag must take precedence over all other flags when displayed in Singapore.\n(2) When the National Flag is displayed with any other flag or flags, the National Flag must be displayed prominently, in the position of honour and, where practicable, above the other flag or flags.\n(3) When raised or carried in a procession with any other flag or flags, the National Flag must be raised or carried —\n(a)high on the right shoulder of the standard bearer;\n(b)if in a single file, in front of the other flag or flags; and\n(c)if carried side‑by‑side with the other flag or flags, in the position of honour.\n(4) The National Flag must not be displayed below any other flag, emblem or object.\n(5) When the National Flag is displayed on a platform or stage, the National Flag must —\n(a)be above all decorations;\n(b)subject to sub‑paragraph (c), be behind and above any person speaking from the platform or stage; and\n(c)if displayed from a staff standing on the platform or stage, be on the right side of any person speaking from the platform or stage.\n(6) When the National Flag is hung —\n(a)the National Flag must be hung against a vertical wall or other vertical flat surface; and\n(b)the crescent and stars must be on the top left position as seen by a spectator facing the National Flag and the wall or surface, as the case may be.\n(7) The National Flag must not be dipped in salute to any person or thing.\n(8) A person who knowingly contravenes paragraph (1), (2), (3), (4), (5), (6) or (7) commits an offence and shall be liable on conviction to a fine not exceeding $5,000.\n(9) In this regulation —\n“flag” means any flag that is not the national flag of another State;\n“position of honour”, in relation to the display of the National Flag side‑by‑side with, and at the same level as, any other flag or flags, means —\n(a)the left as seen by any spectator facing —\n(i)the National Flag and the other flag or flags; or\n(ii)the front of the building on which, or in front of which, the National Flag and the other flag or flags are flown; or\n(b)where the National Flag and the other flag or flags are carried in a procession, the right as seen by the standard bearers."}},{"id":"SG-H3339-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Lowering to half‑mast"},"text":{"en":"9.—(1) The National Flag must be flown at full mast.\n(2) However, during a period of national mourning declared by the Government, the National Flag may be lowered to half‑mast.\n(3) The declaration of a period of national mourning must be published in the Gazette or in some other way that will secure adequate publicity for the declaration.\n(4) A person who knowingly contravenes paragraph (1) commits an offence and shall be liable on conviction to a fine not exceeding $5,000."}},{"id":"SG-H3339-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"National Flag not to be displayed if damaged, etc."},"text":{"en":"10.—(1) A person must not knowingly display, or cause to be displayed, a National Flag that is damaged or not in a proper and clean condition.\n(2) A person who contravenes paragraph (1) commits an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Use of National Flag or image thereof for private funeral, etc."},"text":{"en":"11.—(1) A person must not knowingly use or display the National Flag or an image of the National Flag at a private funeral, wake, memorial service or other funerary rite, ceremony or procession unless the Minister approves the use or display.\n(2) The Minister must not give approval under paragraph (1) unless the Minister is satisfied that the use or display of the National Flag or an image of the National Flag will not give rise to disrespect to the National Flag.\n(3) A person who contravenes paragraph (1) commits an offence and shall be liable on conviction to a fine not exceeding $5,000."}},{"id":"SG-H3339-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Commercial use of National Flag or image thereof"},"text":{"en":"12.—(1) A person must not knowingly use or apply the National Flag or an image of the National Flag —\n(a)for a commercial purpose; or\n(b)as a means of advertisement or for the purpose of any advertisement.\n(2) However, a person may use or apply the National Flag or an image of the National Flag if —\n(a)the use or application is during the National Day period and does not give rise to disrespect to the National Flag; or\n(b)the use or application is approved by the Minister.\n(3) The Minister must not give approval under paragraph (2)(b) unless the Minister is satisfied that the use or application of the National Flag or an image of the National Flag will not give rise to disrespect to the National Flag.\n(4) A person must not knowingly use or apply the National Flag or an image of the National Flag as or as part of a trademark.\n(5) A person who contravenes paragraph (1) or (4) commits an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Use of National Flag or image thereof as decoration, etc."},"text":{"en":"13.—(1) A person must not knowingly use or apply the National Flag or an image of the National Flag as part of any furnishing, covering or receptacle unless the Minister approves the use or application.\n(2) A person must not knowingly use or apply the National Flag or an image of the National Flag as a decoration unless —\n(a)the use or application —\n(i)is during the National Day period; and\n(ii)does not give rise to disrespect to the National Flag; or\n(b)the use or application is approved by the Minister.\n(3) The Minister must not give approval under paragraph (1) or (2)(b) unless the Minister is satisfied that the use or application of the National Flag or an image of the National Flag will not give rise to disrespect to the National Flag.\n(4) A person who contravenes paragraph (1) or (2) commits an offence and shall be liable on conviction —\n(a)in a case involving disrespect to the National Flag — to a fine not exceeding $30,000 or to imprisonment for a term not exceeding 6 months or to both; or\n(b)in any other case — to a fine not exceeding $5,000.\n(5) In this regulation, “receptacle” includes a paper, plastic and refuse bag."}},{"id":"SG-H3339-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Use of National Flag or image thereof on attire"},"text":{"en":"14.—(1) A person must not knowingly use or apply the National Flag or an image of the National Flag as part of any costume or attire unless —\n(a)the use or application —\n(i)is not for a commercial purpose; and\n(ii)does not give rise to disrespect to the National Flag;\n(b)the use or application —\n(i)is during the National Day period; and\n(ii)does not give rise to disrespect to the National Flag; or\n(c)the use or application is approved by the Minister.\n(2) The Minister must not give approval under paragraph (1)(c) unless the Minister is satisfied that the use or application of the National Flag or an image of the National Flag will not give rise to disrespect to the National Flag.\n(3) A person who contravenes paragraph (1) commits an offence and shall be liable on conviction —\n(a)in a case where the National Flag is used or applied in a manner that gives rise to disrespect to the National Flag — to a fine not exceeding $30,000 or to imprisonment for a term not exceeding 6 months or to both;\n(b)in any other case — to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Flags that distort or modify National Flag, etc."},"text":{"en":"15.—(1) A person must not knowingly produce or display a flag that distorts or otherwise modifies the design of the National Flag.\nExample\nA flag with words or graphics superimposed on the design of the National Flag, or vice versa, is a modification of the design of the National Flag.\n(2) Paragraph (1) does not apply in relation to the flag of a Government department.\n(3) A person who contravenes paragraph (1) commits an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 2 NATIONAL FLAG"},"heading":{"en":"Stop order against disrespectful acts"},"text":{"en":"16.—(1) If —\n(a)a person has done or is doing an act in relation to the National Flag; and\n(b)an authorised officer is of the opinion that the act causes disrespect to the National Flag,\nthe authorised officer may order the person to do one or both of the following:\n(c)cease doing the act;\n(d)take any specified action to remedy the disrespect caused.\n(2) For the purposes of paragraph (1), an act in relation to the National Flag includes —\n(a)an act in relation to an image of the National Flag; and\n(b)an act in relation to distorted, or otherwise modified, but still recognisable elements of the National Flag.\n(3) Part 10 applies to and in relation to an order under paragraph (1)."}},{"id":"SG-H3339-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 3 NATIONAL ANTHEM"},"heading":{"en":"Occasions for performing National Anthem"},"text":{"en":"17.—(1) The National Anthem is to be performed when the President receives a general salute.\n(2) The National Anthem may be performed or sung on any appropriate occasion."}},{"id":"SG-H3339-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 3 NATIONAL ANTHEM"},"heading":{"en":"Respect for National Anthem"},"text":{"en":"18.—(1) When the National Anthem is performed or sung, every person present must stand up as a mark of respect.\n(2) A person who contravenes paragraph (1) without reasonable excuse commits an offence and shall be liable on conviction to a fine not exceeding $5,000."}},{"id":"SG-H3339-A19","no":19,"noLabel":{"en":"19."},"chapter":{"en":"PART 3 NATIONAL ANTHEM"},"heading":{"en":"Musical arrangements of National Anthem"},"text":{"en":"19.—(1) A person performing or singing the National Anthem must do so according to the arrangement in Part 2 of the First Schedule to the Act or any other arrangement permitted under paragraph (2).\n(2) The National Anthem may be rearranged subject to the following conditions:\n(a)the National Anthem must not be incorporated into any other composition or medley;\n(b)every arrangement of the National Anthem must accurately reflect the complete tune and, if lyrics are included, the complete lyrics of the National Anthem;\n(c)the rearrangement must be in keeping with the dignity due to the National Anthem.\n(3) A person must not make a musical record that includes a rearrangement of the National Anthem that contravenes paragraph (2).\n(4) A person who sings the National Anthem —\n(a)must follow the lyrics in Part 2 of the First Schedule to the Act; and\n(b)must not sing any translation of those lyrics.\n(5) A person who knowingly contravenes paragraph (1), (2), (3) or (4) commits an offence and shall be liable on conviction to a fine not exceeding $5,000."}},{"id":"SG-H3339-A20","no":20,"noLabel":{"en":"20."},"chapter":{"en":"PART 3 NATIONAL ANTHEM"},"heading":{"en":"No unauthorised commercial use of National Anthem"},"text":{"en":"20.—(1) The tune or lyrics of the National Anthem must not be used for any commercial purpose unless the Minister approves the use.\n(2) The Minister must not give approval under paragraph (1) unless the Minister is satisfied that the use of the National Anthem will not give rise to disrespect to the National Anthem.\n(3) A person who knowingly contravenes paragraph (1) commits an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A21","no":21,"noLabel":{"en":"21."},"chapter":{"en":"PART 3 NATIONAL ANTHEM"},"heading":{"en":"Stop order against disrespectful acts"},"text":{"en":"21.—(1) If —\n(a)a person has done or is doing an act in relation to the National Anthem; and\n(b)an authorised officer is of the opinion that the act causes disrespect to the National Anthem,\nthe authorised officer may order the person to do one or both of the following:\n(c)cease doing the act;\n(d)take any specified action to remedy the disrespect caused.\n(2) For the purposes of paragraph (1), an act in relation to the National Anthem includes an act in relation to a distorted, or otherwise modified, but still recognisable version of the National Anthem.\n(3) Part 10 applies to and in relation to an order under paragraph (1)."}},{"id":"SG-H3339-A22","no":22,"noLabel":{"en":"22."},"chapter":{"en":"PART 4 NATIONAL PLEDGE"},"heading":{"en":"Taking National Pledge"},"text":{"en":"22.—(1) The National Pledge may be taken on any appropriate occasion.\n(2) A person taking the National Pledge must recite the complete National Pledge.\n(3) A person who contravenes paragraph (2) without reasonable excuse commits an offence and shall be liable on conviction to a fine not exceeding $5,000."}},{"id":"SG-H3339-A23","no":23,"noLabel":{"en":"23."},"chapter":{"en":"PART 4 NATIONAL PLEDGE"},"heading":{"en":"No unauthorised commercial use of National Pledge"},"text":{"en":"23.—(1) A person must not knowingly use the National Pledge —\n(a)for a commercial purpose; or\n(b)as a means of advertisement or for the purpose of any advertisement,\nunless the Minister approves the use.\n(2) The Minister must not give approval under paragraph (1) unless the Minister is satisfied that the use of the National Pledge will not give rise to disrespect to the National Pledge.\n(3) A person who contravenes paragraph (1) commits an offence and shall be liable on conviction to a fine not exceeding $10,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A24","no":24,"noLabel":{"en":"24."},"chapter":{"en":"PART 4 NATIONAL PLEDGE"},"heading":{"en":"Stop order against disrespectful acts"},"text":{"en":"24.—(1) If —\n(a)a person has done or is doing an act in relation to the National Pledge; and\n(b)an authorised officer is of the opinion that the act causes disrespect to the National Pledge,\nthe authorised officer may order the person to do one or both of the following:\n(c)cease doing the act;\n(d)take any specified action to remedy the disrespect caused.\n(2) For the purposes of paragraph (1), an act relates to the National Pledge only if the act relates to the whole or substantially the whole of the National Pledge in any of the 4 official languages.\n(3) Part 10 applies to and in relation to an order under paragraph (1)."}},{"id":"SG-H3339-A25","no":25,"noLabel":{"en":"25."},"chapter":{"en":"PART 5 NATIONAL COAT OF ARMS"},"heading":{"en":"Making or dealing in copies of National Coat of Arms"},"text":{"en":"25.—(1) In this regulation, “copy of the National Coat of Arms” —\n(a)means a copy of the National Coat of Arms in 2 or 3 dimensions; and\n(b)includes an image or object that is capable of being mistaken for the National Coat of Arms.\n(2) Subject to this regulation, a person must not knowingly —\n(a)make or deal in a copy of the National Coat of Arms; or\n(b)cause a copy of the National Coat of Arms to be made or dealt in.\nExamples\n(a)Examples of ways in which copies may be made include printing, drawing, sculpting, tattooing and manufacturing.\n(b)Examples of dealings include serving, sending, distributing, publishing, selling, offering for sale and exhibiting.\n(3) Paragraph (2) does not apply to —\n(a)anything done by or with the authority of a Government department;\n(b)anything done with the approval of the Minister;\n(c)anything done in good faith and for the purposes of reporting a disrespectful or unlawful use of the National Coat of Arms to a public officer;\n(d)anything done for the purposes of reporting news; or\n(e)anything done —\n(i)incidentally to an act that is otherwise lawful; and\n(ii)without causing disrespect to the National Coat of Arms.\nExamples\n(a)A replica of the National Coat of Arms is installed on a Government building. A person takes a photograph of the building, and the photograph includes the replica. The person has made a copy of the National Coat of Arms, but the reproduction would come within the exception in paragraph (3)(e) if the taking of the photograph is otherwise lawful and does not cause disrespect to the National Coat of Arms.\n(b)A person copies a Government letter bearing the National Coat of Arms for the purpose of committing fraud. The person has made a copy of the National Coat of Arms, and paragraph (3)(e) would not apply because the reproduction was done incidentally to an unlawful act.\n(4) A person who contravenes paragraph (2) commits an offence and shall be liable on conviction to a fine not exceeding $30,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A26","no":26,"noLabel":{"en":"26."},"chapter":{"en":"PART 5 NATIONAL COAT OF ARMS"},"heading":{"en":"No distortion of National Coat of Arms"},"text":{"en":"26.—(1) A person must not knowingly make, use or display an image or object that is or includes a distorted or otherwise modified design of the National Coat of Arms.\n(2) Paragraph (1) does not apply in relation to the symbol of a Government department.\n(3) A person who contravenes paragraph (1) commits an offence and shall be liable on conviction to a fine not exceeding $30,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A27","no":27,"noLabel":{"en":"27."},"chapter":{"en":"PART 6 PUBLIC SEAL"},"heading":{"en":"Affixing of public seal"},"text":{"en":"27.—(1) The public seal may only be affixed —\n(a)by or with the authority of the President; or\n(b)as required or permitted by law.\n(2) A person who knowingly contravenes paragraph (1) commits an offence and shall be liable on conviction to a fine not exceeding $30,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A28","no":28,"noLabel":{"en":"28."},"chapter":{"en":"PART 7 PRESIDENTIAL STANDARD"},"heading":{"en":"No unauthorised use of Presidential Standard or its image"},"text":{"en":"28.—(1) The Presidential Standard may only be flown, displayed or otherwise used by or with the authority of the President.\n(2) An image of the Presidential Standard may only be applied on a surface or otherwise used by or with the authority of the President.\n(3) A person who knowingly contravenes paragraph (1) or (2) commits an offence and shall be liable on conviction to a fine not exceeding $30,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A29","no":29,"noLabel":{"en":"29."},"chapter":{"en":"PART 8 PRESIDENTIAL COAT OF ARMS"},"heading":{"en":"Making or dealing in copies of Presidential Coat of Arms"},"text":{"en":"29.—(1) In this regulation, “copy of the Presidential Coat of Arms” —\n(a)means a copy of the Presidential Coat of Arms in 2 or 3 dimensions; and\n(b)includes an image or object that is capable of being mistaken for the Presidential Coat of Arms.\n(2) Subject to this regulation, a person must not knowingly —\n(a)make or deal in a copy of the Presidential Coat of Arms; or\n(b)cause a copy of the Presidential Coat of Arms to be made or dealt in.\nExamples\n(a)Examples of ways in which copies may be made include printing, drawing, sculpting, tattooing and manufacturing.\n(b)Examples of dealings include serving, sending, distributing, publishing, selling, offering for sale and exhibiting.\n(3) Paragraph (2) does not apply to —\n(a)anything done by or with the authority of the President;\n(b)anything done in good faith and for the purposes of reporting a disrespectful or unlawful use of the Presidential Coat of Arms to a public officer;\n(c)anything done for the purposes of reporting news; or\n(d)anything done —\n(i)incidentally to an act that is otherwise lawful; and\n(ii)without causing disrespect to the Presidential Coat of Arms.\nExample\nA person copies a letter bearing the Presidential Coat of Arms for the purpose of committing fraud. The person has made a copy of the Presidential Coat of Arms, and paragraph (3)(d) would not apply because the reproduction was done incidentally to an unlawful act.\n(4) A person who contravenes paragraph (2) commits an offence and shall be liable on conviction to a fine not exceeding $30,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A30","no":30,"noLabel":{"en":"30."},"chapter":{"en":"PART 8 PRESIDENTIAL COAT OF ARMS"},"heading":{"en":"No distortion of Presidential Coat of Arms"},"text":{"en":"30.—(1) A person must not knowingly make, use or display an image or object that is or includes a distorted or otherwise modified design of the Presidential Coat of Arms.\n(2) A person who contravenes paragraph (1) commits an offence and shall be liable on conviction to a fine not exceeding $30,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A31","no":31,"noLabel":{"en":"31."},"chapter":{"en":"PART 9 SEAL OF PRESIDENT"},"heading":{"en":"Affixing of seal of President"},"text":{"en":"31.—(1) The seal of the President may only be affixed by or with the authority of the President.\n(2) A person who knowingly contravenes paragraph (1) commits an offence and shall be liable on conviction to a fine not exceeding $30,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A32","no":32,"noLabel":{"en":"32."},"chapter":{"en":"PART 10 SUPPLEMENTARY PROVISIONS FOR STOP ORDERS"},"heading":{"en":"Application of this Part"},"text":{"en":"32. This Part applies to and in relation to an order made under regulation 16, 21 or 24 (called in this Part a stop order)."}},{"id":"SG-H3339-A33","no":33,"noLabel":{"en":"33."},"chapter":{"en":"PART 10 SUPPLEMENTARY PROVISIONS FOR STOP ORDERS"},"heading":{"en":"Form and contents of stop order"},"text":{"en":"33.—(1) A stop order must be in writing.\n(2) A stop order must —\n(a)describe the disrespectful act against which the order is made;\n(b)explain why that act is disrespectful;\n(c)specify what is required of the person against whom the order is made; and\n(d)state that a contravention of the order is an offence."}},{"id":"SG-H3339-A34","no":34,"noLabel":{"en":"34."},"chapter":{"en":"PART 10 SUPPLEMENTARY PROVISIONS FOR STOP ORDERS"},"heading":{"en":"Service of stop order"},"text":{"en":"34.—(1) A stop order must be served on the person against whom the order is made.\n(2) A stop order has effect from the date on which it is served or any later date specified in the order.\n(3) A stop order may be served on a person by any of the following means:\n(a)by giving a copy of the order —\n(i)in the case of an individual, to the individual;\n(ii)in the case of a body corporate (including a limited liability partnership) or an unincorporated association, to the secretary or other like officer of the body corporate or unincorporated association, or the limited liability partnership’s manager; or\n(iii)in the case of a partnership (other than a limited liability partnership), to any partner or other like officer of the partnership;\n(b)by leaving a copy of the order —\n(i)in the case of an individual, at the individual’s usual or last known place of residence with an adult apparently resident there, or at the individual’s business address with an adult apparently employed there; or\n(ii)in the case of a person other than an individual, at the person’s business address;\n(c)if the person is an individual, by affixing a copy of the order in a conspicuous place at the individual’s usual or last known place of residence or at the individual’s business address;\n(d)by ordinary or registered post to the business address, or usual or last known address in Singapore, of the person.\n(4) If —\n(a)a stop order is made against an act done by a person on an online location; and\n(b)the online location provides a mechanism by which —\n(i)the person may receive electronic communications; or\n(ii)comments may be posted in response to the act,\nthe stop order may be served on the person by sending an electronic copy of the stop order to the person through that mechanism.\nIllustration\nA stop order requires a person to remove an image that the person posted on the Instagram application. The stop order may be served on the person by sending the person a copy of the order through the direct message function of the Instagram application or through a comment on the Instagram post.\n(5) In this regulation, “online location” means any website, webpage, chatroom or forum, or any other thing that is hosted on a computer (as defined in the Computer Misuse Act 1993) and can be seen, heard or otherwise perceived by means of the internet."}},{"id":"SG-H3339-A35","no":35,"noLabel":{"en":"35."},"chapter":{"en":"PART 10 SUPPLEMENTARY PROVISIONS FOR STOP ORDERS"},"heading":{"en":"Variation or revocation of stop order"},"text":{"en":"35.—(1) An authorised officer may at any time vary or revoke a stop order by written notice.\n(2) A notice under paragraph (1) must be served on the person against whom the stop order is made.\n(3) A notice under paragraph (1) has effect from the date on which it is served or any later date specified in the notice.\n(4) A notice under paragraph (1) may be served in the same manner as a stop order."}},{"id":"SG-H3339-A36","no":36,"noLabel":{"en":"36."},"chapter":{"en":"PART 10 SUPPLEMENTARY PROVISIONS FOR STOP ORDERS"},"heading":{"en":"Appeal against stop order"},"text":{"en":"36.—(1) A person against whom a stop order is made may appeal in writing to the Minister against the making of the order and against any variation of the order.\n(2) An appeal must be made within 14 days, or any longer time that the Minister may allow, after the stop order or the notice of variation (as the case may be) is served.\n(3) An appellant —\n(a)may submit any information or document in support of the appeal; and\n(b)must submit any information or document required by the Minister in relation to the appeal.\n(4) The Minister may reject an appeal without considering its merits if the appeal is not made in accordance with this regulation.\n(5) After considering an appeal, the Minister may confirm, vary or revoke the stop order that is the subject of the appeal.\n(6) Unless the Minister or an authorised officer otherwise directs, a stop order or a variation of a stop order continues to have effect pending the determination of an appeal against the order or variation."}},{"id":"SG-H3339-A37","no":37,"noLabel":{"en":"37."},"chapter":{"en":"PART 10 SUPPLEMENTARY PROVISIONS FOR STOP ORDERS"},"heading":{"en":"Offence"},"text":{"en":"37. A person who, without reasonable excuse, fails to comply with a stop order commits an offence and shall be liable on conviction to a fine not exceeding $20,000 or to imprisonment for a term not exceeding 6 months or to both."}},{"id":"SG-H3339-A38","no":38,"noLabel":{"en":"38."},"chapter":{"en":"PART 11 MISCELLANEOUS"},"heading":{"en":"Offences by corporations"},"text":{"en":"38.—(1) Where a corporation commits an offence under these Regulations, a person —\n(a)who is —\n(i)an officer of the corporation; or\n(ii)an individual involved in the management of the corporation and in a position to influence the conduct of the corporation in relation to the commission of the offence; and\n(b)who —\n(i)consented or connived, or conspired with others, to effect the commission of the offence;\n(ii)is in any other way, whether by act or omission, knowingly concerned in, or is party to, the commission of the offence by the corporation; or\n(iii)knew or ought reasonably to have known that the offence by the corporation (or an offence of the same type) would be or is being committed, and failed to take all reasonable steps to prevent or stop the commission of that offence,\nshall be guilty of that same offence as is the corporation, and shall be liable on conviction to be punished accordingly.\n(2) A person mentioned in paragraph (1) may rely on a defence that would be available to the corporation if it were charged with the offence with which the person is charged and, in doing so, the person bears the same burden of proof that the corporation would bear.\n(3) To avoid doubt, this regulation does not affect the application of Chapters 5 and 5A of the Penal Code 1871.\n(4) To avoid doubt, paragraph (1) does not affect the liability of a corporation for an offence under these Regulations, and applies whether or not the corporation is convicted of the offence.\n(5) In this regulation —\n“corporation” includes a limited liability partnership within the meaning of section 2(1) of the Limited Liability Partnerships Act 2005;\n“officer”, in relation to a corporation, means any director, partner, chief executive, manager, secretary or other similar officer of the corporation, and includes —\n(a)any person purporting to act in any such capacity; and\n(b)for a corporation whose affairs are managed by its members, any of those members as if the member were a director of the corporation;\n“partner” includes a person purporting to act as a partner."}},{"id":"SG-H3339-A39","no":39,"noLabel":{"en":"39."},"chapter":{"en":"PART 11 MISCELLANEOUS"},"heading":{"en":"Composition of offences"},"text":{"en":"39.—(1) An offence under these Regulations may be compounded by an authorised officer in accordance with section 243 of the Criminal Procedure Code 2010.\n(2) An authorised officer may compound an offence under these Regulations by collecting from a person who is reasonably suspected of having committed the offence a sum of money not exceeding $2,000."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National Symbols Regulations 2023","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3340"] = {"id":"SG-H3340","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NUSCA2005-S208-2008?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"新加坡国立大学（公司化）（解散日期）公告 2008","en":"National University of Singapore (Corporatisation) (Dissolution Date) Notification 2008","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NUSCA2005-S208-2008","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3340-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification may be cited as the National University of Singapore (Corporatisation) (Dissolution Date) Notification 2008 and shall be deemed to have come into operation on 28th December 2006."}},{"id":"SG-H3340-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Dissolution date"},"text":{"en":"2. The date specified for the purposes of section 18(3) of the Act is 28th December 2007."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National University of Singapore (Corporatisation) (Dissolution Date) Notification 2008","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3341"] = {"id":"SG-H3341","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/Act/NUSCA2005?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":22,"structureMode":"ARTICLE","title":{"zh":"新加坡国立大学（法人化）法 2005","en":"National University of Singapore (Corporatisation) Act 2005","orig":null},"level":"law","status":"active","docNumber":"Act NUSCA2005","completenessNote":"全文，共 22 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 2 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3341-A1","no":1,"noLabel":{"en":"1."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Short title"},"text":{"en":"1. This Act is the National University of Singapore (Corporatisation) Act 2005."}},{"id":"SG-H3341-A2","no":2,"noLabel":{"en":"2."},"chapter":{"en":"PART 1 PRELIMINARY"},"heading":{"en":"Interpretation"},"text":{"en":"2.—(1) In this Act, unless the context otherwise requires —\n“Board” means the Board of Trustees of the university company mentioned in its constituent documents;\n“constituent documents”, in relation to the university company, means the memorandum of association and articles of association of the university company;\n“predecessor university” means the National University of Singapore established under the repealed National University of Singapore Act (Cap. 204, 2002 Revised Edition);\n“university company” means the company limited by guarantee incorporated under the Companies Act 1967 under the name “National University of Singapore”.\n(2) To avoid doubt —\n(a)any reference in this Act to property vested in the predecessor university is a reference to such property, whether situated in Singapore or elsewhere; and\n(b)any reference in this Act to rights or liabilities of the predecessor university is a reference to such rights to which the predecessor university is entitled or such liabilities to which the predecessor university is subject (as the case may be) whether under the laws of Singapore or of any country outside Singapore, and includes such rights or liabilities arising under loans raised by the predecessor university."}},{"id":"SG-H3341-A3","no":3,"noLabel":{"en":"3."},"chapter":{"en":"PART 2 PROVISIONS RELATING TO UNIVERSITY COMPANY"},"heading":{"en":"Function of university company"},"text":{"en":"3. The function of the university company is to pursue, within the limits of the financial resources available to it, the objects provided by its constituent documents and, in particular, to confer and award degrees, diplomas and certificates, including honorary degrees and other distinctions."}},{"id":"SG-H3341-A4","no":4,"noLabel":{"en":"4."},"chapter":{"en":"PART 2 PROVISIONS RELATING TO UNIVERSITY COMPANY"},"heading":{"en":"Accountability and evaluation"},"text":{"en":"4.—(1) The university company must comply with the accountability framework set out by way of any written agreement between the university company and the Minister or any person authorised by the Minister.\n(2) The university company must evaluate the performance of its activities in accordance with such quality assurance framework as the Minister may determine.\n(3) The university company must participate in the evaluation of its activities by any external review panel that the Minister may commission from time to time."}},{"id":"SG-H3341-A5","no":5,"noLabel":{"en":"5."},"chapter":{"en":"PART 2 PROVISIONS RELATING TO UNIVERSITY COMPANY"},"heading":{"en":"Directions in respect of policies on higher education in Singapore"},"text":{"en":"5.—(1) The Minister may, in consultation with the university company, establish any policies on higher education in Singapore that the Minister thinks fit and may direct the university company to implement those policies.\n(2) The university company must comply with any direction given by the Minister under subsection (1)."}},{"id":"SG-H3341-A6","no":6,"noLabel":{"en":"6."},"chapter":{"en":"PART 2 PROVISIONS RELATING TO UNIVERSITY COMPANY"},"heading":{"en":"Appointment to Board"},"text":{"en":"6.—(1) The Board consists of such number of trustees as the Minister may appoint.\n(2) The Minister may, at any time, remove or replace any trustee, or appoint new or additional trustees to the Board."}},{"id":"SG-H3341-A7","no":7,"noLabel":{"en":"7."},"chapter":{"en":"PART 2 PROVISIONS RELATING TO UNIVERSITY COMPANY"},"heading":{"en":"Consent of Minister"},"text":{"en":"7.—(1) The prior written consent of the Minister is required for —\n(a)the admission of any person as a member of the university company and the removal of any such member;\n(b)the disposal of the whole or substantially the whole of the university company’s undertaking or property;\n(c)the voluntary winding up of the university company;\n(d)the addition, deletion or alteration of any provision of the constituent documents of the university company; and\n(e)the removal of any trustee from the Board.\n(2) The requirements under subsection (1) apply in addition to the requirements prescribed by the Companies Act 1967 and the Insolvency, Restructuring and Dissolution Act 2018 in respect of the matters referred to in subsection (1)(a) to (e).\n[40/2018]\n(3) Any act done or agreement made in contravention of subsection (1) has no effect and is unenforceable at law."}},{"id":"SG-H3341-A8","no":8,"noLabel":{"en":"8."},"chapter":{"en":"PART 2 PROVISIONS RELATING TO UNIVERSITY COMPANY"},"heading":{"en":"Provision of funds"},"text":{"en":"8.—(1) The Minister must pay to the university company such moneys as Parliament may provide from time to time for the funding of the university company.\n(2) All moneys paid to the university company under subsection (1) may only be applied or expended by the university company for such objects provided by its constituent documents as the Minister may allow."}},{"id":"SG-H3341-A9","no":9,"noLabel":{"en":"9."},"chapter":{"en":"PART 2 PROVISIONS RELATING TO UNIVERSITY COMPANY"},"heading":{"en":"Access to accounts and summary of financial statements"},"text":{"en":"9.—(1) The Minister or a person authorised by the Minister (called in this section an authorised person) is entitled, at all reasonable times, to full and free access to all accounting and other records relating, directly or indirectly, to the financial transactions of the university company.\n(2) The Minister or an authorised person may require any person to provide him or her with any information in that person’s possession, or to which that person has access, that the Minister or authorised person considers necessary for ascertaining —\n(a)whether moneys paid to the university company under section 8 were applied or expended in accordance with that section; and\n(b)any other matters that the Minister or authorised person considers necessary.\n(3) The university company must make available to the public, at such frequency and in such manner as the Minister may determine, a summary of the financial statements of the university company which must be in such form and contain such information as the Minister may determine.\n(4) Any person who, without reasonable excuse, fails to comply with any requirement of the Minister or an authorised person under subsection (2) or who otherwise hinders, obstructs or delays the Minister or an authorised person in the performance of his or her duties or in the exercise of his or her powers under this section, shall be guilty of an offence and shall be liable on conviction to a fine not exceeding $1,000."}},{"id":"SG-H3341-A10","no":10,"noLabel":{"en":"10."},"chapter":{"en":"PART 2 PROVISIONS RELATING TO UNIVERSITY COMPANY"},"heading":{"en":"Application of Societies Act 1966 to student bodies"},"text":{"en":"10.—(1) Despite anything to the contrary in the Societies Act 1966, the provisions of that Act have effect in relation to any student body constituted pursuant to the provisions of the constituent documents of the university company.\n(2) The Minister charged with the responsibility for societies may, by order in the Gazette, exempt any student body mentioned in subsection (1) from all or any of the provisions of the Societies Act 1966 subject to any conditions specified in the order."}},{"id":"SG-H3341-A11","no":11,"noLabel":{"en":"11."},"chapter":{"en":"PART 2 PROVISIONS RELATING TO UNIVERSITY COMPANY"},"heading":{"en":"Act to prevail over constituent documents, etc."},"text":{"en":"11.—(1) Any provision of the constituent documents, or any regulation of the university company made pursuant to any provision of the constituent documents, that is inconsistent with any provision of this Act is, to the extent of the inconsistency, void.\n(2) Nothing in this Act is to be construed as excusing or exempting the university company from complying with any written law that, apart from this Act, would apply to the university company."}},{"id":"SG-H3341-A12","no":12,"noLabel":{"en":"12."},"chapter":{"en":"PART 3 TRANSFER OF PROPERTY, RIGHTS, LIABILITIES, EMPLOYEES, ETC., TO UNIVERSITY COMPANY"},"heading":{"en":"Transfer to university company of property, rights and liabilities"},"text":{"en":"12.—(1) As from 1 April 2006, such property, rights and liabilities comprised in the undertaking of the predecessor university determined by the Minister and agreed to by the Minister for Finance are, by virtue of this section and without further assurance, act or deed, transferred to and vested in the university company.\n(2) Any property which by any scheme, will or other instrument or otherwise was held upon trust for any specific foundation or object of the predecessor university and which has been transferred to or vests in the university company by virtue of subsection (1) must, after the transfer or vesting, be held upon trust for and applied as far as possible to the like foundation or object of the university company.\n(3) Any property which was held upon any trust and which has been transferred to or vests in the university company by virtue of subsection (1) must, after the transfer or vesting, be held upon the same trust.\n(4) If any question arises as to whether any particular property, right or liability has been transferred to or vested in the university company under subsection (1), a certificate under the hand of the Minister for Finance is conclusive evidence that the property, right or liability was or was not so transferred or vested.\n(5) Any immovable property to be transferred to and vested in the university company under subsection (1) must be held by the university company upon the tenure and subject to the terms and conditions determined by the President.\n(6) Despite section 145 of the Land Titles Act 1993, it is not necessary for the university company to make any application to the Registrar of Titles to enter in the land‑register a memorial of the vesting in favour of the university company of all mortgages or charges of registered land comprised in the undertakings transferred to and vested in the university company under this Act.\n(7) Section 56(1) of the Land Titles Act 1993 does not apply to any instrument executed by the university company purporting to dispose of, or to create an interest in, mortgages or charges of registered land comprised in the undertakings transferred to and vested in the university company under this Act and does not prevent the registration of any such instrument executed by the university company, even though the university company may not be named as the proprietor or proprietors of the registered land in the land-register at the time of the registration of that instrument.\n(8) Despite section 4 of the Registration of Deeds Act 1988, it is not necessary for the university company to register the vesting in favour of the university company of all mortgages or charges of unregistered land comprised in the undertakings transferred to and vested in the university company under this Act, and the production of a Government Printer’s copy of this Act is admissible in any court as evidence of the university company’s interest in that land.\n(9) For the purposes of the Land Titles Act 1993 and the Registration of Deeds Act 1988, all caveats or memoranda of charge claiming an interest in land as mortgagee or chargee lodged by the predecessor university and subsisting as at 1 April 2006 are construed and have effect on and after that date as if every reference in them to the predecessor university were substituted with a reference to the university company.\n(10) All proceedings by or against the predecessor university which were commenced before 1 April 2006 and which are pending on that date may be continued, completed and enforced by or against the university company on and after that date.\n(11) Every agreement relating to any of the transferred properties to which the predecessor university was a party immediately before 1 April 2006, whether or not of a nature that the rights and liabilities under the agreement can be assigned, has effect on and after that date as if —\n(a)the university company had been a party to the agreement; and\n(b)every reference in the agreement to the predecessor university were substituted in respect of anything to be done on or after that date, with a reference to the university company."}},{"id":"SG-H3341-A13","no":13,"noLabel":{"en":"13."},"chapter":{"en":"PART 3 TRANSFER OF PROPERTY, RIGHTS, LIABILITIES, EMPLOYEES, ETC., TO UNIVERSITY COMPANY"},"heading":{"en":"Transfer of employees"},"text":{"en":"13.—(1) As from 1 April 2006, all persons employed immediately before that date by the predecessor university are transferred to the service of the university company on terms no less favourable than those enjoyed by them immediately prior to their transfer.\n(2) Until the terms and conditions of service are drawn up by the university company, the scheme and terms and conditions of service in the predecessor university continue to apply to every person transferred to the service of the university company under subsection (1) as if the person were still in the service of the predecessor university."}},{"id":"SG-H3341-A14","no":14,"noLabel":{"en":"14."},"chapter":{"en":"PART 3 TRANSFER OF PROPERTY, RIGHTS, LIABILITIES, EMPLOYEES, ETC., TO UNIVERSITY COMPANY"},"heading":{"en":"Service rights, etc., of transferred employees"},"text":{"en":"14.—(1) The university company must, in drawing up the terms and conditions of service of any person transferred to the service of the university company under section 13, consider the terms and conditions of service, including any accrued rights to leave, enjoyed by that person while in the employment of the predecessor university.\n(2) The university company must, in drawing up any term or condition relating to the length of service of any person with the university company, provide for the recognition of service under the predecessor university by that person to be service under the university company."}},{"id":"SG-H3341-A15","no":15,"noLabel":{"en":"15."},"chapter":{"en":"PART 3 TRANSFER OF PROPERTY, RIGHTS, LIABILITIES, EMPLOYEES, ETC., TO UNIVERSITY COMPANY"},"heading":{"en":"Existing contracts"},"text":{"en":"15. All deeds, contracts, schemes, bonds, agreements, instruments and arrangements subsisting immediately before 1 April 2006 to which the predecessor university is a party continue in force on and after that date and are enforceable by or against the university company as if the university company had been named in them or had been a party to them instead of the predecessor university."}},{"id":"SG-H3341-A16","no":16,"noLabel":{"en":"16."},"chapter":{"en":"PART 3 TRANSFER OF PROPERTY, RIGHTS, LIABILITIES, EMPLOYEES, ETC., TO UNIVERSITY COMPANY"},"heading":{"en":"Continuation and completion of disciplinary proceedings"},"text":{"en":"16.—(1) Where any disciplinary proceedings commenced before 1 April 2006 against —\n(a)any employee of the predecessor university transferred to the service of the university company under section 13; or\n(b)any student of the predecessor university,\nare pending on that date, the proceedings must, on and after that date, be carried on and completed by the university company.\n(2) Where any hearing or investigation by a duly authorised committee of the predecessor university has commenced before 1 April 2006, but no order, ruling or direction has been made thereon immediately before that date, the committee must, on or after that date, complete the hearing or investigation and may make such order, ruling or direction as it could have made under the authority vested in it before that date.\n(3) Any order, ruling or direction made by a committee under subsection (2) is to be treated as an order, ruling or direction of the university company and has the same force and effect as if it had been made by a duly authorised committee of the university company."}},{"id":"SG-H3341-A17","no":17,"noLabel":{"en":"17."},"chapter":{"en":"PART 3 TRANSFER OF PROPERTY, RIGHTS, LIABILITIES, EMPLOYEES, ETC., TO UNIVERSITY COMPANY"},"heading":{"en":"Misconduct or neglect of duty by employee before transfer"},"text":{"en":"17. The university company may reprimand, reduce in rank, retire, dismiss or punish in any other manner a person who had, while the person was in the employment of the predecessor university, been guilty of any misconduct or neglect of duty which would have rendered the person liable to be reprimanded, reduced in rank, retired, dismissed or punished in any other manner if the person had continued to be in the employment of the predecessor university, and if this Act had not been enacted."}},{"id":"SG-H3341-A18","no":18,"noLabel":{"en":"18."},"chapter":{"en":"PART 4 MISCELLANEOUS"},"heading":{"en":"Predecessor university’s ASPF Scheme"},"text":{"en":"18.—(1) On 1 April 2006, all property, rights and liabilities of the predecessor university relating to the ASPF Scheme are transferred to and vest in the university company.\n(2) Any person who, immediately before 1 April 2006, was a member or former member of the ASPF Scheme continues, on and after that date, to be a member or former member (as the case may be) of the ASPF Scheme.\n(3) The university company must, on 28 December 2007, dissolve the ASPF Scheme in accordance with the First Schedule.\n(4) Despite the repeal of the National University of Singapore Act (Cap. 204, 2002 Revised Edition), until the time that the ASPF Scheme is dissolved —\n(a)section 15 of and the Second Schedule to the National University of Singapore Act (Cap. 204, 2002 Revised Edition) in force immediately before 1 April 2006 and Statute 18 remain in force and continue to apply to the ASPF Scheme; and\n(b)the Board of Trustees of the university company may amend Statute 18 for the purposes of alignment with the prevailing policy in respect of the treatment of moneys or investments under the Central Provident Fund Act 1953.\n(5) On 28 December 2007, the property and rights of the university company relating to the ASPF Scheme are transferred to and vest in the CPF Board in accordance with the First Schedule.\n(6) The Minister may, by order in the Gazette, amend the First Schedule.\n(7) In this section and the First Schedule, unless the context otherwise requires —\n“ASPF Scheme” means the Academic Staff Provident Fund Scheme established by the predecessor university under Statute 18;\n“CPF Board” means the Central Provident Fund Board established and constituted under the Central Provident Fund Act 1953;\n“Statute 18” means Statute 18 (Academic Staff Provident Fund Scheme) made pursuant to the National University of Singapore Act (Cap. 204, 2002 Revised Edition), as may be amended from time to time by the Board under subsection (4)(b)."}},{"id":"SG-H3341-A19","no":19,"noLabel":{"en":"19."},"chapter":{"en":"PART 4 MISCELLANEOUS"},"heading":{"en":"Students’ Union"},"text":{"en":"19. On 1 April 2006, the students’ association known as the National University of Singapore Students’ Union and its constituent bodies are deemed to be constituted pursuant to the provisions of the constituent documents of the university company."}},{"id":"SG-H3341-A20","no":20,"noLabel":{"en":"20."},"chapter":{"en":"PART 4 MISCELLANEOUS"},"heading":{"en":"Register of Guild of Graduates"},"text":{"en":"20. The provisions of the Second Schedule apply to all persons whose names are on the register of the Guild of Graduates of the predecessor university."}},{"id":"SG-H3341-A900000","no":900000,"noLabel":{"en":"FIRST SCHEDULE"},"text":{"en":"FIRST SCHEDULE\nSection 18(3), (5), (6) and (7)\nDissolution of ASPF Scheme\nInterpretation\n1.—(1) In this Schedule, unless the context otherwise requires —\n“ASPF” means the Academic Staff Provident Fund;\n“ASPFAIS Investment” means an investment effected under Clause 19E of Statute 18;\n“ASPF member” means a person who is a member of the ASPF Scheme and who is in the service of the university company as at 28 December 2007;\n“ASPF moneys” means the moneys standing to the credit of any person under the ASPF Scheme;\n“assets of the ASPF” means all property, assets, rights and interests of every description relating to the ASPF Scheme which immediately before 28 December 2006 were vested in the university company or the Trustees, including, without limitation, all moneys, mortgages (legal or equitable) of immovable property and investments (including assurance policies and unit trusts);\n“balance of the assets of the ASPF” means the assets of the ASPF excluding —\n(a)the ASPF moneys, ASPFAIS Investments or Part V Assurances to be transferred or assigned to any relevant person under paragraph 5(b);\n(b)the ASPF moneys, ASPFAIS Investments or Part V Assurances standing to the credit of each living relevant person under the ASPF Scheme credited or to be credited to the relevant person’s CPF account under paragraph 18 or 19;\n(c)the ASPF moneys, ASPFAIS Investments or Part V Assurances to be retained by the university company under paragraphs 33 and 40;\n(d)the mortgages (whether legal or equitable), in relation to the mortgaged properties under the ASPF Scheme, to be transferred to and vested in the CPF Board under paragraph 25(1); and\n(e)the mortgages (whether legal or equitable), in relation to the mortgaged properties under the ASPF Scheme, to be retained by the university company under paragraphs 37 and 44,\nafter deducting the liabilities of the ASPF Scheme and the expenses of winding up the ASPF Scheme;\n“Board of Management” means the board of management of the ASPF Scheme constituted under Clause 8(a) of Statute 18;\n“CPF” means the Central Provident Fund established under the Central Provident Fund Act 1953;\n“CPF account” means an account maintained under the Central Provident Fund Act 1953;\n“CPFIS” means the Central Provident Fund Investment Scheme established under the Central Provident Fund Act 1953;\n“CPF member” means a person who is a member of the CPF as defined by section 2(1) of the Central Provident Fund Act 1953;\n“deceased relevant person” means a relevant person who is not uncontactable and who dies before 28 December 2007;\n“dissolution notice” means the notice to be given by the university company to the relevant persons under paragraph 2;\n“expenses of winding up the ASPF Scheme” means all expenses including legal and accounting costs of winding up the ASPF Scheme and any legal costs and stamps fees incurred in connection with the transfer of the property, assets, rights and interests relating to the ASPF Scheme to the CPF Board, whether incurred before, on or after 28 December 2006;\n“Interest Equalisation Reserve Account” means the account established under Clause 11(ii) of Statute 18;\n“Investment Depreciation Reserve Account” means the account established under Clause 13(i) of Statute 18;\n“Investment Fund” means the Investment Fund constituted under Clause 5 of Statute 18;\n“living relevant person” means any relevant person who is alive immediately before 28 December 2007;\n“mortgaged property under the ASPF Scheme” means any immovable property with a mortgage (whether legal or equitable) in favour of the university company which secures a withdrawal of ASPF moneys to finance the purchase of the property or to finance or re-finance the payment of a housing loan taken out for the purchase of the property;\n“notice period” means the period from 28 December 2006 to 28 December 2007;\n“Part V Assurance” means a life assurance or an endowment assurance effected under Part V of Statute 18;\n“relevant person” means any person who, before 28 December 2007, had ASPF moneys, ASPFAIS Investments or Part V Assurances standing to that person’s credit under the ASPF Scheme or a mortgaged property under the ASPF Scheme;\n“Trustees” means the trustees of the ASPF Scheme;\n“working day” means any day other than a Saturday, Sunday or public holiday.\n(2) In this Schedule, a relevant person is treated as uncontactable if —\n(a)the person does not have a CPF account; and\n(b)the university company is not in possession of any of the following details or documents in respect of the person which are necessary for the opening of a CPF account:\n(i)the person’s nationality;\n(ii)in the case of a relevant person who is a citizen of Singapore, the person’s Singapore national registration identification number;\n(iii)in the case of a relevant person who is not a citizen of Singapore, the person’s passport number and foreign identification number, a copy of each page of the person’s passport which contains the person’s identification information and a copy of the person’s foreign identification card;\n(iv)the person’s date of birth,\ndespite reasonable efforts made by the university company to obtain those details or documents.\nNotification of dissolution of ASPF Scheme\n2. The university company must —\n(a)on a date which is at least 12 months before 28 December 2007, give a written notice to each relevant person who is not uncontactable of its intention to wind up the ASPF Scheme; and\n(b)on the 7th working day after the date on which the dissolution notice is given, cause the dissolution notice to be published in a local daily English newspaper circulating generally in Singapore.\n3. The dissolution notice is deemed to have been duly served on a relevant person —\n(a)where the dissolution notice is sent by post to the relevant person’s address —\n(i)if the address is in Singapore, within 2 clear working days; or\n(ii)if the address is outside Singapore, within 5 clear working days,\nafter the notice was posted; and in proving service of the notice, it is sufficient to prove that the envelope containing the notice was addressed, stamped and posted;\n(b)where the dissolution notice is delivered by hand, immediately upon delivery to the relevant person or upon it being left at the relevant person’s mailbox at the university company’s premises designated by the university company for use by the relevant person;\n(c)where the dissolution notice is in the form of an electronic mail sent to the relevant person’s electronic mail address, on the date and at the time stated in the electronic acknowledgment of receipt by the relevant person which is received by the university company; or\n(d)upon the publication of the dissolution notice in the local daily English newspaper under paragraph 2(b),\nwhichever is the earliest in time.\n4. For the purposes of paragraph 3 —\n(a)the relevant address of a relevant person in paragraph 3(a) is the last known address of the relevant person according to the university company’s records;\n(b)the relevant email address of an ASPF member in paragraph 3(c) is the email address bearing the Internet domain name “nus.edu.sg” which is assigned by the university company to the ASPF member.\nRelevant person 55 years of age or above\n5. The university company must give each relevant person who is 55 years of age or above as at 28 December 2007 and who is not uncontactable, and must by notice inform the relevant person of, the option of either —\n(a)having his or her ASPF moneys, ASPFAIS Investments or Part V Assurances transferred to his or her CPF account or a CPF account opened for him or her in accordance with paragraph 15, as the case may be; or\n(b)having his or her ASPF moneys, ASPFAIS Investments or Part V Assurances transferred or assigned to him or her, or to have the mortgage in relation to his or her mortgage property under the ASPF Scheme discharged (as the case may be) subject to the condition that he or she —\n(i)has sufficient money set aside for the purposes of section 15(6) of the Central Provident Fund Act 1953; or\n(ii)sets aside an amount of ASPF moneys to be transferred to his or her CPF account or a CPF account opened for him or her in accordance with paragraph 15 (as the case may be) for the purposes of section 15(6) of the Central Provident Fund Act 1953.\n6. If the university company is not notified of the option selected by a relevant person mentioned in paragraph 5 in the manner and by the date specified in the university company’s notice to that relevant person under paragraph 5, that relevant person’s ASPF moneys must be transferred to the CPF Board under paragraph 13(b) and his or her ASPFAIS Investments or Part V Assurances (if any) are deemed to be investments under the CPFIS under paragraph 22.\nPart V Assurances or ASPFAIS Investments\n7. All premiums paid towards any Part V Assurance, whether using ASPF moneys or cash, before 28 December 2007, are deemed to have been paid with ASPF moneys.\n8. With effect from 28 December 2006, no new Part V Assurance is allowed to be effected under the ASPF Scheme.\n9.—(1) Before 28 December 2007, the Board of Management must assign every Part V Assurance and ASPFAIS Investment held in the name of the predecessor university on behalf of any relevant person who is not uncontactable back to the relevant person.\n(2) To avoid doubt, any Part V Assurance or ASPFAIS Investment so assigned is, despite the assignment, considered to be standing to the credit of the relevant person under the ASPF Scheme.\nDissolution of ASPF Scheme and transfer of ASPF moneys\n10. During the notice period, the university company may apply the assets of the ASPF to pay the debts and liabilities of the ASPF Scheme and the costs, charges and expenses of winding up the ASPF.\n11.—(1) The university company must —\n(a)cause the accounts of the ASPF to be prepared up to 27 December 2007; and\n(b)within 30 days of 28 December 2007, compute the respective share of the balance of the assets of the ASPF (if any) in respect of each relevant person who has ASPF moneys standing to his or her credit in the ASPF Scheme immediately before 28 December 2007 pro rata to the average of the balances of ASPF moneys in his or her account at the end of each quarter for the period commencing after the last periodical valuation conducted pursuant to Clause 13 of Statute 18 and ending on 27 December 2007,\nand then close the accounts of the ASPF.\n(2) The university company must, as soon as practicable after the accounts of the ASPF are closed, cause the accounts to be audited and must, after the audit, deliver the audited accounts to the CPF Board.\n12. The accounts to be delivered to the CPF Board under paragraph 11(2) must —\n(a)give full particulars of the assets of the ASPF and full particulars of the Investment Fund, Interest Equalisation Reserve Account and Investment Depreciation Reserve Account;\n(b)provide details of the ASPF moneys standing to the credit of each living relevant person under the ASPF Scheme and to be transferred to the CPF Board under paragraph 13(b); and\n(c)provide details of the respective share of the balance of the assets of the ASPF of each living relevant person who has ASPF moneys standing to his or her credit in the ASPF Scheme immediately before 28 December 2007 computed under paragraph 11(1)(b) to be transferred to his or her CPF ordinary account under paragraph 20.\n13. On 28 December 2007 —\n(a)the ASPF Scheme is dissolved;\n(b)the ASPF moneys, including (where applicable) interest under Clause 11(i) of Statute 18, to be credited under paragraph 18 to the CPF accounts of each living relevant person who is not uncontactable (other than a relevant person who has opted for those moneys to be transferred or assigned to him or her under paragraph 5(b)), must be transferred to the CPF Board; and\n(c)the balance of the assets of the ASPF (if any) must be retained by the university company to be held on trust for the relevant persons who have ASPF moneys immediately before 28 December 2007.\n14. Despite paragraph 13, the university company must satisfy all rights against it, the ASPF or the Trustees as are expressly preserved by paragraph 32(2) and must fulfil and perform all duties and obligations in respect of the ASPF Scheme which ought to have been fulfilled or performed by it, by the Board of Management or by the Trustees (as the case may be) and which for any reason remain unfulfilled or unperformed on 28 December 2007.\nOpening of CPF accounts and crediting into CPF accounts\n15. Every living relevant person who is not uncontactable and is not already a CPF member immediately before 28 December 2007 is deemed to be a CPF member on that date, and the CPF Board must open CPF accounts for those persons in accordance with the Central Provident Fund Act 1953.\n16. Every person who is deemed a CPF member under paragraph 15 is bound by the Central Provident Fund Act 1953 and entitled to all rights and privileges of CPF members under that Act.\n17. Any ASPF moneys which are transferred to the CPF Board by virtue of paragraph 13(b) or any Part V Assurance or ASPFAIS Investment deemed to be an investment under the CPFIS under paragraph 22, which was held upon any trust for any living relevant person immediately before 28 December 2007 must, after the transfer or deeming, be held upon the same trust.\n18. Upon the transfer to the CPF Board of the ASPF moneys mentioned in paragraph 13(b), the CPF Board must credit the ordinary and special accounts in the CPF of each living relevant person mentioned in that paragraph with the amounts standing to the credit of that person under the ASPF Scheme immediately before 28 December 2007.\n19. The CPF Board must, in respect of each living relevant person who is not uncontactable and who immediately before 28 December 2007 has any Part V Assurance or ASPFAIS Investment (other than any Part V Assurance or ASPFAIS Investment which that person has opted to be transferred or assigned to him or her under paragraph 5(b)), treat the Part V Assurance or ASPFAIS Investment as an investment under the CPFIS, as deemed under paragraph 22, and must credit the Part V Assurance or ASPFAIS Investment to the relevant person’s CPFIS account.\n20. The respective share of the balance of the assets of the ASPF (if any) of each living relevant person who has ASPF moneys standing to his or her credit under the ASPF Scheme computed under paragraph 11(1)(b) must be transferred from the university company to the CPF Board 30 days after 28 December 2007 and the CPF Board must credit the share to the ordinary account of that person.\n21. Every employment contract or agreement for service between the university company and an ASPF member is deemed to be varied to provide that the ASPF member is, with effect from 28 December 2007, required to contribute to the CPF instead of the ASPF.\nPart V Assurances and ASPFAIS Investments deemed investments under CPFIS\n22. On 28 December 2007, every Part V Assurance and ASPFAIS Investment of a living relevant person who is not uncontactable held by him or her immediately before that date (other than any Part V Assurance or ASPFAIS Investment which that person has opted to be transferred or assigned to him or her under paragraph 5(b)) is deemed to be an investment made by him or her under the CPFIS, and all premiums paid or deemed to have been paid with ASPF moneys in respect of ASPFAIS Investments and Part V Assurances are, on and after that date, deemed to have been paid with CPF moneys from his or her CPF account.\n23. Every living relevant person who, at any time before 28 December 2007, used ASPF moneys for paying the premium on his or her Part V Assurance is, on and after that date, entitled to use moneys credited to his or her ordinary account with the CPF Board for paying the premium on that Part V Assurance and any rider thereto.\n24. To avoid doubt, a living relevant person who did not, at any time before 28 December 2007, use his or her ASPF moneys for paying the premium on his or her Part V Assurance is not entitled to use moneys credited to his or her ordinary account with the CPF Board for paying the premium on that Part V Assurance or any rider thereto.\nPreservation of rights in relation to immovable property\n25.—(1) Each mortgage (whether legal or equitable) in favour of the university company in relation to any mortgaged property under the ASPF Scheme of a living relevant person who is not uncontactable is, on 28 December 2007 transferred to and vests in the CPF Board.\n(2) The CPF Board is, in respect of any mortgage mentioned in sub‑paragraph (1) and the liabilities secured by the mortgage, entitled to the same rights and priorities and subject to the same obligations and incidents on and after 28 December 2007 as the university company would have been entitled and subject to if the mortgage had continued to be held by the university company or in the university company’s favour.\n26. Despite section 145 of the Land Titles Act 1993, it is not necessary for the CPF Board to make any application to the Registrar of Titles to enter in the land‑register a memorial of the vesting in favour of the CPF Board of all mortgages or charges of registered land transferred to and vested in the CPF Board under paragraph 25(1).\n27. Section 56(1) of the Land Titles Act 1993 does not apply to any instrument executed by the CPF Board purporting to dispose of, or to create an interest in, mortgages or charges of registered land transferred to or vested in the CPF Board under paragraph 25(1) and must not prevent the registration of any such instrument executed by the CPF Board, even though the CPF Board may not be named as the proprietor of the registered land in the land-register at the time of the registration of such instrument.\n28. Despite section 4 of the Registration of Deeds Act 1988, it is not necessary for the CPF Board to register the transfer to or vesting in favour of the CPF Board of all mortgages or charges of unregistered land under paragraph 25(1), and the production of a Government Printer’s copy of this Act is admissible in any court as evidence of the CPF Board’s interest in the land.\n29. For the purposes of the Land Titles Act 1993 and the Registration of Deeds Act 1988, all caveats or memoranda of charge claiming an interest in land as mortgagee or chargee in respect of any mortgaged property under the ASPF Scheme lodged by the university company and subsisting as at 28 December 2007 are construed and have effect on and after that date as if any reference in them to the university company is a reference to the CPF Board.\nDisclosure of information\n30. The university company and the CPF Board are entitled, and it is lawful for the university company and the CPF Board, to disclose to each other and to any bank, insurance company or other financial institution which —\n(a)is approved or participating under the CPFIS;\n(b)is approved or participating under any investment scheme referred to in Clause 19E of Statute 18; or\n(c)has issued any Part V Assurance,\nas the case may be, such information relating to —\n(d)the assets of the ASPF;\n(e)any person who has, on 28 December 2006, any ASPF moneys, Part V Assurance, ASPFAIS Investment or mortgaged property under the ASPF Scheme;\n(f)the accounts under the ASPF of any person mentioned in sub‑paragraph (e);\n(g)the CPF accounts of any person mentioned in sub‑paragraph (e); and\n(h)the contact details of any person mentioned in sub‑paragraph (e),\nas the university company or the CPF Board thinks necessary to facilitate the dissolution and transfer of assets.\n31. Any relevant person in respect of whom any information relating to —\n(a)himself or herself;\n(b)any of his or her moneys, investments, assurances or mortgaged property;\n(c)his or her account in the ASPF Scheme; or\n(d)his or her CPF accounts,\nhas been disclosed under paragraph 30 is deemed to have consented to the disclosure.\nClaims against ASPF Scheme\n32.—(1) Upon the dissolution of the ASPF, no relevant person has any claim against the ASPF Scheme, the university company, the Trustees or the CPF Board other than in accordance with and pursuant to the provisions of this Schedule.\n(2) Despite sub-paragraph (1) but subject to the first and paramount lien or charge vested in the university company pursuant to Clause 7 of Statute 18, the dissolution of the ASPF does not prejudice or affect the rights of any relevant person to any payment out of the assets of the ASPF that had accrued immediately before the dissolution of the ASPF.\nASPF moneys, ASPFAIS Investments, Part V Assurances and mortgaged property of deceased relevant persons\n33. All ASPF moneys, ASPFAIS Investments and Part V Assurances of a deceased relevant person must not be transferred to the CPF Board on 28 December 2007.\n34. The ASPF moneys of a deceased relevant person mentioned in paragraph 33 must on 28 December 2007 be transferred to an account opened in the name of the university company as trustee and must be placed on deposit with a bank.\n35. The respective share of the balance of the assets of the ASPF (if any) in respect of the deceased person computed in accordance with paragraph 11(1)(b) must be transferred on 27 January 2008 to the account mentioned in paragraph 34.\n36. The ASPFAIS Investments and Part V Assurances of a deceased relevant person mentioned in paragraph 33 must be held by the university company as trustee.\n37. The university company continues, in respect of any mortgage (whether legal or equitable) in favour of the university company in relation to any mortgaged property under the ASPF Scheme of a deceased relevant person and the liabilities secured by the mortgage, to be entitled to the same rights and priorities and subject to the same obligations and incidents on and after 28 December 2007 as it had been immediately before that date.\n38. The university company has the right to deduct from the moneys transferred to the account under paragraphs 34 and 35 or apply any amount of the property referred to in paragraph 36 that is necessary to reimburse any reasonable expenses incurred by it in administering the moneys, investments or assurances of a deceased relevant person.\n39.—(1) The moneys which have been transferred to the account under paragraphs 34 and 35 and the ASPFAIS Investments and Part V Assurances mentioned in paragraph 36, must be paid or transferred to the trustees or legal personal representatives of the deceased relevant person.\n(2) The university company must arrange for the discharge of the mortgaged property mentioned in paragraph 37.\nASPF moneys, ASPFAIS Investments, Part V Assurances and mortgaged property of uncontactable relevant persons\n40. All ASPF moneys, ASPFAIS Investments and Part V Assurances of a relevant person who is uncontactable must not be transferred to the CPF Board on 28 December 2007.\n41. The ASPF moneys of a relevant person who is uncontactable mentioned in paragraph 40 must on 28 December 2007 be transferred to an account or accounts to be opened in the name of the university company as trustee and must be placed on deposit with a bank.\n42. The amount of the balance of the assets of the ASPF (if any) which is attributable to the shares of the balance of the assets of the ASPF of all uncontactable relevant persons who have ASPF moneys standing to their credit in the ASPF Scheme immediately before the dissolution date, computed under paragraph 11(1)(b), must be transferred on 27 January 2008 to the account or accounts mentioned in paragraph 41.\n43. The ASPFAIS Investments and Part V Assurances of a relevant person who is uncontactable mentioned in paragraph 40 must be held by the university company as trustee.\n44. The university company continues, in respect of any mortgage (whether legal or equitable) in favour of the university company in relation to any mortgaged property under the ASPF Scheme of an uncontactable relevant person and the liabilities secured by the mortgage, to be entitled to the same rights and priorities and subject to the same obligations and incidents on and after 28 December 2007 as it had been immediately before that date.\n45. The university company has the right to deduct from the moneys transferred to the account or accounts under paragraph 41 or 42 or apply any amount of the property referred to in paragraph 43 that is necessary to reimburse any reasonable expenses incurred by it in administering the moneys, investments or assurances of a relevant person who is uncontactable.\n46. Any person entitled to the whole or any part of any amount or property which is held on trust in the account or accounts mentioned in paragraph 41 or under paragraph 43 may apply to the university company to claim that amount or property, or part of it.\n47. Where an application has been made under paragraph 46 by a living relevant person, the CPF Board must, at the university company’s request, open a CPF account for the relevant person.\n48. Upon the opening of the CPF account mentioned in paragraph 47, the university company must —\n(a)where the relevant person is below 55 years of age, transfer his or her ASPF moneys, ASPFAIS Investments or Part V Assurances to that CPF account; or\n(b)where the relevant person is 55 years of age or above, give the relevant person an option —\n(i)to have his or her ASPF moneys, ASPFAIS Investments or Part V Assurances transferred to that CPF account; or\n(ii)to have his or her ASPF moneys, ASPFAIS Investments or Part V Assurances transferred to him or her subject to the condition that he or she sets aside an amount of ASPF moneys in his or her CPF account for the purposes of section 15(6) of the Central Provident Fund Act 1953.\nEvidence of transfer of property, assets, rights and interests\n49. The production of a Government Printer’s copy of this Act is, for all purposes, conclusive evidence of the transfer of the balance of the assets of the ASPF to the CPF Board and the vesting of the balance of the assets of the ASPF in the CPF Board in accordance with the provisions of this Schedule.\n[S 633/2007]"}},{"id":"SG-H3341-A900001","no":900001,"noLabel":{"en":"SECOND SCHEDULE"},"text":{"en":"SECOND SCHEDULE\nSection 20\nProvisions applicable to Register of Guild of Graduates\n1. The university company must maintain a Register of Graduates which consists of —\n(a)the names of all persons who immediately before 8 August 1980 were members of the Guild of Graduates of the University of Singapore and of all persons on whom degrees of the University of Singapore had been conferred;\n(b)the names of all persons who immediately before 1 April 2006 were members of the Guild of Graduates of the predecessor university and of all persons on whom degrees of the predecessor university had been conferred; and\n(c)the names of all graduates of the University.\n2. The Register of Graduates may be in the form determined by the Board but must be divided into 3 Parts, as follows:\n(a)Part A contains the names of all persons specified in paragraph 1(a);\n(b)Part B contains the names of all persons specified in paragraph 1(b);\n(c)Part C contains the names of all graduates of the University.\n3. Any person whose name is on the Register of Graduates may receive such documents or other papers of the University as determined by the Board from time to time.\n4. In this Schedule, “University” means the university known as the National University of Singapore operated, maintained and promoted by the university company."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"National University of Singapore (Corporatisation) Act 2005","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3342"] = {"id":"SG-H3342","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NUSA1980-R5?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"新加坡国立大学（初次任命及其他过渡条文）规则","en":"National University of Singapore (Initial Appointments and Other Transitional Provisions) Rules","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NUSA1980-R5","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3342-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. These Rules may be cited as the National University of Singapore (Initial Appointments and Other Transitional Provisions) Rules."}},{"id":"SG-H3342-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Faculty of Accountancy and Business Administration"},"text":{"en":"2. The School of Accountancy and Business Administration of the University of Singapore shall on and after 8th August 1980 become a faculty of the University to be known as the Faculty of Accountancy and Business Administration."}},{"id":"SG-H3342-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Student Societies"},"text":{"en":"3. All student societies of the University of Singapore registered under the Societies Act [Cap. 311] which have been formed with the approval of the University of Singapore shall be deemed to have been formed with the approval of the University."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National University of Singapore (Initial Appointments and Other Transitional Provisions) Rules","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3343"] = {"id":"SG-H3343","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NUSA1980-R6?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"新加坡国立大学学术人员公积金计划规则","en":"National University of Singapore Academic Staff Provident Fund Scheme Rules","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NUSA1980-R6","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3343-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. These Rules may be cited as the National University of Singapore Academic Staff Provident Fund Scheme Rules."}},{"id":"SG-H3343-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Continuance of Academic Staff Provident Fund Scheme"},"text":{"en":"2. The Academic Staff Provident Scheme, established by the University of Singapore under section 27(f) of the Constitution of the University of Singapore and in force immediately before 8th August 1980, shall continue to be in force on and after that date subject to the following modifications:\n(a)the Scheme shall be known as the National University of Singapore Academic Staff Provident Fund Scheme;\n(b)references to the University of Singapore or to the University shall be construed as references to the National University of Singapore; and\n(c)a new Board of Management of the Scheme shall be constituted as soon as practicable after the appointed day and shall consist of —\n(i)the Vice-Chancellor or his representative;\n(ii)3 persons appointed by the Council from among its members; and\n(iii)3 persons elected by the members of the Scheme.\n[2989/70]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National University of Singapore Academic Staff Provident Fund Scheme Rules","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3344"] = {"id":"SG-H3344","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NUSCA2005-OR1?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"新加坡国立大学学生会及属会（豁免）命令","en":"National University of Singapore Students’ Union and Constituent Bodies (Exemption) Order","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NUSCA2005-OR1","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3344-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the National University of Singapore Students’ Union and Constituent Bodies (Exemption) Order."}},{"id":"SG-H3344-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption from Societies Act"},"text":{"en":"2. The National University of Singapore Students’ Union and its constituent bodies specified in the Schedule (each of which is referred to in this Order as an exempted entity) are hereby exempted from the provisions of the Societies Act (Cap. 311), subject to the following conditions:\n(a)an exempted entity shall furnish the Registrar of Societies with such information concerning, and such documents, accounts and books relating to, the exempted entity as he may require;\n(b)an exempted entity shall not use any flag, symbol, emblem, badge or insignia without the consent in writing of the Registrar of Societies; and\n(c)an exempted entity shall not be used —\n(i)for unlawful purposes;\n(ii)for purposes prejudicial to public peace, welfare or good order in Singapore; or\n(iii)for any purpose incompatible with the objects and rules of the exempted entity."}},{"id":"SG-H3344-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nParagraph 2\nConstituent Bodies of the Union\n1. Students’ Arts and Social Sciences Club.\n2. Students’ Science Club.\n3. Students’ Medical Club.\n4. Students’ Dental Club.\n5. Students’ Law Club.\n6. Students’ Business Club.\n7. Students’ Design and Engineering Club.\n[S 292/2026 wef 14/05/2026]\n8. Students’ NUS College Club.\n[S 292/2026 wef 14/05/2026]\n9. Students’ Computing Club.\n10. [Deleted by S 292/2026 wef 14/05/2026]\n11. Students’ Sports Club.\n12. Students’ Cultural Activities Club.\n13. Students’ Community Service Club.\n14. Students’ Conservatory Club.\n[S 162/2022 wef 04/03/2022]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"National University of Singapore Students’ Union and Constituent Bodies (Exemption) Order","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3345"] = {"id":"SG-H3345","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NPPA1974-R2?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"报章与印刷馆（申请与执照）规则","en":"Newspaper and Printing Presses (Applications and Licences) Rules","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NPPA1974-R2","completenessNote":"全文，共 4 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3345-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. These Rules may be cited as the Newspaper and Printing Presses (Applications and Licences) Rules."}},{"id":"SG-H3345-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Application for licence to keep any press"},"text":{"en":"2. Every application made under section 3 of the Act for a licence to keep and use any press for the printing of documents shall be made in duplicate by the applicant in such form as the Minister may from time to time direct."}},{"id":"SG-H3345-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Form"},"text":{"en":"3. Every licence granted under section 3 of the Act shall be substantially in the form set out in the Schedule."}},{"id":"SG-H3345-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nNEWSPAPER AND PRINTING PRESSES ACT\n(CHAPTER 206)\nNEWSPAPER AND PRINTING PRESSES\n(APPLICATIONS AND LICENCES)\nRULES\nLICENCE TO USE PRINTING PRESS\nLICENCE NUMBER:\nThis Licence is hereby granted, under section 3 of the Newspaper and Printing Presses Act, to\nto keep and use a printing press (or presses) at\nfor the period from ______________ to ______________.\nThis Licence is granted by the Minister, pursuant to the powers conferred by the Newspaper and Printing Presses Act, for printing purposes within Singapore. The holder of this Licence must comply with the conditions specified hereon and overleaf, as well as the conditions (if any) stated in the covering letter for this Licence.\n____________________________\nMinistry of Digital\nDevelopment and Information,\nSingapore.\n[S 574/2024 wef 08/07/2024]\n[S 303/2004 wef 28/05/2004]\nCONDITION\nThis Licence is not transferable. It will cease to be valid in the event of any change in the holder or location as specified in the Licence.\n[S 303/2004 wef 28/05/2004]\nNOTES\n1. The holder of this Licence must have obtained prior planning permission for the use of the premises as a printing press from the Urban Redevelopment Authority or any other relevant authority.\n2. Every document printed within Singapore shall have printed legibly on its first or last printed leaf the name of its printer and publisher as required under section 5(1) of the Newspaper and Printing Presses Act.\n3. A newspaper permit is required for the printing or publication of any newspaper as defined in the Newspaper and Printing Presses Act. The holder of this Licence must ensure that there is a valid newspaper permit in respect of any newspaper to be printed by the holder of this Licence. The holder of this Licence may inspect the original copy of the permit or check with the Registrar of Newspapers should there be any doubt.\n4. Failure to comply with any condition to which this Licence is subject could result in the Licence being withdrawn either permanently or for such period as the Minister thinks fit under section 3(1) of the Newspaper and Printing Presses Act.\n[S 303/2004 wef 28/05/2004]\n[G.N. No. S 356/88]"}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Newspaper and Printing Presses (Applications and Licences) Rules","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3346"] = {"id":"SG-H3346","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NPPA1974-S302-2004?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"报章与印刷馆（申请与许可证）规则 2004","en":"Newspaper and Printing Presses (Applications and Permits) Rules 2004","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NPPA1974-S302-2004","completenessNote":"全文，共 5 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 1 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3346-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Rules may be cited as the Newspaper and Printing Presses (Applications and Permits) Rules 2004 and shall come into operation on 28th May 2004."}},{"id":"SG-H3346-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Applications"},"text":{"en":"2.—(1) Every application for a permit under section 21 of the Act to print or publish, or assist in the printing or publishing of, any newspaper in Singapore shall be made by the applicant in such form as the Minister may, from time to time, direct.\n(2) Every application —\n(a)for a permit under section 22 of the Act to publish, sell, offer for sale or distribute in Singapore any newspaper printed in Malaysia; or\n(b)for a permit under section 23 of the Act to sell or distribute, or import for or possess for sale or distribution, any offshore newspaper in Singapore,\nshall be made by the applicant in such form as the Minister may, from time to time, direct."}},{"id":"SG-H3346-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Form of permit"},"text":{"en":"3. Every permit issued under section 21, 22 or 23 of the Act shall be substantially in the form set out in the Schedule."}},{"id":"SG-H3346-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Revocation"},"text":{"en":"4. The Newspaper and Printing Presses (Applications and Permits) Rules (R 1) are revoked."}},{"id":"SG-H3346-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nRule 3\nNEWSPAPER AND PRINTING PRESSES ACT\n(CHAPTER 206)\nNEWSPAPER AND PRINTING PRESSES\n(APPLICATIONS AND PERMITS)\nRULES 2004\nPERMIT TO PRINT, PUBLISH, SELL OR DISTRIBUTE A NEWSPAPER\nNAME OF NEWSPAPER\nPERMIT NUMBER\nMITA(P) No.\nNAME(S) OF PERMIT HOLDER(S)*:\nDATE OF ISSUE\nDATE OF EXPIRY\nLANGUAGE(S)\nFREQUENCY\nSPECIAL CONDITIONS (IF ANY)\nNATURE OF CONTENTS\nDETAILS OF PUBLISHER\nDETAILS OF PRINTER\nThis Permit is granted, to the Permit holder(s) named above, by the Minister under section 21/22/23 of the Newspaper and Printing Presses Act in respect of the newspaper described above. The holder(s) of this Permit and the newspaper must comply with the conditions specified hereon and overleaf, as well as the conditions (if any) stated in the covering letter for this Permit. The Minister may at any time in his discretion revoke this Permit.\n_______________________\nMinistry of Digital Development\nand Information,\nSingapore.\n[S 575/2024 wef 08/07/2024]\n*Where the application is made by a political association registered under the Societies Act (Cap. 311), state the names of the proprietor, the chief editor, and the members of the committee or other similar governing body of the association.\nCONDITIONS\n1. This Permit is not transferable. It will cease to be valid in the event of any change in the Proprietor, Chief Editor, name of the newspaper, nature of contents, language or frequency.\n2. Every change in the publisher or the printer of the newspaper described overleaf shall be notified to the Registrar of Newspapers no later than 7 days after the change has become effective.\n3. The Permit number shall be printed on the title page of every issue of the newspaper described overleaf, beneath the title of the newspaper.\n4. If the newspaper described overleaf is printed in Singapore, any change in the financial holdings of the newspaper shall be notified to the Registrar of Newspapers within 7 days of being required to do so or such longer period as the Registrar may allow.\n5. The first issue of the newspaper described overleaf shall commence within 3 months of the date of this Permit and, thereafter, publication shall be made regularly at the intervals shown in this Permit.\n6. The newspaper described overleaf shall conform with the nature of contents submitted with the application for this Permit and the relevant Content Guidelines attached.\n7. The Permit holder shall, at his own expense, send 2 copies of every issue of the newspaper described overleaf to the Registrar of Newspapers immediately upon the commencement of sale or distribution of the newspaper.\nNOTES\n1. Section 10 of the National Library Board Act (Cap. 197) requires every publisher to deposit 2 copies of every publication published in Singapore with the National Library Board, at the publisher’s own expense within 4 weeks from the date of the publication.\n2. If the newspaper described overleaf is printed in Singapore, the names of the printer and the publisher shall be printed legibly on the first or last printed leaf as required under section 5(1) of the Newspaper and Printing Presses Act.\n3. If the newspaper described overleaf is printed in Malaysia, its publication, sale or distribution in Singapore as authorised by this Permit is conditional upon the inclusion on the first or last printed leaf of every issue of the name and address of its printer, its publisher, the place or places where it is printed and published and an address within Singapore for the service of legal process upon the printer and the publisher or of a person or persons authorised by the printer and publisher to accept service on their behalf. All this information must be printed legibly in the English or Malay language.\n4. The grant of this Permit to the Proprietor or Chief Editor of a newspaper printed or published in Singapore does not absolve the printer and the publisher from their other obligations under the Newspaper and Printing Presses Act."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Newspaper and Printing Presses (Applications and Permits) Rules 2004","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H3347"] = {"id":"SG-H3347","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NPPA1974-S515-2012?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"报章与印刷机（罪行构成）规则 2012","en":"Newspaper and Printing Presses (Composition of Offences) Rules 2012","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NPPA1974-S515-2012","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3347-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Rules may be cited as the Newspaper and Printing Presses (Composition of Offences) Rules 2012 and shall come into operation on 15th October 2012."}},{"id":"SG-H3347-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Compoundable offences"},"text":{"en":"2. The following offences may be compounded by the Minister or any officer authorised by the Minister in accordance with section 42 of the Act:\n(a)any offence (other than a continuing offence) under section 8(2), 17(1) or (2), 18(3), 21(9), 24(5), 25(4), 26(5), 28(2) or 33(1) or (3) of the Act;\n(b)any offence under section 35 of the Act in connection with any failure to comply with section 3(4), 5(2), 6, 9(1) or (2) or 10(1), (2), (4), (5), (6), (7), (8), (10), (11), (12), (13) or (14) of the Act;\n(c)any offence under section 35 of the Act in connection with any failure to comply with section 23(1) of the Act in respect of the importation for sale or distribution of any offshore newspaper in Singapore."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Newspaper and Printing Presses (Composition of Offences) Rules 2012","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
