  FT["SG-H3349"] = {"id":"SG-H3349","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/NPPA1974-N2?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"报章与印刷机（豁免——星洲日报（新加坡）有限公司）公告","en":"Newspaper and Printing Presses (Exemption — Sin Chew Jit Poh (Singapore) Limited) Notification","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation NPPA1974-N2","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H3349-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Notification may be cited as the Newspaper and Printing Presses (Exemption — Sin Chew Jit Poh (Singapore) Limited) Notification."}},{"id":"SG-H3349-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption of Sin Chew Jit Poh (Singapore) Limited"},"text":{"en":"2. Until further notice, the Sin Chew Jit Poh (Singapore) Limited is exempted from section 9(3) and (5) of the Act so long as the number of management shares issued before the 11th October 1977 by the company does not fall below 41,500 shares."}}],"pack":"sg-p42","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Newspaper and Printing Presses (Exemption — Sin Chew Jit Poh (Singapore) Limited) Notification","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
